window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["文化和旅游部"] = {"shijiewenhuayichanbaohuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对世界文化遗产的保护和管理，履行对《保护世界文化与自然遗产公约》的责任和义务，传承人类文明，依据《中华人民共和国文物保护法》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称世界文化遗产，是指列入联合国教科文组织《世界遗产名录》的世界文化遗产和文化与自然混合遗产中的文化遗产部分。"},{"i":3,"n":"第三条","txt":"世界文化遗产工作贯彻保护为主、抢救第一、合理利用、加强管理的方针，确保世界文化遗产的真实性和完整性。"},{"i":4,"n":"第四条","txt":"国家文物局主管全国世界文化遗产工作，协调、解决世界文化遗产保护和管理中的重大问题，监督、检查世界文化遗产所在地的世界文化遗产工作。 县级以上地方人民政府及其文物主管部门依照本办法的规定，制定管理制度，落实工作措施，负责本行政区域内的世界文化遗产工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府应当将世界文化遗产保护和管理所需的经费纳入本级财政预算。 公民、法人和其他组织可以通过捐赠等方式设立世界文化遗产保护基金，专门用于世界文化遗产保护。世界文化遗产保护基金的募集、使用和管理，依照国家有关法律、行政法规和部门规章的规定执行。"},{"i":6,"n":"第六条","txt":"国家对世界文化遗产保护的重大事项实行专家咨询制度，由国家文物局建立专家咨询机制开展相关工作。 世界文化遗产保护专家咨询工作制度由国家文物局制定并公布。"},{"i":7,"n":"第七条","txt":"公民、法人和其他组织都有依法保护世界文化遗产的义务。 国家鼓励公民、法人和其他组织参与世界文化遗产保护。 国家文物局、县级以上地方人民政府及其文物主管部门应当对在世界文化遗产保护中作出突出贡献的组织或者个人给予奖励。 省级文物主管部门应当建立世界文化遗产保护志愿者工作制度，开展志愿者的组织、指导和培训工作。"},{"i":8,"n":"第八条","txt":"世界文化遗产保护规划由省级人民政府组织编制。承担世界文化遗产保护规划编制任务的机构，应当取得国家文物局颁发的资格证书。世界文化遗产保护规划应当明确世界文化遗产保护的标准和重点，分类确定保护措施，符合联合国教科文组织有关世界文化遗产的保护要求。 尚未编制保护规划，或者保护规划内容不符合本办法要求的世界文化遗产，应当自本办法施行之日起1年内编制、修改保护规划。 世界文化遗产保护规划由省级文物主管部门报国家文物局审定。经国家文物局审定的世界文化遗产保护规划，由省级人民政府公布并组织实施。世界文化遗产保护规划的要求，应当纳入县级以上地方人民政府的国民经济和社会发展规划、土地利用总体规划和城乡规划。"},{"i":9,"n":"第九条","txt":"世界文化遗产中的不可移动文物，应当根据其历史、艺术和科学价值依法核定公布为文物保护单位。尚未核定公布为文物保护单位的不可移动文物，由县级文物主管部门予以登记并公布。 世界文化遗产中的不可移动文物，按照《中华人民共和国文物保护法》和《中华人民共和国文物保护法实施条例》的有关规定实施保护和管理。"},{"i":10,"n":"第十条","txt":"世界文化遗产中的文物保护单位，应当根据世界文化遗产保护的需要依法划定保护范围和建设控制地带并予以公布。保护范围和建设控制地带的划定，应当符合世界文化遗产核心区和缓冲区的保护要求。"},{"i":11,"n":"第十一条","txt":"省级人民政府应当为世界文化遗产作出标志说明。标志说明的设立不得对世界文化遗产造成损害。 世界文化遗产标志说明应当包括世界文化遗产的名称、核心区、缓冲区和保护机构等内容，并包含联合国教科文组织公布的世界遗产标志图案。"},{"i":12,"n":"第十二条","txt":"省级人民政府应当为世界文化遗产建立保护记录档案，并由其文物主管部门报国家文物局备案。 国家文物局应当建立全国的世界文化遗产保护记录档案库，并利用高新技术建立世界文化遗产管理动态信息系统和预警系统。"},{"i":13,"n":"第十三条","txt":"省级人民政府应当为世界文化遗产确定保护机构。保护机构应当对世界文化遗产进行日常维护和监测，并建立日志。发现世界文化遗产存在安全隐患的，保护机构应当采取控制措施，并及时向县级以上地方人民政府和省级文物主管部门报告。 世界文化遗产保护机构的工作人员实行持证上岗制度，主要负责人应当取得国家文物局颁发的资格证书。"},{"i":14,"n":"第十四条","txt":"世界文化遗产辟为参观游览区，应当充分发挥文化遗产的宣传教育作用，并制定完善的参观游览服务管理办法。 世界文化遗产保护机构应当将参观游览服务管理办法报省级文物主管部门备案。省级文物主管部门应当对世界文化遗产的参观游览服务管理工作进行监督检查。"},{"i":15,"n":"第十五条","txt":"在参观游览区内设置服务项目，应当符合世界文化遗产保护规划的管理要求，并与世界文化遗产的历史和文化属性相协调。 服务项目由世界文化遗产保护机构负责具体实施。实施服务项目，应当遵循公开、公平、公正和公共利益优先的原则，并维护当地居民的权益。"},{"i":16,"n":"第十六条","txt":"各级文物主管部门和世界文化遗产保护机构应当组织开展文化旅游的调查和研究工作，发掘并展示世界文化遗产的历史和文化价值，保护并利用世界文化遗产工作中积累的知识产权。"},{"i":17,"n":"第十七条","txt":"发生或可能发生危及世界文化遗产安全的突发事件时，保护机构应当立即采取必要的控制措施，并同时向县级以上地方人民政府和省级文物主管部门报告。省级文物主管部门应当在接到报告2小时内，向省级人民政府和国家文物局报告。 省级文物主管部门接到有关报告后，应当区别情况决定处理办法并负责实施。国家文物局应当督导并检查突发事件的及时处理，提出防范类似事件发生的具体要求，并向各世界文化遗产所在地省级人民政府通报突发事件的发生及处理情况。"},{"i":18,"n":"第十八条","txt":"国家对世界文化遗产保护实行监测巡视制度，由国家文物局建立监测巡视机制开展相关工作。 世界文化遗产保护监测巡视工作制度由国家文物局制定并公布。"},{"i":19,"n":"第十九条","txt":"因保护和管理不善，致使真实性和完整性受到损害的世界文化遗产，由国家文物局列入《中国世界文化遗产警示名单》予以公布。 列入《中国世界文化遗产警示名单》的世界文化遗产所在地省级人民政府，应当对保护和管理工作中存在的问题提出整改措施，限期改进保护管理工作。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，造成世界文化遗产损害的，依据有关规定追究责任人的责任。"},{"i":21,"n":"第二十一条","txt":"列入《中国世界文化遗产预备名单》的文化遗产，参照本办法的规定实施保护和管理。"},{"i":22,"n":"第二十二条","txt":"本办法自公布之日起施行。"}],"zhongwaihezijingyinglvxingsheshidianjingyingchujin4d9fd7":[{"i":1,"n":"第一条","txt":"为了进一步加快旅游业的对外开放，加强国际旅游合作，引进国际先进的旅行社经营模式，促进我国旅行社业的转型升级，提高国际竞争能力，根据《旅行社条例》和国务院《关于加快发展旅游业的意见》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家在试点的基础上，逐步对外商投资旅行社开放经营中国内地居民出境旅游业务。"},{"i":3,"n":"第三条","txt":"中外合资经营旅行社试点经营出境旅游业务应当遵守本办法。"},{"i":4,"n":"第四条","txt":"本办法所称的中外合资经营旅行社试点经营出境旅游业务，是指取得试点资格的中外合资经营旅行社，从事招徕、组织、接待中国内地居民出国旅游和赴香港、澳门特别行政区旅游的经营活动；大陆居民赴台湾地区旅游的除外。"},{"i":5,"n":"第五条","txt":"国家严格控制试点经营出境旅游业务的中外合资经营旅行社的数量。具体数量由国务院旅游行政主管部门决定。"},{"i":6,"n":"第六条","txt":"中外合资经营旅行社申请试点经营出境旅游业务的，应当符合《旅行社条例》第八条规定的条件，并向国务院旅游行政主管部门提出申请，并提交符合《旅行社条例》第八条规定条件的相关证明文件。"},{"i":7,"n":"第七条","txt":"试点经营出境旅游业务的中外合资经营旅行社，由国务院旅游行政主管部门在申请人中选择确定，并向申请人颁发《外商投资旅行社业务经营许可审定意见书》。"},{"i":8,"n":"第八条","txt":"申请人持《外商投资旅行社业务经营许可审定意见书》以及投资各方签订的合同、章程向商务主管部门提出变更经营范围的申请。商务主管部门应当依照有关法律、法规的规定，作出批准或者不予批准的决定。予以批准的，换发《外商投资企业批准证书》，并通知申请人向国务院旅游行政主管部门换领《旅行社业务经营许可证》；不予批准的，应当书面通知申请人并说明理由。 申请人持换领的《旅行社业务经营许可证》和《外商投资企业批准证书》，向工商行政管理机关办理企业经营范围变更登记。"},{"i":9,"n":"第九条","txt":"取得试点经营出境旅游业务资格的中外合资经营旅行社（以下简称试点旅行社），应当自换领《旅行社业务经营许可证》之日起3个工作日内，增存质量保证金120万元人民币，并向国务院旅游行政主管部门提交相关证明文件。"},{"i":10,"n":"第十条","txt":"试点旅行社在经营出境旅游业务后三年内，应当每半年向国务院旅游行政主管部门提交下列经营情况和资料： （一）组织、接待出境旅游者的组团数量和人次； （二）出境旅游业务经营额； （三）取得的经验和效果。"},{"i":11,"n":"第十一条","txt":"本办法施行后三年内，国务院旅游行政主管部门应当按年度对试点经营出境旅游业务的效果进行评估，并可根据评估结果，对试点经营出境旅游业务及试点旅行社的数量作出调整。"},{"i":12,"n":"第十二条","txt":"试点旅行社经营出境旅游业务，其经营活动应当遵守《旅行社条例》、《中国公民出国旅游管理办法》等法律、法规和规章。"},{"i":13,"n":"第十三条","txt":"旅游行政管理部门和其他有关行政管理部门，按照《旅行社条例》、《中国公民出国旅游管理办法》，以及国家有关法律、法规和规章对试点旅行社实施监督管理。"},{"i":14,"n":"第十四条","txt":"试点旅行社违反本办法规定的，由旅游行政管理部门和其他有关行政管理部门，按照《旅行社条例》、《中国公民出国旅游管理办法》，以及国家有关的法律、法规和规章的规定进行处罚。"},{"i":15,"n":"第十五条","txt":"本办法自公布之日起施行。"}],"xiangzhenzonghewenhuazhanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进乡镇综合文化站的建设，加强对乡镇综合文化站的管理，充分发挥乡镇综合文化站的作用，根据《公共文化体育设施条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法中的乡镇综合文化站（以下简称“文化站”），是指由县级或乡镇人民政府设立的公益性文化机构，其基本职能是社会服务、指导基层和协助管理农村文化市场。"},{"i":3,"n":"第三条","txt":"乡镇人民政府负责文化站日常工作的管理，县级文化行政部门负责对文化站进行监督和检查，县文化馆、图书馆等相关文化单位负责对文化站开展对口业务指导和辅导。"},{"i":4,"n":"第四条","txt":"文化部会同有关部门组织制定全国文化站建设规划和标准，并对其实施情况进行监督检查。"},{"i":5,"n":"第五条","txt":"文化站建设应纳入当地国民经济和社会发展计划，与当地经济社会发展水平相适应，建设规模应符合国家有关规定；应纳入当地城乡建设规划，优先安排用地指标，无偿划拨建设用地。 各级人民政府应对少数民族地区、边远贫困地区的文化站建设予以重点扶持。"},{"i":6,"n":"第六条","txt":"文化站应位于交通便利、人口集中、便于群众参与活动的区域，一般不设在乡镇人民政府办公场所内。 文化站的选址、设计、功能安排等应征得县级文化行政部门的同意。"},{"i":7,"n":"第七条","txt":"文化站基本功能空间应包括：多功能活动厅、书刊阅览室、培训教室、文化信息资源共享工程基层点和管理用房，以及室外活动场地、宣传栏等配套设施。"},{"i":8,"n":"第八条","txt":"文化站应配置开展公共文化服务必需的设备、器材和图书等文化资源，并有计划地予以更新、充实。 文化站设施和设备必须按照国家有关规定办理资产登记及相关手续，依法管理，确保国有资产安全、完整和有效使用。"},{"i":9,"n":"第九条","txt":"因乡镇建设规划需拆除文化站或者改变其功能、用途的，应依照国家有关法律、法规的规定择地重建。乡镇人民政府在作出决定前，应广泛听取群众的意见，并征得县级文化行政部门同意，报县级人民政府批准。"},{"i":10,"n":"第十条","txt":"文化站的主要职能是，开展书报刊借阅、时政法制科普教育、文艺演出活动、数字文化信息服务、公共文化资源配送和流动服务、体育健身和青少年校外活动等。"},{"i":11,"n":"第十一条","txt":"文化站通过以下方式履行职能，开展服务： （一）举办各类展览、讲座，普及科学文化知识，传递经济信息，为群众求知致富，促进当地经济建设服务。 （二）根据当地群众的需求和设施、场地条件，组织开展丰富多彩的、群众喜闻乐见的文体活动和广播、电影放映活动；指导村文化室（文化大院、俱乐部等）和农民自办文化组织建设，辅导和培训群众文艺骨干。 （三）协助县级文化馆、图书馆等文化单位配送公共文化资源，开展流动文化服务，保证公共文化资源进村入户。 （四）在县级图书馆的指导下，开办图书室，开展群众读书读报活动，为当地群众提供图书报刊借阅服务。 （五）建成全国文化信息资源共享工程基层服务点，开展数字文化信息服务。 （六）在县级文化行政部门的指导下，搜集、整理非物质文化遗产，开展非物质文化遗产的普查、展示、宣传活动，指导传承人开展传习活动。 （七）协助县级文化行政部门开展文物的宣传保护工作。 （八）受县级文化行政"},{"i":12,"n":"第十二条","txt":"文化站应完善内部管理制度，建立、健全服务规范，并根据其功能、特点向公众开放，保障其设施用于开展文明、健康的文化体育活动。文化站应在醒目位置标明服务内容、开放时间和注意事项。"},{"i":13,"n":"第十三条","txt":"文化站应配备专职人员进行管理，编制数额应根据所承担的职能和任务及所服务的乡镇人口规模等因素确定。"},{"i":14,"n":"第十四条","txt":"文化站站长应具有大专以上学历或具备相当于大专以上文化程度，热爱文化事业，善于组织群众开展文化活动，具备开展文化站工作的业务能力和管理水平。文化站站长由乡镇人民政府任命或聘任，事先应征求县级文化行政部门的意见。"},{"i":15,"n":"第十五条","txt":"文化站实行职业资格制度，文化站从业人员须通过文化行政部门或委托的有关部门组织的相应考试、考核，取得职业资格或岗位培训证书。 文化站从业人员可根据本人的学历条件、任职年限、工作业绩和业务水平等申报相应的专业技术资格。"},{"i":16,"n":"第十六条","txt":"文化站实行聘用制和岗位目标管理责任制。在岗人员退休或被调离、辞退后，应及时配备相应人员，确保文化站正常工作不受影响。"},{"i":17,"n":"第十七条","txt":"文化行政部门负责对文化站从业人员进行定期培训。各级文化培训机构、群艺馆、文化馆、图书馆、艺术学校、艺术院团等具体承担人员培训任务。"},{"i":18,"n":"第十八条","txt":"文化站的建设、维修、日常运转和业务活动所需经费，应列入县乡人民政府基本建设投资计划和财政预算，不得随意核减或挪用。中央、省、市级财政可对文化站设施建设和内容建设予以经费补助。"},{"i":19,"n":"第十九条","txt":"鼓励企业、社会团体、个人捐赠或资助文化站。依法向文化站捐赠财产的，捐赠人可按照有关法律规定享受优惠。"},{"i":20,"n":"第二十条","txt":"文化行政部门负责定期对文化站设施建设、经费投入、工作开展情况等进行检查、考评。文化站建设情况应纳入创建全国和地区性文化先进单位的考核指标体系。"},{"i":21,"n":"第二十一条","txt":"对在农村文化建设中做出突出贡献的文化站和文化站从业人员，由县级以上人民政府或有关部门给予奖励。"},{"i":22,"n":"第二十二条","txt":"本办法由文化部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2009年10月1日起施行。"}],"hulianwangwenhuaguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为了加强对互联网文化的管理，保障互联网文化单位的合法权益，促进我国互联网文化健康、有序地发展，根据《中华人民共和国网络安全法》、《全国人民代表大会常务委员会关于维护互联网安全的决定》和《互联网信息服务管理办法》等国家法律法规有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称互联网文化产品是指通过互联网生产、传播和流通的文化产品，主要包括： （一）专门为互联网而生产的网络音乐娱乐、网络游戏、网络演出剧（节）目、网络表演、网络艺术品、网络动漫等互联网文化产品； （二）将音乐娱乐、游戏、演出剧（节）目、表演、艺术品、动漫等文化产品以一定的技术手段制作、复制到互联网上传播的互联网文化产品。"},{"i":3,"n":"第三条","txt":"本规定所称互联网文化活动是指提供互联网文化产品及其服务的活动，主要包括： （一）互联网文化产品的制作、复制、进口、发行、播放等活动； （二）将文化产品登载在互联网上，或者通过互联网、移动通信网等信息网络发送到计算机、固定电话机、移动电话机、电视机、游戏机等用户端以及网吧等互联网上网服务营业场所，供用户浏览、欣赏、使用或者下载的在线传播行为； （三）互联网文化产品的展览、比赛等活动。 互联网文化活动分为经营性和非经营性两类。经营性互联网文化活动是指以营利为目的，通过向上网用户收费或者以电子商务、广告、赞助等方式获取利益，提供互联网文化产品及其服务的活动。非经营性互联网文化活动是指不以营利为目的向上网用户提供互联网文化产品及其服务的活动。"},{"i":4,"n":"第四条","txt":"本规定所称互联网文化单位，是指经文化行政部门和电信管理机构批准或者备案，从事互联网文化活动的互联网信息服务提供者。 在中华人民共和国境内从事互联网文化活动，适用本规定。"},{"i":5,"n":"第五条","txt":"从事互联网文化活动应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务的方向，弘扬民族优秀文化，传播有益于提高公众文化素质、推动经济发展、促进社会进步的思想道德、科学技术和文化知识，丰富人民的精神生活。"},{"i":6,"n":"第六条","txt":"文化部负责制定互联网文化发展与管理的方针、政策和规划，监督管理全国互联网文化活动。 省、自治区、直辖市人民政府文化行政部门对申请从事经营性互联网文化活动的单位进行审批，对从事非经营性互联网文化活动的单位进行备案。 县级以上人民政府文化行政部门负责本行政区域内互联网文化活动的监督管理工作。县级以上人民政府文化行政部门或者文化市场综合执法机构对从事互联网文化活动违反国家有关法规的行为实施处罚。"},{"i":7,"n":"第七条","txt":"申请从事经营性互联网文化活动，应当符合《互联网信息服务管理办法》的有关规定，并具备以下条件： （一）有单位的名称、住所、组织机构和章程； （二）有确定的互联网文化活动范围； （三）有适应互联网文化活动需要的专业人员、设备、工作场所以及相应的经营管理技术措施； （四）有确定的域名； （五）符合法律、行政法规和国家有关规定的条件。"},{"i":8,"n":"第八条","txt":"申请从事经营性互联网文化活动，应当向所在地省、自治区、直辖市人民政府文化行政部门提出申请，由省、自治区、直辖市人民政府文化行政部门审核批准。"},{"i":9,"n":"第九条","txt":"申请从事经营性互联网文化活动，应当提交下列文件： （一）申请表； （二）营业执照和章程； （三）法定代表人或者主要负责人的身份证明文件； （四）业务范围说明； （五）专业人员、工作场所以及相应经营管理技术措施的说明材料； （六）域名登记证明； （七）依法需要提交的其他文件。 对申请从事经营性互联网文化活动的，省、自治区、直辖市人民政府文化行政部门应当自受理申请之日起20日内做出批准或者不批准的决定。批准的，核发《网络文化经营许可证》，并向社会公告；不批准的，应当书面通知申请人并说明理由。 《网络文化经营许可证》有效期为3年。有效期届满，需继续从事经营的，应当于有效期届满30日前申请续办。"},{"i":10,"n":"第十条","txt":"非经营性互联网文化单位，应当自设立之日起60日内向所在地省、自治区、直辖市人民政府文化行政部门备案，并提交下列文件： （一）备案表； （二）章程； （三）法定代表人或者主要负责人的身份证明文件； （四）域名登记证明； （五）依法需要提交的其他文件。"},{"i":11,"n":"第十一条","txt":"申请从事经营性互联网文化活动经批准后，应当持《网络文化经营许可证》，按照《互联网信息服务管理办法》的有关规定，到所在地电信管理机构或者国务院信息产业主管部门办理相关手续。"},{"i":12,"n":"第十二条","txt":"互联网文化单位应当在其网站主页的显著位置标明文化行政部门颁发的《网络文化经营许可证》编号或者备案编号，标明国务院信息产业主管部门或者省、自治区、直辖市电信管理机构颁发的经营许可证编号或者备案编号。"},{"i":13,"n":"第十三条","txt":"经营性互联网文化单位变更单位名称、域名、法定代表人或者主要负责人、注册地址、经营地址、股权结构以及许可经营范围的，应当自变更之日起20日内到所在地省、自治区、直辖市人民政府文化行政部门办理变更或者备案手续。 非经营性互联网文化单位变更名称、地址、域名、法定代表人或者主要负责人、业务范围的，应当自变更之日起60日内到所在地省、自治区、直辖市人民政府文化行政部门办理备案手续。"},{"i":14,"n":"第十四条","txt":"经营性互联网文化单位终止互联网文化活动的，应当自终止之日起30日内到所在地省、自治区、直辖市人民政府文化行政部门办理注销手续。 经营性互联网文化单位自取得《网络文化经营许可证》并依法办理企业登记之日起满180日未开展互联网文化活动的，由原审核的省、自治区、直辖市人民政府文化行政部门注销《网络文化经营许可证》，同时通知相关省、自治区、直辖市电信管理机构。 非经营性互联网文化单位停止互联网文化活动的，由原备案的省、自治区、直辖市人民政府文化行政部门注销备案，同时通知相关省、自治区、直辖市电信管理机构。"},{"i":15,"n":"第十五条","txt":"经营进口互联网文化产品的活动应当由取得文化行政部门核发的《网络文化经营许可证》的经营性互联网文化单位实施，进口互联网文化产品应当报文化部进行内容审查。 文化部应当自受理内容审查申请之日起20日内（不包括专家评审所需时间）做出批准或者不批准的决定。批准的，发给批准文件；不批准的，应当说明理由。 经批准的进口互联网文化产品应当在其显著位置标明文化部的批准文号，不得擅自变更产品名称或者增删产品内容。自批准之日起一年内未在国内经营的，进口单位应当报文化部备案并说明原因；决定终止进口的，文化部撤销其批准文号。 经营性互联网文化单位经营的国产互联网文化产品应当自正式经营起30日内报省级以上文化行政部门备案，并在其显著位置标明文化部备案编号，具体办法另行规定。"},{"i":16,"n":"第十六条","txt":"互联网文化单位不得提供载有以下内容的文化产品： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）散布谣言，扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":17,"n":"第十七条","txt":"互联网文化单位提供的文化产品，使公民、法人或者其他组织的合法利益受到侵害的，互联网文化单位应当依法承担民事责任。"},{"i":18,"n":"第十八条","txt":"互联网文化单位应当建立自审制度，明确专门部门，配备专业人员负责互联网文化产品内容和活动的自查与管理，保障互联网文化产品内容和活动的合法性。"},{"i":19,"n":"第十九条","txt":"互联网文化单位发现所提供的互联网文化产品含有本规定第十六条所列内容之一的，应当立即停止提供，保存有关记录，向所在地省、自治区、直辖市人民政府文化行政部门报告并抄报文化部。"},{"i":20,"n":"第二十条","txt":"互联网文化单位应当记录备份所提供的文化产品内容及其时间、互联网地址或者域名；记录备份应当保存60日，并在国家有关部门依法查询时予以提供。"},{"i":21,"n":"第二十一条","txt":"未经批准，擅自从事经营性互联网文化活动的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令停止经营性互联网文化活动，予以警告，并处30000元以下罚款；拒不停止经营活动的，依法列入文化市场黑名单，予以信用惩戒。"},{"i":22,"n":"第二十二条","txt":"非经营性互联网文化单位违反本规定第十条，逾期未办理备案手续的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处1000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"经营性互联网文化单位违反本规定第十二条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正，并可根据情节轻重处10000元以下罚款。 非经营性互联网文化单位违反本规定第十二条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处500元以下罚款。"},{"i":24,"n":"第二十四条","txt":"经营性互联网文化单位违反本规定第十三条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，没收违法所得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿直至吊销《网络文化经营许可证》；构成犯罪的，依法追究刑事责任。 非经营性互联网文化单位违反本规定第十三条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处1000元以下罚款。"},{"i":25,"n":"第二十五条","txt":"经营性互联网文化单位违反本规定第十五条，经营进口互联网文化产品未在其显著位置标明文化部批准文号、经营国产互联网文化产品未在其显著位置标明文化部备案编号的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处10000元以下罚款。"},{"i":26,"n":"第二十六条","txt":"经营性互联网文化单位违反本规定第十五条，擅自变更进口互联网文化产品的名称或者增删内容的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令停止提供，没收违法所得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿直至吊销《网络文化经营许可证》；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"经营性互联网文化单位违反本规定第十五条，经营国产互联网文化产品逾期未报文化行政部门备案的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处20000元以下罚款。"},{"i":28,"n":"第二十八条","txt":"经营性互联网文化单位提供含有本规定第十六条禁止内容的互联网文化产品，或者提供未经文化部批准进口的互联网文化产品的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令停止提供，没收违法所得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿直至吊销《网络文化经营许可证》；构成犯罪的，依法追究刑事责任。 非经营性互联网文化单位，提供含有本规定第十六条禁止内容的互联网文化产品，或者提供未经文化部批准进口的互联网文化产品的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令停止提供，处1000元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"经营性互联网文化单位违反本规定第十八条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处20000元以下罚款。"},{"i":30,"n":"第三十条","txt":"经营性互联网文化单位违反本规定第十九条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构予以警告，责令限期改正，并处10000元以下罚款。"},{"i":31,"n":"第三十一条","txt":"违反本规定第二十条的，由省、自治区、直辖市电信管理机构责令改正；情节严重的，由省、自治区、直辖市电信管理机构责令停业整顿或者责令暂时关闭网站。"},{"i":32,"n":"第三十二条","txt":"本规定所称文化市场综合执法机构是指依照国家有关法律、法规和规章的规定，相对集中地行使文化领域行政处罚权以及相关监督检查权、行政强制权的行政执法机构。"},{"i":33,"n":"第三十三条","txt":"文化行政部门或者文化市场综合执法机构查处违法经营活动，依照实施违法经营行为的企业注册地或者企业实际经营地进行管辖；企业注册地和实际经营地无法确定的，由从事违法经营活动网站的信息服务许可地或者备案地进行管辖；没有许可或者备案的，由该网站服务器所在地管辖；网站服务器设置在境外的，由违法行为发生地进行管辖。"},{"i":34,"n":"第三十四条","txt":"本规定自2011年4月1日起施行。2003年5月10日发布、2004年7月1日修订的《互联网文化管理暂行规定》同时废止。"}],"quanguowenhuaxianjinxianquanguowenhuagongzuoxianji0fbfb3":[{"i":1,"n":"第一条","txt":"为了引导和激励广大文化工作者积极进取，促进国家文化艺术事业的发展和繁荣，表彰在有中国特色社会主义文化建设中做出突出成绩的地区、单位和个人，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所授予的荣誉称号是指：全国文化先进县，全国文化工作先进集体，全国文化系统先进工作者、劳动模范。"},{"i":3,"n":"第三条","txt":"本办法规定的荣誉称号适用范围是： （一）全国文化先进县授予符合条件的县、县级市和市辖区（其中包括新疆生产建设兵团的县级单位）； （二）全国文化工作先进集体授予具有独立法人地位的文化企、事业单位和万里边疆文化长廊共建部门文化工作成绩显著的单位； （三）根据人事部下达的指标，全国文化系统先进工作者授予全国文化系统的机关和事业单位的工作人员，全国文化系统劳动模范授予全国文化系统企业单位的工作人员。"},{"i":4,"n":"第四条","txt":"为确保评选质量，特制定全国文化先进县，全国文化工作先进集体，全国文化系统先进工作者、劳动模范评选标准（附件一、二、三）。"},{"i":5,"n":"第五条","txt":"授予荣誉称号，应当严格按照文化部规定的标准进行评选。 全国文化先进县由县政府申报，地、市文化局签署意见，各省、自治区和直辖市文化厅（局）审核并征得省、自治区和直辖市人民政府同意后，上报文化部审批。 全国文化工作先进集体，全国文化系统先进工作者、劳动模范由各省、自治区和直辖市文化厅（局）、人事厅（局）联合上报文化部审批。 在特殊情况下，对做出突出事迹的单位和个人，授予机关可以直接授予荣誉称号。对生前有突出表现或重大贡献者，可由授予机关追授荣誉称号。"},{"i":6,"n":"第六条","txt":"全国文化先进县和全国文化工作先进集体荣誉称号的授予工作每２年进行一次；全国文化系统先进工作者、劳动模范荣誉称号的授予工作每４年进行一次。"},{"i":7,"n":"第七条","txt":"对已获得全国先进工作者、劳动模范以及省部级先进工作者、劳动模范荣誉称号的，不再授予全国文化系统先进工作者、劳动模范荣誉称号。"},{"i":8,"n":"第八条","txt":"对荣誉称号获得者，由授予机关发布表彰决定，召开表彰会或以其他形式颁奖。"},{"i":9,"n":"第九条","txt":"对授予全国文化先进县、全国文化工作先进集体荣誉称号的，颁发证书和奖牌，发给一定数量奖金。对授予全国文化系统先进工作者、劳动模范荣誉称号的个人，颁发证书和奖章，享受省部级先进工作者、劳动模范待遇。"},{"i":10,"n":"第十条","txt":"对已被授予全国文化先进县或全国文化工作先进集体荣誉称号的，如发现有伪造事迹骗取荣誉问题或发生其他严重错误造成不良影响的，撤销其荣誉称号。"},{"i":11,"n":"第十一条","txt":"对已被授予全国文化系统先进工作者或者全国文化系统劳动模范的个人，有下列情形之一的，撤销其荣誉称号： （一）伪造事迹，骗取荣誉的； （二）受行政开除处分的； （三）受劳动教养行政处罚的； （四）受刑事处罚的； （五）有其他严重有损于荣誉称号行为的。"},{"i":12,"n":"第十二条","txt":"撤销荣誉称号，由原申报机关报授予机关审批。特殊情况下，授予机关可直接予以撤销。"},{"i":13,"n":"第十三条","txt":"对被撤销荣誉称号者，收回其证书、奖章或者奖牌。对个人，取消省部级先进工作者、劳动模范待遇，并记入本人档案。"},{"i":14,"n":"第十四条","txt":"本规定由文化部负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自发布之日起施行。１９９７年２月１８日发布的《文化部关于授予全国文化先进地区、全国文化先进集体和全国文化系统先进工作者、劳动模范荣誉称号的暂行办法》同时废止。 附件一：全国文化先进县评选标准 “全国文化先进县”必须坚持文艺为人民服务、为社会主义服务的方向，坚持“百花齐放，百家争鸣”方针，文化工作全面先进，并属于本省（区、市）命名表彰的“文化先进县”。同时还应具备以下条件： 一、党政领导重视文化工作，每年能够召开１－２次专门研究文化工作的会议；文化事业发展有规划、有检查、有落实；逐年增加对文化事业的经费投入，各类公益性文化事业单位年度经费有保证，预算拨款占本地区财政总支出１％以上，并根据经济发展逐年增加；文化设施有明显改善。 二、艺术表演团体坚持弘扬主旋律，提倡多样化的方针，艺术演出面向基层，面向群众。具有较强的艺术生产力，能创作演出优秀的、群众喜闻乐见的剧节目。 三、群众文化组织"}],"bowuguanguanlibanfa":[{"i":1,"n":"第一条","txt":"为贯彻落实科学发展观，规范博物馆管理工作，促进博物馆事业发展，根据《中华人民共和国文物保护法》、《中华人民共和国文物保护法实施条例》、《公共文化体育设施条例》、《事业单位登记管理暂行条例》和《民办非企业单位登记管理暂行条例》等相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称博物馆，是指收藏、保护、研究、展示人类活动和自然环境的见证物，经过文物行政部门审核、相关行政部门批准许可取得法人资格，向公众开放的非营利性社会服务机构。 利用或主要利用国有文物、标本、资料等资产设立的博物馆为国有博物馆。 利用或主要利用非国有文物、标本、资料等资产设立的博物馆为非国有博物馆。"},{"i":3,"n":"第三条","txt":"国家扶持和发展博物馆事业，鼓励个人、法人和其他组织设立博物馆。 县级以上人民政府应当将博物馆事业纳入本级国民经济和社会发展规划，事业经费列入本级财政预算。 博物馆的数量、种类、规模以及布局，应当根据本地区国民经济和社会发展水平、文物等资源条件和公众精神文化需求，统筹兼顾，优化配置。鼓励优先设立填补博物馆门类空白和体现行业特性、区域特点的专题性博物馆。"},{"i":4,"n":"第四条","txt":"国家鼓励博物馆发展相关文化产业，多渠道筹措资金，促进自身发展。 博物馆依法享受税收减免优惠，享有通过依法征集、购买、交换、接受捐赠和调拨等方式取得藏品的权利。"},{"i":5,"n":"第五条","txt":"博物馆应当发挥社会教育功能，传播有益于社会进步的思想道德、科学技术和文化知识。 在博物馆参观或开展其他活动，应当爱护博物馆设施、展品和周边环境，遵守公共秩序。"},{"i":6,"n":"第六条","txt":"国务院文物行政部门主管全国博物馆工作。 县级以上地方文物行政部门对本行政区域内的博物馆实施监督和管理。"},{"i":7,"n":"第七条","txt":"县级以上文物行政部门应当促进博物馆行业组织建设，指导行业组织活动，逐步对博物馆实行分级、分类管理。"},{"i":8,"n":"第八条","txt":"县级以上文物行政部门对发展博物馆事业做出突出贡献的机构、团体或个人，应当给予表彰或奖励。"},{"i":9,"n":"第九条","txt":"申请设立博物馆，应当具备下列条件： （一）具有固定的馆址，设置专用的展厅（室）、库房和文物保护技术场所，展厅（室）面积与展览规模相适应，展览环境适宜对公众开放； （二）具有必要的办馆资金和保障博物馆运行的经费； （三）具有与办馆宗旨相符合、一定数量和成系统的藏品及必要的研究资料； （四）具有与办馆宗旨相符合的专业技术和管理人员； （五）具有符合国家规定的安全和消防设施； （六）能够独立承担民事责任。"},{"i":10,"n":"第十条","txt":"省级文物行政部门负责本行政区域内博物馆设立的审核工作。 博物馆名称一般不得冠以“中国”、“中华”、“国家”等字样（简称“中国”等字样）；特殊情况确需冠以“中国”等字样的，应由中央机构编制委员会办公室会同国务院文物行政部门审核同意。 非国有博物馆的名称不得冠以“中国”等字样。"},{"i":11,"n":"第十一条","txt":"申请设立博物馆，应当由馆址所在地市（县）级文物行政部门初审后，向省级文物行政部门提交下列材料： （一）博物馆设立申请书； （二）馆舍所有权或使用权证明； （三）资金来源证明或验资报告； （四）藏品目录及合法来源说明； （五）陈列展览大纲； （六）拟任法定代表人的基本情况及身份证明； （七）专业技术和管理人员的证明材料。 申请设立非国有博物馆的，应同时提交博物馆章程草案。章程草案应当包括下列主要事项： （一）办馆宗旨及藏品收藏标准； （二）博物馆理事会、董事会或其他形式决策机构的产生办法、人员构成、任期、议事规则等； （三）出资人不要求取得经济回报的约定； （四）博物馆终止时的藏品处置方式； （五）章程修改程序。"},{"i":12,"n":"第十二条","txt":"省级文物行政部门应当自收到博物馆设立申请材料之日起30个工作日内出具审核意见。审核同意的，应报国务院文物行政部门备案。审核不同意的，应当书面说明理由。 经审核同意设立博物馆的，申请人应持审核意见及其他申报材料，向相关行政部门申请取得博物馆法人资格。 博物馆应当自取得法人资格之日起6个月内向社会开放。 本办法实施前已批准设立的博物馆，应当在本办法实施之日起6个月内，向省级文物行政部门提交本办法第十一条第一款规定的除（一）项之外的全部材料；非国有博物馆应同时提交博物馆章程。"},{"i":13,"n":"第十三条","txt":"博物馆的建筑设计应当符合国家和行业颁布的有关标准和规范。博物馆建筑应当划分为陈列展览区、藏品库房区、文物保护技术区、公众服务区和办公区等，相对自成系统。"},{"i":14,"n":"第十四条","txt":"国有博物馆建设工程的设计方案，应当报请所在地省级文物行政部门组织论证。"},{"i":15,"n":"第十五条","txt":"博物馆应当于每年3月31日前向所在地市（县）级文物行政部门报送上一年度的工作报告，接受年度检查。工作报告内容应当包括有关法律和其他规定的执行情况，藏品、展览、人员和机构的变动情况以及社会教育、安全、财务管理等情况。 市（县）级文物行政部门应当于每年4月30日前，将上一年度本行政区域内博物馆年度检查的初步意见报送省级文物行政部门。省级文物行政部门应当于每年5月31日前，将上一年度本行政区域内博物馆的年度检查情况进行审核，并汇总报国务院文物行政部门备案。"},{"i":16,"n":"第十六条","txt":"博物馆的名称、馆址、藏品、基本陈列以及非国有博物馆的章程等重要事项发生变更前，应当报省级文物行政部门审核。 博物馆法定代表人发生变更的，应当自变更之日起10日内报省级文物行政部门备案。"},{"i":17,"n":"第十七条","txt":"博物馆终止前，应当向省级文物行政部门提出终止申请及藏品处置方案，接受主管文物行政部门指导，完成博物馆资产清算工作。 省级文物行政部门应当自收到博物馆终止申请和藏品处置方案之日起30个工作日内出具审核意见。藏品处置方案等符合法定要求的，准予终止；藏品处置方案等不符合法定要求的，责令其改正后准予终止。相关行政部门根据省级文物行政部门的审核意见，给予办理博物馆法人资格注销登记手续。"},{"i":18,"n":"第十八条","txt":"国有博物馆终止的，其藏品由所在地省级文物行政部门指定的国有博物馆接收。 非国有博物馆终止的，其藏品属于法律规定可以依法流通的，允许其以法律规定的方式流通；依法不能流通的藏品，应当转让给其他博物馆；接受捐赠的藏品，应当交由其他博物馆收藏，并告知捐赠人。"},{"i":19,"n":"第十九条","txt":"博物馆藏品的收藏、保护、研究、展示等，应当依法建立、健全相关规章制度，并报所在地市（县）级文物行政部门备案。 博物馆应具有保障藏品安全的设备和设施。馆藏一级文物和其他易损易坏的珍贵文物，应设立专库或专柜并由专人负责保管。"},{"i":20,"n":"第二十条","txt":"博物馆应建立藏品总帐、分类帐及每件藏品的档案，并依法办理备案手续。 博物馆通过依法征集、购买、交换、接受捐赠和调拨等方式取得的藏品，应在30日内登记入藏品总帐。"},{"i":21,"n":"第二十一条","txt":"依法调拨、交换、借用国有博物馆藏品，取得藏品的博物馆可以对提供藏品的博物馆给予实物、技术、培训或资金方面的合理补偿。补偿数额的确定，应当考虑藏品保管、修复、研究、展示等过程中原收藏博物馆发生的实际费用。调拨、交换、借用国有博物馆藏品的申请文件，应当包括合理补偿的方案。"},{"i":22,"n":"第二十二条","txt":"博物馆不够本馆收藏标准，或因腐蚀损毁等原因无法修复并无继续保存价值的藏品，经本馆或受委托的专家委员会评估认定后，可以向省级文物行政部门申请退出馆藏。 退出馆藏申请材料的内容，应当包括拟不再收藏的藏品名称、数量和退出馆藏的原因，并附有关藏品档案复制件。"},{"i":23,"n":"第二十三条","txt":"国有博物馆所在地省级文物行政部门应当在收到退出馆藏申请材料的30个工作日内，组织专家委员会复审。专家委员会复审未通过的，终止该藏品的退出馆藏程序。 专家委员会复审通过的，省级文物行政部门应当将有关材料在国务院文物行政部门和有关省级文物行政部门的官方网站上公示30个工作日。期间如有其他国有文物收藏单位愿意接收有关藏品，则以调拨、交换等方式处理；期间如没有其他国有文物收藏单位愿意接收有关藏品，则由省级文物行政部门统一处置。处置方案报国务院文物行政部门批准后实施，处置所得资金应当用于博物馆事业发展。 国有博物馆应当建立退出馆藏物品专项档案，并报省级文物行政部门备案。专项档案应当保存75年以上。"},{"i":24,"n":"第二十四条","txt":"非国有博物馆申请藏品退出馆藏，申请材料应附理事会、董事会或其他形式决策机构的书面意见。博物馆所在地省级文物行政部门应当在收到申请材料的30个工作日内作出是否允许退出馆藏的决定，并报国务院文物行政部门备案。"},{"i":25,"n":"第二十五条","txt":"博物馆应当以本馆藏品为基础，开展有关专业学科及应用技术的研究，提高业务活动的学术含量，促进专业人才的成长。在确保藏品安全的前提下，博物馆应当为馆外人员研究本馆藏品提供便利。"},{"i":26,"n":"第二十六条","txt":"博物馆举办陈列展览，应当遵循以下原则： （一）与本馆性质和任务相适应，突出馆藏品特色、行业特性和区域特点，具有较高的学术和文化含量； （二）合理运用现代技术、材料、工艺和表现手法，达到形式与内容的和谐统一； （三）展品应以原件为主，复原陈列应当保持历史原貌，使用复制品、仿制品和辅助展品应予明示； （四）展厅内具有符合标准的安全技术防范设备和防止展品遭受自然损害的展出设施； （五）为公众提供文字说明和讲解服务； （六）陈列展览的对外宣传活动及时、准确，形式新颖。"},{"i":27,"n":"第二十七条","txt":"博物馆应当根据办馆宗旨，结合本馆特点开展形式多样、生动活泼的社会教育和服务活动，积极参与社区文化建设。 鼓励博物馆利用电影、电视、音像制品、出版物和互联网等途径传播藏品知识、陈列展览及研究成果。"},{"i":28,"n":"第二十八条","txt":"博物馆对公众开放，应当遵守以下规定： （一）公告服务项目和开放时间；变更服务项目和开放时间的，应当提前7日公告； （二）开放时间应当与公众的工作、学习及休闲时间相协调；法定节假日和学校寒暑假期间，应当适当延长开放时间； （三）无正当理由，国有博物馆全年开放时间不少于10个月，非国有博物馆全年开放时间不少于8个月。"},{"i":29,"n":"第二十九条","txt":"博物馆应当逐步建立减免费开放制度，并向社会公告。 国有博物馆对未成年人集体参观实行免费制度，对老年人、残疾人、现役军人等特殊社会群体参观实行减免费制度。"},{"i":30,"n":"第三十条","txt":"鼓励博物馆研发相关文化产品，传播科学文化知识，开展专业培训、科技成果转让等形式的有偿服务活动。"},{"i":31,"n":"第三十一条","txt":"博物馆违反本办法规定，情节严重的，由所在地省级文物行政部门撤销审核同意意见，由相关行政部门撤销博物馆法人资格。 博物馆违反其他法律、法规规定的，依照有关法律、法规的规定处罚。"},{"i":32,"n":"第三十二条","txt":"本办法自2006年1月1日起施行。"}],"bowuguancangpinguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强博物馆藏品的保护管理，确保藏品安全，促进藏品价值研究与有效利用，满足社会公众的精神文化需求，根据《中华人民共和国文物保护法》《中华人民共和国文物保护法实施条例》《博物馆条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于全国范围内经登记管理机关依法登记且已在所在地省级文物行政部门备案博物馆的藏品管理。 本办法所称藏品，是指博物馆根据本馆的性质、任务依法取得，完成入藏程序并确定为博物馆正式收藏，具有历史、艺术、科学价值的文物藏品和化石、标本、实物资料等其他藏品。"},{"i":3,"n":"第三条","txt":"博物馆藏品是国家宝贵的科学、文化资源，是博物馆业务活动的重要物质基础。藏品管理工作应当做到制度健全、账目清楚、信息准确、保管妥善、保护科学、利用合理。"},{"i":4,"n":"第四条","txt":"国务院文物行政部门负责全国博物馆藏品管理工作的指导和监督。 县级以上地方文物行政部门负责本行政区域内博物馆藏品管理工作的组织协调、业务指导和监督检查。 博物馆负责本馆藏品的收藏、整理、保管、保护、研究和利用工作。"},{"i":5,"n":"第五条","txt":"博物馆法定代表人或者主要负责人是藏品安全第一责任人，应当牵头开展藏品管理的制度建设、任务实施与监督检查工作。博物馆法定代表人或者主要负责人离任前，应当办理藏品清点、移交手续。主管的文物行政部门应当派员对国有博物馆法定代表人或者主要负责人离任藏品清点、移交工作进行监督检查。"},{"i":6,"n":"第六条","txt":"博物馆应当设立藏品保管专门部门，承担藏品管理主要职责。保管部门负责人负责藏品管理相应的审核、监管工作，组织保管人员落实藏品管理制度要求、开展具体工作。无法设立藏品保管专门部门的，应当配备专职保管人员。 保管人员实行岗位责任制，应当经过岗位培训并保持相对稳定，参加岗位所需的业务技能继续教育，严守相关工作秘密。保管人员离任前，应当进行藏品清点、移交，清点、移交结果应当经保管部门负责人和博物馆法定代表人或者主要负责人签字确认。 保护修复、展览陈列、开放服务、资产管理、安全保卫、信息化等部门及其工作人员在各自工作职责范围内，承担藏品管理的相应责任。"},{"i":7,"n":"第七条","txt":"博物馆应当建立包括藏品取得、鉴定、定级、藏品总登记账、藏品档案、库房管理、出入库、清点、退出、修复、复制、拓印等管理要求在内的藏品管理制度，完善内部管理流程，相关藏品管理制度报主管的文物行政部门备案。"},{"i":8,"n":"第八条","txt":"鼓励博物馆积极开展藏品管理信息化建设，信息系统设计遵循统筹规划、业务协同、安全可靠、便捷高效的基本原则，符合相关国家、行业标准，具备重要信息修改自动记录生成操作日志功能，便于藏品信息的动态管理与查询追踪。"},{"i":9,"n":"第九条","txt":"博物馆应当建立健全公众参与和社会监督机制，通过博物馆现场公示、官方网站等方式，向社会公布除涉及国家秘密、商业秘密、工作秘密或者个人隐私外的藏品资源数据和藏品征集、退出等信息，主动接受社会监督。"},{"i":10,"n":"第十条","txt":"博物馆可以通过多种方式，鼓励公民、组织将其收藏的文物捐赠给博物馆或者出借给博物馆展览和研究。"},{"i":11,"n":"第十一条","txt":"博物馆可以通过购买、接受捐赠、依法交换、调拨、移交等法律法规规定的方式取得藏品。 博物馆应当基于本馆的性质和任务制定藏品入藏标准，取得藏品前应当组织专业人员对藏品的真伪和价值进行鉴定评估，确定是否符合本馆入藏标准。"},{"i":12,"n":"第十二条","txt":"博物馆开展藏品征集活动，应当遵循统一领导、集体决策、利益相关方回避等原则，并根据办馆宗旨、收藏体系、发展方向等情况建立藏品征集管理制度。 博物馆征集藏品应当依法履行合理注意义务，对拟征集藏品来源的合法性进行了解、识别，不得征集来源不合法或者来源不明的藏品，征集活动不得有违博物馆职业道德。 博物馆应当为征集藏品建立专项档案，将征集过程所有原始资料、工作记录整理归档，永久保存，并通过年报、官方网站、媒体等方式，及时向社会公布征集藏品的管理、使用等情况，主动接受社会监督。"},{"i":13,"n":"第十三条","txt":"博物馆通过购买方式征集藏品的，应当履行征集调查、意向确定、专家鉴定评估、价格谈判或者协商、订立协议、征集实施及信息公布等基本工作程序。 博物馆应当根据征集物类别，组织三名以上相应研究方向且具有文物博物高级职称的专家，对拟征集物的真伪，历史、艺术、科学价值，流传经历，价格等进行鉴定评估，由专家独立出具书面鉴定评估意见。只要有一名专家不同意征集的，应当立即终止征集程序。 博物馆应当根据专家评估拟征集物价格的平均值，参考本馆征集同类藏品的价格、文物市场中类似物品的成交价格，形成拟征集物估价建议。形成的估价建议价格较高的，应当按照国家有关规定进行资产评估，并以资产评估结果作为估价建议。估价建议应当严格保密，作为开展价格谈判或者协商的上限。"},{"i":14,"n":"第十四条","txt":"博物馆通过接受捐赠方式征集藏品的，可以参照本办法第十三条规定的程序执行，并就捐赠物的详细信息、来源合法性及权利无瑕疵保证、交接验收方式、所有权转移条件、双方权利义务、特殊情形处理和争议解决方式等内容，订立捐赠协议。 博物馆对捐赠藏品者应当给予相应的精神鼓励，确有必要的，可以给予适当物质奖励。"},{"i":15,"n":"第十五条","txt":"国务院文物行政部门和省级文物行政部门可以依法指定国有博物馆接收考古发掘单位和执法、司法、监察等部门移交的文物和其他藏品。博物馆应当接收符合本馆入藏标准的藏品；对不符合本馆入藏标准的，应当及时报请指定接收的文物行政部门另行指定接收单位。"},{"i":16,"n":"第十六条","txt":"博物馆对取得的藏品，应当在三个月内办理入藏手续，逐件填写入藏（馆）凭证或者清册，对藏品进行核收。入藏（馆）凭证、藏品照片等原始资料应当归入藏品档案。"},{"i":17,"n":"第十七条","txt":"博物馆应当对尚未定级文物藏品、新入藏文物藏品及时区分等级。博物馆对文物藏品进行初步鉴选后，向省级文物行政部门提交文物藏品定级申请，省级文物行政部门定期组织开展定级、备案工作，其中馆藏一级文物由省级文物行政部门报国务院文物行政部门进行备案。"},{"i":18,"n":"第十八条","txt":"博物馆应当将完成入藏和定级手续的文物藏品、完成入藏手续的其他藏品，及时登入本馆藏品总登记账。不符合入藏标准的复仿制品、模型、非文物教学标本、当代图书资料等，应当相应设立各类辅助账册。 藏品总登记账是国家科学、文化财产账，所有文物藏品和其他藏品都应当登入藏品总登记账，不得以重复品、参考品为由存在账外藏品，不得将已登入藏品总登记账的藏品划入各类辅助账册。"},{"i":19,"n":"第十九条","txt":"藏品总登记账应当以纸质形式永久保存，不得随意更改，确需修订的，应当经保管部门负责人确认、博物馆法定代表人或者主要负责人批准后留痕订正，经办人应当签字或者盖章。通过藏品信息系统管理藏品总登记账的，所有藏品信息修改应当留痕，重要信息修改应当与纸质藏品总登记账修订保持一致。藏品总登记账与文物资源资产财务账应当定期核对，确保账账相符。 藏品总登记账应当设专人负责管理，妥善保管，管理藏品总登记账的人员不得兼管藏品库房。"},{"i":20,"n":"第二十条","txt":"藏品总登记账应当包括登记日期、总登记号、分类号、名称、时代、数量、尺寸、重量（质量）、质地、完残情况、来源、入馆凭证号、退出凭证号、级别、备注等基本内容。博物馆应当按照相关国家、行业标准填写藏品总登记账信息。 藏品总登记账下可以根据藏品的类别、级别、来源、存放位置等另设藏品分类账。各分类账的藏品数量、类别、级别等基本信息应当与藏品总登记账相符。 藏品总登记号一经确定即永久使用，不能更改和重复使用，藏品退出后原总登记号仍应当保留。藏品总登记号应当以合适的方式标注在藏品的适当部位或者标签上，并回注在入藏（馆）凭证、分类账上。"},{"i":21,"n":"第二十一条","txt":"博物馆可以建立藏品编目卡，简明、准确地记录藏品基础信息、研究信息、管理信息等，便于检索查找与保管利用。"},{"i":22,"n":"第二十二条","txt":"博物馆应当按照相关国家、行业标准建立藏品档案，藏品档案可以以纸质或者电子形式保存，并动态更新藏品情况信息。 档案内容包括藏品在取得、鉴定、定级、保管、保护、研究、展示和利用过程中形成的有关藏品基本信息、管理情况以及其他事项的历史记录。 博物馆应当依法依规履行文物藏品档案备案程序，县级以上地方文物行政部门应当建立本行政区域内的文物藏品档案；国务院文物行政部门应当建立全国馆藏一级文物档案和主管的博物馆文物藏品档案。"},{"i":23,"n":"第二十三条","txt":"文物藏品可以在国有博物馆之间交换。交换文物藏品的，应当经博物馆所在地省级文物行政部门批准，并报国务院文物行政部门备案。未完成建账、建档手续的文物藏品，不得交换。 国务院文物行政部门可以调拨全国的国有文物藏品。省级文物行政部门可以调拨本行政区域内其主管的国有博物馆文物藏品；调拨国有馆藏一级文物，应当报国务院文物行政部门备案。 国有博物馆将接受捐赠的藏品作交换、调拨处理，应当按照与捐赠人约定的协议办理；无约定协议的，应当事先向捐赠人说明情况并取得其书面同意。"},{"i":24,"n":"第二十四条","txt":"国有博物馆对藏品作退出馆藏处理，应当符合下列条件之一： （一）因老化、腐蚀等原因造成藏品毁损且无保存价值； （二）化石、标本、实物资料等其他藏品不够入藏标准； （三）因地震、洪水等不可抗力导致藏品灭失； （四）藏品在国有博物馆之间进行交换、调拨； （五）法律法规规定的其他情形。"},{"i":25,"n":"第二十五条","txt":"国有博物馆应当严格履行藏品退出馆藏的规定程序。国有博物馆对符合本办法第二十四条第一项、第二项规定情形的藏品拟作退出馆藏处理的，应当组织五名以上具有文物博物高级职称的专家对拟退出藏品的基本情况、退出理由等进行评估，由专家独立出具对每一件藏品是否同意退出馆藏的个人评估意见，本馆人员不得担任评估专家。只要有一名专家不同意退出馆藏的，应当立即终止退出程序，且五年内不得就同一件藏品重新启动退出程序。 经专家评估一致同意退出馆藏的藏品，由国有博物馆将藏品的基本情况、专家评估意见、退出处置方案在主管的文物行政部门官方网站、博物馆现场和官方网站上进行公示，公示时间不少于三十个工作日。按照本办法第二十四条第一项、第二项规定情形对藏品作退出馆藏处理的，应当报省级文物行政部门批准后退出馆藏，并且应当将退出藏品纳入辅助账册管理或者提供给国有教学及科研单位保管使用；按照本办法第二十四条第三至五项规定情形对藏品作"},{"i":26,"n":"第二十六条","txt":"藏品信息发生变更，应当经保管部门负责人确认、博物馆法定代表人或者主要负责人批准后，对藏品信息系统、藏品档案、公开资料中的相关信息予以更新，并将藏品信息变更表归入藏品档案。"},{"i":27,"n":"第二十七条","txt":"博物馆应当对藏品进行统计，每年将藏品总数及增减、变化情况等报主管的文物行政部门备案。"},{"i":28,"n":"第二十八条","txt":"博物馆终止或者合并，应当依照有关非营利组织的法律法规处理藏品，藏品属于国家所有的可移动文物的，应当由省级文物行政部门指定其他国有博物馆收藏。"},{"i":29,"n":"第二十九条","txt":"博物馆应当设置固定、专用的藏品库房，由保管部门或者专职保管人员负责管理。库区由安全保卫部门落实二十四小时值班负责制。 凡不具备安全防范和消防条件的场所，禁止存放藏品。展厅、修复室等临时存放出库藏品的场所，应当确定专职工作人员和定岗保卫人员负责藏品安全。"},{"i":30,"n":"第三十条","txt":"藏品库房及其设施应当符合藏品妥善保管、科学保护的要求，具备防火、防水、防震、防雷、防盗、防潮、防尘、防光（紫外线）、防生物危害、防空气污染等功能，配置必要的安全防范和消防设施设备，以及保存环境监测和调控设备，并定期检查维护。"},{"i":31,"n":"第三十一条","txt":"博物馆对完成建账、建档手续的藏品，应当及时按类别、级别或者专题对藏品进行分库或者分区存储，根据藏品的质地、尺寸、重量等情况科学制定存储方法，配置柜架囊匣，确保藏品存储安全、取用便利。有条件的博物馆可以对馆藏珍贵文物和易损藏品建立专库。 取放、移动藏品时，应当根据藏品质地、保存状况等情况，注意操作规范，保证藏品安全。"},{"i":32,"n":"第三十二条","txt":"博物馆内部各部门提用藏品，应当填写提用凭证，提供提用藏品清单，明确使用方式、使用目的、安全要求、出库及归库时间等，经提用部门负责人、保管部门负责人确认、博物馆法定代表人或者主要负责人批准。"},{"i":33,"n":"第三十三条","txt":"其他单位借用藏品，出借博物馆应当检查、评估拟出借藏品的保存现状、借用的必要性与风险，与借用单位确定藏品清单，明确约定藏品借出后的安全责任、运输和保管要求、出借及归还时间等，经集体研究同意后签订借用协议，借用协议约定的期限不得超过三年，并根据文物藏品级别、借用单位情况依法履行相关审批、备案程序。 未完成建账、建档手续的藏品不得出借；保存状况不佳、易因运输包装受损的藏品不得出借。 藏品借用期间，出借博物馆应当加强技术指导、监督检查，超过期限未归还的，博物馆应当及时督促、催还，重大情况应当向主管的文物行政部门报告。"},{"i":34,"n":"第三十四条","txt":"国有博物馆之间因举办展览、科学研究等需借用文物藏品，应当在出借后三十个工作日内，由出借博物馆报主管的文物行政部门备案；借用国有馆藏一级文物的，应当同时报国务院文物行政部门备案。非国有博物馆和其他单位举办展览需借用国有文物藏品，应当在出借前二十个工作日，由出借博物馆报主管的文物行政部门批准；借用国有馆藏一级文物的，应当报国务院文物行政部门批准。境外机构举办展览需借用文物藏品，出借博物馆应当依法履行相关审批程序。"},{"i":35,"n":"第三十五条","txt":"藏品完成馆内提用审批手续或者出馆借用审批手续后，方能办理藏品出库手续。保管部门负责人审核提用凭证或者借用协议、藏品清单、审批文件等材料无误后，指派保管人员入库提取藏品，并在藏品出入库记录簿或者相关凭证上记录藏品出库情况。 提取藏品后，保管人员与提用人员或者借用单位人员应当进行出库点交，确认藏品状况，详细记录藏品现状，文字不能尽述的部分应当采用影像记录，并由双方在藏品出入库点交单上签字确认。 点交完成后，提用部门或者借用单位应当对出库藏品安全负主要责任，保管部门、出借博物馆应当对出库藏品安全使用负监管责任。未采取藏品安全防护措施或者藏品存放场所不具备安全防护条件的，保管部门、出借博物馆有权拒绝藏品出库或者要求藏品提前归库。"},{"i":36,"n":"第三十六条","txt":"藏品归库时，保管人员与提用人员或者借用单位人员应当凭提用凭证或者借用协议、藏品出入库点交单等对藏品逐件进行点交验收，查验确认归库藏品的真实性和保存状况，并在藏品出入库点交单上签字。如发现归库藏品的真实性或者保存状况与出库时不同，双方应当书面提交说明情况，查明原因，根据藏品数量、价值及相关情形履行相应的报告程序，处理完毕后将相关材料归入藏品档案。 保管部门应当对藏品的归库情况进行动态统计与监督核查，对按时归还的藏品及时记录归库情况，对超过期限未归还的藏品，保管部门或者相关责任部门应当及时督促，视情况报告处理。  藏品因借用出库、归库，点交双方应当分别不少于两人。"},{"i":37,"n":"第三十七条","txt":"藏品清点包括全面清点、专项盘库、核查抽检等方式，清点时应当做到账（藏品总登记账）、物（藏品）、卡（编目卡）、照（照片或者影像）相符。 保管部门应当每年对藏品库房、展厅、修复室等地点保管存放的藏品进行核查抽检，核查抽检范围应当涵盖所有的藏品类别，重点核查当年提用、借用藏品和馆藏珍贵文物的账物相符情况及保存现状。 博物馆一经发现藏品账物不符、受损或者超过归库期限未归还等情况，应当及时处置、查找原因，重大情况应当报主管的文物行政部门。 藏品年度清点报告应当经博物馆法定代表人或者主要负责人签字确认，每年12月底前报主管的文物行政部门。"},{"i":38,"n":"第三十八条","txt":"藏品的包装运输应当按照相关国家、行业标准，由博物馆或者具备相关资信和能力的机构承担。借用藏品运输过程中，出借博物馆或者借用单位应当确定专职人员进行监督。"},{"i":39,"n":"第三十九条","txt":"库房管理人员不得单独进入藏品库房，如遇库房管理人员不足两人的特殊情况，应当由博物馆法定代表人或者主要负责人指定博物馆其他人员陪同库房管理人员入库。 非库房管理人员未经批准不得进入藏品库房。经批准进入藏品库房者，应当如实填写人员出入库登记表，记录入库时间、入库事由和陪同人员信息，由两名库房管理人员陪同入库。"},{"i":40,"n":"第四十条","txt":"库房管理人员应当开展日常巡库工作，认真检查藏品库房及藏品动态，填写《库房日记》，真实准确地记录每日出入库时间、出入库人员、入库工作内容、库房温湿度等环境数据及库内安全情况等，发现异常情况应当报告保管部门负责人，采取有效处理措施，重大情况及时报告博物馆法定代表人或者主要负责人。"},{"i":41,"n":"第四十一条","txt":"保管部门、提用部门与安全保卫部门应当对展厅、修复室等地点存放的提用藏品定期进行日常安全检查，评估藏品保存状况，发现不安全因素或者发生藏品受损的，应当采取有效处理措施，并及时报告博物馆法定代表人或者主要负责人处理。 出借博物馆和借用单位应当对长时间借用的藏品定期确认安全状况和保管条件，发现问题应当及时处置。"},{"i":42,"n":"第四十二条","txt":"博物馆应当制定藏品安全应急预案并定期演练，预防各类安全事故和案件发生。 馆藏一级文物损毁的，应当按照安全应急管理相关规定，及时报国务院文物行政部门核查处理，其他文物藏品损毁的，及时报省级文物行政部门核查处理，并将核查处理结果报国务院文物行政部门备案。发生藏品被盗、被抢或者丢失等事件的，应当立即向公安机关报案，并向主管的文物行政部门报告。"},{"i":43,"n":"第四十三条","txt":"博物馆应当对藏品进行定期检查和养护，检查和记录藏品的保存状况和病害情况，开展藏品除尘、杀虫、灭菌、支撑、包装、固定等日常养护工作。"},{"i":44,"n":"第四十四条","txt":"博物馆应当建立多部门共同参与的常态化藏品预防性保护工作机制，完善预防性保护设施设备，监测、评估和控制藏品保存环境，减少温度、湿度、光照、空气污染物、有害生物等各种环境因素对藏品的影响，使藏品处于稳定、洁净的良好保存环境。 博物馆应当严格控制材质脆弱藏品的保存环境，做到有效防护、科学存放，严格限定展出时间，减少提取、运输频次。"},{"i":45,"n":"第四十五条","txt":"博物馆应当使用摄影测量、三维扫描等现代信息技术，积极开展藏品数字化保护工作。由信息化部门会同保管部门制定操作及安全工作方案，规范采集、加工、整理、储存藏品的图像和三维数字资源，并按照相关规定要求加强管理，保障藏品数字资源安全。"},{"i":46,"n":"第四十六条","txt":"博物馆因藏品保护或者科学研究的特殊需要，必须从藏品本体上有损取样进行分析时，应当遵循最小干预原则，由保护修复部门会同保管部门共同制定取样方案，报省级文物行政部门批准后实施。 属于馆藏一级文物的，一般不予取样，可以使用同时代、同类型、同质地的其他藏品替代；必须对馆藏一级文物取样的，应当报国务院文物行政部门批准后实施。"},{"i":47,"n":"第四十七条","txt":"藏品修复应当遵循不改变原状原则，将科学研究贯穿于修复的全过程。 修复馆藏一级文物的，应当报国务院文物行政部门批准后实施。修复馆藏二级、三级文物的，修复方案应当报省级文物行政部门批准后实施。未按照国家相关规定办理审批程序的，博物馆不得自行开展文物藏品的修复。"},{"i":48,"n":"第四十八条","txt":"藏品复制、拓印应当遵循少而精的原则，采用先进技术方法，不得对藏品造成损害。为陈列展览、科学研究等用途制作的复制品、拓片，应当予以登记并妥善保管，不得挪作它用。 复制、拓印馆藏一级文物的，应当报国务院文物行政部门批准。复制、拓印馆藏二级、三级文物的，应当报省级文物行政部门批准。未按照国家相关规定办理审批程序的，博物馆不得自行开展文物藏品的复制、拓印。"},{"i":49,"n":"第四十九条","txt":"从事文物藏品修复、复制、拓印活动的机构或者单位，应当取得可移动文物修复资质。 博物馆应当对修复、复制、拓印活动中的文物藏品安全负责，确认开展文物藏品修复、复制、拓印活动的场所和设施符合博物馆风险等级和安全防护相关国家、行业标准规定的条件，并定期进行安全检查，发现不安全因素及时处理。"},{"i":50,"n":"第五十条","txt":"博物馆应当积极开展对藏品实物形态的基础研究和藏品内涵价值的综合研究，并通过学术交流、陈列展览、文化创意等多种方式进行宣传阐释传播。"},{"i":51,"n":"第五十一条","txt":"鼓励博物馆公开藏品目录、数字影像、研究成果等藏品资源信息，为相关教育教学、科学研究工作提供便利和支持。 博物馆开展藏品资源以及相关数据资源利用活动，应当遵守法律法规，坚持以社会主义核心价值观为引领，以拓展博物馆公共文化服务范畴、更好发挥藏品的社会效益为目的。"},{"i":52,"n":"第五十二条","txt":"博物馆不得将藏品赠与、出租、出售或者抵押、质押给其他单位、个人。 博物馆及其工作人员不得从事文物等藏品商业经营活动，不得举办或者参与举办文物销售单位或者文物拍卖企业。 博物馆工作人员不得借用或者非法侵占文物等藏品。"},{"i":53,"n":"第五十三条","txt":"博物馆有下列行为之一的，由县级以上文物行政部门责令改正，给予警告或者通报批评，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，可以并处五万元以下的罚款： （一）未按规定设置藏品库房及其设施； （二）未按规定履行审批或者备案手续，擅自交换、出借文物藏品； （三）博物馆法定代表人或者主要负责人离任时未按规定移交文物藏品，或者所移交的文物藏品与档案不符； （四）国有博物馆将文物藏品赠与、出租、出售或者抵押、质押给其他单位、个人。"},{"i":54,"n":"第五十四条","txt":"博物馆及其工作人员有下列行为之一的，由县级以上文物行政部门责令改正；情节严重的，对单位处十万元以上三百万元以下的罚款，限制业务活动或者由原发证机关吊销许可证书，对个人处五千元以上五万元以下的罚款： （一）未按规定建立藏品管理制度，或者未将管理制度备案； （二）未按规定建立藏品总登记账，或者未妥善保管藏品总登记账致使账目资料毁损、灭失； （三）未按规定建立藏品档案，或者未将藏品档案备案； （四）未经批准擅自调取文物藏品； （五）未经批准擅自修复、复制、拓印文物藏品； （六）文物藏品损毁未报文物行政部门核查处理，或者文物藏品被盗、被抢或者丢失，博物馆未及时向公安机关或者文物行政部门报告。"},{"i":55,"n":"第五十五条","txt":"博物馆从事文物商业经营活动的，由县级以上文物行政部门责令改正，给予警告或者通报批评，没收违法所得、非法经营的文物；违法经营额三万元以上的，并处违法经营额二倍以上十倍以下的罚款；没有违法经营额或者违法经营额不足三万元的，并处五万元以上二十五万元以下的罚款；情节严重的，由原发证机关吊销许可证书。"},{"i":56,"n":"第五十六条","txt":"博物馆工作人员有下列行为之一的，依法给予处分；情节严重的，依法开除公职或者吊销其从业资格证书： （一）国有博物馆工作人员借用或者非法侵占国有文物藏品； （二）举办或者参与举办文物销售单位或者文物拍卖企业； （三）因不负责任造成馆藏珍贵文物损毁或者流失； （四）贪污、挪用文物保护经费。"},{"i":57,"n":"第五十七条","txt":"博物馆有下列情形之一的，由主管的文物行政部门责令限期改正；逾期不改正的，对博物馆给予警告或者通报批评，并处一万元以上十万元以下罚款： （一）未按规定修订藏品总登记账； （二）未按规定程序开展藏品征集活动； （三）未按规定办理藏品入藏手续； （四）未按规定办理藏品退出手续； （五）未按规定办理藏品提用、借用手续； （六）未按规定办理藏品出库、归库手续； （七）未按规定对藏品进行取样。"},{"i":58,"n":"第五十八条","txt":"博物馆有下列情形之一，造成严重后果或者有其他恶劣情节的，由主管的文物行政部门对博物馆给予警告或者通报批评，并处一万元以上十万元以下罚款： （一）博物馆法定代表人或者主要负责人离任时未按规定移交其他藏品，或者所移交的其他藏品与档案不符； （二）保管人员离任时未按规定移交藏品，或者所移交的藏品与档案不符； （三）保管人员违反保密工作要求； （四）安全保卫部门未落实二十四小时值班职责； （五）未按规定对藏品账物不符、受损或超过归库期限未归还等重大情况进行报告； （六）其他藏品损毁未报文物行政部门核查处理，或者其他藏品被盗、被抢或者丢失，未及时向公安机关或者文物行政部门报告； （七）非国有博物馆将文物藏品赠与、出租、出售或者抵押、质押给其他单位、个人； （八）将其他藏品赠与、出租、出售或者抵押、质押给其他单位、个人。"},{"i":59,"n":"第五十九条","txt":"博物馆取得来源不明或者来源不合法的藏品，由省级文物行政部门或者有关登记管理机关按照职责分工，责令改正，有违法所得的，没收违法所得，并处违法所得二倍以上五倍以下罚款；没有违法所得的，处五千元以上二万元以下罚款，情节严重的，由登记机关撤销登记。"},{"i":60,"n":"第六十条","txt":"违反本办法规定，文物行政部门及国有博物馆工作人员在藏品管理工作中滥用职权、玩忽职守、徇私舞弊的，对负有责任的领导人员和直接责任人员依法给予处分。 违反本办法规定，构成犯罪的，依法追究刑事责任。 博物馆出现藏品安全事故的，由本级人民政府或者上级机关依照有关文物保护、安全生产法律法规的规定处罚。"},{"i":61,"n":"第六十一条","txt":"具有科学价值的古脊椎动物化石和古人类化石应当依据本办法关于文物藏品管理的相关规定实施。化石、标本、实物资料等其他藏品可以参照本办法关于文物藏品管理的相关规定实施。"},{"i":62,"n":"第六十二条","txt":"非国有博物馆可以参照本办法关于国有博物馆藏品管理的相关规定，制定实施本馆的藏品管理制度。"},{"i":63,"n":"第六十三条","txt":"本办法自2026年11月1日起施行。原《博物馆藏品管理办法》（文化部文物字〔1986〕第730号）同时废止。"}],"gurenleihuashihegujizhuidongwuhuashibaohuguanliban9e3045":[{"i":1,"n":"第一条","txt":"为加强对古人类化石和古脊椎动物化石的保护和管理，根据《中华人民共和国文物保护法》制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称古人类化石和古脊椎动物化石，指古猿化石、古人类化石及其与人类活动有关的第四纪古脊椎动物化石。"},{"i":3,"n":"第三条","txt":"国务院文物行政部门主管全国古人类化石和古脊椎动物化石的保护和管理工作。 县级以上地方人民政府文物行政部门对本行政区域内的古人类化石和古脊椎动物化石的保护实施监督管理。"},{"i":4,"n":"第四条","txt":"古人类化石和古脊椎动物化石分为珍贵化石和一般化石；珍贵化石分为三级。古人类化石、与人类有祖裔关系的古猿化石、代表性的与人类有旁系关系的古猿化石、代表性的与人类起源演化有关的第四纪古脊椎动物化石为一级化石；其他与人类有旁系关系的古猿化石、系统地位暂不能确定的古猿化石、其他重要的与人类起源演化有关的第四纪古脊椎动物化石为二级化石；其他有科学价值的与人类起源演化有关的第四纪古脊椎动物化石为三级化石。 一、二、三级化石和一般化石的保护和管理，按照国家有关一、二、三级文物和一般文物保护管理的规定实施。"},{"i":5,"n":"第五条","txt":"古人类化石和古脊椎动物化石地点以及遗迹地点，纳入不可移动文物的保护和管理体系，并根据其价值，报请核定公布为各级文物保护单位。"},{"i":6,"n":"第六条","txt":"古人类化石和古脊椎动物化石的考古调查、勘探和发掘工作，按照国家有关文物考古调查、勘探和发掘的管理规定实施管理。 地下埋藏的古人类化石和古脊椎动物化石，任何单位或者个人不得私自发掘。 古人类化石和古脊椎动物化石的考古发掘项目，其领队及主要工作人员应当具有古生物学及其它相关学科的研究背景。"},{"i":7,"n":"第七条","txt":"建设工程涉及地下可能埋藏古人类化石和古脊椎动物化石的调查、勘探和发掘工作的程序和要求，按照国家有关建设工程涉及地下可能埋藏文物的调查、勘探和发掘工作的规定执行。"},{"i":8,"n":"第八条","txt":"在进行建设工程或者在农业生产中，任何单位或者个人发现古人类化石和古脊椎动物化石，应当保护现场，立即报告当地文物行政部门。文物行政部门应当按照《中华人民共和国文物保护法》第三十二条第一款规定的要求和程序进行处理。"},{"i":9,"n":"第九条","txt":"除出境展览或者因特殊需要经国务院批准出境外，古人类化石和古脊椎动物化石不得出境。 古人类化石和古脊椎动物化石出境展览，按照国家有关文物出境展览的管理规定实施管理。 古人类化石和古脊椎动物化石临时进境，按照国家有关文物临时进境的管理规定实施管理。"},{"i":10,"n":"第十条","txt":"对保护古人类化石和古脊椎动物化石作出突出贡献的单位或个人，由国家给予精神鼓励或者物质奖励。"},{"i":11,"n":"第十一条","txt":"违反本办法规定的，依照有关规定追究法律责任。"},{"i":12,"n":"第十一条","txt":"违反本办法规定的，依照有关规定追究法律责任。"},{"i":13,"n":"第十二条","txt":"本办法自公布之日起施行。"}],"guojiajiwenhuashengtaibaohuquguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强非物质文化遗产区域性整体保护，维护和培育文化生态，传承弘扬中华优秀传统文化，坚定文化自信，满足人民日益增长的美好生活需要，根据《中华人民共和国非物质文化遗产法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的“国家级文化生态保护区”，是指以保护非物质文化遗产为核心，对历史文化积淀丰厚、存续状态良好，具有重要价值和鲜明特色的文化形态进行整体性保护，并经文化和旅游部同意设立的特定区域。"},{"i":3,"n":"第三条","txt":"国家级文化生态保护区建设要以习近平新时代中国特色社会主义思想为指导，充分尊重人民群众的主体地位，贯彻新发展理念，弘扬社会主义核心价值观，推动中华优秀传统文化创造性转化、创新性发展。"},{"i":4,"n":"第四条","txt":"国家级文化生态保护区建设应坚持保护优先、整体保护、见人见物见生活的理念，既保护非物质文化遗产，也保护孕育发展非物质文化遗产的人文环境和自然环境，实现“遗产丰富、氛围浓厚、特色鲜明、民众受益”的目标。"},{"i":5,"n":"第五条","txt":"国家级文化生态保护区依托相关行政区域设立，区域范围为县、地市或若干县域。"},{"i":6,"n":"第六条","txt":"申报和设立国家级文化生态保护区应本着少而精的原则，坚持公开、公平、公正，履行申报、审核、论证、批准等程序。"},{"i":7,"n":"第七条","txt":"具备下列条件的，可以申报国家级文化生态保护区：  （一）传统文化历史积淀丰厚，具有鲜明地域或民族特色，文化生态保持良好；  （二）非物质文化遗产资源丰富，是当地生产生活的重要组成部分；  （三）非物质文化遗产传承有序，传承实践富有活力、氛围浓厚，当地民众广泛参与，认同感强；  （四）与非物质文化遗产密切相关的实物、场所保存利用良好，其周边的自然生态环境能为非物质文化遗产提供良性的发展空间；  （五）所在地人民政府重视文化生态保护，对非物质文化遗产项目集中、自然生态环境基本良好、传统文化生态保持较为完整的乡镇、村落、街区等重点区域以及开展非物质文化遗产传承所依存的重要场所开列清单，并已经制定实施保护办法和措施；  （六）有文化生态保护区建设管理机构和工作人员；  （七）在省（区、市）内已实行文化生态区域性整体保护两年以上，成效明显。"},{"i":8,"n":"第八条","txt":"申报地区人民政府向省级人民政府文化主管部门提出申报国家级文化生态保护区的申请；省级人民政府文化主管部门组织开展审核论证，经省级人民政府同意后，向文化和旅游部提出设立国家级文化生态保护区的申请。"},{"i":9,"n":"第九条","txt":"申报国家级文化生态保护区，应当提交下列材料：  （一）省级人民政府文化主管部门设立国家级文化生态保护区的申请和省级人民政府同意申请的相关文件；  （二）文化生态保护区规划纲要；  （三）省级人民政府文化主管部门组织的专家评审论证意见；  （四）本省（区、市）内实行文化生态区域性整体保护的相关文件；  （五）其他有关材料。"},{"i":10,"n":"第十条","txt":"文化生态保护区规划纲要由省级人民政府文化主管部门、相关地区人民政府负责编制。编制工作应广泛听取非物质文化遗产传承人和当地民众意见，吸收非物质文化遗产保护、地方文化研究、规划等方面的专家学者参与。"},{"i":11,"n":"第十一条","txt":"文化生态保护区规划纲要应包括下列内容：  （一）对文化形态形成的地理环境、历史沿革、现状、鲜明特色、文化内涵与价值的描述和分析；  （二）保护区域范围及重点区域，区域内县级以上非物质文化遗产代表性项目、文物保护单位、相关实物和重要场所清单等；  （三）建设目标、工作原则、保护内容、保护方式等；  （四）保障措施及保障机制；  （五）其他有关资料。"},{"i":12,"n":"第十二条","txt":"文化和旅游部组织对申报材料进行审核。对申报材料齐全且符合要求的申请地区，文化和旅游部根据年度工作计划组织考察组进行实地考察。  考察组应当吸收非物质文化遗产保护、地方文化研究、规划等方面的专家学者参加。"},{"i":13,"n":"第十三条","txt":"文化和旅游部根据实地考察情况，对文化生态保护区规划纲要组织专家论证。根据论证意见，文化和旅游部将符合条件的申请地区设立为国家级文化生态保护实验区。"},{"i":14,"n":"第十四条","txt":"国家级文化生态保护实验区设立后一年内，所在地区人民政府应当在文化生态保护区规划纲要的基础上，细化形成国家级文化生态保护区总体规划，经省级人民政府文化主管部门审核，报省级人民政府审议通过后发布实施，并报文化和旅游部备案。"},{"i":15,"n":"第十五条","txt":"国家级文化生态保护区总体规划应纳入本省（区、市）国民经济与社会发展总体规划，要与相关的生态保护、环境治理、土地利用、旅游发展、文化产业等专门性规划和国家公园、国家文化公园、自然保护区等专项规划相衔接。"},{"i":16,"n":"第十六条","txt":"国家级文化生态保护区总体规划实施三年后，由省级人民政府文化主管部门向文化和旅游部提出验收申请；文化和旅游部根据申请组织开展国家级文化生态保护实验区建设成果验收。验收合格的，正式公布为国家级文化生态保护区并授牌。"},{"i":17,"n":"第十七条","txt":"国家级文化生态保护区建设管理机构负责统筹、指导、协调、推进国家级文化生态保护区的建设工作。"},{"i":18,"n":"第十八条","txt":"国家级文化生态保护区建设管理机构承担以下主要职责：  （一）贯彻落实国家有关文化建设、非物质文化遗产保护的法律、法规和方针、政策；  （二）制定实施国家级文化生态保护区的各项建设管理制度，创新工作机制和保护方式、措施；  （三）负责实施国家级文化生态保护区总体规划；  （四）组织或委托有关机构开展文化生态保护理论和实践研究；  （五）开展文化生态保护的宣传教育和培训；  （六）评估、报告和公布国家级文化生态保护区建设情况和成效。"},{"i":19,"n":"第十九条","txt":"国家级文化生态保护区建设管理机构应当根据非物质文化遗产各个项目、文化遗产与人文和自然环境之间的关联性，依照确定的保护区域范围、重点区域和重要场所保护清单，制定落实保护办法和行动计划。"},{"i":20,"n":"第二十条","txt":"国家级文化生态保护区建设管理机构应当尊重当地居民的意愿，保护当地居民权益，建立严格的管理制度，保持重点区域和重要场所的历史风貌。"},{"i":21,"n":"第二十一条","txt":"国家级文化生态保护区建设管理机构应当进一步加强非物质文化遗产调查工作，建立完善非物质文化遗产档案和数据库，妥善保存非物质文化遗产珍贵实物资料，实施非物质文化遗产记录工程，促进记录成果广泛利用和社会共享。"},{"i":22,"n":"第二十二条","txt":"国家级文化生态保护区建设管理机构应当依托相关研究机构和高等院校，组织或委托开展与当地非物质文化遗产保护传承和文化生态整体性保护理论和实践研究。"},{"i":23,"n":"第二十三条","txt":"国家级文化生态保护区建设管理机构应当开展非物质文化遗产代表性项目存续状况评测和保护绩效评估，制定落实分类保护政策措施，优先保护急需保护的非物质文化遗产代表性项目，不断提高非物质文化遗产代表性项目的传承实践能力，弘扬当代价值，促进发展振兴。"},{"i":24,"n":"第二十四条","txt":"国家级文化生态保护区建设管理机构应当制定相关制度，为各级非物质文化遗产代表性传承人开展传习活动创造条件、提供支持，资助传承人开展授徒传艺、教学、交流等活动。组织实施非物质文化遗产传承人群研修研习培训，帮助非物质文化遗产传承人群提高传承能力，增强传承后劲。  对传承工作有突出贡献的非物质文化遗产代表性传承人予以表彰、奖励，采取助学、奖学等方式支持从业者学习非物质文化遗产相关技艺。"},{"i":25,"n":"第二十五条","txt":"在国家级文化生态保护区内，应当建设综合性非物质文化遗产展示场所，根据当地实际建设非物质文化遗产专题馆，根据传习需要设立各级非物质文化遗产代表性项目传习所或传习点。鼓励将具有地域、民族特色的传统文化元素或符号运用在当地城乡规划和设施建设中。"},{"i":26,"n":"第二十六条","txt":"国家级文化生态保护区建设管理机构应当整合多方资源，推动将非物质文化遗产保护知识纳入当地国民教育体系，编写非物质文化遗产传承普及辅导读本，在保护区内的中小学开设非物质文化遗产乡土课程，在职业学校和高等院校设立非物质文化遗产相关专业或开设选修课，推进非物质文化遗产进校园、进课堂、进教材。"},{"i":27,"n":"第二十七条","txt":"国家级文化生态保护区建设管理机构应当每年定期组织举办有影响力的非物质文化遗产展示展演活动，利用传统节日、文化和自然遗产日等重要节点开展非物质文化遗产宣传传播活动。鼓励和支持当地民众按照当地习俗依法依规举办传统文化活动。"},{"i":28,"n":"第二十八条","txt":"国家级文化生态保护区建设管理机构应当挖掘区域内传统工艺项目资源，培养一批能工巧匠，培育一批知名品牌，推动传统工艺振兴；组织开展区域内建档立卡贫困人口参加传统工艺相关技能培训，带动就业，精准助力区域内贫困群众脱贫增收。"},{"i":29,"n":"第二十九条","txt":"国家级文化生态保护区建设管理机构应当依托区域内独具特色的文化生态资源，开展文化观光游、文化体验游、文化休闲游等多种形式的旅游活动。"},{"i":30,"n":"第三十条","txt":"国家级文化生态保护区建设管理机构应当深入挖掘、阐释非物质文化遗产蕴含的优秀思想观念、人文精神、道德规范，培育文明乡风、良好家风、淳朴民风，提升乡村文明水平，助力乡村振兴。"},{"i":31,"n":"第三十一条","txt":"国家级文化生态保护区建设管理机构应当加强工作机构和队伍建设，配备一定数量的专职工作人员；定期组织开展文化生态保护培训，提高工作人员的业务水平和工作能力；委托相关高等院校或机构，培养一批文化生态保护专业人才；建立一支文化生态保护志愿者队伍，鼓励和引导社会力量参与文化生态保护工作。"},{"i":32,"n":"第三十二条","txt":"国家级文化生态保护区建设经费应当纳入省市级当地公共财政经常性支出预算，并作为重要评估指标。文化和旅游部通过中央财政对国家级文化生态保护区建设予以补贴。鼓励社会资金参与国家级文化生态保护区建设工作。"},{"i":33,"n":"第三十三条","txt":"国家级文化生态保护区建设管理机构应当依据总体规划，每年对总体规划实施情况和建设工作成效开展自评，将年度重点工作清单和自评报告广泛征求区域内民众的意见，并报送文化和旅游部备案。"},{"i":34,"n":"第三十四条","txt":"文化和旅游部不定期对国家级文化生态保护区建设情况进行检查；每五年对国家级文化生态保护区开展一次总体规划实施情况和建设成效评估，评估报告向社会公布。"},{"i":35,"n":"第三十五条","txt":"对建设成绩突出的国家级文化生态保护区，文化和旅游部予以通报表扬，并给予重点支持。因保护不力使文化生态遭到破坏的，文化和旅游部将严肃处理，并予以摘牌。"},{"i":36,"n":"第三十六条","txt":"文化和旅游部已公布的国家级文化生态保护实验区建设管理工作依据本办法执行。"},{"i":37,"n":"第三十七条","txt":"本办法由文化和旅游部负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2019年3月1日起施行。"}],"guojiajifeiwuzhiwenhuayichandaibiaoxingchuanchengrffb8ac":[{"i":1,"n":"第一条","txt":"为传承弘扬中华优秀传统文化，有效保护和传承非物质文化遗产，鼓励和支持国家级非物质文化遗产代表性传承人开展传承活动，根据《中华人民共和国非物质文化遗产法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家级非物质文化遗产代表性传承人，是指承担国家级非物质文化遗产代表性项目传承责任，在特定领域内具有代表性，并在一定区域内具有较大影响，经文化和旅游部认定的传承人。"},{"i":3,"n":"第三条","txt":"国家级非物质文化遗产代表性传承人的认定与管理应当以习近平新时代中国特色社会主义思想为指导，坚持以人民为中心，弘扬社会主义核心价值观，保护传承非物质文化遗产，推动中华优秀传统文化创造性转化、创新性发展。"},{"i":4,"n":"第四条","txt":"国家级非物质文化遗产代表性传承人的认定与管理应当立足于完善非物质文化遗产传承体系，增强非物质文化遗产的存续力，尊重传承人的主体地位和权利，注重社区和群体的认同感。"},{"i":5,"n":"第五条","txt":"国家级非物质文化遗产代表性传承人应当锤炼忠诚、执着、朴实的品格，增强使命和担当意识，提高传承实践能力，在开展传承、传播等活动时遵守宪法和法律法规，遵守社会公德，坚持正确的历史观、国家观、民族观、文化观，铸牢中华民族共同体意识，不得以歪曲、贬损等方式使用非物质文化遗产。"},{"i":6,"n":"第六条","txt":"文化和旅游部一般每五年开展一批国家级非物质文化遗产代表性传承人认定工作。"},{"i":7,"n":"第七条","txt":"认定国家级非物质文化遗产代表性传承人，应当坚持公开、公平、公正的原则，严格履行申报、审核、评审、公示、审定、公布等程序。"},{"i":8,"n":"第八条","txt":"符合下列条件的中国公民可以申请或者被推荐为国家级非物质文化遗产代表性传承人： （一）长期从事该项非物质文化遗产传承实践，熟练掌握其传承的国家级非物质文化遗产代表性项目知识和核心技艺； （二）在特定领域内具有代表性，并在一定区域内具有较大影响； （三）在该项非物质文化遗产的传承中具有重要作用，积极开展传承活动，培养后继人才； （四）爱国敬业，遵纪守法，德艺双馨。 从事非物质文化遗产资料收集、整理和研究的人员不得认定为国家级非物质文化遗产代表性传承人。"},{"i":9,"n":"第九条","txt":"公民提出国家级非物质文化遗产代表性传承人申请的，应当向国家级非物质文化遗产代表性项目所在地文化和旅游主管部门如实提交下列材料： （一）申请人姓名、民族、从业时间、被认定为地方非物质文化遗产代表性传承人时间等基本情况； （二）申请人的传承谱系或师承脉络、学习与实践经历； （三）申请人所掌握的非物质文化遗产知识和核心技艺、成就及相关的证明材料； （四）申请人授徒传艺、参与社会公益性活动等情况； （五）申请人持有该项目的相关实物、资料的情况； （六）申请人志愿从事非物质文化遗产传承活动，履行代表性传承人相关义务的声明； （七）其他有助于说明申请人具有代表性和影响力的材料。 中央各部门直属单位可以通过其主管单位直接向文化和旅游部推荐国家级非物质文化遗产代表性传承人，推荐材料应当包括前款各项内容。"},{"i":10,"n":"第十条","txt":"文化和旅游主管部门收到申请材料或者推荐材料后，应当组织专家进行审核并逐级上报。 省级文化和旅游主管部门收到上述材料后，应当组织审核，提出推荐人选和审核意见，连同申报材料和审核意见一并报送文化和旅游部。"},{"i":11,"n":"第十一条","txt":"文化和旅游部应当对收到的申请材料或者推荐材料进行复核。符合要求的，进入评审程序；不符合要求的，退回材料并说明理由。"},{"i":12,"n":"第十二条","txt":"文化和旅游部应当组织专家评审组和评审委员会，对推荐认定为国家级非物质文化遗产代表性传承人的人选进行初评和审议。根据需要，可以安排现场答辩环节。 评审委员会对初评人选进行审议，提出国家级非物质文化遗产代表性传承人推荐人选。"},{"i":13,"n":"第十三条","txt":"文化和旅游部对评审委员会提出的国家级非物质文化遗产代表性传承人推荐人选向社会公示，公示期为20日。"},{"i":14,"n":"第十四条","txt":"公民、法人或者其他组织对国家级非物质文化遗产代表性传承人推荐人选有异议的，可以在公示期间以书面形式实名向文化和旅游部提出。"},{"i":15,"n":"第十五条","txt":"文化和旅游部根据评审委员会的审议意见和公示结果，审定国家级非物质文化遗产代表性传承人名单，并予以公布。"},{"i":16,"n":"第十六条","txt":"文化和旅游部应当建立国家级非物质文化遗产代表性传承人档案，并及时更新相关信息。 档案内容主要包括传承人基本信息、参加学习培训、开展传承活动、参与社会公益性活动情况等。"},{"i":17,"n":"第十七条","txt":"文化和旅游主管部门根据需要采取下列措施，支持国家级非物质文化遗产代表性传承人开展传承、传播等活动： （一）提供必要的传承场所； （二）提供必要的经费资助其开展授徒、传艺、交流等活动； （三）指导、支持其开展非物质文化遗产记录、整理、建档、研究、出版、展览展示展演等活动； （四）支持其参加学习、培训； （五）支持其参与社会公益性活动； （六）支持其开展传承、传播等活动的其他措施。 对无经济收入来源、生活确有困难的国家级非物质文化遗产代表性传承人，所在地文化和旅游主管部门应当协调有关部门积极创造条件，并鼓励社会组织和个人提供资助，保障其基本生活需求。"},{"i":18,"n":"第十八条","txt":"国家级非物质文化遗产代表性传承人承担下列义务： （一）开展传承活动，培养后继人才； （二）妥善保存相关实物、资料； （三）配合文化和旅游主管部门及其他有关部门进行非物质文化遗产调查； （四）参与非物质文化遗产公益性宣传等活动。"},{"i":19,"n":"第十九条","txt":"省级文化和旅游主管部门应当根据实际情况，列明国家级非物质文化遗产代表性传承人义务，明确传习计划和具体目标任务，报文化和旅游部备案。 国家级非物质文化遗产代表性传承人应当每年向省级文化和旅游主管部门提交传承情况报告。"},{"i":20,"n":"第二十条","txt":"省级文化和旅游主管部门根据传习计划应当于每年6月30日前对上一年度国家级非物质文化遗产代表性传承人义务履行和传习补助经费使用情况进行评估，在广泛征求意见的基础上形成评估报告，报文化和旅游部备案。 评估结果作为享有国家级非物质文化遗产代表性传承人资格、给予传习补助的主要依据。"},{"i":21,"n":"第二十一条","txt":"文化和旅游部按照有关规定，会同有关部门对做出突出贡献的国家级非物质文化遗产代表性传承人予以表彰和奖励。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，经省级文化和旅游主管部门核实后，文化和旅游部取消国家级非物质文化遗产代表性传承人资格，并予以公布： （一）丧失中华人民共和国国籍的； （二）采取弄虚作假等不正当手段取得资格的； （三）无正当理由不履行义务，累计两次评估不合格的； （四）违反法律法规或者违背社会公德，造成重大不良社会影响的； （五）自愿放弃或者其他应当取消国家级非物质文化遗产代表性传承人资格的情形。"},{"i":23,"n":"第二十三条","txt":"国家级非物质文化遗产代表性传承人去世的，省级文化和旅游主管部门可以采取适当方式表示哀悼，组织开展传承人传承事迹等宣传报道，并及时将相关情况报文化和旅游部。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市文化和旅游主管部门可以参照本办法，制定本行政区域内非物质文化遗产代表性传承人的认定与管理办法。 中央各部门直属单位国家级非物质文化遗产代表性传承人的管理参照本办法相关规定执行。"},{"i":25,"n":"第二十五条","txt":"本办法由文化和旅游部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2020年3月1日起施行。原文化部2008年5月14日发布的《国家级非物质文化遗产项目代表性传承人认定与管理暂行办法》同时废止。"}],"guojiajifeiwuzhiwenhuayichanbaohuyuguanlizanxingba054e22":[{"i":1,"n":"第一条","txt":"为有效保护和传承国家级非物质文化遗产，加强保护工作的管理，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称“国家级非物质文化遗产”是指列入国务院批准公布的国家级非物质文化遗产名录中的所有非物质文化遗产项目。"},{"i":3,"n":"第三条","txt":"国家级非物质文化遗产的保护，实行“保护为主、抢救第一、合理利用、传承发展”的方针，坚持真实性和整体性的保护原则。"},{"i":4,"n":"第四条","txt":"国务院文化行政部门负责组织、协调和监督全国范围内国家级非物质文化遗产的保护工作。 省级人民政府文化行政部门负责组织、协调和监督本行政区域内国家级非物质文化遗产的保护工作。 国家级非物质文化遗产项目所在地人民政府文化行政部门，负责组织、监督该项目的具体保护工作。"},{"i":5,"n":"第五条","txt":"国务院文化行政部门组织制定国家级非物质文化遗产保护整体规划，并定期对规划的实施情况进行检查。 省级人民政府文化行政部门组织制定本行政区域内国家级非物质文化遗产项目的保护规划，经国务院文化行政部门批准后组织实施，并于每年十一月底前向国务院文化行政部门提交保护规划本年度实施情况和下一年度保护工作计划。"},{"i":6,"n":"第六条","txt":"国家级非物质文化遗产项目应当确定保护单位，具体承担该项目的保护与传承工作。保护单位的推荐名单由该项目的申报地区或者单位提出，经省级文化行政部门组织专家审议后，报国务院文化行政部门认定。"},{"i":7,"n":"第七条","txt":"国家级非物质文化遗产项目保护单位应具备以下基本条件： （一）有该项目代表性传承人或者相对完整的资料； （二）有实施该项目保护计划的能力； （三）有开展传承、展示活动的场所和条件。"},{"i":8,"n":"第八条","txt":"国家级非物质文化遗产项目保护单位应当履行以下职责： （一）全面收集该项目的实物、资料，并登记、整理、建档； （二）为该项目的传承及相关活动提供必要条件； （三）有效保护该项目相关的文化场所； （四）积极开展该项目的展示活动； （五）向负责该项目具体保护工作的当地人民政府文化行政部门报告项目保护实施情况，并接受监督。"},{"i":9,"n":"第九条","txt":"国务院文化行政部门统一制作国家级非物质文化遗产项目标牌，由省级人民政府文化行政部门交该项目保护单位悬挂和保存。"},{"i":10,"n":"第十条","txt":"国务院文化行政部门对国家级非物质文化遗产项目保护给予必要的经费资助。 县级以上人民政府文化行政部门应当积极争取当地政府的财政支持，对在本行政区域内的国家级非物质文化遗产项目的保护给予资助。"},{"i":11,"n":"第十一条","txt":"国家级非物质文化遗产项目保护单位根据自愿原则，提出该项目代表性传承人的推荐名单，经省级人民政府文化行政部门组织专家评议后，报国务院文化行政部门批准。"},{"i":12,"n":"第十二条","txt":"国家级非物质文化遗产项目代表性传承人应当符合以下条件： （一）完整掌握该项目或者其特殊技能； （二）具有该项目公认的代表性、权威性与影响力； （三）积极开展传承活动，培养后继人才。"},{"i":13,"n":"第十三条","txt":"国家级非物质文化遗产项目代表性传承人应当履行传承义务；丧失传承能力、无法履行传承义务的，应当按照程序另行认定该项目代表性传承人；怠于履行传承义务的，取消其代表性传承人的资格。"},{"i":14,"n":"第十四条","txt":"国务院文化行政部门组织建立国家级非物质文化遗产数据库。有条件的地方，应建立国家级非物质文化遗产博物馆或者展示场所。"},{"i":15,"n":"第十五条","txt":"国务院文化行政部门组织制定国家级非物质文化遗产实物资料等级标准和出入境标准。其中经文物部门认定为文物的，适用文物保护法律法规的有关规定。"},{"i":16,"n":"第十六条","txt":"国家级非物质文化遗产项目保护单位和相关实物资料的保护机构应当建立健全规章制度，妥善保管实物资料，防止损毁和流失。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府文化行政部门应当鼓励、支持通过节日活动、展览、培训、教育、大众传媒等手段，宣传、普及国家级非物质文化遗产知识，促进其传承和社会共享。"},{"i":18,"n":"第十八条","txt":"省级人民政府文化行政部门应当对国家级非物质文化遗产项目所依存的文化场所划定保护范围，制作标识说明，进行整体性保护，并报国务院文化行政部门备案。"},{"i":19,"n":"第十九条","txt":"省级人民政府文化行政部门可以选择本行政区域内的国家级非物质文化遗产项目，为申报联合国教科文组织“人类非物质文化遗产代表作”，向国务院文化行政部门提出申请。"},{"i":20,"n":"第二十条","txt":"国家级非物质文化遗产项目的名称和保护单位不得擅自变更；未经国务院文化行政部门批准，不得对国家级非物质文化遗产项目标牌进行复制或者转让。 国家级非物质文化遗产项目的域名和商标注册和保护，依据相关法律法规执行。"},{"i":21,"n":"第二十一条","txt":"利用国家级非物质文化遗产项目进行艺术创作、产品开发、旅游活动等，应当尊重其原真形式和文化内涵，防止歪曲与滥用。"},{"i":22,"n":"第二十二条","txt":"国家级非物质文化遗产项目含有国家秘密的，应当按照国家保密法律法规的规定确定密级，予以保护；含有商业秘密的，按照国家有关法律法规执行。"},{"i":23,"n":"第二十三条","txt":"各级人民政府文化行政部门应当鼓励和支持企事业单位、社会团体和个人捐赠国家级非物质文化遗产实物资料或者捐赠资金和实物用于国家级非物质文化遗产保护。"},{"i":24,"n":"第二十四条","txt":"国务院文化行政部门对在国家级非物质文化遗产保护工作中有突出贡献的单位和个人，给予表彰奖励。"},{"i":25,"n":"第二十五条","txt":"国务院文化行政部门定期组织对国家级非物质文化遗产项目保护情况的检查。 国家级非物质文化遗产项目保护单位有下列行为之一的，由县级以上人民政府文化行政部门责令改正，并视情节轻重予以警告、严重警告，直至解除其保护单位资格： （一）擅自复制或者转让标牌的； （二）侵占国家级非物质文化遗产珍贵实物资料的； （三）怠于履行保护职责的。"},{"i":26,"n":"第二十六条","txt":"有下列行为之一的，对负有责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）擅自变更国家级非物质文化遗产项目名称或者保护单位的； （二）玩忽职守，致使国家级非物质文化遗产所依存的文化场所及其环境造成破坏的； （三）贪污、挪用国家级非物质文化遗产项目保护经费的。"},{"i":27,"n":"第二十七条","txt":"本办法由国务院文化行政部门负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自2006年12月1日起施行。"}],"zaixianlvyoujingyingfuwuguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为保障旅游者合法权益，规范在线旅游市场秩序，促进在线旅游行业可持续发展，依据《中华人民共和国旅游法》《中华人民共和国消费者权益保护法》《中华人民共和国网络安全法》《中华人民共和国电子商务法》《旅行社条例》等相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供在线旅游经营服务，适用本规定。 本规定所称在线旅游经营服务，是指通过互联网等信息网络为旅游者提供包价旅游服务或者交通、住宿、餐饮、游览、娱乐等单项旅游服务的经营活动。"},{"i":3,"n":"第三条","txt":"本规定所称在线旅游经营者，是指从事在线旅游经营服务的自然人、法人和非法人组织，包括在线旅游平台经营者、平台内经营者以及通过自建网站、其他网络服务提供旅游服务的经营者。 本规定所称平台经营者，是指为在线旅游经营服务交易双方或者多方提供网络经营场所、交易撮合、信息发布等服务的法人或者非法人组织。 本规定所称平台内经营者，是指通过平台经营者提供旅游服务的在线旅游经营者。"},{"i":4,"n":"第四条","txt":"在线旅游经营者提供在线旅游经营服务，应当遵守社会主义核心价值观的要求，坚守人身财产安全、信息内容安全、网络安全等底线，诚信经营、公平竞争，承担产品和服务质量责任，接受政府和社会的监督。"},{"i":5,"n":"第五条","txt":"文化和旅游部按照职责依法负责全国在线旅游经营服务的指导、协调、监管工作。县级以上地方文化和旅游主管部门按照职责分工负责本辖区内在线旅游经营服务的监督管理工作。"},{"i":6,"n":"第六条","txt":"各级文化和旅游主管部门应当积极协调相关部门在财政、税收、金融、保险等方面支持在线旅游行业发展，保障在线旅游经营者公平参与市场竞争，充分发挥在线旅游经营者在旅游目的地推广、旅游公共服务体系建设、旅游大数据应用、景区门票预约和流量控制等方面的积极作用，推动旅游业高质量发展。"},{"i":7,"n":"第七条","txt":"在线旅游经营者应当依法建立旅游者安全保护制度，制定应急预案，结合有关政府部门发布的安全风险提示等信息进行风险监测和安全评估，及时排查安全隐患，做好旅游安全宣传与引导、风险提示与防范、应急救助与处置等工作。"},{"i":8,"n":"第八条","txt":"在线旅游经营者发现法律、行政法规禁止发布或者传输的信息，应当立即停止传输该信息，采取消除等处置措施防止信息扩散，保存有关记录并向主管部门报告。 平台经营者应当对上传至平台的文字、图片、音视频等信息内容加强审核，确保平台信息内容安全。"},{"i":9,"n":"第九条","txt":"在线旅游经营者应当按照《中华人民共和国网络安全法》等相关法律规定，贯彻网络安全等级保护制度，落实网络安全管理和技术措施，制定网络安全应急预案，并定期组织开展演练，确保在线旅游经营服务正常开展。"},{"i":10,"n":"第十条","txt":"在线旅游经营者经营旅行社业务的，应当依法取得旅行社业务经营许可。"},{"i":11,"n":"第十一条","txt":"平台经营者应当对平台内经营者的身份、地址、联系方式、行政许可、质量标准等级、信用等级等信息进行真实性核验、登记，建立登记档案，并定期核验更新。 平台经营者应当督促平台内经营者对其旅游辅助服务者的相关信息进行真实性核验、登记。"},{"i":12,"n":"第十二条","txt":"在线旅游经营者应当提供真实、准确的旅游服务信息，不得进行虚假宣传；未取得质量标准、信用等级的，不得使用相关称谓和标识。平台经营者应当以显著方式区分标记自营业务和平台内经营者开展的业务。 在线旅游经营者为旅游者提供交通、住宿、游览等预订服务的，应当建立公开、透明、可查询的预订渠道，促成相关预订服务依约履行。"},{"i":13,"n":"第十三条","txt":"在线旅游经营者应当保障旅游者的正当评价权，不得擅自屏蔽、删除旅游者对其产品和服务的评价，不得误导、引诱、替代或者强制旅游者做出评价，对旅游者做出的评价应当保存并向社会公开。在线旅游经营者删除法律、法规禁止发布或者传输的评价信息的，应当在后台记录和保存。"},{"i":14,"n":"第十四条","txt":"在线旅游经营者应当保护旅游者个人信息等数据安全，在收集旅游者信息时事先明示收集旅游者个人信息的目的、方式和范围，并经旅游者同意。 在线旅游经营者在签订包价旅游合同或者出境旅游产品代订合同时，应当提示旅游者提供紧急联络人信息。"},{"i":15,"n":"第十五条","txt":"在线旅游经营者不得滥用大数据分析等技术手段，基于旅游者消费记录、旅游偏好等设置不公平的交易条件，侵犯旅游者合法权益。"},{"i":16,"n":"第十六条","txt":"在线旅游经营者为旅游者提供包价旅游服务的，应当依法与旅游者签订合同，并在全国旅游监管服务平台填报合同有关信息。"},{"i":17,"n":"第十七条","txt":"经营旅行社业务的在线旅游经营者应当投保旅行社责任险。 在线旅游经营者应当提示旅游者投保人身意外伤害保险。销售出境旅游产品时，应当为有购买境外旅游目的地保险需求的旅游者提供必要协助。"},{"i":18,"n":"第十八条","txt":"在线旅游经营者应当协助文化和旅游主管部门对不合理低价游进行管理，不得为其提供交易机会。"},{"i":19,"n":"第十九条","txt":"平台经营者应当对平台内经营者服务情况、旅游合同履行情况以及投诉处理情况等产品和服务信息、交易信息依法进行记录、保存，进行动态管理。"},{"i":20,"n":"第二十条","txt":"社交网络平台、移动应用商店等信息网络提供者知道或者应当知道他人利用其服务从事违法违规在线旅游经营服务，或者侵害旅游者合法权益的，应当采取删除、屏蔽、断开链接等必要措施。"},{"i":21,"n":"第二十一条","txt":"平台经营者应当在首页显著位置公示全国旅游投诉渠道。 平台内经营者与旅游者发生旅游纠纷的，平台经营者应当积极协助旅游者维护合法权益。鼓励平台经营者先行赔付。"},{"i":22,"n":"第二十二条","txt":"平台经营者发现以下情况，应当立即采取必要的救助和处置措施，并依法及时向县级以上文化和旅游主管部门报告： （一）提供的旅游产品或者服务存在缺陷，危及旅游者人身、财产安全的； （二）经营服务过程中发生突发事件或者旅游安全事故的； （三）平台内经营者未经许可经营旅行社业务的; （四）出现法律、法规禁止交易的产品或者服务的； （五）其他应当报告的事项。"},{"i":23,"n":"第二十三条","txt":"各级文化和旅游主管部门应当建立日常检查、定期检查以及与相关部门联合检查的监督管理制度，依法对在线旅游经营服务实施监督检查，查处违法违规行为。 在监督检查过程中，县级以上文化和旅游主管部门要求在线旅游经营者提供相关数据信息的，在线旅游经营者应当予以配合。县级以上文化和旅游主管部门应当采取必要措施保护数据信息的安全。"},{"i":24,"n":"第二十四条","txt":"县级以上文化和旅游主管部门对有不诚信经营、侵害旅游者评价权、滥用技术手段设置不公平交易条件等违法违规经营行为的在线旅游经营者，可以通过约谈等行政指导方式予以提醒、警示、制止，并责令其限期整改。"},{"i":25,"n":"第二十五条","txt":"在线旅游经营服务违法行为由实施违法行为的经营者住所地县级以上文化和旅游主管部门管辖。不能确定经营者住所地的，由经营者注册登记地或者备案地、旅游合同履行地县级以上文化和旅游主管部门管辖。 受理在线旅游经营服务相关投诉，参照前款处理。"},{"i":26,"n":"第二十六条","txt":"县级以上文化和旅游主管部门依法建立在线旅游行业信用档案，将在线旅游经营者市场主体登记、行政许可、抽查检查、列入经营异常名录或者严重违法失信企业名单、行政处罚等信息依法列入信用记录，适时通过全国旅游监管服务平台或者本部门官方网站公示，并与相关部门建立信用档案信息共享机制，依法对严重违法失信者实施联合惩戒措施。"},{"i":27,"n":"第二十七条","txt":"支持在线旅游经营者成立行业组织，并按照本组织章程依法制定行业经营规范和服务标准，加强行业自律，推动行业诚信建设和服务质量评价，监督、引导本行业经营者公平参与市场竞争。"},{"i":28,"n":"第二十八条","txt":"平台经营者知道或者应当知道平台内经营者不符合保障旅游者人身、财产安全要求或者有其他侵害旅游者合法权益行为，未及时采取必要措施的，依法与该平台内经营者承担连带责任。 平台经营者未对平台内经营者资质进行审核，或者未对旅游者尽到安全提示或保障义务，造成旅游者合法权益损害的，依法承担相应责任。"},{"i":29,"n":"第二十九条","txt":"旅游者有下列情形之一的，依法承担相关责任： （一）在旅游活动中从事违法违规活动的； （二）未按要求提供与旅游活动相关的个人健康信息的； （三）不听从在线旅游经营者的告知、警示，参加不适合自身条件的旅游活动，导致出现人身财产损害的； （四）对国家应对重大突发事件暂时限制旅游活动的措施、安全防范和应急处置措施不予配合的。"},{"i":30,"n":"第三十条","txt":"因不可抗力或者第三人造成旅游者损害的，在线旅游经营者应当及时进行救助。在线旅游经营者未及时进行救助造成旅游者损害的，依法承担相应责任。旅游者接受救助后，依法支付应当由个人承担的费用。"},{"i":31,"n":"第三十一条","txt":"在线旅游经营者违反本规定第八条第一款规定，由县级以上文化和旅游主管部门依照《中华人民共和国网络安全法》第六十八条有关规定处理。"},{"i":32,"n":"第三十二条","txt":"在线旅游经营者违反本规定第十条规定，未依法取得旅行社业务经营许可开展相关业务的，由县级以上文化和旅游主管部门依照《中华人民共和国旅游法》第九十五条的规定处理。 在线旅游经营者违反本规定第十七条第一款规定，未依法投保旅行社责任保险的，由县级以上文化和旅游主管部门依照《中华人民共和国旅游法》第九十七条有关规定处理。"},{"i":33,"n":"第三十三条","txt":"平台经营者有下列情形之一的，由县级以上文化和旅游主管部门依照《中华人民共和国电子商务法》第八十条的规定处理： （一）违反本规定第十一条第一款规定，不依法履行核验、登记义务的； （二）违反本规定第二十二条规定，不依法对违法情形采取必要处置措施或者未报告的； （三）违反本规定第十九条规定，不依法履行商品和服务信息、交易信息保存义务的。"},{"i":34,"n":"第三十四条","txt":"在线旅游经营者违反本规定第十二条第一款有关规定，未取得质量标准、信用等级使用相关称谓和标识的，由县级以上文化和旅游主管部门责令改正，给予警告，可并处三万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"违反本规定第十六条规定，未在全国旅游监管服务平台填报包价旅游合同有关信息的，由县级以上文化和旅游主管部门责令改正，给予警告；拒不改正的，处一万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"在线旅游经营者违反本规定第十八条规定，为以不合理低价组织的旅游活动提供交易机会的，由县级以上文化和旅游主管部门责令改正，给予警告，可并处三万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"法律、行政法规对违反本规定行为另有规定的，依照其规定。县级以上地方文化和旅游主管部门在监督检查过程中发现在线旅游经营者有违反《中华人民共和国电子商务法》《中华人民共和国消费者权益保护法》《中华人民共和国网络安全法》等法律、行政法规、部门规章的行为，不属于本部门管辖的，应当及时将相关线索依法移送有关部门。"},{"i":38,"n":"第三十八条","txt":"本规定自2020年10月1日起施行。"}],"dayunheyichanbaohuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对大运河遗产的保护，规范大运河遗产的利用行为，促进大运河沿线经济社会全面协调可持续发展，根据《中华人民共和国文物保护法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称大运河遗产，包括隋唐运河、京杭大运河、浙东运河的水工遗存，各类伴生历史遗存、历史街区村镇，以及相关联的环境景观等。 近代以来兴建的大运河水工设施，凡具有文化代表性和突出价值的，属于本办法所称的大运河遗产。"},{"i":3,"n":"第三条","txt":"大运河遗产保护实行统一规划、分级负责、分段管理，坚持真实性、完整性、延续性原则，依照国家有关法律、行政法规和本办法的规定执行。"},{"i":4,"n":"第四条","txt":"国家设立的大运河保护和申遗省部际会商小组，协调大运河遗产保护中的重大事项，会商解决重大问题。 国务院文物主管部门主管大运河遗产的整体保护工作，并与国务院国土、环保、交通、水利等主管部门合作，依法在各自的职责范围内开展相关工作。 大运河沿线县级以上地方人民政府文物主管部门，负责本行政区域内的大运河遗产保护工作，依法与其他相关主管部门合作开展工作，并将大运河遗产保护经费纳入本级财政预算。"},{"i":5,"n":"第五条","txt":"国家鼓励公民、法人和其他组织参与大运河遗产保护。 公民、法人和其他组织可以通过捐赠等方式设立大运河遗产保护基金，用于大运河遗产保护。大运河遗产保护基金的募集、使用和管理，依照国家有关法律、行政法规的规定执行。 国务院文物主管部门、大运河沿线县级以上地方人民政府文物主管部门，应当对在大运河遗产保护中作出突出贡献的组织或者个人给予奖励。"},{"i":6,"n":"第六条","txt":"大运河沿线省级人民政府文物主管部门应当组织调查本行政区域内的大运河遗产。 属于大运河遗产的不可移动文物，县级以上地方文物主管部门应当依法予以认定，并报同级人民政府核定公布为文物保护单位。大运河遗产中具有重大历史、艺术、科学价值的不可移动文物，应当确定为全国重点文物保护单位，报国务院核定公布。"},{"i":7,"n":"第七条","txt":"国家实行大运河遗产保护规划制度。大运河遗产保护规划由总体规划、省级规划和市级规划构成。 大运河遗产保护总体规划，由国务院文物主管部门会同国务院有关部门制订，经大运河保护和申遗省部际会商小组审定后报国务院批准公布。大运河遗产保护总体规划应当与国家水利、航运、环境等规划相协调。 大运河遗产保护省级规划和市级规划，分别由省级和市级文物主管部门会同同级有关部门制订，报省级和市级人民政府批准公布，并报上级文物主管部门备案。"},{"i":8,"n":"第八条","txt":"大运河遗产保护规划应当明确大运河遗产的构成、保护标准和保护重点，分类制定保护措施。 在大运河遗产保护规划划定的保护范围和建设控制地带内进行工程建设，应当遵守《中华人民共和国文物保护法》的有关规定，并实行建设项目遗产影响评价制度。建设项目遗产影响评价制度，由国务院文物主管部门制定。 除防洪、航道疏浚、水工设施维护、输水河道工程外，任何单位或者个人不得在大运河遗产保护规划划定的保护范围内进行破坏大运河遗产本体的工程建设。"},{"i":9,"n":"第九条","txt":"大运河沿线县级以上地方人民政府文物主管部门，应当建立大运河遗产所在地标识系统，并向公众提供真实、完整的大运河遗产信息。"},{"i":10,"n":"第十条","txt":"将大运河遗产所在地辟为参观游览区，必须保障公众和大运河遗产的安全。 在参观游览区内设置服务项目，必须符合大运河遗产保护规划的要求。 大运河遗产参观游览区保护、展示、利用功能突出，示范意义显著的，可以公布为大运河遗产公园。"},{"i":11,"n":"第十一条","txt":"大运河遗产跨行政区域边界的，其毗邻的县级以上地方人民政府文物主管部门应当定期召开协调会议，研究解决大运河遗产保护中的重大问题。"},{"i":12,"n":"第十二条","txt":"国家实行大运河遗产监测巡视制度，由国务院文物主管部门组织实施，定期发布监测巡视报告。 大运河遗产监测由国家、省级和市级监测系统构成，包括日常监测、定期监测和反应性监测；大运河遗产巡视由国家和省级巡视系统构成，包括定期巡视和不定期巡视。"},{"i":13,"n":"第十三条","txt":"因保护和管理不善，致使真实性、完整性和延续性受到损害的大运河遗产，由国务院文物主管部门列入《大运河遗产保护警示名单》予以公布。 列入《大运河遗产保护警示名单》的遗产所在地保护机构，必须对保护和管理工作中存在的问题制订并公布整改措施，限期改进保护管理工作。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，造成大运河遗产损害，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由主管机关依法给予处罚。 有关行政机关不履行法定职责的，由上级行政机关责令改正，通报批评；对负有责任的主管人员和其他直接责任人员，由主管机关依法处理。"},{"i":15,"n":"第十五条","txt":"本办法自2012年10月1日起施行。"}],"dalujuminfutaiwandiqulvyouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范大陆居民赴台湾地区旅游，根据《旅游法》、《旅行社条例》和《中国公民往来台湾地区管理办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"大陆居民赴台湾地区旅游（以下简称赴台旅游），可采取团队旅游或者个人旅游两种形式。 大陆居民赴台团队旅游应当由指定经营大陆居民赴台旅游业务的旅行社（以下简称组团社）组织，以团队形式整团往返。旅游团成员在台湾期间应当集体活动。 大陆居民赴台个人旅游可自行前往台湾地区，在台湾期间可自行活动。"},{"i":3,"n":"第三条","txt":"组团社由国家旅游局会同有关部门，从取得出境旅游业务经营许可并提出经营赴台旅游业务申请的旅行社范围内指定，但国家另有规定的除外。组团社名单由海峡两岸旅游交流协会公布。 除被指定的组团社外，任何单位和个人不得经营大陆居民赴台旅游业务。"},{"i":4,"n":"第四条","txt":"台湾地区接待大陆居民赴台旅游的旅行社（以下简称地接社），经大陆有关部门会同国家旅游局确认后，由海峡两岸旅游交流协会公布。"},{"i":5,"n":"第五条","txt":"大陆居民赴台团队旅游实行配额管理。配额由国家旅游局会同有关部门确认后下达给组团社。"},{"i":6,"n":"第六条","txt":"组团社在开展组织大陆居民赴台旅游业务前，应当与地接社签订合同、建立合作关系。 大陆居民赴台旅游团队出发前，组团社应当向国家旅游局旅游团队管理和服务信息平台提供符合规定的赴台旅游团队信息。旅游团队信息实行一团一登记。"},{"i":7,"n":"第七条","txt":"组团社应当为每个团队委派领队,并要求地接社派导游全程陪同。 赴台旅游领队应当具备法律、法规规定的领队条件，经省级旅游主管部门培训，由国家旅游局指定。"},{"i":8,"n":"第八条","txt":"大陆居民赴台旅游期间，不得从事或者参与涉及赌博、色情、毒品等内容及有损两岸关系的活动。 组团社不得组织旅游团成员参与前款活动，并应当要求地接社不得引导或者组织旅游团成员参与前款活动。"},{"i":9,"n":"第九条","txt":"组团社应当要求地接社严格按照合同规定的团队日程安排活动；未经双方旅行社及旅游团成员同意，不得变更日程。"},{"i":10,"n":"第十条","txt":"大陆居民赴台旅游应当持有效的《大陆居民往来台湾通行证》，并根据其采取的旅游形式，办理团队旅游签注或者个人旅游签注。"},{"i":11,"n":"第十一条","txt":"大陆居民赴台旅游应当按照有关规定向公安机关出入境管理部门申请办理《大陆居民往来台湾通行证》及相应签注。"},{"i":12,"n":"第十二条","txt":"赴台旅游团队应当凭《大陆居民赴台湾地区旅游团队名单表》，从大陆对外开放口岸整团出入境。"},{"i":13,"n":"第十三条","txt":"旅游团出境前已确定分团入境大陆的，组团社应当事先向有关出入境边防检查总站或者省级公安边防部门备案。 旅游团成员因紧急情况不能随团入境大陆或者不能按期返回大陆的，组团社应当及时向有关出入境边防检查总站或者省级公安边防部门报告。"},{"i":14,"n":"第十四条","txt":"赴台旅游的大陆居民应当按期返回，不得非法滞留。当发生旅游团成员非法滞留时，组团社应当及时向公安机关及旅游主管部门报告，并协助做好有关滞留者的遣返和审查工作。"},{"i":15,"n":"第十五条","txt":"对在台湾地区非法滞留情节严重者，公安机关出入境管理部门自其被遣返回大陆之日起，六个月至三年以内不批准其再次出境。"},{"i":16,"n":"第十六条","txt":"违反本办法规定，未被指定经营大陆居民赴台旅游业务，或者旅行社及从业人员有违反本办法规定行为的，由旅游主管部门根据《旅游法》和《旅行社条例》等规定予以处罚。有关单位和个人违反其他法律、法规规定的，由有关部门依法予以处理。"},{"i":17,"n":"第十七条","txt":"本办法由国家旅游局、公安部、国务院台湾事务办公室负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。 附：1. 国家旅游局　公安部　国务院台湾事务办公室关于修改《大陆居民赴台湾地区旅游管理办法》的决定（令第37号） 国家旅游局、公安部和国务院台湾事务办公室决定对《大陆居民赴台湾地区旅游管理办法》作如下修改： 一、将第一条、第十五条中的“《旅行社管理条例》”修改为“《旅行社条例》”。 二、将第二条修改为：“大陆居民赴台湾地区旅游（以下简称赴台旅游），可采取团队旅游或个人旅游两种形式。” “大陆居民赴台团队旅游须由指定经营大陆居民赴台旅游业务的旅行社（以下简称组团社）组织，以团队形式整团往返。旅游团成员在台湾期间须集体活动。” “大陆居民赴台个人旅游可自行前往台湾地区，在台湾期间可自行活动。” 三、将第五条中的“赴台旅游”修改为“赴台团队旅游”。 四、将第八条修改为：“大陆居民赴台旅游期间，不得从事或参与涉及赌博、色情、毒品等内容及有损两岸关系的活动。” “组团社"}],"yulechangsuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强娱乐场所经营活动管理，维护娱乐场所健康发展，满足人民群众文化娱乐消费需求，根据《娱乐场所管理条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"《条例》所称娱乐场所，是指以营利为目的，向公众开放、消费者自娱自乐的歌舞、游艺等场所。歌舞娱乐场所是指提供伴奏音乐、歌曲点播服务或者提供舞蹈音乐、跳舞场地服务的经营场所；游艺娱乐场所是指通过游戏游艺设备提供游戏游艺服务的经营场所。 其他场所兼营以上娱乐服务的，适用本办法。"},{"i":3,"n":"第三条","txt":"国家鼓励娱乐场所传播民族优秀文化艺术，提供面向大众的、健康有益的文化娱乐内容和服务；鼓励娱乐场所实行连锁化、品牌化经营。"},{"i":4,"n":"第四条","txt":"县级以上人民政府文化主管部门负责所在地娱乐场所经营活动的监管，负责娱乐场所提供的文化产品的内容监管，负责指导所在地娱乐场所行业协会工作。"},{"i":5,"n":"第五条","txt":"娱乐场所行业协会应当依照国家有关法规和协会章程的规定，制定行业规范，加强行业自律，维护行业合法权益。"},{"i":6,"n":"第六条","txt":"娱乐场所不得设立在下列地点： （一）房屋用途中含有住宅的建筑内； （二）博物馆、图书馆和被核定为文物保护单位的建筑物内； （三）居民住宅区； （四）教育法规定的中小学校周围； （五）依照《医疗机构管理条例》及实施细则规定取得《医疗机构执业许可证》的医院周围； （六）各级中国共产党委员会及其所属各工作部门、各级人民代表大会机关、各级人民政府及其所属各工作部门、各级政治协商会议机关、各级人民法院、检察院机关、各级民主党派机关周围； （七）车站、机场等人群密集的场所； （八）建筑物地下一层以下（不含地下一层）； （九）与危险化学品仓库毗连的区域，与危险化学品仓库的距离必须符合《危险化学品安全管理条例》的有关规定。 娱乐场所与学校、医院、机关距离及其测量方法由省级人民政府文化主管部门规定。"},{"i":7,"n":"第七条","txt":"依法登记的娱乐场所申请从事娱乐场所经营活动，应当符合以下条件： （一）有与其经营活动相适应的设施设备，提供的文化产品内容应当符合文化产品生产、出版、进口的规定； （二）符合国家治安管理、消防安全、环境噪声等相关规定； （三）法律、法规和规章规定的其他条件。"},{"i":8,"n":"第八条","txt":"省级人民政府文化主管部门可以结合本地区实际，制定本行政区域内娱乐场所使用面积和消费者人均占有使用面积的最低标准。"},{"i":9,"n":"第九条","txt":"依法登记的娱乐场所申请从事娱乐场所经营活动，应当向所在地县级人民政府文化主管部门提出申请；依法登记的中外合资经营、中外合作经营娱乐场所申请从事娱乐场所经营活动，应当向所在地省级人民政府文化主管部门提出申请，省级人民政府文化主管部门可以委托所在地县级以上文化主管部门进行实地检查。"},{"i":10,"n":"第十条","txt":"依法登记的娱乐场所申请从事娱乐场所经营活动前，可以向负责审批的文化主管部门提交咨询申请，文化主管部门应当提供行政指导。"},{"i":11,"n":"第十一条","txt":"依法登记的娱乐场所申请从事娱乐场所经营活动，应当提交以下文件： （一）申请书； （二）营业执照； （三）投资人、法定代表人、主要负责人的身份证明以及无《条例》第四条、第五条、第五十三条规定情况的书面声明； （四）房产权属证书，租赁场地经营的，还应当提交租赁合同或者租赁意向书； （五）经营场所地理位置图和场所内部结构平面图； （六）消防、环境保护部门的批准文件或者备案证明。 依法登记的中外合资、中外合作经营娱乐场所申请从事娱乐场所经营活动，还应当提交商务主管部门的批准文件。"},{"i":12,"n":"第十二条","txt":"文化主管部门受理申请后，应当对设立场所的位置、周边环境、面积等进行实地检查。符合条件的，应当在设立场所、文化主管部门办公场所显著位置向社会公示10日，并依法组织听证。"},{"i":13,"n":"第十三条","txt":"文化主管部门应当对歌舞娱乐场所使用的歌曲点播系统和游艺娱乐场所使用的游戏游艺设备进行内容核查。"},{"i":14,"n":"第十四条","txt":"文化主管部门应当根据听证和文化产品内容核查结果作出行政许可决定。予以批准的，核发娱乐经营许可证；不予批准的，应当书面告知申请人并说明理由。"},{"i":15,"n":"第十五条","txt":"娱乐场所改建、扩建营业场所或者变更场地的，变更投资人员、投资比例以及娱乐经营许可证载明事项的，应当向原发证机关申请重新核发娱乐经营许可证。"},{"i":16,"n":"第十六条","txt":"歌舞娱乐场所新增、变更歌曲点播系统，游艺娱乐场所新增、变更游戏游艺设备的，应当符合本办法第七条第（一）项规定。"},{"i":17,"n":"第十七条","txt":"娱乐经营许可证有效期2年。娱乐经营许可证有效期届满30日前，娱乐场所经营者应当持许可证、工商营业执照副本以及营业情况报告到原发证机关申请换发许可证。原发证机关应当在有效期届满前做出是否准予延续的决定，逾期未做决定的，视为准予延续。"},{"i":18,"n":"第十八条","txt":"娱乐经营许可证有效期届满未延续的，由原发证机关向社会公告注销娱乐经营许可证，并函告公安机关、工商行政管理部门。"},{"i":19,"n":"第十九条","txt":"娱乐场所法定代表人或者主要负责人是维护本场所经营秩序的第一责任人。"},{"i":20,"n":"第二十条","txt":"歌舞娱乐场所经营应当符合以下规定： （一）播放、表演的节目不得含有《条例》第十三条禁止内容； （二）不得将场所使用的歌曲点播系统连接至境外曲库。"},{"i":21,"n":"第二十一条","txt":"游艺娱乐场所经营应当符合以下规定： （一）不得设置未经文化主管部门内容核查的游戏游艺设备； （二）进行有奖经营活动的，奖品目录应当报所在地县级文化主管部门备案； （三）除国家法定节假日外，设置的电子游戏机不得向未成年人提供。"},{"i":22,"n":"第二十二条","txt":"娱乐场所不得为未经文化主管部门批准的营业性演出活动提供场地。 娱乐场所招用外国人从事演出活动的，应当符合《营业性演出管理条例》及《营业性演出管理条例实施细则》的规定。"},{"i":23,"n":"第二十三条","txt":"娱乐场所应当建立文化产品内容自审和巡查制度，确定专人负责管理在场所内提供的文化产品和服务。巡查情况应当记入营业日志。 消费者利用娱乐场所从事违法违规活动的，娱乐场所应当制止，制止无效的应当及时报告文化主管部门或者公安机关。"},{"i":24,"n":"第二十四条","txt":"娱乐场所应当在显著位置悬挂娱乐经营许可证、未成年人禁入或者限入标志，标志应当注明“12318”文化市场举报电话。"},{"i":25,"n":"第二十五条","txt":"娱乐场所应当配合文化主管部门的日常检查和技术监管措施。"},{"i":26,"n":"第二十六条","txt":"文化主管部门应当建立娱乐场所信用管理档案，记录被文化主管部门、公安机关、工商行政管理部门实施处罚的情况以及娱乐场所法定代表人、主要负责人、投资人等信息。"},{"i":27,"n":"第二十七条","txt":"文化主管部门应当定期组织文化主管部门工作人员、娱乐场所第一责任人和内容管理专职人员进行政策法规培训。"},{"i":28,"n":"第二十八条","txt":"违反《条例》规定，擅自从事娱乐场所经营活动的，由县级以上人民政府文化主管部门责令停止经营活动，依照《条例》第四十一条予以处罚；拒不停止经营活动的，依法列入文化市场黑名单，予以信用惩戒。"},{"i":29,"n":"第二十九条","txt":"歌舞娱乐场所违反本办法第二十条规定的，由县级以上人民政府文化主管部门依照《条例》第四十八条予以处罚。"},{"i":30,"n":"第三十条","txt":"游艺娱乐场所违反本办法第二十一条第（一）项、第（二）项规定的，由县级以上人民政府文化主管部门责令改正，并处5000元以上1万元以下的罚款；违反本办法第二十一条第（三）项规定的，由县级以上人民政府文化主管部门依照《条例》第四十八条予以处罚。"},{"i":31,"n":"第三十一条","txt":"娱乐场所违反本办法第二十二条第一款规定的，由县级以上人民政府文化主管部门责令改正，并处5000元以上1万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"娱乐场所违反本办法第二十三条规定对违法违规行为未及时采取措施制止并依法报告的，由县级以上人民政府文化主管部门依照《条例》第五十条予以处罚。"},{"i":33,"n":"第三十三条","txt":"娱乐场所违反本办法第二十四条规定的，由县级以上人民政府文化主管部门责令改正，予以警告。"},{"i":34,"n":"第三十四条","txt":"娱乐场所违反本办法第二十五条规定的，由县级以上人民政府文化主管部门予以警告，并处5000元以上1万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"本办法自2013年3月11日起施行。"}],"daoyourenyuandengjikaohepingdingguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强导游队伍建设，不断提高导游人员的业务素质，根据《导游人员管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"导游人员等级考核评定工作，遵循自愿申报、逐级晋升、动态管理的原则。"},{"i":3,"n":"第三条","txt":"凡通过全国导游人员资格考试并取得导游员资格证书，符合全国导游人员等级考核评定委员会规定报考条件的导游人员，均可申请参加相应的等级考核评定。"},{"i":4,"n":"第四条","txt":"国家旅游局负责导游人员等级考核评定标准、实施细则的制定工作，负责对导游人员等级考核评定工作进行监督检查。"},{"i":5,"n":"第五条","txt":"国家旅游局组织设立全国导游人员等级考核评定委员会。"},{"i":6,"n":"第六条","txt":"全国导游人员等级考核评定委员会组织实施全国导游人员等级考核评定工作。省、自治区、直辖市和新疆生产建设兵团旅游行政管理部门组织设立导游人员等级考核证实办公室，在全国导游人员等级考核评定委员会的授权和指导下开展相应的工作。"},{"i":7,"n":"第七条","txt":"导游人员等级分为初级、中级、高级、特级四个等级。导游员申报等级时，由低到高，逐级递升，经考核评定合格者，颁发相应的导游员等级证书。"},{"i":8,"n":"第八条","txt":"导游人员等级考核评定工作，按照“申请、受理、考核评定、告知、发证”的程序进行。 中级导游员的考核采取笔试方式。其中，中文导游人员考试科目为“导游知识专题”和“汉语言文学知识”；外语导游人员考试科目为“导游知识专题”和“外语”。高级导游员的考核采取笔试方式，考试科目为“导游案例分析”和“导游词创作”。特级导游员的考核采取论文答辩方式。"},{"i":9,"n":"第九条","txt":"参加省部级以上单位组织的导游技能大赛获得最佳名次的导游人员，报全国导游人员等级考核评定委员会批准后，可晋升一级导游人员等级。一人多次获奖只能晋升一次，晋升的最高等级为高级。"},{"i":10,"n":"第十条","txt":"旅行社和导游管理服务机构应当采取有效措施，鼓励导游人员积极参加导游人员等级考核评定。"},{"i":11,"n":"第十一条","txt":"参与导游人员等级考核评定的命题和考核员必须是经全国导游人员等级考核评定委员会进行资格认定。命题员和考核员接受全国导游人员等级考核评定委员会的委派，承担导游人员等级考核评定相关工作。"},{"i":12,"n":"第十二条","txt":"参与考核评定的命题员和考核员不得徇私舞弊。全国导游人员等级考核评定委员会要加强对考核人员的监督管理，对有违规行为的要从严处理，撤销其资格。"},{"i":13,"n":"第十三条","txt":"导游员等级证书由全国导游人员等级考核评定委员会统一印制。"},{"i":14,"n":"第十四条","txt":"导游人员获得导游员资格证书和中级、高级、特级导游员证书后，可通过省、自治区、直辖市和新疆生产建设兵团旅游行政管理部门申请办理相应等级的导游证。"},{"i":15,"n":"第十五条","txt":"导游人员等级考核评定的收费标准按照国家有关部门审批的标准执行。"},{"i":16,"n":"第十六条","txt":"本办法由国家旅游局负责解释。"},{"i":17,"n":"第十七条","txt":"本办法由2005年7月3日起施行。原有政策、规定与本办法不符的， 以本办法为准。"}],"daoyoudengjikaoheguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强导游队伍建设，提高导游综合素质和职业技能，促进导游服务水平提升，根据《中华人民共和国旅游法》《导游人员管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"导游等级的考核和管理适用本办法。"},{"i":3,"n":"第三条","txt":"全国实行统一的导游等级考核制度。导游等级分为初级、中级、高级、特级四个等级。"},{"i":4,"n":"第四条","txt":"申请参加导游等级考核的人员，应当践行社会主义核心价值观，具备良好的职业道德和职业操守，掌握从事导游职业所需的知识和能力。"},{"i":5,"n":"第五条","txt":"导游等级考核工作遵循自愿申报、逐级晋升、科学规范和动态管理的原则。"},{"i":6,"n":"第六条","txt":"国务院文化和旅游主管部门负责组织实施全国导游等级考核工作。 省级文化和旅游主管部门按照国务院文化和旅游主管部门统一要求，负责实施本行政区域内的导游等级考核具体工作。"},{"i":7,"n":"第七条","txt":"取得导游资格证书的人员，在依法申请取得导游证后，即获得初级导游等级。 中级、高级导游等级通过考核或者激励晋升的方式获得。 特级导游等级通过考核的方式获得。"},{"i":8,"n":"第八条","txt":"导游等级考核的形式包括笔试、面试、论文答辩等。 中级、高级导游等级考核，原则上采取笔试形式，每2年开展一次；特级导游等级考核，原则上采取论文答辩形式，每4年开展一次。根据需要，中级、高级导游等级考核可以增加面试形式，特级导游等级考核可以增加笔试形式。"},{"i":9,"n":"第九条","txt":"导游等级考核的科目和内容主要包括： （一）中级导游为导游专题知识和中国语言文学知识等； （二）高级导游为综合案例分析和导游词创作等； （三）特级导游为导游词创作和导游相关专业论文等。"},{"i":10,"n":"第十条","txt":"申请参加导游等级考核的人员，应当符合下列条件： （一）申请参加中级、高级导游等级考核的，应当具有大学专科以上学历，取得上一个导游等级满2年，2年内在全国旅游监管服务平台的带团记录不少于25次或者90天； （二）申请参加特级导游等级考核的，应当具有大学本科以上学历，取得高级导游等级满3年，3年内在全国旅游监管服务平台的带团记录不少于25次或者90天； （三）2年内未因侵害旅游者合法权益受到罚款以上处罚，未被认定为文化和旅游市场失信主体。"},{"i":11,"n":"第十一条","txt":"导游等级考核包括申请、资格审核、考试或者答辩考核、成绩发布等程序，具体要求由国务院文化和旅游主管部门发布。"},{"i":12,"n":"第十二条","txt":"初级、中级导游在获得下列表彰奖励2年内，可以通过激励晋升的方式申请晋升一个导游等级。多次获得或者同时获得多项表彰奖励的，只晋升一次导游等级： （一）国务院文化和旅游主管部门组织的全国导游大赛一、二、三等奖； （二）省级文化和旅游主管部门组织的省级导游大赛一等奖； （三）省级以上劳动模范、五一劳动奖章、青年岗位能手、三八红旗手、巾帼建功标兵； （四）国务院文化和旅游主管部门认定的其他符合激励晋升的情况。"},{"i":13,"n":"第十三条","txt":"获得第十二条第一项至第三项表彰奖励的导游，可以向省级文化和旅游主管部门申请晋升一个导游等级；省级文化和旅游主管部门作出晋升决定后，应当报国务院文化和旅游主管部门备案。符合第十二条第四项激励晋升情况的导游，可以向国务院文化和旅游主管部门提出晋升申请。"},{"i":14,"n":"第十四条","txt":"导游等级证书由国务院文化和旅游主管部门委托省级文化和旅游主管部门发放，其样式由国务院文化和旅游主管部门制定。"},{"i":15,"n":"第十五条","txt":"各级文化和旅游主管部门应当加强对导游等级考核工作的监督和管理，依法妥善处理导游等级考核相关投诉和举报。"},{"i":16,"n":"第十六条","txt":"申请参加导游等级考核的人员，对本人考核结果有异议的，可以自结果发布之日起5个工作日内，通过省级文化和旅游主管部门向国务院文化和旅游主管部门提出复核申请。 国务院文化和旅游主管部门应当依法进行复核，并通过省级文化和旅游主管部门将复核结果告知复核申请人。考核结果复核仅限于复核是否存在分数错登、错加，不再重新评阅申请人参加考核的内容，复核后的结果为最终结果。"},{"i":17,"n":"第十七条","txt":"导游有下列情形之一的，取消当次和下次考核资格，已经取得的成绩无效，相关违纪行为计入全国旅游监管服务平台导游个人信用信息记录： （一）在考核中提供虚假申请材料或者剽窃他人研究成果、论文等的； （二）代替他人或者让他人代替自己参加考核的； （三）在考核现场作弊、协助他人作弊、串通作弊或者参与有组织作弊的； （四）在考核现场不遵守考场纪律或者严重影响考场秩序的； （五）其他违纪违规行为。"},{"i":18,"n":"第十八条","txt":"导游被吊销、撤销导游证的，获得的导游等级自然取消。 导游激励晋升等级所依据的表彰奖励被取消的，获得的导游等级相应取消。"},{"i":19,"n":"第十九条","txt":"监考人员及其他相关工作人员在导游等级考核工作中存在违法违规行为的，有关文化和旅游主管部门应当立即停止其相关工作，并依法追究相应责任；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"国务院文化和旅游主管部门不断完善导游等级考核制度，激励导游提升等级；加强外语导游人才培养，外语导游晋升等级后，已取得的导游语种予以保留。"},{"i":21,"n":"第二十一条","txt":"鼓励县级以上地方文化和旅游主管部门推动将高级、特级导游纳入人才引进政策范围，在人才培养、行业培训、表彰奖励等工作中对中级以上导游给予支持。"},{"i":22,"n":"第二十二条","txt":"鼓励旅行社制定实施与导游等级相匹配的薪酬、绩效考核制度，激励导游提升导游等级。"},{"i":23,"n":"第二十三条","txt":"鼓励相关旅游行业组织制定激励措施，引导导游提升导游等级，提高服务水平。"},{"i":24,"n":"第二十四条","txt":"本办法由国务院文化和旅游主管部门负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2025年3月1日起施行。《导游人员等级考核评定管理办法（试行）》《导游奖励晋升和加分备案办理程序》同时废止。"}],"daoyouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范导游执业行为，提升导游服务质量，保障导游合法权益，促进导游行业健康发展，依据《中华人民共和国旅游法》《导游人员管理条例》和《旅行社条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"导游执业的许可、管理、保障与激励，适用本办法。"},{"i":3,"n":"第三条","txt":"国家对导游执业实行许可制度。从事导游执业活动的人员，应当取得导游人员资格证和导游证。 国家旅游局建立导游等级考核制度、导游服务星级评价制度和全国旅游监管服务信息系统，各级旅游主管部门运用标准化、信息化手段对导游实施动态监管和服务。"},{"i":4,"n":"第四条","txt":"旅游行业组织应当依法维护导游合法权益，促进导游职业发展，加强导游行业自律。 旅行社等用人单位应当加强对导游的管理和培训，保障导游合法权益，提升导游服务质量。 导游应当恪守职业道德，提升服务水平，自觉维护导游行业形象。"},{"i":5,"n":"第五条","txt":"支持和鼓励各类社会机构积极弘扬导游行业先进典型，优化导游执业环境，促进导游行业健康稳定发展。"},{"i":6,"n":"第六条","txt":"经导游人员资格考试合格的人员，方可取得导游人员资格证。 国家旅游局负责制定全国导游资格考试政策、标准，组织导游资格统一考试，以及对地方各级旅游主管部门导游资格考试实施工作进行监督管理。 省、自治区、直辖市旅游主管部门负责组织、实施本行政区域内导游资格考试具体工作。 全国导游资格考试管理的具体办法，由国家旅游局另行制定。"},{"i":7,"n":"第七条","txt":"取得导游人员资格证，并与旅行社订立劳动合同或者在旅游行业组织注册的人员，可以通过全国旅游监管服务信息系统向所在地旅游主管部门申请取得导游证。 导游证采用电子证件形式，由国家旅游局制定格式标准，由各级旅游主管部门通过全国旅游监管服务信息系统实施管理。电子导游证以电子数据形式保存于导游个人移动电话等移动终端设备中。"},{"i":8,"n":"第八条","txt":"在旅游行业组织注册并申请取得导游证的人员，应当向所在地旅游行业组织提交下列材料： （一）身份证； （二）导游人员资格证； （三）本人近期照片； （四）注册申请。 旅游行业组织在接受申请人取得导游证的注册时，不得收取注册费；旅游行业组织收取会员会费的，应当符合《社会团体登记条例》等法律法规的规定，不得以导游证注册费的名义收取会费。"},{"i":9,"n":"第九条","txt":"导游通过与旅行社订立劳动合同取得导游证的，劳动合同的期限应当在1个月以上。"},{"i":10,"n":"第十条","txt":"申请取得导游证，申请人应当通过全国旅游监管服务信息系统填写申请信息，并提交下列申请材料： （一）身份证的扫描件或者数码照片等电子版； （二）未患有传染性疾病的承诺； （三）无过失犯罪以外的犯罪记录的承诺； （四）与经常执业地区的旅行社订立劳动合同或者在经常执业地区的旅游行业组织注册的确认信息。 前款第（四）项规定的信息，旅行社或者旅游行业组织应当自申请人提交申请之日起5个工作日内确认。"},{"i":11,"n":"第十一条","txt":"所在地旅游主管部门对申请人提出的取得导游证的申请，应当依法出具受理或者不予受理的书面凭证。需补正相关材料的，应当自收到申请材料之日起5个工作日内一次性告知申请人需要补正的全部内容；逾期不告知的，收到材料之日起即为受理。 所在地旅游主管部门应当自受理申请之日起10个工作日内，作出准予核发或者不予核发导游证的决定。不予核发的，应当书面告知申请人理由。"},{"i":12,"n":"第十二条","txt":"具有下列情形的，不予核发导游证： （一）无民事行为能力或者限制民事行为能力的； （二）患有甲类、乙类以及其他可能危害旅游者人身健康安全的传染性疾病的； （三）受过刑事处罚的，过失犯罪的除外； （四）被吊销导游证之日起未逾3年的。"},{"i":13,"n":"第十三条","txt":"导游证的有效期为3年。导游需要在导游证有效期届满后继续执业的，应当在有效期限届满前3个月内，通过全国旅游监管服务信息系统向所在地旅游主管部门提出申请，并提交本办法第十条第（二）项至第（四）项规定的材料。 旅行社或者旅游行业组织应当自导游提交申请之日起3个工作日内确认信息。所在地旅游主管部门应当自旅行社或者旅游行业组织核实信息之日起5个工作日内予以审核，并对符合条件的导游变更导游证信息。"},{"i":14,"n":"第十四条","txt":"导游与旅行社订立的劳动合同解除、终止或者在旅游行业组织取消注册的，导游及旅行社或者旅游行业组织应当自解除、终止合同或者取消注册之日起5个工作日内，通过全国旅游监管服务信息系统将信息变更情况报告旅游主管部门。"},{"i":15,"n":"第十五条","txt":"导游应当自下列情形发生之日起10个工作日内，通过全国旅游监管服务信息系统提交相应材料，申请变更导游证信息： （一）姓名、身份证号、导游等级和语种等信息发生变化的； （二）与旅行社订立的劳动合同解除、终止或者在旅游行业组织取消注册后，在3个月内与其他旅行社订立劳动合同或者在其他旅游行业组织注册的； （三）经常执业地区发生变化的； （四）其他导游身份信息发生变化的。 旅行社或者旅游行业组织应当自收到申请之日起3个工作日内对信息变更情况进行核实。所在地旅游主管部门应当自旅行社或者旅游行业组织核实信息之日起5个工作日内予以审核确认。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，所在地旅游主管部门应当撤销导游证： （一）对不具备申请资格或者不符合法定条件的申请人核发导游证的； （二）申请人以欺骗、贿赂等不正当手段取得导游证的； （三）依法可以撤销导游证的其他情形。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，所在地旅游主管部门应当注销导游证： （一）导游死亡的； （二）导游证有效期届满未申请换发导游证的； （三）导游证依法被撤销、吊销的； （四）导游与旅行社订立的劳动合同解除、终止或者在旅游行业组织取消注册后，超过3个月未与其他旅行社订立劳动合同或者未在其他旅游行业组织注册的； （五）取得导游证后出现本办法第十二条第（一）项至第（三）项情形的； （六）依法应当注销导游证的其他情形。 导游证被注销后，导游符合法定执业条件需要继续执业的，应当依法重新申请取得导游证。"},{"i":18,"n":"第十八条","txt":"导游的经常执业地区应当与其订立劳动合同的旅行社（含旅行社分社）或者注册的旅游行业组织所在地的省级行政区域一致。 导游证申请人的经常执业地区在旅行社分社所在地的，可以由旅行社分社所在地旅游主管部门负责导游证办理相关工作。"},{"i":19,"n":"第十九条","txt":"导游为旅游者提供服务应当接受旅行社委派，但另有规定的除外。"},{"i":20,"n":"第二十条","txt":"导游在执业过程中应当携带电子导游证、佩戴导游身份标识，并开启导游执业相关应用软件。 旅游者有权要求导游展示电子导游证和导游身份标识。"},{"i":21,"n":"第二十一条","txt":"导游身份标识中的导游信息发生变化，导游应当自导游信息发生变化之日起10个工作日内，向所在地旅游主管部门申请更换导游身份标识。旅游主管部门应当自收到申请之日起5个工作日内予以确认更换。 导游身份标识丢失或者因磨损影响使用的，导游可以向所在地旅游主管部门申请重新领取，旅游主管部门应当自收到申请之日起10个工作日内予以发放或者更换。"},{"i":22,"n":"第二十二条","txt":"导游在执业过程中应当履行下列职责： （一）自觉维护国家利益和民族尊严； （二）遵守职业道德，维护职业形象，文明诚信服务； （三）按照旅游合同提供导游服务，讲解自然和人文资源知识、风俗习惯、宗教禁忌、法律法规和有关注意事项； （四）尊重旅游者的人格尊严、宗教信仰、民族风俗和生活习惯； （五）向旅游者告知和解释文明行为规范、不文明行为可能产生的后果，引导旅游者健康、文明旅游，劝阻旅游者违反法律法规、社会公德、文明礼仪规范的行为； （六）对可能危及旅游者人身、财产安全的事项，向旅游者作出真实的说明和明确的警示，并采取防止危害发生的必要措施。"},{"i":23,"n":"第二十三条","txt":"导游在执业过程中不得有下列行为： （一）安排旅游者参观或者参与涉及色情、赌博、毒品等违反我国法律法规和社会公德的项目或者活动； （二）擅自变更旅游行程或者拒绝履行旅游合同； （三）擅自安排购物活动或者另行付费旅游项目； （四）以隐瞒事实、提供虚假情况等方式，诱骗旅游者违背自己的真实意愿，参加购物活动或者另行付费旅游项目； （五）以殴打、弃置、限制活动自由、恐吓、侮辱、咒骂等方式，强迫或者变相强迫旅游者参加购物活动、另行付费等消费项目； （六）获取购物场所、另行付费旅游项目等相关经营者以回扣、佣金、人头费或者奖励费等名义给予的不正当利益； （七）推荐或者安排不合格的经营场所； （八）向旅游者兜售物品； （九）向旅游者索取小费； （十）未经旅行社同意委托他人代为提供导游服务； （十一）法律法规规定的其他行为。"},{"i":24,"n":"第二十四条","txt":"旅游突发事件发生后，导游应当立即采取下列必要的处置措施： （一）向本单位负责人报告，情况紧急或者发生重大、特别重大旅游突发事件时，可以直接向发生地、旅行社所在地县级以上旅游主管部门、安全生产监督管理部门和负有安全生产监督管理职责的其他相关部门报告； （二）救助或者协助救助受困旅游者； （三）根据旅行社、旅游主管部门及有关机构的要求，采取调整或者中止行程、停止带团前往风险区域、撤离风险区域等避险措施。"},{"i":25,"n":"第二十五条","txt":"具备领队条件的导游从事领队业务的，应当符合《旅行社条例实施细则》等法律、法规和规章的规定。 旅行社应当按要求将本单位具备领队条件的领队信息及变更情况，通过全国旅游监管服务信息系统报旅游主管部门备案。"},{"i":26,"n":"第二十六条","txt":"导游在执业过程中，其人格尊严受到尊重，人身安全不受侵犯，合法权益受到保障。导游有权拒绝旅行社和旅游者的下列要求： （一）侮辱其人格尊严的要求； （二）违反其职业道德的要求； （三）不符合我国民族风俗习惯的要求； （四）可能危害其人身安全的要求； （五）其他违反法律、法规和规章规定的要求。 旅行社等用人单位应当维护导游执业安全、提供必要的职业安全卫生条件，并为女性导游提供执业便利、实行特殊劳动保护。"},{"i":27,"n":"第二十七条","txt":"旅行社有下列行为的，导游有权向劳动行政部门投诉举报、申请仲裁或者向人民法院提起诉讼： （一）不依法与聘用的导游订立劳动合同的； （二）不依法向聘用的导游支付劳动报酬、导游服务费用或者缴纳社会保险费用的； （三）要求导游缴纳自身社会保险费用的； （四）支付导游的报酬低于当地最低工资标准的。 旅行社要求导游接待以不合理低价组织的旅游团队或者承担接待旅游团队的相关费用的，导游有权向旅游主管部门投诉举报。 鼓励景区对持有导游证从事执业活动或者与执业相关活动的导游免除门票。"},{"i":28,"n":"第二十八条","txt":"旅行社应当与通过其取得导游证的导游订立不少于1个月期限的劳动合同，并支付基本工资、带团补贴等劳动报酬，缴纳社会保险费用。 旅行社临时聘用在旅游行业组织注册的导游为旅游者提供服务的，应当依照旅游和劳动相关法律、法规的规定足额支付导游服务费用；旅行社临时聘用的导游与其他单位不具有劳动关系或者人事关系的，旅行社应当与其订立劳动合同。"},{"i":29,"n":"第二十九条","txt":"旅行社应当提供设置“导游专座”的旅游客运车辆，安排的旅游者与导游总人数不得超过旅游客运车辆核定乘员数。 导游应当在旅游车辆“导游专座”就坐，避免在高速公路或者危险路段站立讲解。"},{"i":30,"n":"第三十条","txt":"导游服务星级评价是对导游服务水平的综合评价，星级评价指标由技能水平、学习培训经历、从业年限、奖惩情况、执业经历和社会评价等构成。导游服务星级根据星级评价指标通过全国旅游监管服务信息系统自动生成，并根据导游执业情况每年度更新一次。 旅游主管部门、旅游行业组织和旅行社等单位应当通过全国旅游监管服务信息系统，及时、真实地备注各自获取的导游奖惩情况等信息。"},{"i":31,"n":"第三十一条","txt":"各级旅游主管部门应当积极组织开展导游培训，培训内容应当包括政策法规、安全生产、突发事件应对和文明服务等，培训方式可以包括培训班、专题讲座和网络在线培训等，每年累计培训时间不得少于24小时。培训不得向参加人员收取费用。 旅游行业组织和旅行社等应当对导游进行包括安全生产、岗位技能、文明服务和文明引导等内容的岗前培训和执业培训。 导游应当参加旅游主管部门、旅游行业组织和旅行社开展的有关政策法规、安全生产、突发事件应对和文明服务内容的培训；鼓励导游积极参加其他培训，提高服务水平。"},{"i":32,"n":"第三十二条","txt":"导游违反本办法有关规定的，依照下列规定处理： （一）违反本办法第十九条规定的，依据《旅游法》第一百零二条第二款的规定处罚； （二）违反本办法第二十条第一款规定的，依据《导游人员管理条例》第二十一条的规定处罚； （三）违反本办法第二十二条第（一）项规定的，依据《导游人员管理条例》第二十条的规定处罚； （四）违反本办法第二十三条第（一）项规定的，依据《旅游法》第一百零一条的规定处罚； （五）违反本办法第二十三条第（二）项规定的，依据《旅游法》第一百条的规定处罚； （六）违反本办法第二十三条第（三）项至第（六）项规定的，依据《旅游法》第九十八条的规定处罚； （七）违反本办法第二十三条第（七）项规定的，依据《旅游法》第九十七条第（二）项的规定处罚； （八）违反本办法第二十三条第（八）项规定的，依据《导游人员管理条例》第二十三条的规定处罚； （九）违反本办法第二十三条第（九）项规定的，依据《旅游"},{"i":33,"n":"第三十三条","txt":"违反本办法规定，导游有下列行为的，由县级以上旅游主管部门责令改正，并可以处1000元以下罚款；情节严重的，可以处1000元以上5000元以下罚款： （一）未按期报告信息变更情况的； （二）未申请变更导游证信息的； （三）未更换导游身份标识的； （四）不依照本办法第二十四条规定采取相应措施的； （五）未按规定参加旅游主管部门组织的培训的； （六）向负责监督检查的旅游主管部门隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的； （七）在导游服务星级评价中提供虚假材料的。 旅行社或者旅游行业组织有前款第（一）项和第（七）项规定行为的，依照前款规定处罚。"},{"i":34,"n":"第三十四条","txt":"导游执业许可申请人隐瞒有关情况或者提供虚假材料申请取得导游人员资格证、导游证的，县级以上旅游主管部门不予受理或者不予许可，并给予警告；申请人在一年内不得再次申请该导游执业许可。 导游以欺骗、贿赂等不正当手段取得导游人员资格证、导游证的，除依法撤销相关证件外，可以由所在地旅游主管部门处1000元以上5000元以下罚款；申请人在三年内不得再次申请导游执业许可。"},{"i":35,"n":"第三十五条","txt":"导游涂改、倒卖、出租、出借导游人员资格证、导游证，以其他形式非法转让导游执业许可，或者擅自委托他人代为提供导游服务的，由县级以上旅游主管部门责令改正，并可以处2000元以上1万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"违反本办法第二十五条第二款规定，旅行社不按要求报备领队信息及变更情况，或者备案的领队不具备领队条件的，由县级以上旅游主管部门责令改正，并可以删除全国旅游监管服务信息系统中不具备领队条件的领队信息；拒不改正的，可以处5000元以下罚款。 旅游行业组织、旅行社为导游证申请人申请取得导游证隐瞒有关情况或者提供虚假材料的，由县级以上旅游主管部门责令改正，并可以处5000元以下罚款。"},{"i":37,"n":"第三十七条","txt":"对导游违反本办法规定的行为，县级以上旅游主管部门应当依照旅游经营服务不良信息管理有关规定，纳入旅游经营服务不良信息管理；构成犯罪的，依法移送公安机关追究其刑事责任。"},{"i":38,"n":"第三十八条","txt":"旅游主管部门及其工作人员在履行导游执业许可、管理职责中，滥用职权、玩忽职守、徇私舞弊的，由有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":39,"n":"第三十九条","txt":"本办法下列用语的含义： （一）所在地旅游主管部门，是指旅行社（含旅行社分社）、旅游行业组织所在地的省、自治区、直辖市旅游主管部门或者其委托的设区的市级旅游主管部门、县级旅游主管部门； （二）旅游行业组织，是指依照《社会团体登记管理条例》成立的导游协会，以及在旅游协会、旅行社协会等旅游行业社会团体内设立的导游分会或者导游工作部门，具体由所在地旅游主管部门确定； （三）经常执业地区，是指导游连续执业或者3个月内累计执业达到30日的省级行政区域； （四）导游身份标识，是指标识有导游姓名、证件号码等导游基本信息，以便于旅游者和执法人员识别身份的工作标牌，具体标准由国家旅游局制定。"},{"i":40,"n":"第四十条","txt":"本办法自2018年1月1日起施行。"}],"wenhuahelvyoushichangxinyongguanliguiding":[{"i":1,"n":"第一条","txt":"为规范和加强文化和旅游市场信用管理，保护各类市场主体、从业人员和消费者合法权益，维护文化和旅游市场秩序，促进文化和旅游市场高质量发展，根据《中华人民共和国旅游法》《中华人民共和国未成年人保护法》《营业性演出管理条例》《娱乐场所管理条例》《互联网上网服务营业场所管理条例》《旅行社条例》等相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"文化和旅游主管部门实施信用管理，应当坚持依法行政、合理关联、保护权益、审慎适度原则，确保奖惩措施与守信失信行为相当。"},{"i":3,"n":"第三条","txt":"本规定适用于文化和旅游市场主体和从业人员的信用信息的采集、归集、公开和共享，守信激励和失信惩戒，信用修复，信用承诺和信用评价等活动。 文化市场主体包括从事营业性演出、娱乐场所、艺术品、互联网上网服务、网络文化、社会艺术水平考级等经营活动的法人或者其他组织；从业人员包括上述市场主体的法定代表人、主要负责人、实际控制人等有关人员。 旅游市场主体包括从事旅行社经营服务、A级旅游景区经营服务、旅游住宿经营服务、在线旅游经营服务的法人或者其他组织；从业人员包括上述市场主体的法定代表人、主要负责人、实际控制人以及导游等有关人员。"},{"i":4,"n":"第四条","txt":"文化和旅游部信用管理部门负责指导协调和监督管理全国文化和旅游市场信用管理工作。具体职责包括： （一）承担文化和旅游行业信用体系建设工作，拟定行业信用体系建设规划并组织实施，实施行业信用监管，统筹推进信用联合奖惩； （二）组织起草文化和旅游市场信用管理规章制度、标准规范等，开展信用监督检查； （三）承担社会信用体系建设部际联席会议相关工作，开展文化和旅游市场失信主体认定工作； （四）负责管理文化和旅游市场信用信息采集、归集、公开和共享工作； （五）负责管理信用承诺、信用评价、守信激励和失信惩戒、信用修复等工作； （六）负责建设管理全国文化和旅游市场信用管理系统，负责信用信息安全管理，组织开展信用信息分析与监测工作； （七）开展诚信文化建设，指导组织信用培训和宣传等工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府文化和旅游主管部门负责本行政区域内文化和旅游市场信用管理工作。具体职责包括： （一）负责本行政区域文化和旅游市场信用管理制度规范的组织实施，开展本行政区域文化和旅游市场失信主体认定工作； （二）开展本行政区域内信用信息采集、归集、公开和共享工作，组织开展信用承诺、信用评价、守信激励和失信惩戒、信用修复等工作； （三）组织开展本行政区域诚信文化建设、信用信息分析与监测、信用培训和宣传等工作。"},{"i":6,"n":"第六条","txt":"鼓励行业协会商会、第三方信用服务机构、金融机构、新闻媒体等各类单位和个人依法参与信用管理。鼓励各类市场主体在生产经营活动中广泛、主动地应用信用报告。 支持行业协会商会开展行业信用建设。支持行业协会商会对认定为失信主体的会员采取公开谴责、取消评优评先资格等行业自律措施，加强诚信宣传教育。"},{"i":7,"n":"第七条","txt":"文化和旅游部建立全国文化和旅游市场主体和从业人员信用信息记录。 地方各级文化和旅游主管部门负责补充完善信用信息记录，管理本行政区域内信用信息有关工作。"},{"i":8,"n":"第八条","txt":"文化和旅游市场信用信息包括下列信息： （一）注册登记、备案等用以识别、记载市场主体和从业人员基本情况的信息； （二）司法裁判仲裁执行信息； （三）行政许可、行政处罚信息； （四）与其他部门实施联合奖惩的信息； （五）信用评价结果信息、信用承诺履行情况信息； （六）其他反映市场主体和从业人员信用状况的相关信息。"},{"i":9,"n":"第九条","txt":"文化和旅游主管部门应当按照“谁管理、谁采集”的要求，依法依职责采集相关信用信息，任何单位和个人不得违法违规采集。"},{"i":10,"n":"第十条","txt":"文化和旅游主管部门应当通过全国文化和旅游市场信用管理系统归集职责范围内的相关信用信息。"},{"i":11,"n":"第十一条","txt":"文化和旅游市场失信主体分为严重失信主体和轻微失信主体。"},{"i":12,"n":"第十二条","txt":"文化市场主体和从业人员有下列情形之一的，应当将其认定为严重失信主体： （一）因欺骗、故意隐匿、伪造、变造材料等不正当手段取得许可证、批准文件的，或者伪造、变造许可证、批准文件的； （二）提供含有法律、行政法规、规章禁止的内容，造成严重后果的； （三）受到文化和旅游主管部门吊销许可证行政处罚的； （四）擅自从事营业性演出、娱乐场所、互联网上网服务等文化市场经营活动，特别是造成重大事故或者恶劣社会影响的； （五）其他应当认定为严重失信主体的情形。"},{"i":13,"n":"第十三条","txt":"旅游市场主体和从业人员有下列情形之一的，应当将其认定为严重失信主体： （一）因欺骗、故意隐匿、伪造、变造材料等不正当手段取得许可证、批准文件的，或者伪造、变造许可证、批准文件的； （二）发生重大安全事故，属于旅游市场主体主要责任的； （三）因侵害旅游者合法权益，造成游客滞留或者严重社会不良影响的； （四）受到文化和旅游主管部门吊销旅行社业务经营许可证、导游证行政处罚的； （五）未经许可从事旅游市场经营活动，特别是造成重大事故或者恶劣社会影响的； （六）其他应当认定为严重失信主体的情形。"},{"i":14,"n":"第十四条","txt":"文化和旅游主管部门将市场主体和从业人员认定为严重失信主体，应当遵守以下程序规定： （一）告知。经查证符合严重失信主体认定标准的，应当向文化和旅游市场主体和从业人员送达《严重失信主体认定告知书》，载明认定理由、依据、惩戒措施和当事人享有的陈述、申辩权利。 （二）陈述与申辩。当事人在被告知的10个工作日内有权向认定部门提交书面陈述、申辩及相关证明材料，逾期不提交的，视为放弃。认定部门应当在15个工作日内给予答复。陈述、申辩理由被采纳的，不认定为严重失信主体。 （三）认定。符合严重失信主体认定标准的，经专家评估、法制审核、集体讨论等程序，依法在15个工作日内作出决定。 （四）决定与送达。认定部门应当向当事人出具《严重失信主体认定决定书》并送达。"},{"i":15,"n":"第十五条","txt":"文化和旅游市场主体和从业人员有下列情形之一的，应当认定为轻微失信主体： （一）存在“捂票炒票”、虚假宣传、未履行相关义务、违反公序良俗等行为，造成不良社会影响的； （二）因故意或者重大过失严重损害旅游者合法权益，但尚不符合严重失信主体认定情形的； （三）在旅游经营活动中存在安全隐患，未在指定期限内整改完毕的； （四）拒不配合投诉处置、执法检查，拒不履行行政处罚决定，造成不良社会影响的； （五）12个月内受到文化和旅游主管部门两次较大数额罚款行政处罚，造成不良社会影响的； （六）其他应当认定为轻微失信主体的情形。 12个月内第3次认定为轻微失信主体的，应当认定为严重失信主体。"},{"i":16,"n":"第十六条","txt":"符合轻微失信主体认定标准的，由县级以上地方人民政府文化和旅游主管部门依法作出决定。认定部门应当向行政相对人出具《轻微失信主体认定决定书》并送达。 符合轻微失信主体认定标准的，在作出决定前，经文化和旅游主管部门约谈督促，改正违法行为、履行赔偿补偿义务、挽回社会不良影响的，可以不认定为轻微失信主体。"},{"i":17,"n":"第十七条","txt":"文化和旅游主管部门对守信情况良好的市场主体和从业人员，可以采取加强宣传、公开鼓励、提供便利服务等激励措施。"},{"i":18,"n":"第十八条","txt":"文化和旅游主管部门对文化市场严重失信主体实施下列管理措施： （一）适当提高抽查比例和频次，纳入重点监管对象； （二）将失信信息提供给有关部门查询，供其在相关行政管理、公共服务、评优评先等活动中参考使用； （三）将失信信息提供给各类市场主体查询，供其在市场活动中参考使用； （四）因擅自从事娱乐场所经营活动而被认定为严重失信主体的，其投资人和负责人终身不得投资开办娱乐场所或者担任娱乐场所的法定代表人、负责人； （五）因擅自设立互联网上网服务营业场所经营单位而被认定为严重失信主体的，其法定代表人或者主要负责人5年内不得担任互联网上网服务营业场所经营单位的法定代表人或者主要负责人； （六）因被吊销营业性演出许可证而被认定为严重失信主体的，当事人为单位的，其法定代表人、主要负责人5年内不得担任文艺表演团体、演出经纪机构或者演出场所经营单位的法定代表人、主要负责人； （七）因营业性演出含有禁止内容"},{"i":19,"n":"第十九条","txt":"文化和旅游主管部门对旅游市场严重失信主体实施下列管理措施： （一）适当提高抽查比例和频次，纳入重点监管对象； （二）将失信信息提供给有关部门查询，供其在相关行政管理、公共服务、评优评先等活动中参考使用； （三）将失信信息提供给各类市场主体查询，供其在市场活动中参考使用； （四）旅行社因被吊销旅行社业务经营许可证而被认定为严重失信主体的，其主要负责人5年内不得担任任何旅行社的主要负责人； （五）导游、领队因被吊销导游证而被认定为严重失信主体的，旅行社有关管理人员因旅行社被吊销旅行社业务经营许可证而被认定为严重失信主体的，自处罚之日起3年内不得重新申请导游证或者从事旅行社业务； （六）旅行社因侵犯旅游者合法权益受到罚款以上行政处罚而被认定为严重失信主体的，自处罚之日起2年内不得申请出境旅游业务； （七）法律、行政法规和党中央、国务院政策文件规定的其他管理措施。"},{"i":20,"n":"第二十条","txt":"文化和旅游主管部门对轻微失信主体实施下列管理措施： （一）依据法律、行政法规和党中央、国务院政策文件，在审查行政许可、资质资格等时作为参考因素； （二）加大日常监管力度，提高随机抽查的比例和频次； （三）将失信信息提供给有关部门查询，供其在相关行政管理、公共服务等活动中参考使用； （四）在行政奖励、授予称号等方面予以重点审查； （五）法律、行政法规和党中央、国务院政策文件规定的其他管理措施。"},{"i":21,"n":"第二十一条","txt":"对严重失信主体实施信用管理措施的期限为3年，对轻微失信主体实施信用管理措施的期限为1年。 法律法规另有规定的，从其规定。"},{"i":22,"n":"第二十二条","txt":"文化和旅游市场信用信息的公开与共享坚持合法、必要、安全原则，防止信息泄露，不得侵犯商业秘密和个人隐私。"},{"i":23,"n":"第二十三条","txt":"失信主体信息应当按照“谁认定、谁公开”原则通过全国文化和旅游市场信用管理系统等渠道公开。 法律法规另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"文化和旅游部信用管理部门应当建立健全信用信息查询、应用和反馈机制，推进信用信息与其他有关部门共享，实施信用联合奖惩。 各级文化和旅游主管部门有关职能部门、文化市场综合执法机构，应当将执法信息等相关信用信息及时与同级文化和旅游信用管理部门共享。"},{"i":25,"n":"第二十五条","txt":"公民、法人和其他组织有权查询与自身相关的信用信息。文化和旅游主管部门应当依法依规为查询提供便利。 认定部门或者信用信息归集管理部门发现信用信息有误的，应当及时主动更正。 公民、法人和其他组织认为自己的信用信息有误时，有权向认定部门申请更正相关信息。认定部门应当在收到实名提交的书面更正申请之日起5个工作日内作出是否更正的决定。"},{"i":26,"n":"第二十六条","txt":"符合以下条件的，认定部门应当主动进行信用修复： （一）实施信用管理措施期限届满； （二）认定为失信主体的依据被撤销或者变更，不符合认定为失信主体标准的； （三）因为政策变化或者法律法规修订，已经不适宜认定为失信主体的； （四）其他应当主动修复的情形。 信用修复应当通过全国文化和旅游市场信用管理系统进行。"},{"i":27,"n":"第二十七条","txt":"文化和旅游市场失信主体积极进行合规整改、纠正失信行为、消除不良影响、接受信用修复培训、作出信用承诺的，可以向认定部门提出信用修复申请并遵循以下程序： （一）申请。有关市场主体和从业人员可以向认定部门提出信用修复申请，说明事实和理由，提交信用修复申请书、培训记录、纠正失信行为等有关材料。 （二）受理。认定部门收到申请后，应当于10个工作日内予以受理。不符合条件的不予受理并说明理由。 （三）核查。认定部门应当自受理之日起10个工作日内，采取线上、书面、实地等方式检查核实。必要时，可以组织开展约谈或者指导。 （四）决定。认定部门应当自核查完成之日起5个工作日内作出准予信用修复或者不予信用修复的决定，不予信用修复的应当说明理由。 （五）修复。认定部门应当自作出准予信用修复决定之日起5个工作日内，解除对失信主体的相关管理措施。"},{"i":28,"n":"第二十八条","txt":"具有下列情形之一的，不予信用修复： （一）认定为严重失信主体不满6个月的、认定为轻微失信主体不满3个月的； （二）因违反相关法律法规规定，依法被限制或者禁止行业准入期限尚未届满的； （三）距离上一次信用修复时间不到1年的； （四）申请信用修复过程中存在弄虚作假、故意隐瞒事实等欺诈行为的； （五）申请信用修复过程中又因同一原因受到行政处罚，造成不良社会影响的； （六）法律法规和党中央、国务院政策文件明确规定不可修复的。"},{"i":29,"n":"第二十九条","txt":"文化和旅游部根据工作需要，制定行业信用评价制度和规范，组织开展信用评价，实施分级分类管理。各级文化和旅游主管部门在职责范围内开展信用评价工作。 鼓励行业协会商会、第三方信用服务机构等具备条件的机构依法依规参与信用评价。"},{"i":30,"n":"第三十条","txt":"鼓励各部门在评优评先、人员招聘、试点示范等方面优先选择信用评价较好的市场主体和从业人员。 鼓励和支持有关机构积极利用信用评价结果，拓展信用应用场景。"},{"i":31,"n":"第三十一条","txt":"文化和旅游主管部门在行政管理、政务服务等工作中应当规范应用信用承诺，将文化和旅游市场主体和从业人员的承诺履约情况记入信用信息记录，作为监督管理的重要依据。 文化和旅游市场主体和从业人员被认定为严重失信主体或者曾经作出虚假承诺的，不适用信用承诺的有关规定。"},{"i":32,"n":"第三十二条","txt":"文化和旅游主管部门应当对信用管理工作进行检查和评估，并采取通报表扬、通报批评、责令改正等措施。"},{"i":33,"n":"第三十三条","txt":"文化和旅游主管部门及其工作人员未依照本规定履行职责的，依法予以处理。"},{"i":34,"n":"第三十四条","txt":"文化和旅游主管部门应当依法保障市场主体和从业人员的合法权益。"},{"i":35,"n":"第三十五条","txt":"《严重失信主体认定告知书》《严重失信主体认定决定书》《轻微失信主体认定决定书》等文书格式由文化和旅游部另行制定。"},{"i":36,"n":"第三十六条","txt":"文化和旅游主管部门对收到的人民法院生效法律文书，根据法律、行政法规和党中央、国务院政策文件需要实施严重失信管理措施的，参照本规定执行。"},{"i":37,"n":"第三十七条","txt":"本规定自2022年1月1日起施行。《文化和旅游部关于印发〈全国文化市场黑名单管理办法〉的通知》（文旅市发〔2018〕30号）、《文化和旅游部关于印发〈旅游市场黑名单管理办法（试行）〉的通知》（文旅市场发〔2018〕119号）同时废止。"}],"wenhuahelvyoubulifagongzuoguiding":[{"i":1,"n":"第一条","txt":"为规范文化和旅游部立法工作，保证立法质量，提高立法效率，根据《中华人民共和国立法法》《行政法规制定程序条例》《规章制定程序条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称立法工作是指： （一）编制年度立法计划； （二）根据全国人大、国务院授权或者委托，起草、修改法律、行政法规草案，以及提出相关立法建议； （三）起草、解释、修改、废止部门规章； （四）审议文物方面的立法。"},{"i":3,"n":"第三条","txt":"立法工作应当遵循下列原则： （一）坚持以习近平法治思想为指导,加强党对立法工作的领导，全面贯彻落实党的路线方针政策和决策部署，将社会主义核心价值观融入立法全过程； （二）坚持科学立法、民主立法、依法立法，立法内容和程序符合宪法和上位法规定； （三）切实保障自然人、法人及其他组织的合法权益，在规定义务的同时明确其相应的权利和保障权利实现的途径； （四）体现行政机关的职权与责任相统一的原则，在赋予职权的同时明确其行使职权的条件、程序和应承担的责任。"},{"i":4,"n":"第四条","txt":"涉及文化和旅游领域重大体制和重大政策调整的重要立法，应当按照有关规定及时报告党中央。"},{"i":5,"n":"第五条","txt":"政策法规司负责组织协调立法工作，各司局按照职能分工，负责有关立法项目申报、调研论证、草案起草和征求意见等工作。"},{"i":6,"n":"第六条","txt":"政策法规司负责编制文化和旅游部年度立法计划。 各司局应当于每年年底前将立项申请报送政策法规司，对制定规章的必要性和可行性、所要解决的主要问题、拟确立的主要制度、进展情况和进度安排等作出说明。政策法规司应当对各司局报送的立项申请进行评估论证，形成立法计划报部务会议审定后印发公布执行。"},{"i":7,"n":"第七条","txt":"各司局认为需要对年度立法计划进行调整的，应当向政策法规司提出调整建议。政策法规司经审查认为确需调整的，提出调整建议报部务会议审定。"},{"i":8,"n":"第八条","txt":"政策法规司应当监督年度立法计划实施，及时跟踪年度立法计划进展情况，向有关司局提出立法项目督办建议。对于未按照年度立法计划完成立法任务的，相关司局应当向部务会议作出说明。"},{"i":9,"n":"第九条","txt":"列入年度立法计划的法律、行政法规、部门规章，由提出立项申请的起草单位负责。立法项目内容涉及两个以上起草单位的，在提出立项申请时应当确定牵头起草单位。 起草单位应当成立成员相对固定的起草工作小组，并提供必要的经费保障。"},{"i":10,"n":"第十条","txt":"起草立法草案，应当深入调查研究，总结实践经验，广泛听取自然人、法人或者其他组织的意见。听取意见可以采取书面征求意见、座谈会、论证会、听证会等多种形式。 除依法需要保密的外，起草单位应当将立法草案及其说明等向社会征求意见。向社会征求意见的期限一般不少于30日。"},{"i":11,"n":"第十一条","txt":"立法草案有下列情形的，起草单位应当进行论证咨询听取意见，并在论证、起草阶段及时与政策法规司沟通有关情况。 （一）涉及社会公众普遍关注的热点难点问题和经济社会发展遇到的突出矛盾的； （二）减损自然人、法人、其他组织权利或者增加其义务的； （三）对社会公众有重要影响等重大利益调整事项的。依法需要进行听证的，起草单位应当举行听证。"},{"i":12,"n":"第十二条","txt":"立法草案可能影响市场主体经济活动的，起草单位应当按照规定进行公平竞争审查。 立法草案涉及国际条约和对外贸易政策的，起草单位应当开展贸易政策合规评估。 立法草案涉及自然人、法人、其他组织切身利益的重大改革或者重大行政措施等情形的，或者可能造成较大舆论影响的，起草单位应当依法开展风险评估，提出应对预案。"},{"i":13,"n":"第十三条","txt":"起草单位向政策法规司报送草案送审稿时，应当提交下列材料： （一）草案送审稿； （二）起草说明，包括起草目的和依据、立法必要性、起草过程、拟确立的主要制度和措施、征求意见情况、需要说明的重点问题等； （三）汇总的意见，包括对草案送审稿主要问题的不同意见； （四）其他有关材料，包括领导有关批示指示、所规范领域的发展情况和相关数据、实践中存在的主要问题、有关条款的上位法依据、听证会笔录、调研报告、国内外有关立法资料等。"},{"i":14,"n":"第十四条","txt":"草案送审稿由政策法规司负责统一审核。 政策法规司应当重点从下列方面进行审核： （一）实践中存在的问题是否需要立法解决； （二）草案送审稿确立的主要制度是否能有效解决目前存在的问题，是否可行； （三）草案送审稿内容与宪法、法律、行政法规和中央有关政策是否抵触，是否符合社会主义核心价值观的要求； （四）调研论证是否充分，是否正确处理自然人、法人或者其他组织对草案送审稿的意见； （五）草案送审稿是否符合本规定第三条、第四条和第十二条的规定； （六）草案送审稿是否符合立法技术要求。"},{"i":15,"n":"第十五条","txt":"政策法规司应当采取下列形式审核草案送审稿： （一）将草案送审稿或者草案送审稿涉及的主要问题送有关机关、组织和专家征求意见，必要时向社会公开征求意见，公开征求意见的期限一般不少于30日； （二）就草案送审稿涉及的主要问题深入基层进行实地调查研究，听取有关方面的意见建议； （三）就草案送审稿涉及的重大问题，召开座谈会、专家论证会； （四）草案送审稿直接涉及自然人、法人或者其他组织切身利益，有关机关、组织或者自然人对其有重大意见分歧，起草单位在起草过程中未向社会公布，也未举行听证会的，经部领导批准向社会公布或者举行听证会。"},{"i":16,"n":"第十六条","txt":"草案送审稿有下列情形之一的，政策法规司可以退回起草单位进行论证： （一）立法条件尚不成熟或者形势发生重大变化的； （二）草案送审稿的主要制度存在较大争议，起草单位未与有关机构或者部门充分协商的； （三）未依法公开征求意见的； （四）草案送审稿不符合本规定第十三条规定的。 被退回的草案送审稿，经起草单位修改完善、符合送审条件的，可以重新送审。"},{"i":17,"n":"第十七条","txt":"政策法规司应当认真研究各方面意见，会同起草单位对草案送审稿进行修改，形成草案和对草案的说明。 草案和说明由政策法规司主要负责人签署，提出提请部务会议审议的建议。"},{"i":18,"n":"第十八条","txt":"立法草案应当经部务会议审议决定。 部务会议审议立法草案时，由起草单位作起草说明，政策法规司作审核说明。"},{"i":19,"n":"第十九条","txt":"根据部务会议审议意见，政策法规司应当组织起草单位对立法草案进行修改，形成草案修改稿，报部长签署。 规章签署后以令的形式公布，法律、行政法规草案送审稿依照《中华人民共和国立法法》《行政法规制定程序条例》规定的程序上报国务院审议。"},{"i":20,"n":"第二十条","txt":"部门规章应当自公布之日起30日后施行。但是，涉及国家安全等重大事项以及公布后不立即施行将有碍规章施行的，可以自公布之日起施行。 规章签署公布之日起20个工作日内，应当及时在部政府门户网站、部属报刊等媒体上刊载。 对涉及重大利益调整、人民群众切身利益、社会关注度高的部门规章,起草单位应当做好出台时机评估,做好内容解读。"},{"i":21,"n":"第二十一条","txt":"部门规章签署公布后，起草单位应当将部门规章和说明送政策法规司。政策法规司应当按照《法规规章备案条例》向国务院办理备案手续。"},{"i":22,"n":"第二十二条","txt":"规章有下列情况之一的，由文化和旅游部负责解释： （一）规章的规定需要进一步明确具体含义的； （二）规章制定后出现新的情况，需要明确适用规章依据的。 部门规章的解释草案由起草单位负责起草，政策法规司参照草案送审稿审核程序提出意见，报请部务会议审议决定后公布。 规章的解释与规章具有同等效力。"},{"i":23,"n":"第二十三条","txt":"政策法规司应当根据上位法规定以及国务院相关部署要求，及时组织各司局开展部门规章清理工作，有关司局应当及时提出修改或者废止的建议。 经清理需要修改、废止的部门规章，由有关司局提出意见，经政策法规司审核报部务会议审议后公布。"},{"i":24,"n":"第二十四条","txt":"政策法规司可以会同有关司局对法律、行政法规和部门规章进行实施情况监督及立法后评估，并把实施情况和评估结果作为修改、废止有关规章的重要参考。"},{"i":25,"n":"第二十五条","txt":"文化和旅游部起草的法律、行政法规的解释、修改、废止，按照有关规定执行。"},{"i":26,"n":"第二十六条","txt":"文物方面立法项目应当列入文化和旅游部立法计划。文物方面的规章草案经文化和旅游部部务会议审议后，以部长令的形式公布。"},{"i":27,"n":"第二十七条","txt":"本规定自2021年3月1日起施行。2006年3月6日颁布的《文化部立法工作规定》（文化部令第37号）、2011年4月6日颁布的《规章和规范性文件制定程序规定》（国家旅游局令第36号）同时废止。"}],"wenhuahelvyoubuxingzhengfuyiheyingsubanfa":[{"i":1,"n":"第一条","txt":"为规范文化和旅游部行政复议和行政应诉工作，保护公民、法人和其他组织的合法权益，监督和保障行政机关依法行使职权，推进法治政府建设，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）及其实施条例、《中华人民共和国行政诉讼法》等法律、行政法规，结合工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"文化和旅游部办理行政复议案件和行政应诉事项，适用本办法。 涉及纪检、监察、审计、信访等事项，根据有关法律、行政法规、党内法规处理，不适用本办法。"},{"i":3,"n":"第三条","txt":"文化和旅游部履行行政复议、行政应诉职责，遵循合法、公正、公开、高效、便民、为民的原则，坚持有错必纠，保障法律、行政法规的正确实施。"},{"i":4,"n":"第四条","txt":"文化和旅游部是本办法所称的行政复议机关，依照《行政复议法》履行行政复议职责。 文化和旅游部法制机构是文化和旅游部行政复议机构（以下简称行政复议机构），同时组织办理文化和旅游部行政应诉有关事项。 文化和旅游部相关司局根据行政复议案件和行政应诉事项的内容，指定专人参与办理涉及本司局业务的行政复议案件和行政应诉事项。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，公民、法人或者其他组织可以依照本办法向文化和旅游部申请行政复议： （一）对文化和旅游部作出的行政处罚决定不服； （二）对文化和旅游部作出的行政强制措施、行政强制执行决定不服； （三）申请行政许可，文化和旅游部拒绝或者在法定期限内不予答复，或者对文化和旅游部作出的有关行政许可的其他决定不服； （四）对文化和旅游部作出的征收征用决定及其补偿决定不服； （五）对文化和旅游部作出的赔偿决定或者不予赔偿决定不服； （六）认为文化和旅游部滥用行政权力排除或者限制竞争； （七）认为文化和旅游部违法集资、摊派费用或者违法要求履行其他义务； （八）申请文化和旅游部履行法定职责，文化和旅游部拒绝履行、未依法履行或者不予答复； （九）认为文化和旅游部不依法订立、不依法履行、未按照约定履行或者违法变更、解除行政协议； （十）认为文化和旅游部在政府信息公开工作中侵犯其合法权益； （十一）认为文"},{"i":6,"n":"第六条","txt":"下列事项不属于文化和旅游部管辖的行政复议范围： （一）国防、外交等国家行为； （二）行政法规、部门规章或者文化和旅游部制定、发布的具有普遍约束力的决定、命令等规范性文件； （三）文化和旅游部对工作人员的奖惩、任免等决定。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织认为文化和旅游部的行政行为所依据的有关规范性文件不合法，在对行政行为申请行政复议时，可以一并向文化和旅游部提出对该规范性文件的附带审查申请。 前款所列规范性文件不含部门规章。部门规章的审查依照法律、行政法规办理。"},{"i":8,"n":"第八条","txt":"依法申请行政复议的公民、法人或者其他组织是申请人。 有权申请行政复议的公民死亡的，其近亲属可以申请行政复议。有权申请行政复议的法人或者其他组织终止的，其权利义务承受人可以申请行政复议。 有权申请行政复议的公民为无民事行为能力人或者限制民事行为能力人的，其法定代理人可以代为申请行政复议。"},{"i":9,"n":"第九条","txt":"同一行政复议案件申请人人数众多的，可以由申请人推选代表人参加行政复议。 代表人参加行政复议的行为对其所代表的申请人发生效力，但是代表人变更行政复议请求、撤回行政复议申请、承认第三人请求的，应当经被代表的申请人同意。"},{"i":10,"n":"第十条","txt":"申请人以外的同被申请行政复议的行政行为或者行政复议案件处理结果有利害关系的公民、法人或者其他组织，可以作为第三人申请参加行政复议，或者由行政复议机构通知其作为第三人参加行政复议。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":11,"n":"第十一条","txt":"申请人、第三人可以委托一至二名律师、基层法律服务工作者或者其他代理人代为参加行政复议。 申请人、第三人委托代理人的，应当向行政复议机构提交授权委托书、委托人及被委托人的身份证明文件。授权委托书应当载明委托事项、权限和期限。申请人、第三人变更或者解除代理人权限的，应当书面告知行政复议机构。"},{"i":12,"n":"第十二条","txt":"公民、法人或者其他组织对文化和旅游部作出的行政行为不服申请行政复议的，文化和旅游部是被申请人；文化和旅游部与其他行政机关以共同的名义作出同一行政行为的，文化和旅游部与共同作出行政行为的行政机关是被申请人。"},{"i":13,"n":"第十三条","txt":"公民、法人或者其他组织认为行政行为侵犯其合法权益的，可以自知道或者应当知道该行政行为之日起六十日内向文化和旅游部提出行政复议申请；但是法律规定的申请期限超过六十日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。 行政行为作出时，未告知公民、法人或者其他组织申请行政复议的权利、行政复议机关和申请期限的，申请期限自公民、法人或者其他组织知道或者应当知道申请行政复议的权利、行政复议机关和申请期限之日起计算，但是自知道或者应当知道行政行为内容之日起最长不得超过一年。 向文化和旅游部提出行政复议申请的，自行政行为作出之日起超过五年的，文化和旅游部不予受理。"},{"i":14,"n":"第十四条","txt":"申请人申请行政复议，可以书面申请；书面申请有困难的，也可以口头申请。 书面申请的，可以通过邮寄或者文化和旅游部指定的互联网渠道等方式提交行政复议申请书，也可以当面提交行政复议申请书。文化和旅游部通过互联网渠道送达行政行为决定书的，应当同时提供提交行政复议申请书的互联网渠道。 口头申请的，行政复议机构工作人员应当当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间，并由申请人签字确认。 申请人对两个以上行政行为不服的，应当分别申请行政复议。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，申请人应当先向文化和旅游部申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼。 （一）对文化和旅游部当场作出的行政处罚决定不服； （二）认为文化和旅游部存在未履行法定职责情形； （三）申请政府信息公开，文化和旅游部不予公开； （四）法律、行政法规规定应当先向行政复议机关申请行政复议的其他情形。 对前款规定的情形，文化和旅游部在作出行政行为时应当告知公民、法人或者其他组织先向文化和旅游部申请行政复议。"},{"i":16,"n":"第十六条","txt":"向文化和旅游部提起的行政复议，由行政复议机构统一受理。 文化和旅游部公文接收部门、各机关司局收到书面行政复议申请的，应及时登记记录，并于一日内转送行政复议机构。行政复议机构应当对收到的行政复议申请进行登记。"},{"i":17,"n":"第十七条","txt":"文化和旅游部在收到行政复议申请后，应当在五日内进行审查。对符合《行政复议法》第三十条第一款规定情形的，文化和旅游部应当予以受理。 对不符合《行政复议法》第三十条第一款规定情形的行政复议申请，文化和旅游部应当在审查期限内决定不予受理并说明理由；不属于文化和旅游部管辖的，还应当在不予受理决定中告知申请人有管辖权的行政复议机关。 行政复议申请的审查期限届满，文化和旅游部未作出不予受理决定的，审查期限届满之日起视为受理。"},{"i":18,"n":"第十八条","txt":"行政复议申请材料不齐全或者表述不清楚，无法判断行政复议申请是否符合《行政复议法》第三十条第一款规定的，文化和旅游部应当自收到申请之日起五日内书面通知申请人补正。补正通知应当一次性载明需要补正的事项。 申请人应当自收到补正通知之日起十日内提交补正材料。有正当理由不能按期补正的，文化和旅游部可以延长合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请，并记录在案。 文化和旅游部收到补正材料后，依照《行政复议法》第三十条的规定处理。"},{"i":19,"n":"第十九条","txt":"文化和旅游部受理行政复议申请后，发现该行政复议申请不符合《行政复议法》第三十条第一款规定的，应当依法决定驳回申请并说明理由。"},{"i":20,"n":"第二十条","txt":"文化和旅游部受理行政复议申请后，依照《行政复议法》适用普通程序或者简易程序进行审理。行政复议机构应当指定行政复议人员负责办理行政复议案件。 行政复议人员对办理行政复议案件过程中知悉的国家秘密、商业秘密和个人隐私，应当予以保密。"},{"i":21,"n":"第二十一条","txt":"行政复议期间有《行政复议法》第三十九条第一款规定情形之一的，行政复议中止。 行政复议中止的原因消除后，应当及时恢复行政复议案件的审理。 中止、恢复行政复议案件的审理，文化和旅游部应当书面告知当事人。"},{"i":22,"n":"第二十二条","txt":"行政复议期间有《行政复议法》第四十一条规定情形之一的，行政复议终止。"},{"i":23,"n":"第二十三条","txt":"行政复议期间行政行为不停止执行；但是有《行政复议法》第四十二条规定情形之一的，应当停止执行。"},{"i":24,"n":"第二十四条","txt":"文化和旅游部相关司局对其以文化和旅游部名义作出行政行为的合法性、适当性负有举证责任。 有下列情形之一的，申请人应当提供证据: （一）认为文化和旅游部不履行法定职责的，提供曾经要求文化和旅游部履行法定职责的证据，但是文化和旅游部应当依职权主动履行法定职责或者申请人因正当理由不能提供的除外； （二）提出行政赔偿请求的，提供受行政行为侵害而造成损害的证据，但是因文化和旅游部原因导致申请人无法举证的，由文化和旅游部承担举证责任； （三）法律、法规规定需要申请人提供证据的其他情形。"},{"i":25,"n":"第二十五条","txt":"行政复议期间，申请人、第三人及其委托代理人可以按照规定查阅、复制相关书面答复、作出行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密、个人隐私或者可能危及国家安全、公共安全、社会稳定的情形外，行政复议机构应当同意。"},{"i":26,"n":"第二十六条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当自行政复议申请受理之日起七日内，将行政复议申请书副本或者行政复议申请笔录复印件发送文化和旅游部相关司局。 文化和旅游部相关司局应当自收到复议申请书副本或者行政复议申请笔录复印件之日起十日内，提出书面答复，制作行政复议答复书，并提交作出行政行为的证据、依据和其他有关材料。 行政复议答复书应当载明下列事项： （一）作出行政行为的事实依据及有关的证据材料； （二）作出行政行为所依据的法律、行政法规、部门规章和规范性文件的具体条款； （三）对申请人具体复议请求的意见和理由； （四）作出答复的日期。 提交的证据材料应当分类编号，并简要说明证据材料的来源、证明对象和内容。"},{"i":27,"n":"第二十七条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当当面或者通过互联网、电话等方式听取当事人的意见，并将听取的意见记录在案。因当事人原因不能听取意见的，可以书面审理。"},{"i":28,"n":"第二十八条","txt":"审理重大、疑难、复杂的行政复议案件，行政复议机构应当依法组织听证。 行政复议机构认为有必要听证，或者申请人请求听证的，行政复议机构可以组织听证。 行政复议机构组织听证的，听证程序按照《行政复议普通程序听证办法》执行。 申请人无正当理由拒不参加听证的，视为放弃听证权利。"},{"i":29,"n":"第二十九条","txt":"文化和旅游部审理行政复议案件，认为存在《行政复议法》第五十三条第一款规定情形的，可以适用简易程序。 除《行政复议法》第五十三条第一款规定情形以外的行政复议案件，当事人各方同意适用简易程序的，可以适用简易程序。"},{"i":30,"n":"第三十条","txt":"适用简易程序审理的行政复议案件，行政复议机构应当自受理行政复议申请之日起三日内，将行政复议申请书副本或者行政复议申请笔录复印件发送文化和旅游部相关司局。 文化和旅游部相关司局应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起五日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。 适用简易程序审理的行政复议案件，可以书面审理。"},{"i":31,"n":"第三十一条","txt":"适用简易程序审理的行政复议案件，行政复议机构认为不宜适用简易程序的，经行政复议机构的负责人批准，可以转为普通程序审理。"},{"i":32,"n":"第三十二条","txt":"申请人提出对有关规范性文件的附带审查申请，或者文化和旅游部在对行政行为进行审查时认为其依据不合法，行政复议机构应当中止行政复议，并于三日内根据情况作出以下处理： （一）规范性文件或者依据是由文化和旅游部制定的，行政复议机构将有关材料转送制定该规范性文件或者依据的司局，文化和旅游部相关司局应当在十日内就相关条款的合法性提交书面答复及相关材料； （二）规范性文件或者依据是由其他行政复议机关制定的，行政复议机构应当在七日内将有关材料转送有权处理的行政复议机关依法处理。"},{"i":33,"n":"第三十三条","txt":"文化和旅游部接到其他行政复议机关按照《行政复议法》第五十六条、第五十七条的规定转送的对规范性文件或者行政行为的依据进行审查的有关材料后，行政复议机构应当于五日内将有关材料转送制定该规范性文件或者依据的司局。文化和旅游部相关司局应当于十日内将处理意见回复行政复议机构。 文化和旅游部应当自收到转送之日起六十日内，将处理意见回复转送的行政复议机关。"},{"i":34,"n":"第三十四条","txt":"文化和旅游部依法审理行政复议案件，由行政复议机构对行政行为进行审查，提出意见，经文化和旅游部负责人同意或者集体讨论通过后，依照《行政复议法》第六十三条至七十二条规定，以文化和旅游部的名义作出行政复议决定。 经过听证的行政复议案件，文化和旅游部应当根据听证笔录、审查认定的事实和证据，作出行政复议决定。"},{"i":35,"n":"第三十五条","txt":"适用普通程序审理的行政复议案件，文化和旅游部应当自受理申请之日起六十日内作出行政复议决定；但是法律规定的行政复议期限少于六十日的除外。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机构负责人批准，可以适当延长，并书面告知当事人；但是延长期限最多不得超过三十日。 适用简易程序审理的行政复议案件，应当自受理申请之日起三十日内作出行政复议决定。"},{"i":36,"n":"第三十六条","txt":"文化和旅游部办理行政复议案件，可以进行调解。 调解应当遵循合法、自愿的原则，不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、行政法规的强制性规定。 当事人经调解达成协议的，文化和旅游部应当制作行政复议调解书，经各方当事人签字或者签章，并加盖文化和旅游部行政复议专用章，即具有法律效力。 调解未达成协议或者调解书生效前一方反悔的，文化和旅游部应当依法审查或者及时作出行政复议决定。"},{"i":37,"n":"第三十七条","txt":"当事人在行政复议决定作出前可以自愿达成和解，和解内容不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、行政法规的强制性规定。 当事人达成和解后，由申请人向行政复议机构撤回行政复议申请。行政复议机构准予撤回行政复议申请、文化和旅游部决定终止行政复议的，申请人不得再以同一事实和理由提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意愿的除外。"},{"i":38,"n":"第三十八条","txt":"行政复议不予受理决定书和终止决定书由行政复议机构负责人签发，加盖文化和旅游部行政复议专用章并依法送达。 变更、撤销、确认违法、确认无效、维持和驳回的行政复议决定书及行政复议调解书，由文化和旅游部负责人签发，加盖文化和旅游部行政复议专用章并依法送达。 行政复议决定书一经送达，即发生法律效力。"},{"i":39,"n":"第三十九条","txt":"人民法院送达的以文化和旅游部为被告的行政诉讼案件应诉通知、行政起诉状副本、传票等材料由行政复议机构统一接收。 文化和旅游部公文接收部门、各机关司局收到前款所列文书或者材料的，应及时登记记录，并于一日内转送行政复议机构。"},{"i":40,"n":"第四十条","txt":"行政复议机构对应诉通知、行政起诉状副本进行登记后，组织文化和旅游部相关司局办理并及时拟定答辩状，整理证据、依据和其他有关材料，经报文化和旅游部负责人审定后，在法定期限内提交人民法院。"},{"i":41,"n":"第四十一条","txt":"在行政应诉中，文化和旅游部相关司局应当指派专人负责案件调查、收集证据材料，提出初步答辩意见，协助行政复议机构组织开展应诉工作。"},{"i":42,"n":"第四十二条","txt":"在行政应诉中，文化和旅游部相关司局应当确定一名诉讼代理人，经行政复议机构审核后，报请文化和旅游部负责人决定。必要时，可以委托律师共同担任诉讼代理人。 行政复议机构根据文化和旅游部负责人决定，办理授权委托书等材料。"},{"i":43,"n":"第四十三条","txt":"在人民法院一审判决书或者裁定书送达后，行政复议机构应当组织文化和旅游部相关司局提出是否上诉的意见。决定上诉的，由行政复议机构组织文化和旅游部相关司局拟定上诉材料，经报文化和旅游部负责人审定后，在法定期限内提交人民法院。 对人民法院已发生法律效力的判决、裁定，行政复议机构可以组织文化和旅游部相关司局提出是否申请再审的意见。申请再审的，由行政复议机构组织文化和旅游部相关司局拟定再审材料，经报文化和旅游部负责人审定后，在法定期限内提交人民法院。"},{"i":44,"n":"第四十四条","txt":"行政诉讼案件结案后，诉讼代理人应当及时将案件材料交行政复议机构立卷归档。"},{"i":45,"n":"第四十五条","txt":"人民检察院的检察建议书和人民法院的司法建议书，由行政复议机构统一接收。 行政复议机构对检察建议书、司法建议书进行登记后，组织文化和旅游部相关司局办理并及时拟定答复意见，经报文化和旅游部负责人审定后，在法定期限内提交人民检察院或者人民法院。"},{"i":46,"n":"第四十六条","txt":"文化和旅游部工作人员在行政复议工作中，徇私舞弊或者有其他渎职、失职行为的，依照《行政复议法》有关规定给予处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"除《行政复议法》另有规定外，本办法中有关“一日”“三日”“五日”“七日”“十日”的规定是指工作日，不含法定休假日。 行政复议期间的计算和行政复议文书的送达，本办法没有规定的，依照《行政复议法》《中华人民共和国民事诉讼法》关于期间、送达的规定执行。"},{"i":48,"n":"第四十八条","txt":"文化和旅游部办理行政复议裁决、民事应诉工作参照本办法第四章办理。"},{"i":49,"n":"第四十九条","txt":"本办法自2025年9月1日起施行。《文化部行政复议工作程序规定》（文化部令第44号）、《国家旅游局行政复议和应诉办法》（旅办发〔2016〕339号）同时废止。"}],"wenhuashichangzonghexingzhengzhifaguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范文化市场综合行政执法行为，加强文化市场管理，维护文化市场秩序，保护公民、法人和其他组织的合法权益，促进文化市场健康发展，根据《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》等国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称文化市场综合行政执法是指文化市场综合行政执法机构（以下简称综合执法机构），依照国家有关法律、法规、规章的规定，对公民、法人或者其他组织的文化经营活动进行监督检查，并对违法行为进行处理的具体行政行为。"},{"i":3,"n":"第三条","txt":"本办法所称综合执法机构包括： （一）经法律、法规授权实施文化市场综合行政执法，对同级人民政府负责的执法机构； （二）接受有关行政部门委托实施文化市场综合行政执法，接受委托机关的指导和监督，对委托机关负责的执法机构。"},{"i":4,"n":"第四条","txt":"文化市场综合行政执法应当遵循公平、公正、公开的原则，建立权责明确、行为规范、监督有效、保障有力的行政执法运行机制。"},{"i":5,"n":"第五条","txt":"文化部负责指导全国文化市场综合行政执法，建立统一完善的文化市场综合行政执法工作制度，建设全国文化市场技术监管体系，加强文化市场综合行政执法队伍的专业化、规范化、信息化建设，完善对文化市场综合行政执法工作的绩效考核。 各有关行政部门在各自职责权限范围内，指导综合执法机构依法开展执法业务。 各级综合执法机构依照职责分工负责本行政区域内的文化市场综合行政执法工作。"},{"i":6,"n":"第六条","txt":"综合执法机构与各有关行政部门应当建立协作机制，及时掌握行政执法的依据、标准以及相关行政许可情况，定期通报市场动态和行政执法情况，提出政策或者工作建议。"},{"i":7,"n":"第七条","txt":"文化市场综合行政执法人员（以下简称执法人员）应当具备以下条件： （一）具有中华人民共和国国籍； （二）年满十八周岁； （三）遵纪守法、品行良好、身体健康； （四）熟悉文化市场管理法律法规，掌握文化市场管理所需的业务知识和技能； （五）无犯罪或者开除公职记录； （六）法律法规规定的其他条件。 录用执法人员应当参照《中华人民共和国公务员法》的有关规定公开招考，择优录取。"},{"i":8,"n":"第八条","txt":"执法人员经岗位培训和考试合格，取得《中华人民共和国文化市场综合行政执法证》或者各级人民政府核发的行政执法证后，方可从事行政执法工作。 综合执法机构应当每年对执法人员进行业务考核。对考核不合格的执法人员，应当暂扣执法证件。"},{"i":9,"n":"第九条","txt":"综合执法机构应当有计划地对执法人员进行业务培训，鼓励和支持执法人员参加在职继续教育。"},{"i":10,"n":"第十条","txt":"综合执法机构应当配备调查询问、证据保存等专用房间及交通、通讯、取证、检测等行政执法所必需的设施设备；为执法人员购买人身意外伤害保险。"},{"i":11,"n":"第十一条","txt":"综合执法机构应当实行执法人员定期岗位轮换制度。执法人员在同一执法岗位上连续工作时间原则上不超过5年。"},{"i":12,"n":"第十二条","txt":"各有关行政部门或者综合执法机构可按有关规定对工作成绩显著的综合执法机构和执法人员给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"综合执法机构应当建立健全12318文化市场举报体系，向社会公布举报方式，依法及时有效受理、办理举报，对举报有功人员可给予一定奖励。 对日常巡查或者定期检查中发现的违法行为，公民、法人及其他组织举报的违法行为，上级交办的、下级报请处理的或者有关部门移送的案件，应当及时处理。"},{"i":14,"n":"第十四条","txt":"重大案件发生后12小时内，当地综合执法机构应当将案件情况向上级报告。上级综合执法机构或者委托机关应当对重大案件的查处进行督办。"},{"i":15,"n":"第十五条","txt":"文化市场行政违法案件由违法行为发生地所在的县级以上有关行政部门或者综合执法机构管辖。法律、法规、规章另有规定的，从其规定。对管辖发生争议的，报请共同的上一级行政机关指定管辖。 发现受理的案件不属于自己管辖的，应当及时将案件移交给有管辖权的有关行政部门、综合执法机构；违法行为涉嫌构成犯罪的，应当移送司法机关依法处理。"},{"i":16,"n":"第十六条","txt":"执法人员依法执行公务时，应当规范着装，佩戴执法标志。"},{"i":17,"n":"第十七条","txt":"综合执法机构开展行政执法活动，应当严格按照法律、法规和本办法规定的程序进行，并依法制作执法文书。"},{"i":18,"n":"第十八条","txt":"对于公民、法人或者其他组织违反文化市场管理法律法规的行为，依法应当给予行政处罚的，必须查明事实；违法事实不清的，不得给予行政处罚。"},{"i":19,"n":"第十九条","txt":"在作出行政处罚之前，应当告知当事人作出行政处罚决定的事实、理由和依据，并告知当事人依法享有的权利。 执法人员应当充分听取当事人的陈述和申辩，并制作笔录，对当事人提出的事实、理由和证据进行复核，经复核成立的应当采纳。"},{"i":20,"n":"第二十条","txt":"违法事实确凿并有法定依据，对公民处以50元以下、对法人或者其他组织处以1000元以下罚款或者警告的行政处罚的，可以当场作出处罚决定；执法人员应当填写预定格式、编有号码的行政处罚决定书，经签名或者盖章后，当场交付当事人。 执法人员应当自作出当场处罚决定之日起3日内向所属综合执法机构报告并备案。"},{"i":21,"n":"第二十一条","txt":"除依法可以当场作出的行政处罚外，发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，应当登记立案，客观公正地进行调查，收集有关证据，必要时可以依照法律、法规的有关规定进行检查。 证据包括书证、物证、证人证言、视听资料、当事人陈述、鉴定结论、勘验笔录和现场笔录或者其他有关证据。证据必须查证属实，才能作为认定事实的根据。"},{"i":22,"n":"第二十二条","txt":"在调查或者执法检查时，执法人员不得少于2名，并应当向当事人或者有关人员出示执法证件。当事人及有关人员应当如实回答询问，并协助调查或者检查。执法人员应当制作调查询问或者现场检查笔录，经当事人或者有关人员核对无误后，由当事人或者有关人员签名或者盖章。当事人或者有关人员拒绝的，由2名以上执法人员在笔录上注明情况并签名。 执法人员与当事人有直接利害关系的，应当回避。"},{"i":23,"n":"第二十三条","txt":"在调查或者执法检查中，发现正在发生的违法违规行为，情况紧急无法立案的，执法人员可以采取以下措施： （一）对违法行为予以制止或者纠正； （二）依据相关法律法规规定，对有关物品、工具进行查封或者扣押； （三）收集、提取有关证据。"},{"i":24,"n":"第二十四条","txt":"执法人员在收集证据时，可以采取抽样取证的方法；在证据可能灭失或者以后难以取得的情况下，经依法批准后，可以采取先行登记保存等措施。 对证据进行抽样取证或者登记保存，应当有当事人在场；当事人不在场或者拒绝到场的，可以请在场的其他人员见证并注明。 对抽样取证或者登记保存的物品应当开列清单，并依据情况分别制作抽样取证凭证或者证据登记保存清单，标明物品名称、数量、单价等事项，由执法人员、当事人签名或者盖章，交付当事人。当事人拒绝签名、盖章或者接收的，由2名以上执法人员在凭证或者清单上注明情况并签名。 登记保存物品时，在原地保存可能灭失或者妨害公共安全的，可以异地保存。"},{"i":25,"n":"第二十五条","txt":"对先行登记保存的证据，应当在7日内作出下列处理决定： （一）需要进行技术检验或者鉴定的，送交检验或者鉴定； （二）依法不需要没收的物品，退还当事人； （三）依法应当移交有关部门处理的，移交有关部门。 法律法规另有规定的，从其规定。"},{"i":26,"n":"第二十六条","txt":"对情节复杂或者重大的案件作出责令停业整顿、吊销许可证或者较大数额罚款等行政处罚前，应当经过集体讨论后，再做决定。"},{"i":27,"n":"第二十七条","txt":"拟作出责令停业整顿、吊销许可证、较大数额罚款等行政处罚决定的，应当告知当事人有听证的权利。当事人要求听证的，应当组织听证。"},{"i":28,"n":"第二十八条","txt":"听证会应当按照以下程序进行： （一）听证主持人宣布听证开始，宣布案由、听证纪律、当事人的权利和义务，宣布和核对听证参加人员名单； （二）调查人员提出当事人违法的事实、证据、处罚依据和行政处罚的理由； （三）当事人可以提出证据，进行陈述和申辩，对调查人员提出的证据进行质证； （四）听证主持人向当事人、调查人员、证人等有关人员询问； （五）当事人最后陈述； （六）听证主持人宣布听证结束。"},{"i":29,"n":"第二十九条","txt":"听证会应当制作笔录，交当事人核阅无误后签字或者盖章。 听证主持人应当依据听证情况作出书面报告，报告的主要内容为：案由，听证时间、地点，听证参加人姓名或者名称，申辩和质证的事项，证据鉴别和事实认定情况。"},{"i":30,"n":"第三十条","txt":"行政处罚决定书应当在宣告后当场交付当事人，由当事人在送达回证上记明收到日期，签名或者盖章。 当事人不在场的，应当自作出行政处罚决定之日起７日内依照民事诉讼法的有关规定，将行政处罚决定书送达当事人。"},{"i":31,"n":"第三十一条","txt":"作出责令停业整顿、吊销许可证等重大行政处罚的，应当自作出行政处罚决定之日起15日内，报许可机关和上级综合执法机构备案，必要时可将处罚决定抄告有关部门。"},{"i":32,"n":"第三十二条","txt":"依法没收的财物，必须按照国家有关规定公开拍卖或者处理。 依法应当予以销毁的物品，经综合执法机构负责人批准，由2名以上执法人员监督销毁，并制作销毁记录。"},{"i":33,"n":"第三十三条","txt":"执法文书及有关材料，应当依照有关法律、法规、规章的规定，编目装订，立卷归档。"},{"i":34,"n":"第三十四条","txt":"上级综合执法机构对下级综合执法机构及执法人员的执法行为实行执法监督。 综合执法机构接受同级人民政府及有关行政部门的执法监督。"},{"i":35,"n":"第三十五条","txt":"执法监督的内容包括： （一）执法主体； （二）执法程序； （三）法律、法规、规章的适用； （四）履行法定职责的情况； （五）罚没财物的处理； （六）其他需要监督的内容。"},{"i":36,"n":"第三十六条","txt":"执法监督的方式： （一）受理对违法违规执法行为的申诉、控告和检举，并直接处理或者责成有关部门处理； （二）对执法工作进行检查； （三）调阅执法案卷和其他资料； （四）在职权范围内采取的其他方式。"},{"i":37,"n":"第三十七条","txt":"在执法过程中有下列情形之一的，应当予以纠正或者撤销行政处罚，损害当事人合法权益的，应当依法给予赔偿： （一）执法主体不合法的； （二）执法程序违法的； （三）具体行政行为适用法律、法规、规章错误的； （四）违法处置罚没或者扣押财物的。"},{"i":38,"n":"第三十八条","txt":"因第三十七条列举情形造成以下后果的，应当依法追究直接责任人和主要负责人的责任： （一）人民法院撤销、变更行政处罚决定的； （二）复议机关撤销、变更行政处罚决定的。"},{"i":39,"n":"第三十九条","txt":"执法人员有下列情形之一，尚不构成犯罪的，应当依法给予行政处分，并收回其执法证件；情节严重，构成犯罪的，依法追究刑事责任： （一）滥用职权，侵犯公民、法人及其他组织合法权益的； （二）利用职权或者工作之便索取或者收受他人财物，或者支持、纵容、包庇文化市场违法经营活动的； （三）伪造、篡改、隐匿和销毁证据的； （四）玩忽职守、贻误工作的； （五）泄露举报内容和执法行动安排的； （六）其他违反法律、法规、规章的行为。"},{"i":40,"n":"第四十条","txt":"执法人员在被暂扣执法证件期间，不得从事行政执法工作；执法人员被收回执法证件的，应当调离执法岗位，不得再从事行政执法工作。"},{"i":41,"n":"第四十一条","txt":"《中华人民共和国文化市场综合行政执法证》是执法人员履行职责时的合法证件，由文化部统一制式，省级文化行政部门或者综合执法机构监制并核发。 各级人民政府核发的行政执法证，也是执法人员履行职责时的合法证件。 执法文书由文化部统一格式，省级文化行政部门或者综合执法机构监制。"},{"i":42,"n":"第四十二条","txt":"本办法所称“较大数额罚款”是指对公民处以1万元以上、对法人或者其他组织处以5万元以上的罚款，法律、法规、规章另有规定的，从其规定。"},{"i":43,"n":"第四十三条","txt":"本办法由文化部负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2012年2月1日起施行。2006年7月1日文化部发布的《文化市场行政执法管理办法》同时废止。"}],"wenhuabushewaiwenhuayishubiaoyanjizhanlanguanliguie36a62":[{"i":1,"n":"第一条","txt":"为加强对涉外文化艺术表演及展览活动的管理，根据国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称涉外文化艺术表演活动，是指中国与外国间开展的各类音乐、舞蹈、戏剧、戏曲、曲艺、杂技、马戏、动物表演、魔术、木偶、皮影、民间文艺表演、服饰和时装表演、武术及气功演出等交流活动。 本规定所称涉外文化艺术展览活动，是指中国与外国间开展的各类美术、工艺美术、民间美术、摄影（图片）、书法碑贴、篆刻、古代和传统服饰、艺术收藏品以及专题性文化艺术展览等交流活动。"},{"i":3,"n":"第三条","txt":"本规定适用于下列活动： （一）我国与外国政府间文化协定和合作文件确定的文化艺术表演及展览； （二）我国与外国通过民间渠道开展的非商业性文化艺术表演及展览； （三）我国与外国间进行的商业和有偿文化艺术表演及展览（展销）； （四）属于文化交流范畴的其他涉外文化艺术表演及展览。"},{"i":4,"n":"第四条","txt":"有关文物展览对外交流活动的管理办法，另行规定。"},{"i":5,"n":"第五条","txt":"涉外文化艺术表演及展览活动，必须服从国家外交工作的大局，服从社会主义精神文明建设的大局。"},{"i":6,"n":"第六条","txt":"文化部负责全国涉外文化艺术表演及展览活动的归口管理和宏观调控，行使下列职权： （一）统筹安排和组织实施国家级涉外文化艺术表演及展览活动计划； （二）协调、平衡全国各省、自治区、直辖市、中央和国家机关部委、解放军系统和全国性人民团体的涉外文化艺术表演及展览工作； （三）批准或不批准涉外文化艺术表演及展览活动的立项申请，本规定另有规定的除外； （四）认定中央和国家机关部委、解放军系统和全国性人民团体及所属机构涉外非商业性文化艺术表演及展览活动组织者的资格； （五）审核并认定全国从事涉外商业和有偿文化艺术表演及展览（展销）活动的经营机构的资格； （六）监督和检查涉外文化艺术表演及展览机构及活动情况； （七）查处有重大影响的涉外文化艺术表演及展览活动中的违法事件； （八）其他应由文化部行使的职权。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市文化厅（局）是本地区涉外文化艺术表演及展览活动的主管部门，行使下列职权： （一）统筹安排和组织实施本省、自治区、直辖市涉外文化艺术表演及展览活动计划； （二）协调、平衡本地区的涉外文化艺术表演及展览活动； （三）负责本地区涉外文化艺术表演及展览项目、经营涉外商业和有偿文化艺术表演及展览（展销）活动机构资格认定的初审、报批、执行等事宜； （四）批准或不批准已经文化部批准的本地区涉外非商业性文化艺术表演及展览项目２０天以内的延期申请； （五）批准或不批准本地区个人通过因私渠道出国进行文化艺术表演及展览活动的申请； （六）认定本地区涉外非商业性文化艺术表演及展览活动组织者的资格； （七）审核并认定本地区经营场所从事外国来华商业和有偿文化艺术表演及展览（展销）活动的资格； （八）监督和检查本地区涉外文化艺术表演及展览机构及活动情况； （九）协助上级领导机关或有关部门，查处本地"},{"i":8,"n":"第八条","txt":"经批准的第七条第（四）、（五）和（七）项的项目，均须报文化部备案。"},{"i":9,"n":"第九条","txt":"文化部对从事涉外文化艺术表演及展览活动的组织者实行资格认定制度。"},{"i":10,"n":"第十条","txt":"下列部门和机构有资格从事涉外非商业性文化艺术表演及展览活动： （一）文化部、各省、自治区、直辖市人民政府及其文化厅（局）； （二）文化部认定的有对外文化交流任务的中央和国家机关部委、解放军系统和全国性人民团体； （三）省、自治区、直辖市文化厅（局）认定的本地区有对外文化交流任务的部门和团体； （四）文化部认定的有从事涉外商业和有偿文化艺术表演及展览（展销）资格的经营机构； （五）省、自治区、直辖市文化厅（局）认定的有从事来华商业和有偿文化艺术表演及展览（展销）资格的经营场所（只限于来华项目）。"},{"i":11,"n":"第十一条","txt":"文化部和各省、自治区、直辖市文化厅（局）按照本规定，在接受涉外非商业性文化艺术表演及展览立项申请的同时，根据申请单位的工作和任务性质、业务和组织能力对其进行资格认定。"},{"i":12,"n":"第十二条","txt":"申请从事涉外商业和有偿文化艺术表演及展览（展销）活动资格的经营机构，须具备下列条件： （一）有经文化部或省、自治区、直辖市文化厅（局）认定的对外文化交流业务和能力； （二）有独立的法人资格和营业执照； （三）有相应的从事对外文化活动必需的资金、设备及固定的办公地点； （四）有相应的从事涉外文化艺术表演及展览活动的专业管理人员和组织能力； （五）有健全的外汇财务管理制度和专职财会管理人员。"},{"i":13,"n":"第十三条","txt":"申请从事外国来华商业和有偿文化艺术表演及展览（展销）活动资格的经营场所，必须具备下列条件： （一）本规定第十二条第（二）、（三）、（四）、（五）项规定的条件； （二）有与演出或展览相适应的固定营业场所和设备； （三）有符合国家规定的安全、消防和卫生设施。"},{"i":14,"n":"第十四条","txt":"涉外商业和有偿文化艺术表演及展览（展销）经营机构和经营场所的资格认定程序： （一）具备本规定第十二条和第十三条规定条件的经营机构或经营场所，向所在省、自治区、直辖市文化厅（局）或有对外文化交流任务的中央和国家机关部委、解放军系统和全国性人民团体提出申请。 （二）经营机构的资格认定，由其所在地文化厅（局）、有隶属关系的中央或国家机关部委、解放军系统和全国性人民团体进行初审，通过后，出具有效证明，向文化部提出申请。 （三）经营场所的资格认定，由其所在省、自治区、直辖市文化厅（局）办理。 （四）经营机构申请时需提供营业执照、资信证明、资产使用证明、专业人员资历证明和财务制度文件。 （五）经营场所申请时除提供上述资料外，还须提供文化行政管理部门颁发的相应许可证和公安部门颁发的《安全合格证》。 （六）文化部及有关省、自治区、直辖市文化厅（局）在接到申请之日起６０天内，根据国家有关规定予以审批，合"},{"i":15,"n":"第十五条","txt":"对取得涉外商业和有偿文化艺术表演及展览（展销）活动资格的经营机构和经营场所，实行定期审验制度。 凡不再具备第十二条和第十三条规定条件的经营单位，资格认定部门有权取消或暂停其涉外商业和有偿文化艺术表演及展览（展销）活动的经营资格。"},{"i":16,"n":"第十六条","txt":"鼓励下列文化艺术表演及展览项目出国： （一）弘扬中华民族优秀传统文化的； （二）宣传我国现代化建设成就的； （三）体现当今我国文化艺术水平的； （四）维护国家统一和民族团结的； （五）有利于促进中国同世界各国人民之间友谊的。"},{"i":17,"n":"第十七条","txt":"禁止有下列内容的文化艺术表演及展览项目出国： （一）损害国家利益和形象的； （二）违背国家对外方针和政策的； （三）不利于我国民族团结和国家统一的； （四）宣扬封建迷信和愚昧习俗的； （五）表演上有损国格、人格或艺术上粗俗、低劣的； （六）违反前往国家或地区宗教信仰和风俗习惯的； （七）有可能损害我国同其他国家关系的； （八）法律和行政法规禁止的其他内容。"},{"i":18,"n":"第十八条","txt":"鼓励下列文化艺术表演及展览项目来华： （一）优秀的、具有世界水平的； （二）内容健康、艺术上有借鉴作用的； （三）传统文明、民族民间的； （四）有利于提高公众艺术欣赏水平的； （五）促进我国同其他国家间友谊的。"},{"i":19,"n":"第十九条","txt":"禁止有下列内容的文化艺术表演及展览项目来华： （一）反对我国国家制度和政策、诋毁我国国家形象的； （二）影响我国社会稳定的； （三）制造我国民族分裂，破坏国家统一的； （四）干涉我国内政的； （五）思想腐朽、颓废，表现形式庸俗、疯狂的； （六）宣扬迷信、色情、暴力、恐怖、吸毒的； （七）有损观众身心健康的； （八）违反我国社会道德规范的； （九）可能影响我国与其他国家友好关系的； （十）法律和行政法规禁止的其他内容。"},{"i":20,"n":"第二十条","txt":"文化部对国际上流行，艺术表现手法独特，但不符合我民族习俗或有较大社会争议的艺术品类的引进，进行限制。此类项目不得进行公开演出或展览，仅供国内专业人员借鉴和观摩。"},{"i":21,"n":"第二十一条","txt":"项目报批程序： （一）项目主办（承办）单位按照行政隶属关系，向其所在有对外文化交流任务的中央和国家机关部委、解放军系统和全国性人民团体、省、自治区、直辖市文化厅（局）等主管部门，提出立项申请，并附相关资料； （二）上述主管部门对项目申请及相关资料进行审核，认为合格的，报文化部审批。"},{"i":22,"n":"第二十二条","txt":"我国与外国政府间文化协定和合作文件确定的文化艺术表演及展览交流项目，由文化部下达任务通知，各地方、各单位应认真落实。"},{"i":23,"n":"第二十三条","txt":"我国与外国通过民间渠道开展的非商业性文化艺术表演及展览交流活动由文化部确定任务，通知有关部门或省、自治区、直辖市文化厅（局）具体实施；或由有对外文化交流资格的机构，通过规定程序，报文化部批准后实施。"},{"i":24,"n":"第二十四条","txt":"我国与外国进行的商业和有偿文化艺术表演及展览（展销）活动，必须由经文化行政部门认定的有对外经营商业和有偿文化艺术表演及展览（展销）资格的机构、场所或团体提出申请，通过其所在地文化厅（局）、有隶属关系的中央或国家机关部委、解放军系统和全国性人民团体，报文化部审批。 项目经文化部批准后，方可与外方签订正式合同，并报文化部备案。"},{"i":25,"n":"第二十五条","txt":"涉外非商业性艺术表演及展览项目的申请报告须包括下列资料： （一）主办（承办）单位或个人的名称及背景资料； （二）活动团组的名称、人员组成及名单等； （三）活动内容、时间、地点、场次、经费来源及费用支付方式； （四）全部节目录像带、展品照片及文字说明等； （五）如出国项目，需附包括本条（二）、（三）项内容的外方邀请信或双方草签的意向书。"},{"i":26,"n":"第二十六条","txt":"申报涉外商业和有偿文化艺术表演及展览（展销）项目须提供下列资料： （一）中方在确定外方经纪机构资信情况可靠之后，与其草签的意向书。 意向书的内容包括： １、活动的组织单位或个人的国别、名称及所在地； ２、活动的内容、时间、地点及参加团组的人员组成； ３、演出或展览场次； ４、往返国际旅费、运费、保险费、当地食宿交通费、医疗费、演出及展览场地费、劳务费、宣传费和生活零用费的负担责任； ５、价格、报酬、付款方式及收入分配办法； ６、违约索赔等条款。 （二）涉外商业和有偿艺术表演及展览（展销）活动资格证明； （三）国外合作方的有关背景资料、资信证明等； （四）全部节目录像带、展品照片及文字说明等； （五）文化行政部门对节目或作品内容的鉴定意见（世界名剧和名作除外）； （六）申报艺术团或展览团出国的项目，需提供中介机构与相关艺术团、展览（博物）馆或其它部门之间的协议书。"},{"i":27,"n":"第二十七条","txt":"我国与外国友好省、州、市之间非商业性文化艺术表演（杂技或另有规定的除外）及展览交流项目，由有关省、自治区、直辖市文化厅（局）报同级人民政府审批，并报文化部备案。"},{"i":28,"n":"第二十八条","txt":"我国与外国友好省、州、市之间商业和有偿文化艺术表演及展览、杂技出国演出和跨出友好省、州、市之间的文化艺术表演及展览交流项目，须按本规定的程序，报文化部审批。"},{"i":29,"n":"第二十九条","txt":"杂技团携带熊猫出国演出，须经文化部会同外交部和林业部，报国务院审批。"},{"i":30,"n":"第三十条","txt":"携带其他珍稀动物出国或来国内展演，须按规定报文化部审批，并办理有关动物检疫和进出境手续。"},{"i":31,"n":"第三十一条","txt":"同未建交国家和地区进行文化艺术表演及展览交流活动，须按审批程序，经文化部会同外交部，报国务院审批。"},{"i":32,"n":"第三十二条","txt":"组织跨部门或跨省、自治区、直辖市的涉外文化艺术表演及展览活动，须附所涉及部门或省、自治区、直辖市文化厅（局）的同意函，报文化部审批。"},{"i":33,"n":"第三十三条","txt":"报文化部审批的涉外文化艺术表演及展览项目，须按审批程序，在项目实施前２个月报到文化部。"},{"i":34,"n":"第三十四条","txt":"未经批准，任何机构或个人不得对外作出承诺或与外方签订有关文化艺术表演及展览（展销）活动的正式合同。"},{"i":35,"n":"第三十五条","txt":"涉外文化艺术表演及展览项目的申报单位，必须是项目的主办或承办单位。严禁买卖或转让项目批件。"},{"i":36,"n":"第三十六条","txt":"派出文化艺术表演及展览团组应遵守下列规定： （一）出国艺术表演及展览团组，应以专业人员为主； （二）在外期间必须加强内部管理，严格组织纪律； （三）在外开展活动，须接受我驻有关国家使（领）馆的领导； （四）禁止利用出国从事文化艺术表演及展览交流之机，进行旅游或变相旅游；经营未经批准的商业活动；从事有损国格、人格活动等行为。"},{"i":37,"n":"第三十七条","txt":"禁止以劳务输出输入名义，或通过旅游、探亲和访友等渠道，从事文化艺术表演及展览的对外交流活动。"},{"i":38,"n":"第三十八条","txt":"涉外文化艺术表演及展览活动的承办单位必须严格遵守国家有关规定，接受政府文化行政部门、海关、工商、财政、税务、物价、公安、卫生、检疫、审计及其它有关部门的管理、监督和检查。"},{"i":39,"n":"第三十九条","txt":"主办单位如需变更已经文化部批准的涉外文化艺术表演及展览项目内容，或在签订正式合同时变更已经批准的意向书内容，须在活动具体实施前３０天另行报批。"},{"i":40,"n":"第四十条","txt":"违反本规定，有下列行为之一的，由省级以上文化行政部门根据情节轻重，给予警告、罚款、暂停或取消对外文化活动资格的处罚；构成犯罪的，依法追究刑事责任： （一）未经批准，派出或邀请文化艺术表演及展览团组的； （二）未经批准，延长在国外或国内停留时间的； （三）未经批准，与外方签定演出及展览合同或进行经营性活动的； （四）倒卖项目批件的； （五）在申报项目过程中弄虚作假的； （六）从事有损国格人格演出或展览活动的； （七）造成恶劣影响或引起外交事件的。 前款规定的处罚可以并处。"},{"i":41,"n":"第四十一条","txt":"对发生第四十条情况的部门或地区，省级以上文化行政部门可以视情况，给予通报批评及暂停对外文化活动等处罚。"},{"i":42,"n":"第四十二条","txt":"对违反本规定，给国家和集体造成经济损失的，责令赔偿损失，并追究当事人和有关领导者的责任。"},{"i":43,"n":"第四十三条","txt":"对从事涉外文化艺术表演及展览活动行政管理工作中玩忽职守、徇私舞弊、滥用职权的工作人员，由主管部门视情节轻重，给予当事人和直接领导者以相应的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"涉外文化艺术表演及展览合同纠纷的解决适用中国法律。法律、法规另有规定的除外。"},{"i":45,"n":"第四十五条","txt":"有关边境省、自治区同毗邻国家边境地区的文化艺术表演及展览交流活动，按文化部有关管理办法执行。"},{"i":46,"n":"第四十六条","txt":"有关涉外文化艺术表演及展览活动的财务管理，按文化部、财政部和国家外汇管理局的有关规定执行。"},{"i":47,"n":"第四十七条","txt":"文化部以前颁发的有关规定中，凡有与本规定相抵触的内容的，以本规定为准。"},{"i":48,"n":"第四十八条","txt":"本规定由文化部负责解释。"},{"i":49,"n":"第四十九条","txt":"本规定自１９９７年８月１日起施行。"}],"wenhuabuxingzhengfuyigongzuochengxuguiding":[{"i":1,"n":"第一条","txt":"为规范文化部行政复议工作程序，提高行政复议工作质量和效率，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）、《中华人民共和国行政复议法实施条例》（以下简称《行政复议法实施条例》），结合文化部工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"文化部处理行政复议案件，适用本规定。"},{"i":3,"n":"第三条","txt":"公民、法人和其他组织对文化部和省、自治区、直辖市文化行政部门作出的具体行政行为不服，可以向文化部申请行政复议。"},{"i":4,"n":"第四条","txt":"文化部政策法规司是文化部行政复议机构，具体办理行政复议案件，履行下列职责： （一）审查行政复议申请，并决定是否受理； （二）组织行政复议案件的审查处理，向有关组织和人员调查取证，查阅文件和资料； （三）审查申请行政复议的具体行政行为是否合法与适当，拟订行政复议决定； （四）处理或转送对《行政复议法》第七条所列有关规定的审查申请； （五）办理因不服行政复议决定提起行政诉讼的应诉事项； （六）依照《行政复议法》第二十六条、第二十七条的规定转送有关行政复议申请； （七）办理《行政复议法》第二十九条规定的行政赔偿等事项； （八）按照职责权限，督促行政复议申请的受理和行政复议决定的履行； （九）办理行政复议、行政应诉案件统计和重大行政复议决定备案事项； （十）办理或者组织办理未经行政复议直接提起行政诉讼的行政应诉事项； （十一）研究行政复议工作中发现的问题，及时向有关机关提出改进建议； （十二）"},{"i":5,"n":"第五条","txt":"文化部有关司局根据行政复议案件的内容，指定专人，参与办理涉及本司局业务的行政复议案件。"},{"i":6,"n":"第六条","txt":"文化部承担行政复议工作的机构、工作人员和涉及行政复议事项的司局应当在法定时限内履行职责。"},{"i":7,"n":"第七条","txt":"文化部设立行政复议专项经费，制作启用行政复议专用章。"},{"i":8,"n":"第八条","txt":"申请人申请行政复议，可以书面申请，也可以口头申请。申请人提出口头申请，行政复议机构工作人员应当依照《行政复议法实施条例》第十九条规定的事项，当场制作行政复议申请笔录交申请人核对或者向申请人宣读，并由申请人签字确认。"},{"i":9,"n":"第九条","txt":"文化部办公厅统一接收行政复议申请，办公厅签收后应于当日转交政策法规司。 文化部其他司局收到行政复议申请，应于当日经办公厅签收后转交政策法规司。"},{"i":10,"n":"第十条","txt":"政策法规司收到行政复议申请后，应当在5日内进行审查，行政复议申请不符合《行政复议法》和《行政复议法实施条例》规定的，政策法规司应当制作《行政复议申请不予受理决定书》，加盖行政复议专用章，告知申请人；行政复议申请符合《行政复议法》和《行政复议法实施条例》的规定，但不属于文化部受理范围的，政策法规司应当制作《行政复议告知书》，加盖行政复议专用章，告知申请人向有关行政机关申请复议。 除前款规定外，行政复议申请自政策法规司收到之日起即为受理。"},{"i":11,"n":"第十一条","txt":"政策法规司可以就是否受理行政复议申请征求相关司局意见，相关司局应当在2日内提出书面答复。"},{"i":12,"n":"第十二条","txt":"行政复议申请原则上采取书面审查的办法，但申请人提出要求或政策法规司认为有必要时，可以向有关组织和人员调查情况，听取申请人、被申请人或有关当事人的意见。"},{"i":13,"n":"第十三条","txt":"对已受理的行政复议申请，政策法规司应当自收到行政复议申请之日起7日内，制作《提出答复通知书》，加盖行政复议专用章，连同《行政复议申请书》（副本）送达被申请人，被申请人应当自收到之日起10日内提出书面答复，并提交当初做出具体行政行为的证据、依据和其他有关材料。 被申请人是文化部的，由作出具体行政行为的司局按照《行政复议法》和《行政复议法实施条例》的规定提出书面答复和提供相关材料。"},{"i":14,"n":"第十四条","txt":"政策法规司收到被申请人提交的答复材料后，应当按照《行政复议法》和《行政复议法实施条例》规定的内容与方式，对案件进行全面审查。 行政复议申请材料不齐全或者表述不清楚的，政策法规司可以自收到该行政复议申请之日起5日内，将需要补正的事项和补正期限书面通知申请人。无正当理由逾期不补正的，视为申请人放弃行政复议申请，补正申请材料所用时间不计入行政复议审理期限。"},{"i":15,"n":"第十五条","txt":"对于属于相关司局业务主管范围内的行政复议案件，需要相关司局协助审查的，政策法规司应将基本案情、案件受理情况、被申请人答辩情况等内容告知相关司局，相关司局应当在收到材料后7日内，提出书面处理建议。 文化部是被申请人的不适用前款规定。"},{"i":16,"n":"第十六条","txt":"相关司局应当协助政策法规司审理属于本司局业务主管范围内的行政复议案件，参与办理因不服行政复议决定而提起的行政诉讼的应诉工作，参与办理《行政复议法》第二十九条规定的行政赔偿等事项。"},{"i":17,"n":"第十七条","txt":"申请人在申请行政复议时，依据《行政复议法》第七条规定，一并对具体行政行为所依据的规定提出审查要求，文化部有权处理的，政策法规司应当会同相关司局提出处理建议，经部领导批准后，30日内依法处理。文化部无权处理的，政策法规司应当制作《规范性文件转送函》，加盖行政复议专用章，7日内转送有权处理的行政机关处理。处理期间，中止对具体行政行为的审查。"},{"i":18,"n":"第十八条","txt":"政策法规司对被申请人的具体行政行为进行审查时，认为其依据不合法，文化部有权处理的，政策法规司应当会同相关司局提出处理建议，经部领导批准后，30日内依法处理。文化部无权处理的，政策法规司应当制作《行政复议转送函》，加盖行政复议专用章，在7日内转送有权处理的行政机关处理。处理期间，中止对具体行政行为的审查。"},{"i":19,"n":"第十九条","txt":"行政复议期间有下列情形之一，影响行政复议案件审理的，行政复议中止： （一）作为申请人的自然人死亡，其近亲属尚未确定是否参加行政复议的； （二）作为申请人的自然人丧失参加行政复议的能力，尚未确定法定代理人参加行政复议的； （三）作为申请人的法人或者其他组织中止，尚未确定权利义务承受人的； （四）作为申请人的自然人下落不明或者被宣告失踪的； （五）申请人、被申请人因不可抗力，不能参加行政复议的； （六）案件涉及法律适用问题，需要有权机关作出解释或者确认的； （七）案件审理需要以其他案件的审理结果为依据，而其他案件尚未审结的； （八）其他需要中止行政复议的情形。"},{"i":20,"n":"第二十条","txt":"根据第十七条、第十八条、第十九条规定，中止对具体行政行为审查的，政策法规司应当制作《行政复议中止通知书》，加盖行政复议专用章，送达申请人、被申请人和有关当事人。 行政复议中止的原因消除后，政策法规司应当及时恢复行政复议案件的审理。 政策法规司中止、恢复行政复议案件的审理，应当告知有关当事人。"},{"i":21,"n":"第二十一条","txt":"行政复议的和解和调解程序，分别按照《行政复议法实施条例》第四十条和第五十条的规定执行。"},{"i":22,"n":"第二十二条","txt":"文化部应当自收到行政复议申请之日起60日内作出行政复议决定，法律另有规定的除外。情况复杂，不能在规定期限内作出行政复议决定的，经部领导批准后，可以适当延长，但是延长期限最多不超过30日。 决定延长复议期限的，政策法规司应当拟定《行政复议案件复议期限延期通知书》，经部领导批准后，加盖部章，送达申请人、被申请人和有关当事人。"},{"i":23,"n":"第二十三条","txt":"政策法规司应当对被申请人作出的具体行政行为提出处理意见，依法做出行政复议决定，拟定《行政复议决定书》，经部领导批准后，加盖部章，送达申请人、被申请人和有关当事人。 政策法规司可以就复议决定征求相关司局意见，相关司局应当在5日内提出反馈意见。"},{"i":24,"n":"第二十四条","txt":"遇有疑难复杂、社会影响大或对处理意见有分歧的行政复议案件，复议决定应经部长办公会集体讨论，必要时也可进行听证。"},{"i":25,"n":"第二十五条","txt":"申请人在行政复议决定作出前自愿撤回行政复议申请的，经政策法规司同意，可以撤回。撤回行政复议申请的,行政复议终止。"},{"i":26,"n":"第二十六条","txt":"终止行政复议的，政策法规司应当制作《行政复议终止通知书》，加盖行政复议专用章，送达申请人、被申请人和有关当事人。"},{"i":27,"n":"第二十七条","txt":"文化部行政复议工作中的行政复议文书应当使用国务院法制办印发的行政复议法律文书格式文本，并统一编号。"},{"i":28,"n":"第二十八条","txt":"文化部办公厅优先安排行政复议文书印制、盖章，确保行政复议文书在法定期限内送达当事人。"},{"i":29,"n":"第二十九条","txt":"本规定关于行政复议期间的计算和行政复议文书的送达按照民事诉讼法的规定执行。"},{"i":30,"n":"第三十条","txt":"本规定中有关“2日”“5日”“7日”的规定是指工作日，不含节假日。"},{"i":31,"n":"第三十一条","txt":"本规定自2008年3月1日起施行。"}],"wenwubaohugongchengguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步加强文物保护工程的管理，根据《中华人民共和国文物保护法》和《中华人民共和国建筑法》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称文物保护工程，是指对核定为文物保护单位的和其它具有文物价值的古文化遗址、古墓葬、古建筑、石窟寺和石刻、近现代重要史迹及代表性建筑、壁画等不可移动文物进行的保护工程。"},{"i":3,"n":"第三条","txt":"文物保护工程必须遵守不改变文物原状的原则，全面地保存、延续文物的真实历史信息和价值；按照国际、国内公认的准则，保护文物本体及与之相关的历史、人文和自然环境。"},{"i":4,"n":"第四条","txt":"文物保护单位应当制定专项的总体保护规划，文物保护工程应当依据批准的规划进行。"},{"i":5,"n":"第五条","txt":"文物保护工程分为：保养维护工程、抢险加固工程、修缮工程、保护性设施建设工程、迁移工程等。 （一）保养维护工程，系指针对文物的轻微损害所作的日常性、季节性的养护。 （二）抢险加固工程，系指文物突发严重危险时，由于时间、技术、经费等条件的限制，不能进行彻底修缮而对文物采取具有可逆性的临时抢险加固措施的工程。 （三）修缮工程，系指为保护文物本体所必需的结构加固处理和维修，包括结合结构加固而进行的局部复原工程。 （四）保护性设施建设工程，系指为保护文物而附加安全防护设施的工程。 （五）迁移工程，系指因保护工作特别需要，并无其它更为有效的手段时所采取的将文物整体或局部搬迁、异地保护的工程。"},{"i":6,"n":"第六条","txt":"国家文物局负责全国文物保护工程的管理，并组织制定文物保护工程的相关规范、标准和定额。"},{"i":7,"n":"第七条","txt":"具有法人资格的文物管理或使用单位，包括经国家批准，使用文物保护单位的机关、团体、部队、学校、宗教组织和其它企事业单位，为文物保护工程的业主单位。"},{"i":8,"n":"第八条","txt":"承担文物保护工程的勘察、设计、施工、监理单位必须具有国家文物局认定的文物保护工程资质。资质认定办法和分级标准由国家文物局另行制定。"},{"i":9,"n":"第九条","txt":"文物保护工程管理主要指立项、勘察设计、施工、监理及验收管理。"},{"i":10,"n":"第十条","txt":"文物保护工程按照文物保护单位级别实行分级管理，并按以下规定履行报批程序： （一）全国重点文物保护单位保护工程，以省、自治区、直辖市文物行政部门为申报机关，国家文物局为审批机关。 （二）省、自治区、直辖市级文物保护单位保护工程以文物所在地的市、县级文物行政部门为申报机关，省、自治区、直辖市文物行政部门为审批机关。 市县级文物保护单位及未核定为文物保护单位的不可移动文物的保护工程的申报机关、审批机关由省级文物行政部门确定。"},{"i":11,"n":"第十一条","txt":"保养维护工程由文物使用单位列入每年的工作计划和经费预算，并报省、自治区、直辖市文物行政部门备案。 抢险加固工程、修缮工程、保护性设施建设工程的立项与勘察设计方案按本办法第十条的规定履行报批程序。抢险加固工程中确因情况紧急需要即刻实施的，可在实施的同时补报。 迁移工程按《中华人民共和国文物保护法》第二十条的规定获得批准后，按本办法第十条的规定报批勘察设计方案。"},{"i":12,"n":"第十二条","txt":"因特殊情况需要在原址重建已经全部毁坏的不可移动文物的，按《中华人民共和国文物保护法》第二十二条的规定获得批准后，按本办法第十条的规定报批勘察设计方案。"},{"i":13,"n":"第十三条","txt":"工程项目的立项申报资料包括以下内容： （一）工程业主单位及上级主管部门名称； （二）拟立项目名称、地点，文物保护单位级别、时代，保护范围与建设控制地带的划定、公布与执行情况； （三）保护工程必要性与实施可能性的技术文件与形象资料（录像或照片）； （四）经费估算、来源及计划工期安排； （五）拟聘请的勘察设计单位名称及资信。"},{"i":14,"n":"第十四条","txt":"已立项的文物保护工程应当申报勘察、方案设计和施工技术设计文件。重大工程要在方案获得批准后，再进行技术设计。"},{"i":15,"n":"第十五条","txt":"勘察和方案设计文件包括： （一）反映文物历史状况、固有特征和损害情况的勘察报告、实测图、照片； （二）保护工程方案、设计图及相关技术文件； （三）工程设计概算； （四）必要时应提供考古勘探发掘资料、材料试验报告书、环境污染情况报告书、工程地质和水文地质资料及勘探报告。"},{"i":16,"n":"第十六条","txt":"施工技术设计文件包括: （一）施工图； （二）设计说明书； （三）施工图预算； （四）相关材料试验报告及检测鉴定结果。"},{"i":17,"n":"第十七条","txt":"文物保护工程中的修缮工程、保护性设施建设工程和迁移工程实行招投标和工程监理。"},{"i":18,"n":"第十八条","txt":"重要文物保护工程按本办法第十条规定的程序报批招标文件及拟选用的施工单位。"},{"i":19,"n":"第十九条","txt":"文物保护工程必须遵守国家有关施工的法律、法规和规章、规范，购置的工程材料应当符合文物保护工程质量的要求。施工单位应当严格按照设计文件的要求进行施工，其工作程序为： (一)依据设计文件，编制施工方案； (二)施工人员进场前要接受文物保护相关知识的培训； (三)按文物保护工程的要求作好施工记录和施工统计文件，收集有关文物资料； (四)进行质量自检，对工程的隐蔽部分必须与业主单位、设计单位、监理单位共同检验并做好记录； (五)提交竣工资料； (六)按合同约定负责保修，保修期限自竣工验收之日起计算，除保养维护、抢险加固工程以外，不少于五年。"},{"i":20,"n":"第二十条","txt":"施工过程中如发现新的文物、有关资料或其它影响文物保护的重大问题，要立即记录，保护现场，并经原申报机关向原审批机关报告，请示处理办法。"},{"i":21,"n":"第二十一条","txt":"施工过程中如需变更或补充已批准的技术设计，由工程业主单位、设计单位和施工单位共同现场洽商，并报原申报机关备案；如需变更已批准的工程项目或方案设计中的重要内容，必须经原申报机关报审批机关批准。"},{"i":22,"n":"第二十二条","txt":"文物保护工程应当按工序分阶段验收。重大工程告一段落时，项目的审批机关应当组织或者委托有关单位进行阶段验收。"},{"i":23,"n":"第二十三条","txt":"工程竣工后，由业主单位会同设计单位、施工单位、监理单位对工程质量进行验评，并提交工程总结报告、竣工报告、竣工图纸、财务决算书及说明等资料，经原申报机关初验合格后报审批机关。项目的审批机关视工程项目的实际情况成立验收小组或者委托有关单位，组织竣工验收。"},{"i":24,"n":"第二十四条","txt":"对工程验收中发现的质量问题，由业主单位及时组织整改。"},{"i":25,"n":"第二十五条","txt":"文物保护工程的业主单位、勘察设计单位、施工单位、申报机关和审批机关应当建立有关工程行政、技术和财务文件的档案管理制度。所有工程资料应当立卷存档并归入文物保护单位记录档案。 重要工程应当在验收后三年内发表技术报告。"},{"i":26,"n":"第二十六条","txt":"文物保护工程设立优秀工程奖，具体办法由国家文物局制定。"},{"i":27,"n":"第二十七条","txt":"违反本办法、或对文物造成破坏的，按《中华人民共和国文物保护法》及国务院有关规定处罚。"},{"i":28,"n":"第二十八条","txt":"非国有不可移动文物的保护维修，参照执行本办法。"},{"i":29,"n":"第二十九条","txt":"以前发布的规章与本办法相抵触的，以本办法的规定为准。"},{"i":30,"n":"第三十条","txt":"本办法自2003年5月1日起施行。"}],"wenwucangpindingjibiaozhun":[],"wenwuxingzhengchufachengxuzanxingguiding":[{"i":1,"n":"第一条","txt":"为规范文物行政部门的行政处罚行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政处罚法》、《中华人民共和国文物保护法》及其他有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"国务院文物行政部门以及县级以上地方各级文物行政部门，对违反文物保护法律、法规的行为实施行政处罚的，适用本规定。法律、法规另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"文物行政部门实施行政处罚应当遵循以下原则： （一）以法律、法规、规章为依据； （二）遵循法定程序； （三）公正、公平地行使法律赋予的行政职权； （四）坚持处罚与教育相结合。"},{"i":4,"n":"第四条","txt":"上级文物行政部门对下级文物行政部门实施的文物行政处罚行为进行监督。上级文物行政部门对下级文物行政部门违法作出的行政处罚决定，可责令其限期改正。逾期不改正的，上级文物行政部门有权依法对违法作出的行政处罚决定予以变更或者撤销。"},{"i":5,"n":"第五条","txt":"文物行政处罚由违法行为发生地的县级以上地方文物行政部门管辖。法律、法规另有规定的除外。"},{"i":6,"n":"第六条","txt":"国务院文物行政部门督查并指导地方文物行政部门处理全国范围有重大影响的行政处罚案件。 省级文物行政部门可依据有关规定和本地区实际情况，规定辖区内的级别管辖。"},{"i":7,"n":"第七条","txt":"上级文物行政部门必要时可依法直接管辖下级文物行政部门管辖的行政处罚案件；下级文物行政部门对其管辖的行政处罚案件，认为需要由上级文物行政部门管辖时，可以报请上级文物行政部门决定。"},{"i":8,"n":"第八条","txt":"两个以上地方文物行政部门对同一违法行为均有管辖权时，应当由先立案的文物行政部门管辖。 地方文物行政部门因管辖权发生争议的，由争议双方协商解决；协商不成的，报请共同的上一级文物行政部门指定管辖，其共同的上一级文物行政部门也可以直接指定管辖。"},{"i":9,"n":"第九条","txt":"地方文物行政部门发现案件不属于本单位管辖或者主管的，应当将相关材料移送有管辖权的文物行政部门或者相关的行政部门处理，同时报上一级文物行政部门备案。受移送的文物行政部门应当将案件处理结果及时函告移送案件的文物行政部门。 受移送的文物行政部门如果认为移送不当，应当报请共同的上一级文物行政部门指定管辖，不得再次移送。"},{"i":10,"n":"第十条","txt":"文物行政部门对下列途径发现的违法案件应当及时处理： （一）在检查中发现的； （二）公民、法人及其他组织举报的； （三）上级交办的，下级报请处理的，或者有关部门移送的。"},{"i":11,"n":"第十一条","txt":"文物行政部门适用一般程序处理违法行为的，应当立案。"},{"i":12,"n":"第十二条","txt":"文物行政部门发现违法行为具有下列情形的，应当在5日内立案： （一）有明确的违法嫌疑人； （二）有客观的违法事实； （三）属于文物行政处罚的范围； （四）属于本部门管辖。 决定立案的，应当填写立案审批表，报本部门主管负责人批准，并确定两名以上文物行政执法人员为案件承办人。"},{"i":13,"n":"第十三条","txt":"文物行政执法人员在执法检查过程中，发现违法行为正在实施，情况紧急的，可以采取下列措施： （一）对违法行为予以制止或者纠正； （二）对涉案文物依法先行登记保存； （三）收集、调取其他有关证据。 文物行政执法人员应当及时将有关情况和材料报告所属文物行政部门，并办理立案手续。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的文物行政执法人员，不能被确定为案件承办人： （一）是案件当事人或者当事人近亲属的； （二）与案件有直接利害关系的； （三）与案件当事人有其他关系，可能影响案件公正处理的。 案件承办人具有上述情形之一的，应当自行申请回避。当事人认为案件承办人符合上述情形之一时，可以向文物行政部门申请回避。案件承办人的回避由本部门主管负责人决定。"},{"i":15,"n":"第十五条","txt":"案件立案后，案件承办人应当及时收集、调取证据。"},{"i":16,"n":"第十六条","txt":"案件承办人调查案件，不得少于两人。案件承办人在调查取证时，应当出示执法证件。 对涉及国家机密、商业秘密和个人隐私的，案件承办人应当保守秘密。"},{"i":17,"n":"第十七条","txt":"案件承办人可以对当事人及证明人进行询问。询问应当单独进行。询问前应当告知其如实陈述事实、提供证据。 询问应当制作笔录，并交被询问人核对；对没有阅读能力的，应当向其宣读。笔录如有差错、遗漏，应当允许其更正或者补充。经核对无误后，由被询问人逐页在笔录上签名或者盖章。案件承办人也应当在笔录上签名。被询问人拒绝签名或者盖章的，案件承办人应当在笔录上注明。"},{"i":18,"n":"第十八条","txt":"案件承办人进行现场检查时，当事人应当在场。案件承办人应当制作现场检查笔录，当事人应当签名并注明对该笔录真实性的意见；当事人拒绝到场或者签名的，应当由案件承办人在现场笔录中注明。"},{"i":19,"n":"第十九条","txt":"案件承办人可以要求当事人及证明人提供相关证明材料，并由材料提供人在有关材料上签名或者盖章。材料提供人拒绝签名或者盖章的，案件承办人应当在材料上注明。"},{"i":20,"n":"第二十条","txt":"案件承办人调取的证据应当是原件、原物。调取原件、原物确有困难的，可由提交证据复制品的单位或者个人在复制品上盖章或者签名，并注明“与原件（物）相同”字样或者文字说明。"},{"i":21,"n":"第二十一条","txt":"在证据可能灭失，或者以后难以取得的情况下，案件承办人应当填写先行登记保存证据审批表，报本部门主管负责人批准。先行登记保存证据时，案件承办人应当向当事人出具先行登记保存证据通知书。"},{"i":22,"n":"第二十二条","txt":"文物行政部门实施先行登记保存证据时，应当有当事人在场。当事人拒绝到场的，案件承办人可以邀请有关人员参加。 对先行登记保存的证据应当开列物品清单，由案件承办人、当事人或者其他有关人员签名或者盖章。 当事人拒绝签名、盖章或者接收物品清单的，应当由案件承办人在清单上签名并注明情况。"},{"i":23,"n":"第二十三条","txt":"对于先行登记保存的证据，应当在7日内作出处理决定： （一）需要进行技术检验或者鉴定的，送交检验或者鉴定； （二）依法不需要没收的物品，退还当事人； （三）依法应当移交有关部门处理的，移交有关部门。 法律另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"文物行政部门在处理案件过程中，需要委托其他文物行政部门调查的，应当出具文物执法调查委托书。受委托的文物行政部门应当积极完成调查工作。"},{"i":25,"n":"第二十五条","txt":"对案件处理过程中需要解决的专业性问题，文物行政部门应当委托专门机构或者聘请专业人员提出意见。 文物的鉴定，应当以办理案件的文物行政部门所在地省级文物鉴定机构的鉴定意见为准。国家文物鉴定机构可以根据办理案件的文物行政部门的申请，对省级文物鉴定机构的鉴定意见进行复核。"},{"i":26,"n":"第二十六条","txt":"对于违法事实清楚、证据确凿，依法应当作出下列行政处罚的，可以当场作出行政处罚决定： （一）警告； （二）对公民处以50元以下罚款； （三）对法人或者其他组织处以1000元以下罚款。"},{"i":27,"n":"第二十七条","txt":"文物行政执法人员当场作出行政处罚决定的，应当向当事人出示执法证件，并填写加盖文物行政部门公章的当场处罚决定书。 当场处罚决定书应当载明当事人的违法行为，行政处罚依据（适用的法律、法规、规章名称及具体条款），具体处罚的内容、时间、地点，不服行政处罚决定申请行政复议或者提起行政诉讼的途径，以及文物行政部门名称等内容。 当场处罚决定书由文物行政执法人员填写并签名后，当场交付当事人。"},{"i":28,"n":"第二十八条","txt":"文物行政执法人员当场作出的行政处罚决定，应当报所属文物行政部门备案。"},{"i":29,"n":"第二十九条","txt":"违法行为经立案并调查终结后，案件承办人应当制作调查终结报告，报文物行政部门负责人审查。"},{"i":30,"n":"第三十条","txt":"办理案件的文物行政部门负责人对调查结果进行审查，根据不同情况分别作出如下决定： （一）确有应当受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不得给予行政处罚； （四）违法行为已构成犯罪的，移送司法机关。 对情节复杂或者重大违法行为给予较重的行政处罚，文物行政部门的负责人应当集体讨论决定。"},{"i":31,"n":"第三十一条","txt":"文物行政部门拟作出行政处罚决定的，应当由本部门负责人签发行政处罚告知书。行政处罚告知书应当载明拟作出行政处罚决定的事实、理由和依据，并告知当事人依法享有的陈述权、申辩权和其他权利。"},{"i":32,"n":"第三十二条","txt":"当事人要求陈述、申辩的，应当在收到行政处罚告知书后3日内，向文物行政部门提出陈述、申辩意见以及相应的事实、理由。当事人在此期间未行使陈述权、申辩权的，视为放弃权利。当事人放弃权利的，由文物行政部门负责人签发行政处罚决定书，并送达当事人。"},{"i":33,"n":"第三十三条","txt":"案件承办人应当充分听取当事人的陈述、申辩意见，对当事人提出的事实、理由进行复核，并向文物行政部门负责人提交复核报告。 案件承办人不得因当事人的申辩加重对当事人的处罚。"},{"i":34,"n":"第三十四条","txt":"文物行政部门负责人根据复核情况作出最终决定，并签发行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规或者规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出行政处罚决定的文物行政部门名称和作出决定的日期。 行政处罚决定书应当加盖作出行政处罚决定的文物行政部门的印章。"},{"i":35,"n":"第三十五条","txt":"文物行政部门作出责令停产停业、吊销许可证或者执照、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利；当事人要求听证的，文物行政部门应当组织听证。 地方文物行政部门对较大数额罚款的界定，依照当地省级人大常委会或者人民政府的具体规定执行。"},{"i":36,"n":"第三十六条","txt":"文物行政部门对于符合听证程序条件的案件，应当在作出行政处罚决定前,向当事人送达听证通知。"},{"i":37,"n":"第三十七条","txt":"当事人在收到听证通知后3日内提出听证要求的，文物行政部门应当在当事人提出听证要求之日起3日内确定听证人员的组成、听证时间、地点和方式，并在举行听证7日前通知当事人。"},{"i":38,"n":"第三十八条","txt":"除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":39,"n":"第三十九条","txt":"文物行政部门主管负责人应当指定本部门非本案承办人员担任听证主持人和书记员。 当事人认为听证主持人和书记员与本案有利害关系的，有权申请回避。听证主持人和书记员的回避由文物行政部门主管负责人决定。"},{"i":40,"n":"第四十条","txt":"当事人收到听证通知后，应当按时参加听证，也可以委托1至2人代理听证。委托他人代理听证的，应当向听证主持人提交由当事人签名或者盖章的委托书。 当事人无正当理由不按时参加听证的，视为放弃听证要求。"},{"i":41,"n":"第四十一条","txt":"举行听证时，案件承办人应当提出当事人违法的事实、证据和行政处罚建议；当事人可以进行申辩和质证。"},{"i":42,"n":"第四十二条","txt":"举行听证应当制作听证笔录。听证笔录应当载明下列事项： （一）案由； （二）听证参加人姓名或者名称、地址； （三）听证主持人、书记员姓名； （四）举行听证的时间、地点； （五）案件承办人提出的事实、证据和行政处罚建议； （六）当事人陈述、申辩和质证的内容； （七）听证参加人签名或者盖章。 听证结束后，听证笔录应当交当事人和案件承办人审核无误后签名或者盖章。当事人拒绝签名或者盖章的，应当在听证笔录上注明。"},{"i":43,"n":"第四十三条","txt":"听证结束后，文物行政部门依照本规定第三十条的规定，作出决定。"},{"i":44,"n":"第四十四条","txt":"行政处罚决定书应当当场交付当事人；当事人不在场的，文物行政部门应当依照民事诉讼法的有关规定在7日内送达当事人。"},{"i":45,"n":"第四十五条","txt":"行政处罚决定书送达后，当事人应当在规定期限内对处罚决定予以履行。 当事人确有经济困难，需要延期或者分期缴纳罚款的，经当事人提出书面申请，报文物行政部门负责人批准。"},{"i":46,"n":"第四十六条","txt":"作出罚款和没收违法所得决定的文物行政部门应当与收缴罚没款的机构分离。除按规定当场收缴的罚款外，文物行政执法人员不得自行收缴罚没款。"},{"i":47,"n":"第四十七条","txt":"当场作出行政处罚决定，有下列情形之一的，文物行政执法人员可以当场收缴罚款： （一）依法给予20元以下罚款的； （二）不当场收缴事后难以执行的。"},{"i":48,"n":"第四十八条","txt":"在边远、水上、交通不便地区，文物行政执法人员依照本规定作出罚款决定后，当事人向指定的银行缴纳罚款确有困难，经当事人提出，文物行政执法人员可以当场收缴罚款。"},{"i":49,"n":"第四十九条","txt":"文物行政执法人员当场收缴罚款的，应当向当事人出具省级财政部门统一制发的罚款收据。 文物行政执法人员当场收缴的罚款，应当自收缴罚款之日起2日内交至文物行政部门；文物行政部门应当在2日内将罚款缴付指定的银行。"},{"i":50,"n":"第五十条","txt":"当事人逾期不履行行政处罚决定的，文物行政部门应当申请人民法院强制执行。"},{"i":51,"n":"第五十一条","txt":"行政处罚决定履行或者执行后，案件承办人应当填写结案报告，报文物行政部门负责人批准。"},{"i":52,"n":"第五十二条","txt":"行政处罚决定执行完毕后，文物行政部门应当及时将案件材料立卷归档。"},{"i":53,"n":"第五十三条","txt":"本规定自发布之日起施行。"}],"wenwurendingguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范文物认定管理工作，根据《中华人民共和国文物保护法》制定本办法。 本办法所称文物认定，是指文物行政部门将具有历史、艺术、科学价值的文化资源确认为文物的行政行为。"},{"i":2,"n":"第二条","txt":"《中华人民共和国文物保护法》第二条第一款所列各项，应当认定为文物。 乡土建筑、工业遗产、农业遗产、商业老字号、文化线路、文化景观等特殊类型文物，按照本办法认定。"},{"i":3,"n":"第三条","txt":"认定文物，由县级以上地方文物行政部门负责。认定文物发生争议的，由省级文物行政部门作出裁定。 省级文物行政部门应当根据国务院文物行政部门的要求，认定特定的文化资源为文物。"},{"i":4,"n":"第四条","txt":"国务院文物行政部门应当定期发布指导意见，明确文物认定工作的范围和重点。"},{"i":5,"n":"第五条","txt":"各级文物行政部门应当定期组织开展文物普查，并由县级以上地方文物行政部门对普查中发现的文物予以认定。 各级文物行政部门应当完善制度，鼓励公民、法人和其他组织在文物普查工作中发挥作用。"},{"i":6,"n":"第六条","txt":"所有权人或持有人书面要求认定文物的，应当向县级以上地方文物行政部门提供其姓名或者名称、住所、有效身份证件号码或者有效证照号码，以及认定对象的来源说明。县级以上地方文物行政部门应当作出决定并予以答复。 县级以上地方文物行政部门应当告知文物所有权人或持有人依法承担的文物保护责任。 县级以上地方文物行政部门应当整理并保存上述工作的文件和资料。"},{"i":7,"n":"第七条","txt":"公民、法人和其他组织书面要求认定不可移动文物的，应当向县级以上地方文物行政部门提供其姓名或者名称、住所、有效身份证件号码或者有效证照号码。县级以上地方文物行政部门应当通过听证会等形式听取公众意见并作出决定予以答复。"},{"i":8,"n":"第八条","txt":"县级以上地方文物行政部门认定文物，应当开展调查研究，收集相关资料，充分听取专家意见，召集专门会议研究并作出书面决定。 县级以上地方文物行政部门可以委托或设置专门机构开展认定文物的具体工作。"},{"i":9,"n":"第九条","txt":"不可移动文物的认定，自县级以上地方文物行政部门公告之日起生效。 可移动文物的认定，自县级以上地方文物行政部门作出决定之日起生效。列入文物收藏单位藏品档案的文物，自主管的文物行政部门备案之日起生效。"},{"i":10,"n":"第十条","txt":"各级文物行政部门应当根据《中华人民共和国文物保护法》第三条的规定，组织开展经常性的文物定级工作。"},{"i":11,"n":"第十一条","txt":"文物收藏单位收藏文物的定级，由主管的文物行政部门备案确认。 文物行政部门应当建立民间收藏文物定级的工作机制，组织开展民间收藏文物的定级工作。定级的民间收藏文物，由主管的地方文物行政部门备案。"},{"i":12,"n":"第十二条","txt":"公民、法人和其他组织，以及所有权人书面要求对不可移动文物进行定级的，应当向有关文物行政部门提供其姓名或者名称、住所、有效身份证件号码或者有效证照号码。有关文物行政部门应当通过听证会等形式听取公众意见并予以答复。"},{"i":13,"n":"第十三条","txt":"对文物认定和定级决定不服的，可以依法申请行政复议。"},{"i":14,"n":"第十四条","txt":"国家实行文物登录制度，由县级以上文物行政部门委托或设置专门机构开展相关工作。 文物登录，应当对各类文物分别制定登录指标体系。登录指标体系应当满足文物保护、研究和公众教育等需要。 根据私有文物所有权人的要求，文物登录管理机构应当对其身份予以保密。"},{"i":15,"n":"第十五条","txt":"违反本办法规定，造成文物破坏的，对负有责任的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"古猿化石、古人类化石、与人类活动有关的第四纪古脊椎动物化石，以及上述化石地点和遗迹地点的认定和定级工作，按照本办法的规定执行。 历史文化名城、街区及村镇的认定和定级工作，按照有关法律法规的规定执行。"},{"i":17,"n":"第十七条","txt":"本办法自2009年10月1日起施行。"}],"wenwujinchujingshenheguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对文物进出境审核的管理，根据《中华人民共和国文物保护法》和《中华人民共和国文物保护法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家文物局负责文物进出境审核管理工作，指定文物进出境审核机构承担文物进出境审核工作。 文物进出境审核机构是文物行政执法机构，依法独立行使职权，向国家文物局汇报工作，接受国家文物局业务指导。"},{"i":3,"n":"第三条","txt":"文物进出境审核机构由国家文物局和省级人民政府联合组建。省级人民政府应当保障文物进出境审核机构的编制、办公场所及工作经费。国家文物局应当对文物进出境审核机构的业务经费予以补助。"},{"i":4,"n":"第四条","txt":"文物进出境审核机构应当具备以下条件： （一）有7名以上专职文物鉴定人员，其中文物进出境责任鉴定员不少于5名； （二）有固定的办公场所和必要的技术设备； （三）工作经费全额纳入财政预算。"},{"i":5,"n":"第五条","txt":"国家文物局根据文物进出境审核工作的需要，指定具备条件的文物进出境审核机构承担文物进出境审核工作，使用文物出境标识和文物临时进境标识，对允许出境的文物发放文物出境许可证。"},{"i":6,"n":"第六条","txt":"文物进出境审核机构的工作人员实行持证上岗制度，不得在文物商店或者拍卖企业任职、兼职。文物进出境审核机构的主要负责人应当取得国家文物局颁发的资格证书。 文物进出境责任鉴定员应当取得大学本科以上学历和文物博物专业中级以上职称，并经国家文物局考核合格。"},{"i":7,"n":"第七条","txt":"文物进出境审核机构的日常管理工作由所在地省级文物主管部门负责。省级文物主管部门应当制定相关管理制度，并报国家文物局备案。 文物进出境审核机构应当采取措施，保证审核工作高效公正。"},{"i":8,"n":"第八条","txt":"下列文物出境，应当经过审核： （一）1949年（含）以前的各类艺术品、工艺美术品； （二）1949年（含）以前的手稿、文献资料和图书资料； （三）1949年（含）以前的与各民族社会制度、社会生产、社会生活有关的实物； （四）1949年以后的与重大事件或著名人物有关的代表性实物； （五）1949年以后的反映各民族生产活动、生活习俗、文化艺术和宗教信仰的代表性实物； （六）国家文物局公布限制出境的已故现代著名书画家、工艺美术家作品； （七）古猿化石、古人类化石，以及与人类活动有关的第四纪古脊椎动物化石。 文物出境审核标准，由国家文物局定期修订并公布。"},{"i":9,"n":"第九条","txt":"运送、邮寄、携带文物出境，应当在文物出境前填写文物出境申请表，报文物进出境审核机构审核。 文物进出境审核机构应当自收到文物出境申请之日起15个工作日内作出是否允许出境的审核意见。"},{"i":10,"n":"第十条","txt":"文物进出境审核机构审核文物，应当有3名以上专职文物鉴定人员参加，其中文物进出境责任鉴定员不得少于2名。 文物出境许可证，由参加审核的文物进出境责任鉴定员共同签署。文物进出境责任鉴定员一致同意允许出境的文物，文物进出境审核机构方可加盖文物出境审核专用章。"},{"i":11,"n":"第十一条","txt":"经审核允许出境的文物，由文物进出境审核机构标明文物出境标识，发放文物出境许可证。海关查验文物出境标识后，凭文物出境许可证放行。 文物出境许可证一式三联，第一联由文物进出境审核机构留存，第二联由文物出境地海关留存，第三联由文物出境携运人留存。 经审核不允许出境的文物，由文物进出境审核机构登记并发还。 根据出境地海关或携运人的要求，文物进出境审核机构可以为经审核属于文物复仿制品的申报物品出具文物复仿制品证明。"},{"i":12,"n":"第十二条","txt":"因修复、展览、销售、鉴定等原因临时进境的文物，经海关加封后，报文物进出境审核机构审核、登记。文物进出境审核机构查验海关封志完好无损后，对每件临时进境文物进行审核，标明文物临时进境标识并登记。 临时进境文物复出境时，应向原审核、登记的文物进出境审核机构申报。文物进出境审核机构应对照进境记录审核查验，确认文物临时进境标识无误后，标明文物出境标识，发给文物出境许可证。"},{"i":13,"n":"第十三条","txt":"临时进境文物在境内滞留时间，除经海关和文物进出境审核机构批准外，不得超过6个月。 临时进境文物滞留境内逾期复出境，依照文物出境审核标准和程序进行审核。"},{"i":14,"n":"第十四条","txt":"因展览、科研等原因临时出境的文物，出境前应向文物进出境审核机构申报。文物进出境审核机构应当按国家文物局的批准文件办理审核登记手续。 临时出境文物复进境时，由原审核登记的文物进出境审核机构审核查验。"},{"i":15,"n":"第十五条","txt":"文物进出境审核机构在审核文物过程中，发现涉嫌非法持有文物或文物流失问题的，应立即向公安机关和国家文物局报告。"},{"i":16,"n":"第十六条","txt":"文物出境标识、文物临时进境标识和文物出境许可证，由文物进出境审核机构指定专人保管。使用上述物品，由文物进出境审核机构负责人签字确认。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，造成文物流失的，依据有关规定追究责任人的责任。"},{"i":18,"n":"第十八条","txt":"文物出境标识、文物临时进境标识、文物出境许可证、文物复仿制品证明和文物出境申请表，由国家文物局统一制作。"},{"i":19,"n":"第十九条","txt":"尚未组建文物进出境审核机构的省、自治区、直辖市，应当根据本办法的规定组建文物进出境审核机构；组建前的文物进出境审核工作由国家文物局指定文物进出境审核机构承担。"},{"i":20,"n":"第二十条","txt":"本办法自公布之日起施行，1989年文化部发布的《文物出境鉴定管理办法》同日废止。"}],"lvyouanquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强旅游安全管理，提高应对旅游突发事件的能力，保障旅游者的人身、财产安全，促进旅游业持续健康发展，根据《中华人民共和国旅游法》、《中华人民共和国安全生产法》、《中华人民共和国突发事件应对法》、《旅行社条例》和《生产安全事故报告和调查处理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"旅游经营者的安全生产、旅游主管部门的安全监督管理，以及旅游突发事件的应对，应当遵守有关法律、法规和本办法的规定。 本办法所称旅游经营者，是指旅行社及地方性法规规定旅游主管部门负有行业监管职责的景区和饭店等单位。"},{"i":3,"n":"第三条","txt":"各级旅游主管部门应当在同级人民政府的领导和上级旅游主管部门及有关部门的指导下，在职责范围内，依法对旅游安全工作进行指导、防范、监管、培训、统计分析和应急处理。"},{"i":4,"n":"第四条","txt":"旅游经营者应当承担旅游安全的主体责任，加强安全管理，建立、健全安全管理制度，关注安全风险预警和提示，妥善应对旅游突发事件。 旅游从业人员应当严格遵守本单位的安全管理制度，接受安全生产教育和培训，增强旅游突发事件防范和应急处理能力。"},{"i":5,"n":"第五条","txt":"旅游主管部门、旅游经营者及其从业人员应当依法履行旅游突发事件报告义务。"},{"i":6,"n":"第六条","txt":"旅游经营者应当遵守下列要求： （一）服务场所、服务项目和设施设备符合有关安全法律、法规和强制性标准的要求； （二）配备必要的安全和救援人员、设施设备； （三）建立安全管理制度和责任体系； （四）保证安全工作的资金投入。"},{"i":7,"n":"第七条","txt":"旅游经营者应当定期检查本单位安全措施的落实情况，及时排除安全隐患；对可能发生的旅游突发事件及采取安全防范措施的情况，应当按照规定及时向所在地人民政府或者人民政府有关部门报告。"},{"i":8,"n":"第八条","txt":"旅游经营者应当对其提供的产品和服务进行风险监测和安全评估，依法履行安全风险提示义务，必要时应当采取暂停服务、调整活动内容等措施。 经营高风险旅游项目或者向老年人、未成年人、残疾人提供旅游服务的，应当根据需要采取相应的安全保护措施。"},{"i":9,"n":"第九条","txt":"旅游经营者应当对从业人员进行安全生产教育和培训，保证从业人员掌握必要的安全生产知识、规章制度、操作规程、岗位技能和应急处理措施，知悉自身在安全生产方面的权利和义务。 旅游经营者建立安全生产教育和培训档案，如实记录安全生产教育和培训的时间、内容、参加人员以及考核结果等情况。 未经安全生产教育和培训合格的旅游从业人员，不得上岗作业；特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格。"},{"i":10,"n":"第十条","txt":"旅游经营者应当主动询问与旅游活动相关的个人健康信息，要求旅游者按照明示的安全规程，使用旅游设施和接受服务，并要求旅游者对旅游经营者采取的安全防范措施予以配合。"},{"i":11,"n":"第十一条","txt":"旅行社组织和接待旅游者，应当合理安排旅游行程，向合格的供应商订购产品和服务。 旅行社及其从业人员发现履行辅助人提供的服务不符合法律、法规规定或者存在安全隐患的，应当予以制止或者更换。"},{"i":12,"n":"第十二条","txt":"旅行社组织出境旅游，应当制作安全信息卡。 安全信息卡应当包括旅游者姓名、出境证件号码和国籍，以及紧急情况下的联系人、联系方式等信息，使用中文和目的地官方语言（或者英文）填写。 旅行社应当将安全信息卡交由旅游者随身携带，并告知其自行填写血型、过敏药物和重大疾病等信息。"},{"i":13,"n":"第十三条","txt":"旅游经营者应当依法制定旅游突发事件应急预案，与所在地县级以上地方人民政府及其相关部门的应急预案相衔接，并定期组织演练。"},{"i":14,"n":"第十四条","txt":"旅游突发事件发生后，旅游经营者及其现场人员应当采取合理、必要的措施救助受害旅游者，控制事态发展，防止损害扩大。 旅游经营者应当按照履行统一领导职责或者组织处置突发事件的人民政府的要求，配合其采取的应急处置措施，并参加所在地人民政府组织的应急救援和善后处置工作。 旅游突发事件发生在境外的，旅行社及其领队应当在中国驻当地使领馆或者政府派出机构的指导下，全力做好突发事件应对处置工作。"},{"i":15,"n":"第十五条","txt":"旅游突发事件发生后，旅游经营者的现场人员应当立即向本单位负责人报告，单位负责人接到报告后，应当于1小时内向发生地县级旅游主管部门、安全生产监督管理部门和负有安全生产监督管理职责的其他相关部门报告；旅行社负责人应当同时向单位所在地县级以上地方旅游主管部门报告。 情况紧急或者发生重大、特别重大旅游突发事件时，现场有关人员可直接向发生地、旅行社所在地县级以上旅游主管部门、安全生产监督管理部门和负有安全生产监督管理职责的其他相关部门报告。 旅游突发事件发生在境外的，旅游团队的领队应当立即向当地警方、中国驻当地使领馆或者政府派出机构，以及旅行社负责人报告。旅行社负责人应当在接到领队报告后1小时内，向单位所在地县级以上地方旅游主管部门报告。"},{"i":16,"n":"第十六条","txt":"国家建立旅游目的地安全风险（以下简称风险）提示制度。 根据可能对旅游者造成的危害程度、紧急程度和发展态势，风险提示级别分为一级（特别严重）、二级（严重）、三级（较重）和四级（一般），分别用红色、橙色、黄色和蓝色标示。 风险提示级别的划分标准，由国家旅游局会同外交、卫生、公安、国土、交通、气象、地震和海洋等有关部门制定或者确定。"},{"i":17,"n":"第十七条","txt":"风险提示信息，应当包括风险类别、提示级别、可能影响的区域、起始时间、注意事项、应采取的措施和发布机关等内容。 一级、二级风险的结束时间能够与风险提示信息内容同时发布的，应当同时发布；无法同时发布的，待风险消失后通过原渠道补充发布。 三级、四级风险提示可以不发布风险结束时间，待风险消失后自然结束。"},{"i":18,"n":"第十八条","txt":"风险提示发布后，旅行社应当根据风险级别采取下列措施： （一）四级风险的，加强对旅游者的提示； （二）三级风险的，采取必要的安全防范措施； （三）二级风险的，停止组团或者带团前往风险区域；已在风险区域的，调整或者中止行程； （四）一级风险的，停止组团或者带团前往风险区域，组织已在风险区域的旅游者撤离。 其他旅游经营者应当根据风险提示的级别，加强对旅游者的风险提示，采取相应的安全防范措施，妥善安置旅游者，并根据政府或者有关部门的要求，暂停或者关闭易受风险危害的旅游项目或者场所。"},{"i":19,"n":"第十九条","txt":"风险提示发布后，旅游者应当关注相关风险，加强个人安全防范，并配合国家应对风险暂时限制旅游活动的措施，以及有关部门、机构或者旅游经营者采取的安全防范和应急处置措施。"},{"i":20,"n":"第二十条","txt":"国家旅游局负责发布境外旅游目的地国家（地区），以及风险区域范围覆盖全国或者跨省级行政区域的风险提示。发布一级风险提示的，需经国务院批准；发布境外旅游目的地国家（地区）风险提示的，需经外交部门同意。 地方各级旅游主管部门应当及时转发上级旅游主管部门发布的风险提示，并负责发布前款规定之外涉及本辖区的风险提示。"},{"i":21,"n":"第二十一条","txt":"风险提示信息应当通过官方网站、手机短信及公众易查阅的媒体渠道对外发布。一级、二级风险提示应同时通报有关媒体。"},{"i":22,"n":"第二十二条","txt":"旅游主管部门应当加强下列旅游安全日常管理工作： （一）督促旅游经营者贯彻执行安全和应急管理的有关法律、法规，并引导其实施相关国家标准、行业标准或者地方标准，提高其安全经营和突发事件应对能力； （二）指导旅游经营者组织开展从业人员的安全及应急管理培训，并通过新闻媒体等多种渠道，组织开展旅游安全及应急知识的宣传普及活动； （三）统计分析本行政区域内发生旅游安全事故的情况； （四）法律、法规规定的其他旅游安全管理工作。 旅游主管部门应当加强对星级饭店和A级景区旅游安全和应急管理工作的指导。"},{"i":23,"n":"第二十三条","txt":"地方各级旅游主管部门应当根据有关法律、法规的规定，制定、修订本地区或者本部门旅游突发事件应急预案，并报上一级旅游主管部门备案，必要时组织应急演练。"},{"i":24,"n":"第二十四条","txt":"地方各级旅游主管部门应当在当地人民政府的领导下，依法对景区符合安全开放条件进行指导，核定或者配合相关景区主管部门核定景区最大承载量，引导景区采取门票预约等方式控制景区流量；在旅游者数量可能达到最大承载量时，配合当地人民政府采取疏导、分流等措施。"},{"i":25,"n":"第二十五条","txt":"旅游突发事件发生后，发生地县级以上旅游主管部门应当根据同级人民政府的要求和有关规定，启动旅游突发事件应急预案，并采取下列一项或者多项措施： （一）组织或者协同、配合相关部门开展对旅游者的救助及善后处置，防止次生、衍生事件； （二）协调医疗、救援和保险等机构对旅游者进行救助及善后处置； （三）按照同级人民政府的要求，统一、准确、及时发布有关事态发展和应急处置工作的信息，并公布咨询电话。"},{"i":26,"n":"第二十六条","txt":"旅游突发事件发生后，发生地县级以上旅游主管部门应当根据同级人民政府的要求和有关规定，参与旅游突发事件的调查，配合相关部门依法对应当承担事件责任的旅游经营者及其责任人进行处理。"},{"i":27,"n":"第二十七条","txt":"各级旅游主管部门应当建立旅游突发事件报告制度。"},{"i":28,"n":"第二十八条","txt":"旅游主管部门在接到旅游经营者依据本办法第十五条规定的报告后，应当向同级人民政府和上级旅游主管部门报告。一般旅游突发事件上报至设区的市级旅游主管部门；较大旅游突发事件逐级上报至省级旅游主管部门；重大和特别重大旅游突发事件逐级上报至国家旅游局。向上级旅游主管部门报告旅游突发事件，应当包括下列内容： （一）事件发生的时间、地点、信息来源； （二）简要经过、伤亡人数、影响范围； （三）事件涉及的旅游经营者、其他有关单位的名称； （四）事件发生原因及发展趋势的初步判断； （五）采取的应急措施及处置情况； （六）需要支持协助的事项； （七）报告人姓名、单位及联系电话。 前款所列内容暂时无法确定的，应当先报告已知情况；报告后出现新情况的，应当及时补报、续报。"},{"i":29,"n":"第二十九条","txt":"各级旅游主管部门应当建立旅游突发事件信息通报制度。旅游突发事件发生后，旅游主管部门应当及时将有关信息通报相关行业主管部门。"},{"i":30,"n":"第三十条","txt":"旅游突发事件处置结束后，发生地旅游主管部门应当及时查明突发事件的发生经过和原因，总结突发事件应急处置工作的经验教训，制定改进措施，并在30日内按照下列程序提交总结报告： （一）一般旅游突发事件向设区的市级旅游主管部门提交； （二）较大旅游突发事件逐级向省级旅游主管部门提交； （三）重大和特别重大旅游突发事件逐级向国家旅游局提交。 旅游团队在境外遇到突发事件的，由组团社所在地旅游主管部门提交总结报告。"},{"i":31,"n":"第三十一条","txt":"省级旅游主管部门应当于每月5日前，将本地区上月发生的较大旅游突发事件报国家旅游局备案，内容应当包括突发事件发生的时间、地点、原因及事件类型和伤亡人数等。"},{"i":32,"n":"第三十二条","txt":"县级以上地方各级旅游主管部门应当定期统计分析本行政区域内发生旅游突发事件的情况，并于每年1月底前将上一年度相关情况逐级报国家旅游局。"},{"i":33,"n":"第三十三条","txt":"旅游经营者及其主要负责人、旅游从业人员违反法律、法规有关安全生产和突发事件应对规定的，依照相关法律、法规处理。"},{"i":34,"n":"第三十四条","txt":"旅行社违反本办法第十一条第二款的规定，未制止履行辅助人的非法、不安全服务行为，或者未更换履行辅助人的，由旅游主管部门给予警告，可并处2000元以下罚款；情节严重的，处2000元以上10000元以下罚款。"},{"i":35,"n":"第三十五条","txt":"旅行社违反本办法第十二条的规定，不按要求制作安全信息卡，未将安全信息卡交由旅游者，或者未告知旅游者相关信息的，由旅游主管部门给予警告，可并处2000元以下罚款；情节严重的，处2000元以上10000元以下罚款。"},{"i":36,"n":"第三十六条","txt":"旅行社违反本办法第十八条规定，不采取相应措施的，由旅游主管部门处2000元以下罚款；情节严重的，处2000元以上10000元以下罚款。"},{"i":37,"n":"第三十七条","txt":"按照旅游业国家标准、行业标准评定的旅游经营者违反本办法规定的，由旅游主管部门建议评定组织依据相关标准作出处理。"},{"i":38,"n":"第三十八条","txt":"旅游主管部门及其工作人员违反相关法律、法规及本办法规定，玩忽职守，未履行安全管理职责的，由有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":39,"n":"第三十九条","txt":"本办法所称旅游突发事件，是指突然发生，造成或者可能造成旅游者人身伤亡、财产损失，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和社会安全事件。 根据旅游突发事件的性质、危害程度、可控性以及造成或者可能造成的影响，旅游突发事件一般分为特别重大、重大、较大和一般四级。"},{"i":40,"n":"第四十条","txt":"本办法所称特别重大旅游突发事件，是指下列情形： （一）造成或者可能造成人员死亡（含失踪）30人以上或者重伤100人以上； （二）旅游者500人以上滞留超过24小时,并对当地生产生活秩序造成严重影响； （三）其他在境内外产生特别重大影响，并对旅游者人身、财产安全造成特别重大威胁的事件。"},{"i":41,"n":"第四十一条","txt":"本办法所称重大旅游突发事件，是指下列情形： （一）造成或者可能造成人员死亡（含失踪）10人以上、30人以下或者重伤50人以上、100人以下； （二）旅游者200人以上滞留超过24小时,对当地生产生活秩序造成较严重影响； （三）其他在境内外产生重大影响，并对旅游者人身、财产安全造成重大威胁的事件。"},{"i":42,"n":"第四十二条","txt":"本办法所称较大旅游突发事件，是指下列情形： （一）造成或者可能造成人员死亡（含失踪）3人以上10人以下或者重伤10人以上、50人以下； （二）旅游者50人以上、200人以下滞留超过24小时,并对当地生产生活秩序造成较大影响； （三）其他在境内外产生较大影响，并对旅游者人身、财产安全造成较大威胁的事件。"},{"i":43,"n":"第四十三条","txt":"本办法所称一般旅游突发事件，是指下列情形： （一）造成或者可能造成人员死亡（含失踪）3人以下或者重伤10人以下； （二）旅游者50人以下滞留超过24小时,并对当地生产生活秩序造成一定影响； （三）其他在境内外产生一定影响，并对旅游者人身、财产安全造成一定威胁的事件。"},{"i":44,"n":"第四十四条","txt":"本办法所称的“以上”包括本数；除第三十四条、第三十五条、第三十六条的规定外，所称的“以下”不包括本数。"},{"i":45,"n":"第四十五条","txt":"本办法自2016年12月1日起施行。国家旅游局1990年2月20日发布的《旅游安全管理暂行办法》同时废止。"}],"lvyoutousuchulibanfa-2":[{"i":1,"n":"第一条","txt":"为了维护旅游者和旅游经营者的合法权益，依法公正处理旅游投诉，依据《中华人民共和国消费者权益保护法》、《旅行社条例》、《导游人员管理条例》和《中国公民出国旅游管理办法》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称旅游投诉，是指旅游者认为旅游经营者损害其合法权益，请求旅游行政管理部门、旅游质量监督管理机构或者旅游执法机构（以下统称“旅游投诉处理机构”），对双方发生的民事争议进行处理的行为。"},{"i":3,"n":"第三条","txt":"旅游投诉处理机构应当在其职责范围内处理旅游投诉。 地方各级旅游行政主管部门应当在本级人民政府的领导下，建立、健全相关行政管理部门共同处理旅游投诉的工作机制。"},{"i":4,"n":"第四条","txt":"旅游投诉处理机构在处理旅游投诉中，发现被投诉人或者其从业人员有违法或犯罪行为的，应当按照法律、法规和规章的规定，作出行政处罚、向有关行政管理部门提出行政处罚建议或者移送司法机关。"},{"i":5,"n":"第五条","txt":"旅游投诉由旅游合同签订地或者被投诉人所在地县级以上地方旅游投诉处理机构管辖。 需要立即制止、纠正被投诉人的损害行为的，应当由损害行为发生地旅游投诉处理机构管辖。"},{"i":6,"n":"第六条","txt":"上级旅游投诉处理机构有权处理下级旅游投诉处理机构管辖的投诉案件。"},{"i":7,"n":"第七条","txt":"发生管辖争议的，旅游投诉处理机构可以协商确定，或者报请共同的上级旅游投诉处理机构指定管辖。"},{"i":8,"n":"第八条","txt":"投诉人可以就下列事项向旅游投诉处理机构投诉： （一）认为旅游经营者违反合同约定的； （二）因旅游经营者的责任致使投诉人人身、财产受到损害的； （三）因不可抗力、意外事故致使旅游合同不能履行或者不能完全履行，投诉人与被投诉人发生争议的； （四）其他损害旅游者合法权益的。"},{"i":9,"n":"第九条","txt":"下列情形不予受理： （一）人民法院、仲裁机构、其他行政管理部门或者社会调解机构已经受理或者处理的； （二）旅游投诉处理机构已经作出处理，且没有新情况、新理由的； （三）不属于旅游投诉处理机构职责范围或者管辖范围的； （四）超过旅游合同结束之日90天的； （五）不符合本办法第十条规定的旅游投诉条件的； （六）本办法规定情形之外的其他经济纠纷。 属于前款第（三）项规定的情形的，旅游投诉处理机构应当及时告知投诉人向有管辖权的旅游投诉处理机构或者有关行政管理部门投诉。"},{"i":10,"n":"第十条","txt":"旅游投诉应当符合下列条件： （一）投诉人与投诉事项有直接利害关系； （二）有明确的被投诉人、具体的投诉请求、事实和理由。"},{"i":11,"n":"第十一条","txt":"旅游投诉一般应当采取书面形式，一式两份，并载明下列事项： （一）投诉人的姓名、性别、国籍、通讯地址、邮政编码、联系电话及投诉日期； （二）被投诉人的名称、所在地； （三）投诉的要求、理由及相关的事实根据。"},{"i":12,"n":"第十二条","txt":"投诉事项比较简单的，投诉人可以口头投诉，由旅游投诉处理机构进行记录或者登记，并告知被投诉人；对于不符合受理条件的投诉，旅游投诉处理机构可以口头告知投诉人不予受理及其理由，并进行记录或者登记。"},{"i":13,"n":"第十三条","txt":"投诉人委托代理人进行投诉活动的，应当向旅游投诉处理机构提交授权委托书，并载明委托权限。"},{"i":14,"n":"第十四条","txt":"投诉人4人以上，以同一事由投诉同一被投诉人的，为共同投诉。 共同投诉可以由投诉人推选1至3名代表进行投诉。代表人参加旅游投诉处理机构处理投诉过程的行为，对全体投诉人发生效力，但代表人变更、放弃投诉请求或者进行和解，应当经全体投诉人同意。"},{"i":15,"n":"第十五条","txt":"旅游投诉处理机构接到投诉，应当在5个工作日内作出以下处理： （一）投诉符合本办法的，予以受理； （二）投诉不符合本办法的，应当向投诉人送达《旅游投诉不予受理通知书》，告知不予受理的理由； （三）依照有关法律、法规和本办法规定，本机构无管辖权的，应当以《旅游投诉转办通知书》或者《旅游投诉转办函》，将投诉材料转交有管辖权的旅游投诉处理机构或者其他有关行政管理部门，并书面告知投诉人。"},{"i":16,"n":"第十六条","txt":"旅游投诉处理机构处理旅游投诉，除本办法另有规定外，实行调解制度。 旅游投诉处理机构应当在查明事实的基础上，遵循自愿、合法的原则进行调解，促使投诉人与被投诉人相互谅解，达成协议。"},{"i":17,"n":"第十七条","txt":"旅游投诉处理机构处理旅游投诉，应当立案办理，填写《旅游投诉立案表》，并附有关投诉材料，在受理投诉之日起5个工作日内，将《旅游投诉受理通知书》和投诉书副本送达被投诉人。 对于事实清楚、应当即时制止或者纠正被投诉人损害行为的，可以不填写《旅游投诉立案表》和向被投诉人送达《旅游投诉受理通知书》，但应当对处理情况进行记录存档。"},{"i":18,"n":"第十八条","txt":"被投诉人应当在接到通知之日起10日内作出书面答复，提出答辩的事实、理由和证据。"},{"i":19,"n":"第十九条","txt":"投诉人和被投诉人应当对自己的投诉或者答辩提供证据。"},{"i":20,"n":"第二十条","txt":"旅游投诉处理机构应当对双方当事人提出的事实、理由及证据进行审查。 旅游投诉处理机构认为有必要收集新的证据，可以根据有关法律、法规的规定，自行收集或者召集有关当事人进行调查。"},{"i":21,"n":"第二十一条","txt":"需要委托其他旅游投诉处理机构协助调查、取证的，应当出具《旅游投诉调查取证委托书》，受委托的旅游投诉处理机构应当予以协助。"},{"i":22,"n":"第二十二条","txt":"对专门性事项需要鉴定或者检测的，可以由当事人双方约定的鉴定或者检测部门鉴定。没有约定的，当事人一方可以自行向法定鉴定或者检测机构申请鉴定或者检测。 鉴定、检测费用按双方约定承担。没有约定的，由鉴定、检测申请方先行承担；达成调解协议后，按调解协议承担。 鉴定、检测的时间不计入投诉处理时间。"},{"i":23,"n":"第二十三条","txt":"在投诉处理过程中，投诉人与被投诉人自行和解的，应当将和解结果告知旅游投诉处理机构；旅游投诉处理机构在核实后应当予以记录并由双方当事人、投诉处理人员签名或者盖章。"},{"i":24,"n":"第二十四条","txt":"旅游投诉处理机构受理投诉后，应当积极安排当事双方进行调解，提出调解方案，促成双方达成调解协议。"},{"i":25,"n":"第二十五条","txt":"旅游投诉处理机构应当在受理旅游投诉之日起60日内，作出以下处理： （一）双方达成调解协议的，应当制作《旅游投诉调解书》，载明投诉请求、查明的事实、处理过程和调解结果，由当事人双方签字并加盖旅游投诉处理机构印章； （二）调解不成的，终止调解，旅游投诉处理机构应当向双方当事人出具《旅游投诉终止调解书》。 调解不成的，或者调解书生效后没有执行的，投诉人可以按照国家法律、法规的规定，向仲裁机构申请仲裁或者向人民法院提起诉讼。"},{"i":26,"n":"第二十六条","txt":"在下列情形下，经旅游投诉处理机构调解，投诉人与旅行社不能达成调解协议的，旅游投诉处理机构应当做出划拨旅行社质量保证金赔偿的决定，或向旅游行政管理部门提出划拨旅行社质量保证金的建议： （一）旅行社因解散、破产或者其他原因造成旅游者预交旅游费用损失的； （二）因旅行社中止履行旅游合同义务、造成旅游者滞留，而实际发生了交通、食宿或返程等必要及合理费用的。"},{"i":27,"n":"第二十七条","txt":"旅游投诉处理机构应当每季度公布旅游者的投诉信息。"},{"i":28,"n":"第二十八条","txt":"旅游投诉处理机构应当使用统一规范的旅游投诉处理信息系统。"},{"i":29,"n":"第二十九条","txt":"旅游投诉处理机构应当为受理的投诉制作档案并妥善保管相关资料。"},{"i":30,"n":"第三十条","txt":"本办法中有关文书式样，由国家旅游局统一制定。"},{"i":31,"n":"第三十一条","txt":"本办法由国家旅游局负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2010年7月1 日起施行。《旅行社质量保证金暂行规定》、《旅行社质量保证金暂行规定实施细则》、《旅行社质量保证金赔偿暂行办法》同时废止。"}],"lvyoutousuchulibanfa":[{"i":1,"n":"第一条","txt":"为了依法公正处理旅游投诉，维护旅游者和旅游经营者的合法权益，根据《中华人民共和国旅游法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"旅游投诉的受理、处理、监督和保障，适用本办法。 本办法所称旅游投诉，是指旅游者认为旅游经营者损害其合法权益，请求文化和旅游主管部门或者其所属承担旅游投诉处理职能的组织（以下统称“旅游投诉处理机构”），对双方发生的旅游纠纷进行处理的行为。"},{"i":3,"n":"第三条","txt":"旅游投诉处理机构应当在其职责范围内处理旅游投诉。 县级以上地方文化和旅游主管部门应当在本级人民政府的领导下，建立、健全与有关行政管理部门和消费者组织、人民调解组织等机构共同处理旅游投诉的工作机制。"},{"i":4,"n":"第四条","txt":"旅游投诉处理机构在处理旅游投诉时，发现旅游经营者或者其从业人员涉嫌违反法律、法规和规章规定的，应当依法及时作出处理。对属于本机构职责范围的，应当依法给予行政处罚；对不属于本机构职责范围的，应当及时书面通知并移交有关部门查处；构成犯罪的，依法追究刑事责任。"},{"i":5,"n":"第五条","txt":"旅游投诉由旅游经营者住所地、旅游合同签订地或者旅游纠纷发生地县级以上旅游投诉处理机构管辖。 需要立即制止、纠正旅游经营者的损害行为的，应当由旅游纠纷发生地旅游投诉处理机构管辖。"},{"i":6,"n":"第六条","txt":"上级旅游投诉处理机构认为必要时，可以将本机构管辖的投诉交由下级旅游投诉处理机构管辖。 对由下级旅游投诉处理机构管辖的投诉，上级旅游投诉处理机构认为必要时，可以直接处理或者指定其他下级旅游投诉处理机构管辖。"},{"i":7,"n":"第七条","txt":"除本办法第五条第二款规定的情形外，对于同一个旅游纠纷，两个以上的旅游投诉处理机构都有管辖权的，由最先收到的旅游投诉处理机构管辖。 发生管辖争议的，旅游投诉处理机构应当协商确定，协商不成的，报请共同的上一级旅游投诉处理机构指定管辖；也可以直接由共同的上一级旅游投诉处理机构指定管辖。"},{"i":8,"n":"第八条","txt":"旅游者可以就下列事项向旅游投诉处理机构投诉： （一）认为旅游经营者违反合同约定的； （二）因旅游经营者的责任致使旅游者人身、财产受到损害的； （三）因不可抗力致使合同不能履行或者不能完全履行，旅游者与旅游经营者发生争议的； （四）其他损害旅游者合法权益的。"},{"i":9,"n":"第九条","txt":"旅游投诉应当符合下列条件： （一）投诉人与投诉事项有直接利害关系； （二）有明确的被投诉人、具体的投诉请求。"},{"i":10,"n":"第十条","txt":"旅游投诉一般应当包含下列事项： （一）投诉人的姓名或者名称、通讯地址、联系电话； （二）被投诉人的名称、住所； （三）投诉请求和所根据的旅游纠纷发生时间、地点、经过等事实与理由。 旅游投诉处理机构应当对受理、处理旅游投诉过程中知悉的商业秘密、个人隐私以及其他未公开信息予以保密，除依法开展调解等工作需要外，不得向投诉人、被投诉人或者第三人提供。"},{"i":11,"n":"第十一条","txt":"旅游投诉有下列情形之一的，不予受理： （一）不属于旅游投诉处理机构管辖范围的； （二）超过旅游合同履行期限届满之日九十日的； （三）人民法院、仲裁机构、其他行政管理部门、消费者组织或者人民调解组织等机构已经受理或者处理的； （四）旅游投诉处理机构已经作出处理，且没有新情况、新理由的； （五）不符合本办法第九条规定的受理条件的； （六）本办法规定情形之外的经济纠纷、劳动人事纠纷等其他纠纷。"},{"i":12,"n":"第十二条","txt":"投诉人委托代理人进行投诉活动的，应当向旅游投诉处理机构提交授权委托书，并载明代理人的姓名或者名称及委托事项、权限和期限。"},{"i":13,"n":"第十三条","txt":"投诉人四人以上，以同一事由投诉同一被投诉人的，为共同投诉。 共同投诉可以由投诉人推选一至三名代表人进行投诉。代表人参加旅游投诉处理机构处理投诉过程的行为，对全体投诉人发生效力，但代表人变更、放弃投诉请求或者进行和解，应当经全体投诉人同意。"},{"i":14,"n":"第十四条","txt":"旅游投诉处理机构接到投诉，应当在二个工作日以内决定是否受理： （一）投诉符合本办法规定的，予以受理； （二）投诉不符合本办法规定的，以口头、书面或者其他适当方式告知投诉人不予受理的理由；根据投诉内容能够确定其他解决纠纷途径的，一并告知投诉人。"},{"i":15,"n":"第十五条","txt":"旅游投诉处理机构处理旅游投诉，除本办法另有规定外，实行调解制度。 调解应当以事实为基础，遵循自愿、平等、合法、高效的原则，尊重当事人权利，促使投诉人与被投诉人相互谅解，达成协议。 调解不得损害国家利益、公共利益或者他人的合法权益。"},{"i":16,"n":"第十六条","txt":"旅游投诉处理机构受理旅游投诉后,应当按照以下方式进行处理： （一）对于事实清楚的，应当立即调解并记录情况； （二）对于情况复杂的,应当填写《旅游投诉处理通知书》，与有关投诉材料副本一并送达被投诉人；被投诉人应当在接到通知之日起五个工作日以内作出书面答复，提出事实、理由和答辩意见。"},{"i":17,"n":"第十七条","txt":"投诉人和被投诉人应当对自己的投诉或者答辩提供证据。 旅游投诉处理机构应当对投诉人和被投诉人提出的事实、理由及证据进行核查，必要时可以依法自行开展调查，投诉人与被投诉人应当予以配合。"},{"i":18,"n":"第十八条","txt":"在投诉处理过程中，发现投诉人的投诉内容或者证据材料存在捏造、歪曲事实或者投诉属于本办法第十一条规定的不予受理情形的，旅游投诉处理机构可以终止调解。 被投诉人拒不配合投诉处置，造成不良社会影响的，文化和旅游主管部门应当依据有关规定对其实施信用管理措施。 任何组织和个人不得打击报复投诉人。"},{"i":19,"n":"第十九条","txt":"旅游投诉处理机构因处理旅游投诉需要，可以出具《旅游投诉调查取证委托书》，向其他旅游投诉处理机构提出协助调查、取证请求。协助事项属于被请求机构职权范围内的，应当依法予以协助。"},{"i":20,"n":"第二十条","txt":"对专门性事项需要鉴定或者检测的，可以由双方约定的鉴定或者检测机构进行鉴定或者检测。没有约定的，一方可以自行向法定鉴定或者检测机构申请鉴定或者检测。 鉴定、检测费用按双方约定承担。没有约定的，由鉴定、检测申请方先行垫付；达成调解协议后，按照调解协议负担。 鉴定、检测时间不计入投诉处理时间。"},{"i":21,"n":"第二十一条","txt":"在投诉处理过程中，投诉人与被投诉人自行和解的，应当将和解结果告知旅游投诉处理机构；旅游投诉处理机构在核实后，应当予以记录，并终止调解程序。"},{"i":22,"n":"第二十二条","txt":"旅游投诉处理机构受理旅游投诉后，应当组织投诉人与被投诉人通过现场、网络、电话、信函等方式进行调解，提出调解意见，促成双方达成调解协议。"},{"i":23,"n":"第二十三条","txt":"旅游投诉处理机构应当在受理旅游投诉之日起六十日以内，作出以下处理： （一）达成调解协议的，应当制作《旅游投诉调解书》，由投诉人与被投诉人签字、盖章或者以适当方式确认，并加盖旅游投诉处理机构公章； （二）调解不成的，应当终止调解，制作《旅游投诉终止调解书》，并以适当方式告知投诉人与被投诉人。 调解不成或者达成调解协议后没有执行的，投诉人可以按照有关法律、法规的规定，向仲裁机构申请仲裁或者向人民法院提起诉讼。"},{"i":24,"n":"第二十四条","txt":"被投诉人为旅行社，有下列情形之一的，经旅游投诉处理机构调解，投诉人与被投诉人未能达成调解协议，文化和旅游主管部门可以依法使用旅游服务质量保证金进行赔偿或者垫付： （一）旅行社因解散、破产或者其他原因造成旅游者预交旅游费用损失的； （二）旅行社违反《中华人民共和国旅游法》相关规定拒绝履行合同，造成旅游者滞留而实际发生交通、食宿或者返程等必要及合理费用的； （三）法律、行政法规规定的其他情形。"},{"i":25,"n":"第二十五条","txt":"旅游投诉处理机构应当使用统一规范的旅游投诉处理信息系统。 旅游投诉处理机构应当与相关部门建立数据信息共享机制，加强数据分析利用。"},{"i":26,"n":"第二十六条","txt":"县级以上地方文化和旅游主管部门应当为旅游投诉处理机构开展工作提供人员、经费、办公场所、车辆和设备等必要保障。 旅游投诉处理机构应当对旅游投诉处理工作人员定期进行思想政治、法律法规、专业知识、文明礼仪等方面的培训，提高其业务知识和工作技能。"},{"i":27,"n":"第二十七条","txt":"县级以上文化和旅游主管部门应当加强对旅游投诉处理工作的监督，规范相关工作行为。 县级以上文化和旅游主管部门对在旅游投诉处理工作中有突出成绩或者贡献的人员，可以给予适当的奖励。"},{"i":28,"n":"第二十八条","txt":"旅游投诉处理结束后，旅游投诉处理机构应当妥善保管相关材料，保管期限不低于三年。"},{"i":29,"n":"第二十九条","txt":"本办法中有关文书式样，由文化和旅游部统一制定。"},{"i":30,"n":"第三十条","txt":"本办法所称以上、以内，包括本数。本办法中的“日”，除已明确为工作日外，指自然日。"},{"i":31,"n":"第三十一条","txt":"本办法由文化和旅游部负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2026年3月15日起施行。2010年5月5日原国家旅游局令第32号公布的《旅游投诉处理办法》同时废止。"}],"lvyouxingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"为规范旅游行政处罚行为，维护旅游市场秩序，保护旅游者、旅游经营者和旅游从业人员的合法权益，根据《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》、《中华人民共和国旅游法》及有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"旅游行政处罚的实施和监督，应当遵守《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》、《中华人民共和国旅游法》及有关法律、法规和本办法的规定。"},{"i":3,"n":"第三条","txt":"实施旅游行政处罚，应当遵循合法合理、公正公开、处罚与教育相结合的原则。"},{"i":4,"n":"第四条","txt":"旅游行政处罚的种类包括： （一）警告； （二）罚款； （三）没收违法所得； （四）暂停或者取消出国（境）旅游业务经营资格； （五）责令停业整顿； （六）暂扣或者吊销导游证、领队证； （七）吊销旅行社业务经营许可证； （八）法律、行政法规规定的其他种类。"},{"i":5,"n":"第五条","txt":"县级以上人民政府组织旅游主管部门、有关主管部门和工商行政管理、产品质量监督、交通等执法部门对相关旅游经营行为实施监督检查。 县级以上旅游主管部门应当在同级人民政府的组织和领导下，加强与相关部门的执法协作和联合检查。 县级以上地方旅游主管部门应当逐步建立跨地区协同执法机制，加强执法协作，共享旅游违法行为查处信息，配合、协助其他地区旅游主管部门依法对本地区旅游经营者和从业人员实施的行政处罚。"},{"i":6,"n":"第六条","txt":"对在行政处罚中获取的涉及相对人商业秘密或者个人隐私的内容，旅游主管部门及其执法人员应当予以保密。"},{"i":7,"n":"第七条","txt":"除涉及国家秘密、商业秘密和个人隐私外，行政处罚结果应当向社会公开。"},{"i":8,"n":"第八条","txt":"县级以上旅游主管部门应当在法定职权范围内实施行政处罚。 法律、法规授权从事旅游执法的机构，应当在法定授权范围内以自己的名义实施行政处罚，并对该行为的后果独立承担法律责任。"},{"i":9,"n":"第九条","txt":"旅游主管部门可以在其法定职权范围内委托符合法定条件的旅游质监执法机构实施行政处罚，并对该行为的后果承担法律责任。受委托机构在委托范围内，以作出委托的旅游主管部门的名义实施行政处罚。 旅游主管部门委托实施行政处罚的，应当与受委托机构签订书面委托书，载明受委托机构名称、委托的依据、事项、权限和责任等内容，报上一级旅游主管部门备案，并将受委托机构名称、委托权限和事项向社会公示。 委托实施行政处罚，可以设定委托期限。"},{"i":10,"n":"第十条","txt":"县级以上旅游主管部门应当加强行政执法队伍建设，强化对执法人员的教育和培训，全面提高执法人员素质。 国家旅游局执法人员应当取得本局颁发的行政执法证件；县级以上地方旅游主管部门的执法人员应当取得县级以上地方人民政府颁发的行政执法证件。"},{"i":11,"n":"第十一条","txt":"旅游行政处罚由违法行为发生地的县级以上地方旅游主管部门管辖。 旅行社组织境内旅游，旅游主管部门在查处地接社的违法行为时，发现组团社有其他违法行为的，应当将有关材料或其副本送组团社所在地县级以上地方旅游主管部门。旅行社组织出境旅游违法行为的处罚，由组团社所在地县级以上地方旅游主管部门管辖。"},{"i":12,"n":"第十二条","txt":"国家旅游局负责查处在全国范围内有重大影响的案件。 省、自治区、直辖市旅游主管部门负责查处本地区内重大、复杂的案件。 设区的市级和县级旅游主管部门的管辖权限，由省、自治区、直辖市旅游主管部门确定。 吊销旅行社业务经营许可证、导游证、领队证或者取消出国（境）旅游业务经营资格的行政处罚，由设区的市级以上旅游主管部门作出。"},{"i":13,"n":"第十三条","txt":"旅游主管部门发现已立案的案件不属于自己管辖的，应当在10日内移送有管辖权的旅游主管部门或者其它部门处理。接受移送的旅游主管部门认为案件不属于本部门管辖的，应当报上级旅游主管部门指定管辖，不得再自行移送。 违法行为构成犯罪的，应当按照《行政执法机关移送涉嫌犯罪案件的规定》，将案件移送司法机关，不得以行政处罚代替刑事处罚。"},{"i":14,"n":"第十四条","txt":"两个以上旅游主管部门都有管辖权的行政处罚案件，由最先立案的旅游主管部门管辖，或者由相关旅游主管部门协商；协商不成的，报共同的上级旅游主管部门指定管辖。"},{"i":15,"n":"第十五条","txt":"上级旅游主管部门有权查处下级旅游主管部门管辖的案件，也可以把自己管辖的案件移交下级旅游主管部门查处。 下级旅游主管部门对其管辖的案件，认为需要由上级旅游主管部门查处的，可以报请上级旅游主管部门决定。"},{"i":16,"n":"第十六条","txt":"国家旅游局逐步建立、完善旅游行政裁量权指导标准。各级旅游主管部门行使旅游行政处罚裁量权应当综合考虑下列情节： （一）违法行为的具体方式、手段、程度或者次数； （二）违法行为危害的对象或者所造成的危害后果； （三）当事人改正违法行为的态度、措施和效果； （四）当事人的主观过错程度。 旅游主管部门实施处罚时，对性质相同、情节相近、危害后果基本相当、违法主体类同的违法行为，处罚种类及处罚幅度应当基本一致。"},{"i":17,"n":"第十七条","txt":"当事人的同一违法行为同时违反两个以上法律、法规或者规章规定的，效力高的优先适用。 法律、法规、规章规定两种以上处罚可以单处或者并处的，可以选择适用；规定应当并处的，不得选择适用。 对当事人的同一违法行为，不得给予两次以上罚款的行政处罚。"},{"i":18,"n":"第十八条","txt":"违法行为轻微并及时纠正，且没有造成危害后果的，不予处罚。违法行为在2年内未被发现的，不再给予行政处罚，但法律另有规定的除外。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，应当从轻或者减轻处罚： （一）主动消除或者减轻违法行为危害后果的； （二）受他人胁迫实施违法行为的； （三）配合行政机关查处违法行为有立功表现的； （四）其他依法应当从轻或者减轻处罚的情形。"},{"i":20,"n":"第二十条","txt":"执法人员在现场检查中发现违法行为或者实施行政处罚时，应当责令当事人立即改正违法行为。不能立即改正的，应当责令限期改正，限期改正期限一般不得超过15日，改正期间当事人应当停止相关违法行为。 责令改正应当以书面形式作出，可以一并列入行政处罚决定书。单独出具责令改正通知书的，应当说明违法行为的事实，以及责令改正的依据、期限、要求。"},{"i":21,"n":"第二十一条","txt":"旅游主管部门在监督检查、接到举报、处理投诉或者接受移送、交办的案件，发现当事人的行为涉嫌违反旅游法律、法规、规章时，对符合下列条件的，应当在7个工作日内立案： （一）对该行为可能作出行政处罚的； （二）属于本部门管辖的； （三）违法行为未过追责时效的。 立案应当经案件承办机构或者旅游主管部门负责人批准。 案件情况复杂的，经承办机构负责人批准，立案时间可以延长至14个工作日内。"},{"i":22,"n":"第二十二条","txt":"旅游主管部门对不符合立案条件的，不予立案；立案后发现不符合立案条件的，应当撤销立案。 对实名投诉、举报不予立案或者撤销立案的，应当告知投诉人、举报人，并说明理由。"},{"i":23,"n":"第二十三条","txt":"在现场检查中发现旅游违法行为时，认为证据以后难以取得的，可以先行调查取证，并在10日内决定是否立案和补办立案手续。"},{"i":24,"n":"第二十四条","txt":"对已经立案的案件，案件承办机构应当指定两名以上的执法人员承办，及时组织调查取证。"},{"i":25,"n":"第二十五条","txt":"执法人员有下列情形之一的，应当自行回避，当事人及其代理人也有权申请其回避： （一）是本案当事人或者其近亲属的； （二）本人或者其近亲属与本案有直接利害关系的； （三）与当事人有其他关系，可能影响公正执法的。"},{"i":26,"n":"第二十六条","txt":"需要委托其他旅游主管部门协助调查取证的，应当出具书面委托调查函。受委托的旅游主管部门应当予以协助；有正当理由确实无法协助的，应当及时函告。"},{"i":27,"n":"第二十七条","txt":"执法人员在调查、检查时，有权采取下列措施： （一）进入有关场所进行检查、勘验、先行登记保存证据、录音、拍照、录像； （二）询问当事人及有关人员，要求其说明相关事项和提供有关材料； （三）查阅、复制经营记录和其他有关材料。"},{"i":28,"n":"第二十八条","txt":"执法人员在调查、检查时，应当遵守下列规定： （一）不得少于两人； （二）佩戴执法标志，并向当事人或者有关人员出示执法证件； （三）全面、客观、及时、公正地调查违法事实、违法情节和危害后果等情况； （四）询问当事人时，应当告知其依法享有的权利； （五）依法收集与案件有关的证据，不得以诱导、欺骗等违法手段获取证据； （六）如实记录当事人、证人或者其他有关人员的陈述； （七）除必要情况外，应当避免延误团队旅游行程。"},{"i":29,"n":"第二十九条","txt":"旅游行政处罚的证据包括当事人的陈述和辩解、证人证言、现场笔录、勘验笔录、询问笔录、听证笔录、鉴定意见、视听资料、电子数据和书证、物证等。 据以认定事实的证据，应当合法取得，并经查证属实。 旅游主管部门办理移送或者指定管辖的案件，应当对原案件办理部门依法取得的证据进行核实。"},{"i":30,"n":"第三十条","txt":"执法人员现场检查、勘验时，应当通知当事人到场，可以采取拍照、录像或者其他方式记录现场情况，并制作笔录，载明时间、地点和事件等内容。无法找到当事人、当事人拒绝到场或者在笔录上签名、盖章的，应当注明原因。有其亲属、所在单位人员或者基层组织人员等其他人在现场的，可由其他人签名。"},{"i":31,"n":"第三十一条","txt":"执法人员询问当事人和有关人员时，应当单独进行，并制作询问笔录，由执法人员、被询问人、陈述人、谈话人签名或者盖章。一份询问笔录只能对应一个被询问人、陈述人或者谈话人。"},{"i":32,"n":"第三十二条","txt":"执法人员应当收集、调取与案件有关的书证、物证、视听资料和电子数据等原始凭证作为证据，调取原始证据确有困难的，可以提取相应的复印件、复制件、照片、节录本或者录像。 书证应当经核对与原件无误，注明出证日期和证据出处，由证据提供人和执法人员签名或者盖章；证据提供人拒绝签名或者盖章的，应当注明原因。"},{"i":33,"n":"第三十三条","txt":"在证据可能灭失或者以后难以取得的情况下，经旅游主管部门负责人批准，执法人员可以采取先行登记保存措施，并移转保存。执法人员难以保存或者无须移转的，可以就地保存。 情况紧急的，执法人员可以先采取登记保存措施，再报请旅游主管部门负责人批准。 先行登记保存有关证据，应当当场出具先行登记保存证据决定书，载明先行登记保存证据的名称、单位、数量以及保存地点、时间、要求等内容，送达当事人。"},{"i":34,"n":"第三十四条","txt":"对于先行登记保存的证据，应当在7日内采取下列措施： （一）及时采取记录、复制、拍照、录像、公证等证据保全措施； （二）需要鉴定的，送交鉴定。 旅游主管部门应当在期限届满前，解除先行登记保存措施。已移转保存的，应当返还当事人。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，可以终结调查： （一）违法事实清楚、证据充分的； （二）违法事实不成立的； （三）作为当事人的自然人死亡的； （四）作为当事人的法人或者其他组织终止，无法人或者其他组织承受其权利义务，又无其他关系人可以追查的； （五）其他依法应当终结调查的情形。 调查终结后，对违法行为应当给予处罚的，执法人员应当提出行政处罚建议，并报案件承办机构或者旅游主管部门负责人批准；不予处罚或者免予处罚的，报案件承办机构或者旅游主管部门负责人批准后，终止案件。"},{"i":36,"n":"第三十六条","txt":"旅游主管部门在作出行政处罚决定前，应当以书面形式告知当事人作出行政处罚决定的事实、理由、依据和当事人依法享有的陈述、申辩权利。 旅游主管部门可以就违法行为的性质、情节、危害后果、主观过错等因素，以及选择的处罚种类、幅度等情况，向当事人作出说明。"},{"i":37,"n":"第三十七条","txt":"旅游主管部门应当充分听取当事人的陈述和申辩并制作笔录，对当事人提出的事实、理由和证据，应当进行复核。当事人提出的事实、理由或者证据成立的，应当予以采纳；不能成立而不予采纳的，应当向当事人说明理由。 旅游主管部门不得因当事人申辩而加重处罚。"},{"i":38,"n":"第三十八条","txt":"旅游主管部门作出较大数额罚款、没收较大数额违法所得、取消出国（境）旅游业务经营资格、责令停业整顿、吊销旅行社业务经营许可证、导游证或者领队证等行政处罚决定前，应当以书面形式告知当事人有申请听证的权利。 听证告知的内容应当包括，提出听证申请的期限，未如期提出申请的法律后果，以及受理听证申请的旅游主管部门名称、地址等内容。 第一款所称较大数额，对公民为1万元人民币以上、对法人或者其他组织为5万元人民币以上；地方人民代表大会及其常务委员会或者地方人民政府另有规定的，从其规定。"},{"i":39,"n":"第三十九条","txt":"听证应当遵循公开、公正和效率的原则，保障当事人的合法权益。 除涉及国家秘密、商业秘密或者个人隐私的外，应当公开听证。"},{"i":40,"n":"第四十条","txt":"当事人要求听证的，应当在收到行政处罚听证告知书后3日内，向听证部门提出申请。 旅游主管部门接到申请后，应当在30日内举行听证，并在听证7日前，将举行听证的时间、地点、主持人，以及当事人可以申请听证回避、公开、延期、委托代理人、提供证据等事项，书面通知当事人。 申请人不是本案当事人，当事人未在规定期限内提出申请，或者有其他不符合听证条件的情形，旅游主管部门可以不举行听证，但应当向申请人说明理由。"},{"i":41,"n":"第四十一条","txt":"同一旅游行政处罚案件的两个以上当事人分别提出听证申请的，可以合并举行听证；部分当事人提出听证申请的，可以只对该部分当事人的有关情况进行听证。"},{"i":42,"n":"第四十二条","txt":"当事人应当按期参加听证，未按期参加听证且未事先说明理由的，视为放弃听证权利。 当事人有正当理由要求延期的，经听证承办机构负责人批准可以延期一次，并通知听证参加人。延期不得超过15日。"},{"i":43,"n":"第四十三条","txt":"听证应当由旅游主管部门负责法制工作的机构承办。听证由一名主持人和若干名听证员组织，也可以由主持人一人组织。听证主持人、听证员、书记员应当由旅游主管部门负责人指定的非本案调查人员担任。 涉及专业知识的听证案件，可以邀请有关专家担任听证员。 听证参加人由案件调查人员、当事人和与本案处理结果有直接利害关系的第三人及其委托代理人等组成。公开举行的听证，公民、法人或者其他组织可以申请参加旁听。 当事人认为听证主持人、听证员或者书记员与本案有直接利害关系的，有权向旅游主管部门提出回避申请。"},{"i":44,"n":"第四十四条","txt":"当事人在听证中有下列权利： （一）对案件事实、适用法律及有关情况进行陈述和申辩； （二）对案件调查人员提出的证据进行质证并提出新的证据； （三）核对听证笔录，依法查阅案卷相关证据材料。 当事人、案件调查人员、第三人、有关证人举证、质证应当客观、真实，如实陈述案件事实和回答主持人的提问，遵守听证纪律。 听证主持人有权对参加人不当的辩论内容予以制止，维护正常的听证程序。听证参加人和旁听人员违反听证纪律的，听证主持人可以予以警告，情节特别严重的，可以责令其退出会场。"},{"i":45,"n":"第四十五条","txt":"组织听证应当按下列程序进行： （一）听证主持人询问核实案件调查人员、听证当事人、第三人的身份，宣布听证的目的、会场纪律、注意事项、当事人的权利和义务，介绍听证主持人、听证员和书记员，询问当事人、第三人是否申请回避，宣布听证开始； （二）调查人员就当事人的违法事实进行陈述，并向听证主持人提交有关证据、处罚依据； （三）当事人就案件的事实进行陈述和辩解，提交有关证据； （四）第三人陈述事实，并就其要求提出理由，提交证据； （五）调查人员、当事人、第三人对相关证据进行质证，听证主持人对重要的事实及证据予以核实； （六）调查人员、当事人、第三人就与本案相关的事实、处罚理由和依据进行辩论； （七）调查人员、当事人、第三人作最后陈述； （八）主持人宣布听证结束。 听证过程应当制作笔录，案件调查人员、当事人、第三人应当在听证结束后核对听证笔录，确认无误后签名或者盖章。"},{"i":46,"n":"第四十六条","txt":"听证主持人认为听证过程中提出的新的事实、理由、依据有待进一步调查核实或者鉴定的，可以中止听证并通知听证参加人。经调查核实或者作出鉴定意见后，应当恢复听证。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，终止听证： （一）申请人撤回听证申请的； （二）申请人无正当理由不参加听证会、在听证中擅自退场，或者严重违反听证纪律被听证主持人责令退场的； （三）应当终止听证的其他情形。 听证举行过程中终止听证的，应当记入听证笔录。"},{"i":48,"n":"第四十八条","txt":"听证结束后，听证主持人应当向旅游主管部门提交听证报告，并对拟作出的行政处罚决定，依照下列情形提出意见： （一）违法事实清楚、证据充分、适用法律、法规、规章正确，过罚相当的，建议作出处罚； （二）违法事实清楚、证据充分，但适用法律、法规、规章错误或者处罚显失公正的，建议重新作出处罚； （三）违法事实不清、证据不足，或者由于违反法定程序可能影响案件公正处理的，建议另行指定执法人员重新调查。 听证会结束后，行政处罚决定作出前，执法人员发现新的违法事实，对当事人可能加重处罚的，应当按照本办法第三十六条、第四十条的规定，重新履行处罚决定告知和听证告知程序。"},{"i":49,"n":"第四十九条","txt":"旅游主管部门组织听证所需费用，列入本部门行政经费，不得向当事人收取任何费用。"},{"i":50,"n":"第五十条","txt":"案件调查终结并依法告知、听证后，需要作出行政处罚的，执法人员应当填写行政处罚审批表，经案件承办机构负责人同意后，报旅游主管部门负责人批准。 旅游主管部门应当对调查结果进行审查，根据下列情况，分别作出处理： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不得给予行政处罚； （四）违法行为已构成犯罪的，移送司法机关。 对情节复杂的案件或者因重大违法行为给予公民3万元以上罚款、法人或者其他组织20万元以上罚款，取消出国（境）旅游业务经营资格，责令停业整顿，吊销旅行社业务经营许可证、导游证、领队证等行政处罚的，旅游主管部门负责人应当集体讨论决定。地方人民代表大会及其常务委员会或者地方人民政府对集体讨论的情形另有规定的，从其规定。"},{"i":51,"n":"第五十一条","txt":"决定给予行政处罚的，应当制作行政处罚决定书。旅游行政处罚决定书应当载明下列内容： （一）当事人的姓名或者名称、证照号码、地址、联系方式等基本情况； （二）违反法律、法规或者规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）逾期不缴纳罚款的后果； （六）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （七）作出行政处罚决定的旅游主管部门名称和作出决定的日期，并加盖部门印章。"},{"i":52,"n":"第五十二条","txt":"旅游行政处罚案件应当自立案之日起的3个月内作出决定；案情复杂或者重大的，经旅游主管部门负责人批准可以延长，但不得超过3个月。 案件办理过程中组织听证、鉴定证据、送达文书，以及请示法律适用或者解释的时间，不计入期限。"},{"i":53,"n":"第五十三条","txt":"旅游行政处罚文书应当送达当事人，并符合下列要求： （一）有送达回证并直接送交受送达人，由受送达人在送达回证上载明收到的日期，并签名或者盖章； （二）受送达人是个人的，本人不在交他的同住成年家属签收，并在送达回证上载明与受送达人的关系； （三）受送达人或者他的同住成年家属拒绝接收的，送达人可以邀请有关基层组织的代表或者有关人员到场，说明情况，在送达回证上载明拒收的事由和日期，由送达人、见证人签名或者盖章，把文书留置受送达人的住所或者收发部门，也可以把文书留在受送达人的住所，并采用拍照、录像等方式记录送达过程； （四）受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织办公室、收发室等负责收件的人签收或者盖章，拒绝签收或者盖章的，适用第（三）项留置送达的规定； （五）经受送达人同意，可以采用传真、电子邮件等能够确认其收悉的方式送达行政处罚决定书以外的文"},{"i":54,"n":"第五十四条","txt":"旅游行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，旅游主管部门应当按照本办法第五十三条的规定，在7日内送达当事人，并根据需要抄送与案件有关的单位和个人。"},{"i":55,"n":"第五十五条","txt":"在案件处理过程中，当事人委托代理人的，应当提交授权委托书，载明委托人及其代理人的基本信息、委托事项及权限、代理权的起止日期、委托日期和委托人签名或者盖章。"},{"i":56,"n":"第五十六条","txt":"违法行为发生地的旅游主管部门对非本部门许可的旅游经营者作出行政处罚的，应当依法将被处罚人的违法事实、处理结果告知原许可的旅游主管部门。取消出国（境）旅游业务经营资格或者吊销旅行社业务经营许可证、导游证、领队证的，原许可的旅游主管部门应当注销或者换发许可证件。"},{"i":57,"n":"第五十七条","txt":"违法事实清楚、证据确凿并有法定依据，对公民处以50元以下、对法人或者其他组织处以1000元以下罚款或者警告的旅游行政处罚，可以适用本章简易程序，当场作出行政处罚决定。"},{"i":58,"n":"第五十八条","txt":"当场作出旅游行政处罚决定时，执法人员应当制作笔录，并遵守下列规定： （一）不得少于两人，并向当事人出示行政执法证件； （二）向当事人说明违法的事实、处罚的理由和依据以及拟给予的行政处罚； （三）询问当事人对违法事实、处罚依据是否有异议，并告知当事人有陈述、申辩的权利，听取当事人的陈述和申辩； （四）责令当事人改正违法行为，并填写预定格式、编有号码、盖有旅游主管部门印章的行政处罚决定书，由执法人员和当事人签名或者盖章，并将行政处罚决定书当场交付当事人； （五）依法当场收缴罚款的，应当向当事人出具省、自治区、直辖市财政部门统一制发的罚款收据。 当场作出行政处罚决定的，执法人员应当在决定之日起3日内向旅游主管部门报告；当场收缴的罚款应当在规定时限内存入指定的银行。"},{"i":59,"n":"第五十九条","txt":"当场处罚决定书应当载明第五十一条规定的内容和作出处罚的地点。"},{"i":60,"n":"第六十条","txt":"当事人应当在行政处罚决定书确定的期限内，履行处罚决定；被处以罚款的，应当自收到行政处罚决定书之日起15日内，向指定的银行缴纳罚款。 申请行政复议或者提起行政诉讼的，不停止行政处罚决定的执行，但有下列情形的除外： （一）处罚机关认为需要停止执行的； （二）行政复议机关认为需要停止执行的； （三）申请人申请停止执行，行政复议机关认为其要求合理决定停止执行，或者人民法院认为执行会造成难以弥补的损失，并且停止执行不损害社会性公共利益，裁定停止执行的； （四）法律、法规规定的其他情形。"},{"i":61,"n":"第六十一条","txt":"当事人逾期不履行处罚决定的，作出处罚决定的旅游主管部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，但加处罚款的数额不得超出罚款额； （二）向旅游主管部门所在地有管辖权的人民法院申请强制执行。"},{"i":62,"n":"第六十二条","txt":"申请人民法院强制执行应当在下列期限内提出： （一）行政处罚决定书送达后，当事人未申请行政复议或者提起行政诉讼的，在处罚决定书送达之日起3个月后起算的3个月内； （二）复议决定书送达后当事人未提起行政诉讼的，在复议决定书送达之日起15日后起算的3个月内； （三）人民法院对当事人提起行政诉讼作出的判决、裁定生效之日起3个月内。"},{"i":63,"n":"第六十三条","txt":"旅游主管部门申请人民法院强制执行前，应当催告当事人履行义务。催告应当以书面形式作出，并载明下列事项： （一）履行义务的期限； （二）履行义务的方式； （三）涉及金钱给付的，应当有明确的金额和给付方式； （四）当事人依法享有的陈述权和申辩权。 旅游主管部门应当充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行记录、复核。当事人提出的事实、理由或者证据成立的，应当采纳。 催告书送达10日后当事人仍未履行义务的，可以申请强制执行。"},{"i":64,"n":"第六十四条","txt":"旅游主管部门向人民法院申请强制执行，应当提供下列材料： （一）强制执行申请书； （二）处罚决定书及作出决定的事实、理由和依据； （三）旅游主管部门的催告及当事人的陈述或申辩情况； （四）申请强制执行标的情况； （五）法律、行政法规规定的其他材料。 强制执行申请书应当由旅游主管部门负责人签名，加盖旅游主管部门的印章，并注明日期。"},{"i":65,"n":"第六十五条","txt":"当事人确有经济困难，需要延期或者分期缴纳罚款的，应当在行政处罚决定书确定的缴纳期限届满前，向作出行政处罚决定的旅游主管部门提出延期或者分期缴纳的书面申请。 批准当事人延期或者分期缴纳罚款的，应当制作同意延期（分期）缴纳罚款通知书，送达当事人，并告知当事人缴纳罚款时，应当向收缴机构出示。 延期、分期缴纳罚款的，最长不得超过6个月，或者最后一期缴纳时间不得晚于申请人民法院强制执行的最后期限。"},{"i":66,"n":"第六十六条","txt":"旅游主管部门和执法人员应当严格执行罚缴分离的规定，不得非法自行收缴罚款。 罚没款及没收物品的变价款，应当全部上缴国库，任何单位和个人不得截留、私分或者变相私分。"},{"i":67,"n":"第六十七条","txt":"有下列情形之一的，应当结案： （一）行政处罚决定由当事人履行完毕的； （二）行政处罚决定依法强制执行完毕的； （三）不予处罚或者免予处罚等无须执行的； （四）行政处罚决定被依法撤销的； （五）旅游主管部门认为可以结案的其他情形。"},{"i":68,"n":"第六十八条","txt":"结案的旅游行政处罚案件，应当制作结案报告，报案件承办机构负责人批准。结案报告应当包括案由、案源、立案时间、当事人基本情况、主要案情、案件办理情况、复议和诉讼情况、执行情况、承办人结案意见等内容。"},{"i":69,"n":"第六十九条","txt":"旅游行政处罚案件结案后15日内，案件承办人员应当将案件材料立卷，并符合下列要求： （一）一案一卷； （二）与案件相关的各类文书应当齐全，手续完备； （三）书写文书用签字笔或者钢笔； （四）案卷装订应当规范有序，符合文档要求。"},{"i":70,"n":"第七十条","txt":"案卷材料可以分为正卷、副卷。主要文书、外部程序的材料立正卷；请示报告与批示、集体讨论材料、涉密文件等内部程序的材料立副卷。"},{"i":71,"n":"第七十一条","txt":"立卷完成后应当立即将案卷统一归档。案卷保管及查阅，按档案管理有关规定执行，任何单位、个人不得非法修改、增加、抽取案卷材料。"},{"i":72,"n":"第七十二条","txt":"各级旅游主管部门应当加强行政处罚监督工作。 各级旅游主管部门负责对本部门和受其委托的旅游质监执法机构实施的行政处罚行为，进行督促、检查和纠正；上级旅游主管部门负责对下级旅游主管部门及其委托的旅游质监执法机构实施的行政处罚行为，进行督促、检查和纠正。 各级旅游主管部门法制工作机构，应当在本级旅游主管部门的组织、领导下，具体实施、协调和指导行政处罚工作。 各级旅游主管部门应当设立法制工作机构或者配备行政执法监督检查人员。"},{"i":73,"n":"第七十三条","txt":"旅游行政处罚监督的主要内容包括： （一）旅游行政执法主体资格是否符合规定； （二）执法人员及其执法证件是否合法、有效； （三）行政检查和行政处罚行为是否符合权限； （四）对违法行为查处是否及时； （五）适用的行政处罚依据是否准确、规范； （六）行政处罚的种类和幅度是否合法、适当； （七）行政处罚程序是否合法； （八）行政处罚文书使用是否规范； （九）重大行政处罚备案情况。"},{"i":74,"n":"第七十四条","txt":"对旅游行政处罚的监督，可以采取定期或者不定期方式，通过案卷评查和现场检查等形式进行；处理对行政处罚行为的投诉、举报时，可以进行调查、查询，调阅旅游行政处罚案卷和其他有关材料。"},{"i":75,"n":"第七十五条","txt":"各级旅游主管部门及其委托的旅游质监执法机构不履行法定职责，或者实施的行政处罚行为违反法律、法规和本办法规定、处罚不当的，应当主动纠正。 上级旅游主管部门在行政处罚监督中，发现下级旅游主管部门有不履行法定职责、处罚不当或者实施的行政处罚行为违反法律、法规和本办法规定等情形的，应当责令其纠正。"},{"i":76,"n":"第七十六条","txt":"重大旅游行政处罚案件实行备案制度。 县级以上地方旅游主管部门作出的行政处罚决定，符合本办法第三十八条第一款规定的听证条件的，应当自结案之日起15日内，将行政处罚决定书的副本，报上一级旅游主管部门备案。"},{"i":77,"n":"第七十七条","txt":"旅游行政处罚实行工作报告制度。 县级以上地方旅游主管部门应当分别于当年7月和翌年1月，汇总本地区旅游行政处罚案件，并对旅游行政处罚工作的基本情况、存在的问题以及改进建议，提出工作报告，报上一级旅游主管部门。 省、自治区、直辖市旅游主管部门应当在当年8月31日和翌年2月28日前，将工作总结和案件汇总情况报国家旅游局。"},{"i":78,"n":"第七十八条","txt":"承担行政复议职责的旅游主管部门应当认真履行行政复议职责，依照有关规定配备专职行政复议人员，依法对违法的行政处罚决定予以撤销、变更或者确认，保障法律、法规的正确实施和对行政处罚工作的监督。"},{"i":79,"n":"第七十九条","txt":"各级旅游主管部门应当建立健全对案件承办机构和执法人员旅游行政处罚工作的投诉、举报制度，并公布投诉、举报电话。受理投诉、举报的机构应当按照信访、纪检等有关规定对投诉、举报内容核查处理或者责成有关机构核查处理，并将处理结果通知投诉、举报人。受理举报、投诉的部门应当为举报、投诉人保密。"},{"i":80,"n":"第八十条","txt":"各级旅游主管部门可以采取组织考评、个人自我考评和互查互评相结合，案卷评查和听取行政相对人意见相结合，日常评议考核和年度评议考核相结合的方法，对本部门案件承办机构和执法人员的行政处罚工作进行评议考核。"},{"i":81,"n":"第八十一条","txt":"对在行政处罚工作中做出显著成绩和贡献的单位和个人，旅游主管部门可以依照国家或者地方的有关规定给予表彰和奖励。 旅游行政执法人员有下列行为之一的，由任免机关、监察机关依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）不依法履行行政执法职责的； （二）滥用职权、徇私舞弊的； （三）其他失职、渎职的行为。"},{"i":82,"n":"第八十二条","txt":"本办法有关期间的规定，除第二十一条的规定外，均按自然日计算。期间开始之日，不计算在内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。行政处罚文书在期满前邮寄的，视为在有效期内。"},{"i":83,"n":"第八十三条","txt":"本办法所称的“以上”包括本数或者本级，所称的“以下”不包括本数。"},{"i":84,"n":"第八十四条","txt":"省、自治区、直辖市人民政府决定旅游行政处罚权由其他部门集中行使的，其旅游行政处罚的实施参照适用本办法。"},{"i":85,"n":"第八十五条","txt":"本办法自2013年10月1日起施行。"}],"lvyouxingzhengxukebanfa":[{"i":1,"n":"第一条","txt":"为了规范旅游行政许可行为，保护公民、法人和其他组织的合法权益，保障和监督旅游主管部门有效实施行政管理，根据《行政许可法》及有关法律、行政法规，结合旅游工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称旅游行政许可，是指旅游主管部门及具有旅游行政许可权的其他行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。"},{"i":3,"n":"第三条","txt":"旅游行政许可的设定、实施和监督检查，应当遵守《行政许可法》《旅游法》及有关法律、法规和本办法的规定。 旅游主管部门对其他机关或者对其直接管理的事业单位的人事、财务、外事等事项的审批，不适用本办法。"},{"i":4,"n":"第四条","txt":"实施旅游行政许可，应当依照法定的权限、范围、条件和程序，遵循公开、公平、公正的原则。 旅游主管部门应当按照国家有关规定将行政许可事项向社会公布，未经公布不得实施相关行政许可。行政许可的实施和结果，除涉及国家秘密、商业秘密或者个人隐私的外，应当公开。 符合法定条件、标准的，申请人有依法取得旅游行政许可的平等权利，旅游主管部门不得歧视。"},{"i":5,"n":"第五条","txt":"实施旅游行政许可，应当遵循便民、高效的原则，以行政许可标准化建设为指引，运用标准化原理、方法和技术，提高办事效率，提供优质服务。 国家旅游局负责建立完善旅游行政许可全国网上审批平台，逐步推动旅游行政许可事项的网上办理和审批。地方各级旅游主管部门应当逐步将本部门旅游行政许可事项纳入或者接入全国网上审批平台统一实施。 实施行政许可的旅游主管部门应当编制旅游行政许可服务指南，建立和实施旅游行政许可信息公开制、一次性告知制、首问责任制、顶岗补位制、服务承诺制、责任追究制和文明服务制等服务制度和规范。"},{"i":6,"n":"第六条","txt":"旅游行政规章、规范性文件及其他文件一律不得设定行政许可。 旅游行政规章可以在上位法设定的行政许可事项范围内，对实施该行政许可作出具体规定，但不得增设行政许可；对行政许可条件作出的具体规定，不得增设违反上位法的其他条件。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织对旅游主管部门实施行政许可，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；其合法权益因旅游主管部门违法实施行政许可受到损害的，有权依法要求赔偿。"},{"i":8,"n":"第八条","txt":"旅游行政许可决定依法作出即具有法律效力，非经法定程序不得改变。 旅游行政许可所依据的法律、法规、规章修改或者废止，或者准予行政许可所依据的客观情况发生重大变化的，为了公共利益的需要，旅游主管部门可以依法变更或者撤回已经生效的行政许可。由此给公民、法人或者其他组织造成财产损失的，应当依法给予补偿。"},{"i":9,"n":"第九条","txt":"旅游行政许可由旅游主管部门或者具有旅游行政许可权的其他行政机关在其法定职权范围内实施。 旅游主管部门内设机构和派出机构不得以自己的名义实施行政许可。"},{"i":10,"n":"第十条","txt":"旅游主管部门可以在其法定职权范围内委托具有权限的下级旅游主管部门实施行政许可，并应当将受委托的旅游主管部门和委托实施的旅游行政许可事项予以公告。 委托的旅游主管部门对委托行为的后果，依法承担法律责任。 受委托的旅游主管部门在委托范围内，以委托的旅游主管部门名义实施行政许可，不得转委托。"},{"i":11,"n":"第十一条","txt":"旅游主管部门应当确定具体承担旅游行政许可办理工作的内设机构（以下简称承办机构）。承办机构的主要职责包括： （一）受理、审查旅游行政许可申请，并向旅游主管部门提出许可决定建议； （二）组织旅游行政许可听证工作； （三）送达旅游行政许可决定和证件； （四）旅游行政许可的信息统计、信息公开工作； （五）旅游行政许可档案管理工作； （六）提供旅游行政许可业务咨询服务； （七）依法对被许可人从事旅游行政许可事项的活动进行监督检查。 承办机构需要其他业务机构协助办理的，相关业务机构应当积极配合。"},{"i":12,"n":"第十二条","txt":"从事依法需要取得旅游行政许可活动的，应当向行政机关提出申请。申请书需要采用格式文本的，旅游主管部门应当免费提供申请书格式文本和常见错误实例。申请书格式文本中不得包含与申请行政许可事项没有直接关系的内容。 申请人依法委托代理人提出行政许可申请的，应当提交申请人、代理人的身份证明文件和授权委托书。授权委托书应当载明授权委托事项和授权范围。"},{"i":13,"n":"第十三条","txt":"旅游主管部门应当将旅游行政许可事项、依据、申请条件、数量限制、办理流程、办结期限及申请材料目录和申请书示范文本等，在办公场所或者受理场所及政务网站公示，方便申请人索取使用、获取信息。 申请人要求对公示内容予以说明、解释的，承办机构应当说明、解释，提供准确、可靠的信息。"},{"i":14,"n":"第十四条","txt":"旅游主管部门应当设置一个固定场所作为旅游行政许可业务办理窗口，配备政治素质高、业务能力强、熟悉掌握旅游行政许可业务工作的受理人员，统一受理申请、提供咨询和送达决定，并在办公区域显著位置设立指示标志，引导申请人到受理窗口办理许可业务。 旅游行政许可事项纳入行政服务大厅集中受理的，按照相关规定和要求执行。"},{"i":15,"n":"第十五条","txt":"申请人申请行政许可，应当如实向旅游主管部门提交有关材料和反映真实情况，并对其申请材料实质内容的真实性负责。旅游主管部门不得要求申请人提交与其申请的行政许可事项无关的材料。"},{"i":16,"n":"第十六条","txt":"受理申请时，旅游行政许可受理人员应当审查下列事项： （一）申请事项是否属于本部门行政许可受理范围； （二）申请人或者代理人提交的身份证件和授权委托书是否合法有效，授权事项及范围是否明确； （三）申请材料中是否明确附有申请人签名或者盖章； （四）申请人提交的材料是否符合所申请事项的各项受理要求。"},{"i":17,"n":"第十七条","txt":"对申请人提出的行政许可申请，旅游主管部门应当根据下列情况分别作出处理： （一）申请事项依法不需要取得行政许可的，应当即时告知申请人不受理，并向申请人出具《行政许可申请不予受理通知书》，说明理由和依据； （二）申请事项依法不属于本部门职权范围的，应当即时作出不予受理的决定，并向申请人出具《行政许可申请不予受理通知书》，告知申请人向有关行政机关申请； （三）申请材料存在文字、计算等可以当场更正的错误的，应当允许申请人当场更正，并告知其在修改处签名或者盖章确认； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在5日内一次性告知申请人需要补正的全部内容，并向申请人出具《行政许可申请补正材料通知书》。逾期不告知的，自收到申请材料之日起即为受理； （五）申请人未在规定的期限内提交补正材料，或者提交的材料仍不符合要求但拒绝再补正的，应当作出不予受理的决定，并向申请人出具《行政许可申请不予受理"},{"i":18,"n":"第十八条","txt":"旅游主管部门应当根据申请人提交的申请材料，对其是否具备许可条件、是否存在不予许可的情形等进行书面审查；依法需要对申请材料的实质内容进行核实的，应当指派两名以上工作人员进行现场核查。 核查人员在现场核查或者询问时，应当出示证件，并制作现场核查笔录或者询问笔录。现场核查笔录、询问笔录应当如实记载核查的时间、地点、参加人和内容，经被核查人、被询问人核对无误后签名或者盖章，并由核查人员签字。当事人或者有关人员应当如实回答询问，并协助核查。"},{"i":19,"n":"第十九条","txt":"旅游主管部门对行政许可申请进行审查时，发现该行政许可事项直接关系他人重大利益的，应当告知该利害关系人。申请人、利害关系人有权进行陈述和申辩。 行政许可办理工作人员对申请人、利害关系人的口头陈述和申辩，应当制作陈述、申辩笔录；经复核，申请人、利害关系人提出的事实、理由成立的，应当采纳。"},{"i":20,"n":"第二十条","txt":"申请人在作出行政许可决定前自愿撤回行政许可申请的，旅游主管部门应当准许。 申请人撤回申请的，应当以书面形式提出，并返还旅游主管部门已出具的相关书面凭证。对纸质申请材料，旅游主管部门应当留存复制件，并将原件退回。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，旅游主管部门应当作出中止审查的决定，并通知申请人： （一）申请人因涉嫌侵害旅游者合法权益等违法违规行为被行政机关调查，或者被司法机关侦查，尚未结案，对其行政许可事项影响重大的； （二）申请人被依法采取限制业务活动、责令停业整顿、指定其他机构托管、接管等措施，尚未解除的； （三）对有关法律、法规、规章的规定，需要进一步明确具体含义，请求有关机关作出解释的； （四）申请人主动要求中止审查，理由正当的。 法律、法规、规章对前款情形另有规定的，从其规定。 行政许可中止的原因消除后，应当及时恢复审查。中止审查的时间不计算在法定期限内。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，旅游主管部门应当作出终止审查的决定，并通知申请人： （一）申请人自愿撤回申请的； （二）作为申请人的自然人死亡或者丧失行为能力的； （三）作为申请人的法人或者其他组织终止的。"},{"i":23,"n":"第二十三条","txt":"旅游主管部门对行政许可申请进行审查后，能够当场作出决定的，应当当场作出书面行政许可决定；不能当场作出决定的，应当在法定期限内按照规定程序作出行政许可决定。"},{"i":24,"n":"第二十四条","txt":"申请人的申请符合法定条件、标准的，旅游主管部门应当依法作出准予行政许可的书面决定；不符合法定条件、标准的，旅游主管部门应当依法作出不予行政许可的书面决定，说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 行政许可书面决定应当载明作出决定的时间，并加盖单位印章或者行政许可专用印章。"},{"i":25,"n":"第二十五条","txt":"旅游主管部门作出准予行政许可的决定，需要颁发行政许可证件的，应当在法定期限内向申请人颁发加盖单位印章或者行政许可专用印章的行政许可证件。 行政许可证件一般应当载明证件名称、发证机关名称、被许可人名称、行政许可事项、证件编号、发证日期和证件有效期等事项。"},{"i":26,"n":"第二十六条","txt":"旅游主管部门可以采取下列方式送达行政许可决定以及其他行政许可文书： （一）受送达人到旅游主管部门办公场所或者受理场所直接领取，在送达回证上注明收到日期，并签名或者盖章； （二）邮寄送达的，申请书载明的联系地址为送达地址，受送达人及其代收人应当在邮件回执上签名或者盖章，回执上注明的收件日期为送达日期； （三）受送达人拒绝接收行政许可文书的，送达人可以邀请有关基层组织或者所在单位的代表到场，说明情况，在送达回证上记明拒收事由和日期，由送达人、见证人签名或者盖章，把许可文书留在受送达人的住所；也可以把许可文书留在受送达人的住所，并采用拍照、录像等方式记录送达过程，即视为送达； （四）直接送达有困难的，可以委托当地旅游主管部门送达； （五）无法采取上述方式送达的，可以在公告栏、受送达人住所地张贴公告，也可以在报刊上刊登公告。自公告发布之日起60日后，即视为送达。"},{"i":27,"n":"第二十七条","txt":"旅游主管部门作出的准予行政许可决定，应当按照《政府信息公开条例》的规定予以公开，并允许公众查阅。"},{"i":28,"n":"第二十八条","txt":"旅游主管部门应当在颁发行政许可证件之日起30日内，逐级向上级旅游主管部门备案被许可人名称、行政许可事项、证件编号、发证日期和证件有效期等事项或者共享相关信息。"},{"i":29,"n":"第二十九条","txt":"法律、法规、规章规定实施旅游行政许可应当听证的事项，或者旅游主管部门认为需要听证的其他涉及公共利益的重大行政许可事项，旅游主管部门应当向社会公告，并举行听证。"},{"i":30,"n":"第三十条","txt":"旅游行政许可直接涉及申请人与他人之间重大利益关系的，旅游主管部门应当在作出行政许可决定前发出《行政许可听证告知书》，告知申请人、利害关系人有要求听证的权利。"},{"i":31,"n":"第三十一条","txt":"申请人、利害关系人要求听证的，应当在收到旅游主管部门《行政许可听证告知书》之日起5日内提交申请听证的书面材料；逾期不提交的，视为放弃听证权利。"},{"i":32,"n":"第三十二条","txt":"旅游主管部门应当在接到申请人、利害关系人申请听证的书面材料后20日内组织听证，并在举行听证的7日前，发出《行政许可听证通知书》，将听证的事项、时间、地点通知申请人、利害关系人，必要时予以公告。"},{"i":33,"n":"第三十三条","txt":"听证主持人由旅游主管部门从审查该行政许可申请的工作人员以外的人员中指定，申请人、利害关系人认为主持人与该行政许可事项有直接利害关系的，有权申请回避。"},{"i":34,"n":"第三十四条","txt":"行政许可审查工作人员应当在举行听证5日前，向听证主持人提交行政许可审查意见的证据、理由等全部材料。申请人、利害关系人也可以提出证据。"},{"i":35,"n":"第三十五条","txt":"听证会按照下列程序公开进行： （一）主持人宣布会场纪律； （二）核对听证参加人姓名、年龄、身份，告知听证参加人权利、义务； （三）行政许可审查工作人员提出审查意见的证据、理由； （四）申请人、利害关系人进行申辩和质证； （五）行政许可审查工作人员与申请人、利害关系人就争议事实进行辩论； （六）行政许可审查工作人员与申请人、利害关系人作最后陈述； （七）主持人宣布听证会中止、延期或者结束。"},{"i":36,"n":"第三十六条","txt":"对于申请人、利害关系人或者其委托的代理人无正当理由不出席听证、未经听证主持人许可中途退出或者放弃申辩和质证权利退出听证会的，听证主持人可以宣布听证取消或者终止。"},{"i":37,"n":"第三十七条","txt":"听证记录员应当将听证的全部活动制作笔录，由听证主持人和记录员签名。 听证笔录应当经听证参加人确认无误或者补正后，当场签名或者盖章。听证参加人拒绝签名或者盖章的，由听证主持人记明情况，在听证笔录中予以载明。"},{"i":38,"n":"第三十八条","txt":"旅游主管部门应当根据听证笔录，作出行政许可决定。对听证笔录中未认证、记载的事实依据，或者听证结束后申请人提交的证据，旅游主管部门不予采信。"},{"i":39,"n":"第三十九条","txt":"旅游主管部门应当按照档案管理法律、法规和标准要求，建立科学的管理制度，配备必要的设施设备，指定专门的人员，采用先进技术，加强旅游行政许可档案管理。"},{"i":40,"n":"第四十条","txt":"旅游行政许可档案管理内容主要包括下列材料： （一）申请人依法提交的各项申请材料； （二）旅游主管部门实施许可过程中直接形成的材料； （三）法律、法规规定需要管理的其他材料。 材料形式应当包括文字、图标、声像等不同形式的记录。"},{"i":41,"n":"第四十一条","txt":"承办机构应当对档案材料进行分类、编号、排列、登记、装订，及时整理立卷，并定期移交本部门档案管理机构归档。 档案交接、保管、借阅、查阅、复制等，应当遵守有关规定，严格履行签收、登记、审批手续。涉及国家秘密的，还应当依照《保密法》及其实施条例的规定办理。"},{"i":42,"n":"第四十二条","txt":"旅游主管部门应当明确有关许可档案的保管期限。保管期限到期时，经鉴定档案无保存价值的，可按有关规定销毁。"},{"i":43,"n":"第四十三条","txt":"旅游主管部门应当建立健全旅游行政许可监督检查制度，采取定期或者不定期抽查等方式，对许可实施情况进行监督检查，及时纠正行政许可实施中的违法行为。 旅游主管部门应当制定旅游行政许可实施评价方案，明确评价主体、方式、指标和程序，并组织开展评价，依据评估结果持续提高许可工作质量。"},{"i":44,"n":"第四十四条","txt":"旅游主管部门应当依法对被许可人从事旅游行政许可事项的活动进行监督检查，并将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档。公众有权查阅监督检查记录。"},{"i":45,"n":"第四十五条","txt":"有《行政许可法》规定的撤销、注销情形的，旅游主管部门应当依法作出撤销决定、办理注销手续。"},{"i":46,"n":"第四十六条","txt":"旅游主管部门及其工作人员在实施行政许可、监督检查过程中滥用职权、玩忽职守、徇私舞弊的，由有权机关依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"行政许可申请人、被许可人有违反《行政许可法》《旅游法》及有关法律、法规和本办法规定行为的，旅游主管部门应当依法给予处理；构成犯罪的，依法追究刑事责任。 公民、法人或者其他组织未经行政许可，擅自从事依法应当取得旅游行政许可的活动的，旅游主管部门应当依法采取措施予以制止，并依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"本办法规定的期限以工作日计算，但第二十六条和第二十八条规定的期限除外。"},{"i":49,"n":"第四十九条","txt":"法规、规章对旅游主管部门实施旅游行政许可有特别规定的，按照有关规定执行。 省、自治区、直辖市人民政府决定旅游行政许可权由其他部门集中行使的，其旅游行政许可的实施参照适用本办法。"},{"i":50,"n":"第五十条","txt":"本办法自2018年5月1日起施行。2006年11月7日国家旅游局发布的《国家旅游局行政许可实施暂行办法》同时废止。"}],"lvxingshetiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《旅行社条例》(以下简称《条例》)，制定本实施细则。"},{"i":2,"n":"第二条","txt":"《条例》第二条所称招徕、组织、接待旅游者提供的相关旅游服务，主要包括： （一）安排交通服务； （二）安排住宿服务； （三）安排餐饮服务； （四）安排观光游览、休闲度假等服务； （五）导游、领队服务； （六）旅游咨询、旅游活动设计服务。 旅行社还可以接受委托，提供下列旅游服务： （一）接受旅游者的委托，代订交通客票、代订住宿和代办出境、入境、签证手续等； （二）接受机关、事业单位和社会团体的委托，为其差旅、考察、会议、展览等公务活动，代办交通、住宿、餐饮、会务等事务； （三）接受企业委托，为其各类商务活动、奖励旅游等，代办交通、住宿、餐饮、会务、观光游览、休闲度假等事务； （四）其他旅游服务。 前款所列出境、签证手续等服务，应当由具备出境旅游业务经营权的旅行社代办。"},{"i":3,"n":"第三条","txt":"《条例》第二条所称国内旅游业务，是指旅行社招徕、组织和接待中国内地居民在境内旅游的业务。 《条例》第二条所称入境旅游业务，是指旅行社招徕、组织、接待外国旅游者来我国旅游，香港特别行政区、澳门特别行政区旅游者来内地旅游，台湾地区居民来大陆旅游，以及招徕、组织、接待在中国内地的外国人，在内地的香港特别行政区、澳门特别行政区居民和在大陆的台湾地区居民在境内旅游的业务。 《条例》第二条所称出境旅游业务，是指旅行社招徕、组织、接待中国内地居民出国旅游，赴香港特别行政区、澳门特别行政区和台湾地区旅游，以及招徕、组织、接待在中国内地的外国人、在内地的香港特别行政区、澳门特别行政区居民和在大陆的台湾地区居民出境旅游的业务。"},{"i":4,"n":"第四条","txt":"对旅行社及其分支机构的监督管理，县级以上旅游行政管理部门应当按照《条例》、本细则的规定和职责，实行分级管理和属地管理。"},{"i":5,"n":"第五条","txt":"鼓励旅行社实行服务质量等级制度；鼓励旅行社向专业化、网络化、品牌化发展。"},{"i":6,"n":"第六条","txt":"旅行社的经营场所应当符合下列要求： （一）申请者拥有产权的营业用房，或者申请者租用的、租期不少于1年的营业用房； （二）营业用房应当满足申请者业务经营的需要。"},{"i":7,"n":"第七条","txt":"旅行社的营业设施应当至少包括下列设施、设备： （一）2部以上的直线固定电话； （二）传真机、复印机； （三）具备与旅游行政管理部门及其他旅游经营者联网条件的计算机。"},{"i":8,"n":"第八条","txt":"申请设立旅行社，经营国内旅游业务和入境旅游业务的，应当向省、自治区、直辖市旅游行政管理部门（简称省级旅游行政管理部门，下同）提交下列文件： （一）设立申请书。内容包括申请设立的旅行社的中英文名称及英文缩写，设立地址，企业形式、出资人、出资额和出资方式，申请人、受理申请部门的全称、申请书名称和申请的时间； （二）法定代表人履历表及身份证明； （三）企业章程； （四）经营场所的证明； （五）营业设施、设备的证明或者说明； （六）工商行政管理部门出具的《企业法人营业执照》。 旅游行政管理部门应当根据《条例》第六条规定的最低注册资本限额要求，通过查看企业章程、在企业信用信息公示系统查询等方式，对旅行社认缴的出资额进行审查。 旅行社经营国内旅游业务和入境旅游业务的，《企业法人营业执照》的经营范围不得包括边境旅游业务、出境旅游业务；包括相关业务的，旅游行政管理部门应当告知申请人变更经营范围;申请人"},{"i":9,"n":"第九条","txt":"受理申请的旅游行政管理部门可以对申请人的经营场所、营业设施、设备进行现场检查，或者委托下级旅游行政管理部门检查。"},{"i":10,"n":"第十条","txt":"旅行社申请出境旅游业务的，应当向国务院旅游行政主管部门提交经营旅行社业务满两年、且连续两年未因侵害旅游者合法权益受到行政机关罚款以上处罚的承诺书和经工商行政管理部门变更经营范围的《企业法人营业执照》。 旅行社取得出境旅游经营业务许可的，由国务院旅游行政主管部门换发旅行社业务经营许可证。 国务院旅游行政主管部门可以委托省级旅游行政管理部门受理旅行社经营出境旅游业务的申请，并作出许可或者不予许可的决定。 旅行社申请经营边境旅游业务的，适用《边境旅游暂行管理办法》的规定。 旅行社申请经营赴台湾地区旅游业务的，适用《大陆居民赴台湾地区旅游管理办法》的规定。"},{"i":11,"n":"第十一条","txt":"旅行社因业务经营需要，可以向原许可的旅游行政管理部门申请核发旅行社业务经营许可证副本。 旅行社业务经营许可证及副本，由国务院旅游行政主管部门制定统一样式，国务院旅游行政主管部门和省级旅游行政管理部门分别印制。 旅行社业务经营许可证及副本损毁或者遗失的，旅行社应当向原许可的旅游行政管理部门申请换发或者补发。 申请补发旅行社业务经营许可证及副本的，旅行社应当通过本省、自治区、直辖市范围内公开发行的报刊，或者省级以上旅游行政管理部门网站，刊登损毁或者遗失作废声明。"},{"i":12,"n":"第十二条","txt":"旅行社名称、经营场所、出资人、法定代表人等登记事项变更的，应当在办理变更登记后，持已变更的《企业法人营业执照》向原许可的旅游行政管理部门备案。 旅行社终止经营的，应当在办理注销手续后，持工商行政管理部门出具的注销文件，向原许可的旅游行政管理部门备案。 外商投资旅行社的，适用《条例》第三章的规定。未经批准，旅行社不得引进外商投资。"},{"i":13,"n":"第十三条","txt":"国务院旅游行政主管部门指定的作为旅行社存入质量保证金的商业银行，应当提交具有下列内容的书面承诺： （一）同意与存入质量保证金的旅行社签订符合本实施细则第十五条规定的协议； （二）当县级以上旅游行政管理部门或者人民法院依据《条例》规定，划拨质量保证金后3个工作日内，将划拨情况及其数额，通知旅行社所在地的省级旅游行政管理部门，并提供县级以上旅游行政管理部门出具的划拨文件或者人民法院生效法律文书的复印件； （三）非因《条例》规定的情形，出现质量保证金减少时，承担补足义务。 旅行社应当在国务院旅游行政主管部门指定银行的范围内，选择存入质量保证金的银行。"},{"i":14,"n":"第十四条","txt":"旅行社在银行存入质量保证金的，应当设立独立账户，存期由旅行社确定，但不得少于1年。账户存期届满1个月前，旅行社应当办理续存手续或者提交银行担保。"},{"i":15,"n":"第十五条","txt":"旅行社存入、续存、增存质量保证金后7个工作日内，应当向作出许可的旅游行政管理部门提交存入、续存、增存质量保证金的证明文件，以及旅行社与银行达成的使用质量保证金的协议。 前款协议应当包含下列内容： （一）旅行社与银行双方同意依照《条例》规定使用质量保证金； （二）旅行社与银行双方承诺，除依照县级以上旅游行政管理部门出具的划拨质量保证金，或者省级以上旅游行政管理部门出具的降低、退还质量保证金的文件，以及人民法院作出的认定旅行社损害旅游者合法权益的生效法律文书外，任何单位和个人不得动用质量保证金。"},{"i":16,"n":"第十六条","txt":"旅行社符合《条例》第十七条降低质量保证金数额规定条件的，原许可的旅游行政管理部门应当根据旅行社的要求，在10个工作日内向其出具降低质量保证金数额的文件。"},{"i":17,"n":"第十七条","txt":"旅行社按照《条例》第十八条规定补足质量保证金后7个工作日内，应当向原许可的旅游行政管理部门提交补足的证明文件。"},{"i":18,"n":"第十八条","txt":"旅行社分社（简称分社，下同）及旅行社服务网点（简称服务网点，下同），不具有法人资格，以设立分社、服务网点的旅行社（简称设立社，下同）的名义从事《条例》规定的经营活动，其经营活动的责任和后果，由设立社承担。"},{"i":19,"n":"第十九条","txt":"设立社向分社所在地工商行政管理部门办理分社设立登记后，应当持下列文件向分社所在地与工商登记同级的旅游行政管理部门备案： （一）分社的《营业执照》； （二）分社经理的履历表和身份证明； （三）增存质量保证金的证明文件。 没有同级的旅游行政管理部门的，向上一级旅游行政管理部门备案。"},{"i":20,"n":"第二十条","txt":"分社的经营场所、营业设施、设备，应当符合本实施细则第六条、第七条规定的要求。 分社的名称中应当包含设立社名称、分社所在地地名和“分社”或者“分公司”字样。"},{"i":21,"n":"第二十一条","txt":"服务网点是指旅行社设立的，为旅行社招徕旅游者，并以旅行社的名义与旅游者签订旅游合同的门市部等机构。 设立社可以在其所在地的省、自治区、直辖市行政区划内设立服务网点；设立社在其所在地的省、自治区、直辖市行政区划外设立分社的，可以在该分社所在地设区的市的行政区划内设立服务网点。分社不得设立服务网点。 设立社不得在前款规定的区域范围外，设立服务网点。"},{"i":22,"n":"第二十二条","txt":"服务网点应当设在方便旅游者认识和出入的公众场所。 服务网点的名称、标牌应当包括设立社名称、服务网点所在地地名等，不得含有使消费者误解为是旅行社或者分社的内容，也不得作易使消费者误解的简称。 服务网点应当在设立社的经营范围内，招徕旅游者、提供旅游咨询服务。"},{"i":23,"n":"第二十三条","txt":"设立社向服务网点所在地工商行政管理部门办理服务网点设立登记后，应当在3个工作日内，持下列文件向服务网点所在地与工商登记同级的旅游行政管理部门备案： （一）服务网点的《营业执照》； （二）服务网点经理的履历表和身份证明。 没有同级的旅游行政管理部门的，向上一级旅游行政管理部门备案。"},{"i":24,"n":"第二十四条","txt":"分社、服务网点备案后，受理备案的旅游行政管理部门应当向旅行社颁发《旅行社分社备案登记证明》或者《旅行社服务网点备案登记证明》。"},{"i":25,"n":"第二十五条","txt":"设立社应当与分社、服务网点的员工，订立劳动合同。 设立社应当加强对分社和服务网点的管理，对分社实行统一的人事、财务、招徕、接待制度规范，对服务网点实行统一管理、统一财务、统一招徕和统一咨询服务规范。"},{"i":26,"n":"第二十六条","txt":"旅行社及其分社、服务网点，应当将《旅行社业务经营许可证》、《旅行社分社备案登记证明》或者《旅行社服务网点备案登记证明》，与营业执照一起，悬挂在经营场所的显要位置。"},{"i":27,"n":"第二十七条","txt":"旅行社业务经营许可证不得转让、出租或者出借。 旅行社的下列行为属于转让、出租或者出借旅行社业务经营许可证的行为： （一）除招徕旅游者和符合本实施细则第四十条第一款规定的接待旅游者的情形外，准许或者默许其他企业、团体或者个人，以自己的名义从事旅行社业务经营活动的； （二）准许其他企业、团体或者个人，以部门或者个人承包、挂靠的形式经营旅行社业务的。"},{"i":28,"n":"第二十八条","txt":"旅行社设立的办事处、代表处或者联络处等办事机构，不得从事旅行社业务经营活动。"},{"i":29,"n":"第二十九条","txt":"旅行社以互联网形式经营旅行社业务的，除符合法律、法规规定外，其网站首页应当载明旅行社的名称、法定代表人、许可证编号和业务经营范围，以及原许可的旅游行政管理部门的投诉电话。"},{"i":30,"n":"第三十条","txt":"《条例》第二十六条规定的旅行社不得安排的活动，主要包括： （一）含有损害国家利益和民族尊严内容的； （二）含有民族、种族、宗教歧视内容的； （三）含有淫秽、赌博、涉毒内容的； （四）其他含有违反法律、法规规定内容的。"},{"i":31,"n":"第三十一条","txt":"旅行社为组织旅游者出境旅游委派的领队，应当具备下列条件： （一）取得导游证； （二）具有大专以上学历； （三）取得相关语言水平测试等级证书或通过外语语种导游资格考试，但为赴港澳台地区旅游委派的领队除外； （四）具有两年以上旅行社业务经营、管理或者导游等相关从业经历； （五）与委派其从事领队业务的取得出境旅游业务经营许可的旅行社订立劳动合同。 赴台旅游领队还应当符合《大陆居民赴台湾地区旅游管理办法》规定的要求。"},{"i":32,"n":"第三十二条","txt":"旅行社应当将本单位领队信息及变更情况，报所在地设区的市级旅游行政管理部门备案。领队备案信息包括：身份信息、导游证号、学历、语种、语言等级（外语导游）、从业经历、所在旅行社、旅行社社会保险登记证号等。"},{"i":33,"n":"第三十三条","txt":"领队从事领队业务，应当接受与其订立劳动合同的取得出境旅游业务许可的旅行社委派，并携带导游证、佩戴导游身份标识。"},{"i":34,"n":"第三十四条","txt":"领队应当协助旅游者办理出入境手续，协调、监督境外地接社及从业人员履行合同，维护旅游者的合法权益。"},{"i":35,"n":"第三十五条","txt":"不具备领队条件的，不得从事领队业务。 领队不得委托他人代为提供领队服务。"},{"i":36,"n":"第三十六条","txt":"旅行社委派的领队，应当掌握相关旅游目的地国家（地区）语言或者英语。"},{"i":37,"n":"第三十七条","txt":"《条例》第三十四条所规定的旅行社不得要求导游人员和领队人员承担接待旅游团队的相关费用，主要包括： （一）垫付旅游接待费用； （二）为接待旅游团队向旅行社支付费用； （三）其他不合理费用。"},{"i":38,"n":"第三十八条","txt":"旅行社招徕、组织、接待旅游者，其选择的交通、住宿、餐饮、景区等企业，应当符合具有合法经营资格和接待服务能力的要求。"},{"i":39,"n":"第三十九条","txt":"在签订旅游合同时，旅行社不得要求旅游者必须参加旅行社安排的购物活动或者需要旅游者另行付费的旅游项目。 同一旅游团队中，旅行社不得由于下列因素，提出与其他旅游者不同的合同事项： （一）旅游者拒绝参加旅行社安排的购物活动或者需要旅游者另行付费的旅游项目的； （二）旅游者存在的年龄或者职业上的差异。但旅行社提供了与其他旅游者相比更多的服务，或者旅游者主动要求的除外。"},{"i":40,"n":"第四十条","txt":"旅行社需要将在旅游目的地接待旅游者的业务作出委托的，应当按照《条例》第三十六条的规定，委托给旅游目的地的旅行社并签订委托接待合同。 旅行社对接待旅游者的业务作出委托的，应当按照《条例》第三十六条的规定，将旅游目的地接受委托的旅行社的名称、地址、联系人和联系电话，告知旅游者。"},{"i":41,"n":"第四十一条","txt":"旅游行程开始前，当发生约定的解除旅游合同的情形时，经征得旅游者的同意，旅行社可以将旅游者推荐给其他旅行社组织、接待，并由旅游者与被推荐的旅行社签订旅游合同。 未经旅游者同意的，旅行社不得将旅游者转交给其他旅行社组织、接待。"},{"i":42,"n":"第四十二条","txt":"旅行社及其委派的导游人员和领队人员的下列行为，属于擅自改变旅游合同安排行程： （一）减少游览项目或者缩短游览时间的； （二）增加或者变更旅游项目的； （三）增加购物次数或者延长购物时间的； （四）其他擅自改变旅游合同安排的行为。"},{"i":43,"n":"第四十三条","txt":"在旅游行程中，当发生不可抗力、危及旅游者人身、财产安全，或者非旅行社责任造成的意外情形，旅行社不得不调整或者变更旅游合同约定的行程安排时,应当在事前向旅游者作出说明；确因客观情况无法在事前说明的，应当在事后作出说明。"},{"i":44,"n":"第四十四条","txt":"在旅游行程中，旅游者有权拒绝参加旅行社在旅游合同之外安排的购物活动或者需要旅游者另行付费的旅游项目。 旅行社及其委派的导游人员和领队人员不得因旅游者拒绝参加旅行社安排的购物活动或者需要旅游者另行付费的旅游项目等情形，以任何借口、理由，拒绝继续履行合同、提供服务，或者以拒绝继续履行合同、提供服务相威胁。"},{"i":45,"n":"第四十五条","txt":"旅行社及其委派的导游人员、领队人员，应当对其提供的服务可能危及旅游者人身、财物安全的事项，向旅游者作出真实的说明和明确的警示。 在旅游行程中的自由活动时间，旅游者应当选择自己能够控制风险的活动项目，并在自己能够控制风险的范围内活动。"},{"i":46,"n":"第四十六条","txt":"为减少自然灾害等意外风险给旅游者带来的损害，旅行社在招徕、接待旅游者时，可以提示旅游者购买旅游意外保险。 鼓励旅行社依法取得保险代理资格，并接受保险公司的委托，为旅游者提供购买人身意外伤害保险的服务。"},{"i":47,"n":"第四十七条","txt":"发生出境旅游者非法滞留境外或者入境旅游者非法滞留境内的，旅行社应当立即向所在地县级以上旅游行政管理部门、公安机关和外事部门报告。"},{"i":48,"n":"第四十八条","txt":"在旅游行程中，旅行社及其委派的导游人员、领队人员应当提示旅游者遵守文明旅游公约和礼仪。"},{"i":49,"n":"第四十九条","txt":"旅行社及其委派的导游人员、领队人员在经营、服务中享有下列权利： （一）要求旅游者如实提供旅游所必需的个人信息，按时提交相关证明文件； （二）要求旅游者遵守旅游合同约定的旅游行程安排，妥善保管随身物品； （三）出现突发公共事件或者其他危急情形，以及旅行社因违反旅游合同约定采取补救措施时，要求旅游者配合处理防止扩大损失，以将损失降低到最低程度； （四）拒绝旅游者提出的超出旅游合同约定的不合理要求； （五）制止旅游者违背旅游目的地的法律、风俗习惯的言行。"},{"i":50,"n":"第五十条","txt":"旅行社应当妥善保存《条例》规定的招徕、组织、接待旅游者的各类合同及相关文件、资料，以备县级以上旅游行政管理部门核查。 前款所称的合同及文件、资料的保存期，应当不少于两年。 旅行社不得向其他经营者或者个人，泄露旅游者因签订旅游合同提供的个人信息；超过保存期限的旅游者个人信息资料，应当妥善销毁。"},{"i":51,"n":"第五十一条","txt":"根据《条例》和本实施细则规定，受理旅行社申请或者备案的旅游行政管理部门，可以要求申请人或者旅行社，对申请设立旅行社、办理《条例》规定的备案时提交的证明文件、材料的原件，提供复印件并盖章确认，交由旅游行政管理部门留存。"},{"i":52,"n":"第五十二条","txt":"县级以上旅游行政管理部门对旅行社及其分支机构实施监督检查时，可以进入其经营场所，查阅招徕、组织、接待旅游者的各类合同、相关文件、资料，以及财务账簿、交易记录和业务单据等材料，旅行社及其分支机构应当给予配合。 县级以上旅游行政管理部门对旅行社及其分支机构监督检查时，应当由两名以上持有旅游行政执法证件的执法人员进行。 不符合前款规定要求的，旅行社及其分支机构有权拒绝检查。"},{"i":53,"n":"第五十三条","txt":"旅行社应当按年度将下列经营和财务信息等统计资料，在次年4月15日前，报送原许可的旅游行政管理部门： （一）旅行社的基本情况，包括企业形式、出资人、员工人数、部门设置、分支机构、网络体系等； （二）旅行社的经营情况，包括营业收入、利税等； （三）旅行社组织接待情况，包括国内旅游、入境旅游、出境旅游的组织、接待人数等； （四）旅行社安全、质量、信誉情况，包括投保旅行社责任保险、认证认可和奖惩等。 对前款资料中涉及旅行社商业秘密的内容，旅游行政管理部门应当予以保密。"},{"i":54,"n":"第五十四条","txt":"《条例》第十七条、第四十二条规定的各项公告，县级以上旅游行政管理部门应当通过本部门或者上级旅游行政管理部门的政府网站向社会发布。 质量保证金存缴数额降低、旅行社业务经营许可证的颁发、变更和注销的，国务院旅游行政主管部门或者省级旅游行政管理部门应当在作出许可决定或者备案后20个工作日内向社会公告。 旅行社违法经营或者被吊销旅行社业务经营许可证的，由作出行政处罚决定的旅游行政管理部门，在处罚生效后10个工作日内向社会公告。 旅游者对旅行社的投诉信息，由处理投诉的旅游行政管理部门每季度向社会公告。"},{"i":55,"n":"第五十五条","txt":"因下列情形之一，给旅游者的合法权益造成损害的，旅游者有权向县级以上旅游行政管理部门投诉： （一）旅行社违反《条例》和本实施细则规定的； （二）旅行社提供的服务，未达到旅游合同约定的服务标准或者档次的； （三）旅行社破产或者其他原因造成旅游者预交旅游费用损失的。 划拨旅行社质量保证金的决定，应当由旅行社或者其分社所在地处理旅游者投诉的县级以上旅游行政管理部门作出。"},{"i":56,"n":"第五十六条","txt":"县级以上旅游行政管理部门，可以在其法定权限内，委托符合法定条件的同级旅游质监执法机构实施监督检查。"},{"i":57,"n":"第五十七条","txt":"违反本实施细则第十二条第三款、第二十三条、第二十六条的规定，擅自引进外商投资、设立服务网点未在规定期限内备案，或者旅行社及其分社、服务网点未悬挂旅行社业务经营许可证、备案登记证明的，由县级以上旅游行政管理部门责令改正，可以处1万元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"违反本实施细则第二十二条第三款、第二十八条的规定，服务网点超出设立社经营范围招徕旅游者、提供旅游咨询服务，或者旅行社的办事处、联络处、代表处等从事旅行社业务经营活动的，由县级以上旅游行政管理部门依照《条例》第四十六条的规定处罚。"},{"i":59,"n":"第五十九条","txt":"违反本实施细则第三十五条第二款的规定，领队委托他人代为提供领队服务，由县级以上旅游行政管理部门责令改正，可以处1万元以下的罚款。"},{"i":60,"n":"第六十条","txt":"违反本实施细则第三十八条的规定，旅行社为接待旅游者选择的交通、住宿、餐饮、景区等企业，不具有合法经营资格或者接待服务能力的，由县级以上旅游行政管理部门责令改正，没收违法所得，处违法所得3倍以下但最高不超过3万元的罚款，没有违法所得的，处1万元以下的罚款。"},{"i":61,"n":"第六十一条","txt":"违反本实施细则第三十九条的规定，要求旅游者必须参加旅行社安排的购物活动、需要旅游者另行付费的旅游项目，或者对同一旅游团队的旅游者提出与其他旅游者不同合同事项的，由县级以上旅游行政管理部门责令改正，处1万元以下的罚款。"},{"i":62,"n":"第六十二条","txt":"违反本实施细则第四十条第二款的规定，旅行社未将旅游目的地接待旅行社的情况告知旅游者的，由县级以上旅游行政管理部门依照《条例》第五十五条的规定处罚。"},{"i":63,"n":"第六十三条","txt":"违反本实施细则第四十一条第二款的规定，旅行社未经旅游者的同意，将旅游者转交给其他旅行社组织、接待的，由县级以上旅游行政管理部门依照《条例》第五十五条的规定处罚。"},{"i":64,"n":"第六十四条","txt":"违反本实施细则第四十四条第二款的规定，旅行社及其导游人员和领队人员拒绝继续履行合同、提供服务，或者以拒绝继续履行合同、提供服务相威胁的，由县级以上旅游行政管理部门依照《条例》第五十九条的规定处罚。"},{"i":65,"n":"第六十五条","txt":"违反本实施细则第五十条的规定，未妥善保存各类旅游合同及相关文件、资料，保存期不够两年，或者泄露旅游者个人信息的，由县级以上旅游行政管理部门责令改正，没收违法所得，处违法所得3倍以下但最高不超过3万元的罚款；没有违法所得的，处1万元以下的罚款。"},{"i":66,"n":"第六十六条","txt":"对旅行社作出停业整顿行政处罚的，旅行社在停业整顿期间，不得招徕旅游者、签订旅游合同；停业整顿期间，不影响已签订的旅游合同的履行。"},{"i":67,"n":"第六十七条","txt":"本实施细则由国务院旅游行政主管部门负责解释。"},{"i":68,"n":"第六十八条","txt":"本实施细则自2009年5月3日起施行。2001年12月27日国家旅游局公布的《旅行社管理条例实施细则》同时废止。"}],"lvxingshezerenbaoxianguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障旅游者的合法权益，根据《中华人民共和国保险法》和《旅行社条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立的旅行社，应当依照《旅行社条例》和本办法的规定，投保旅行社责任保险。 本办法所称旅行社责任保险，是指以旅行社因其组织的旅游活动对旅游者和受其委派并为旅游者提供服务的导游或者领队人员依法应当承担的赔偿责任为保险标的的保险。"},{"i":3,"n":"第三条","txt":"投保旅行社责任保险的旅行社和承保旅行社责任保险的保险公司，应当遵守本办法。"},{"i":4,"n":"第四条","txt":"旅行社责任保险的保险责任，应当包括旅行社在组织旅游活动中依法对旅游者的人身伤亡、财产损失承担的赔偿责任和依法对受旅行社委派并为旅游者提供服务的导游或者领队人员的人身伤亡承担的赔偿责任。 具体包括下列情形： （一）因旅行社疏忽或过失应当承担赔偿责任的； （二）因发生意外事故旅行社应当承担赔偿责任的； （三）国家旅游局会同中国保险监督管理委员会（以下简称中国保监会）规定的其他情形。"},{"i":5,"n":"第五条","txt":"中国保监会及其派出机构依法对旅行社责任保险的保险条款和保险费率进行管理。"},{"i":6,"n":"第六条","txt":"旅行社责任保险的保险费率应当遵循市场化原则，并与旅行社经营风险相匹配。"},{"i":7,"n":"第七条","txt":"旅行社投保旅行社责任保险的，应当与保险公司依法订立书面旅行社责任保险合同（以下简称保险合同）。"},{"i":8,"n":"第八条","txt":"旅行社与保险公司订立保险合同时，双方应当依照《中华人民共和国保险法》的有关规定履行告知和说明义务。"},{"i":9,"n":"第九条","txt":"订立保险合同时，保险公司不得强制旅行社投保其他商业保险。"},{"i":10,"n":"第十条","txt":"保险合同成立后，旅行社按照约定交付保险费。保险公司应当及时向旅行社签发保险单或者其他保险凭证，并在保险单或者其他保险凭证中载明当事人双方约定的合同内容，同时按照约定的时间开始承担保险责任。"},{"i":11,"n":"第十一条","txt":"保险合同成立后，除符合《中华人民共和国保险法》规定的情形外，保险公司不得解除保险合同。"},{"i":12,"n":"第十二条","txt":"保险合同成立后，旅行社要解除保险合同的，应当同时订立新的保险合同，并书面通知所在地县级以上旅游行政管理部门，但因旅行社业务经营许可证被依法吊销或注销而解除合同的除外。"},{"i":13,"n":"第十三条","txt":"保险合同解除的，保险公司应当收回保险单，并书面通知旅行社所在地县级以上旅游行政管理部门。"},{"i":14,"n":"第十四条","txt":"旅行社的名称、法定代表人或者业务经营范围等重要事项变更时，应当及时通知保险公司。必要时应当依法办理保险合同变更手续。"},{"i":15,"n":"第十五条","txt":"旅行社责任保险的保险期间为1年。"},{"i":16,"n":"第十六条","txt":"旅行社应当在保险合同期满前及时续保。"},{"i":17,"n":"第十七条","txt":"旅行社投保旅行社责任保险，可以依法自主投保，也可以有组织统一投保。"},{"i":18,"n":"第十八条","txt":"旅行社在组织旅游活动中发生本办法第四条所列情形的，保险公司依法根据保险合同约定，在旅行社责任保险责任限额内予以赔偿。 责任限额可以根据旅行社业务经营范围、经营规模、风险管控能力、当地经济社会发展水平和旅行社自身需要，由旅行社与保险公司协商确定，但每人人身伤亡责任限额不得低于20万元人民币。"},{"i":19,"n":"第十九条","txt":"旅行社组织的旅游活动中发生保险事故，旅行社或者受害的旅游者、导游、领队人员通知保险公司的，保险公司应当及时告知具体的赔偿程序等有关事项。"},{"i":20,"n":"第二十条","txt":"保险事故发生后，旅行社按照保险合同请求保险公司赔偿保险金时，应当向保险公司提供其所能提供的与确认保险事故的性质、原因、损失程度等有关的证明和资料。 保险公司按照保险合同的约定，认为有关的证明和资料不完整的，应当及时一次性通知旅行社补充提供。 旅行社对旅游者、导游或者领队人员应负的赔偿责任确定的，根据旅行社的请求，保险公司应当直接向受害的旅游者、导游或者领队人员赔偿保险金。旅行社怠于请求的，受害的旅游者、导游或者领队人员有权就其应获赔偿部分直接向保险公司请求赔偿保险金。"},{"i":21,"n":"第二十一条","txt":"保险公司收到赔偿保险金的请求和相关证明、资料后，应当及时做出核定；情形复杂的，应当在30日内作出核定，但合同另有约定的除外。保险公司应当将核定结果通知旅行社以及受害的旅游者、导游、领队人员；对属于保险责任的，在与旅行社达成赔偿保险金的协议后10日内，履行赔偿保险金义务。"},{"i":22,"n":"第二十二条","txt":"因抢救受伤人员需要保险公司先行赔偿保险金用于支付抢救费用的，保险公司在接到旅行社或者受害的旅游者、导游、领队人员通知后，经核对属于保险责任的，可以在责任限额内先向医疗机构支付必要的费用。"},{"i":23,"n":"第二十三条","txt":"因第三者损害而造成保险事故的，保险公司自直接赔偿保险金或者先行支付抢救费用之日起，在赔偿、支付金额范围内代位行使对第三者请求赔偿的权利。旅行社以及受害的旅游者、导游或者领队人员应当向保险公司提供必要的文件和所知道的有关情况。"},{"i":24,"n":"第二十四条","txt":"旅行社与保险公司对赔偿有争议的，可以按照双方的约定申请仲裁，或者依法向人民法院提起诉讼。"},{"i":25,"n":"第二十五条","txt":"保险公司的工作人员对当事人的个人隐私应当保密。"},{"i":26,"n":"第二十六条","txt":"县级以上旅游行政管理部门依法对旅行社投保旅行社责任保险情况实施监督检查。"},{"i":27,"n":"第二十七条","txt":"中国保监会及其派出机构依法对保险公司开展旅行社责任保险业务实施监督管理。"},{"i":28,"n":"第二十八条","txt":"违反本办法第十二条、第十六条、第十八条的规定，旅行社解除保险合同但未同时订立新的保险合同，保险合同期满前未及时续保，或者人身伤亡责任限额低于20万元人民币的，由县级以上旅游行政管理部门依照《旅行社条例》第四十九条的规定处罚。"},{"i":29,"n":"第二十九条","txt":"保险公司经营旅行社责任保险，违反有关保险条款和保险费率管理规定的，由中国保监会或者其派出机构依照《中华人民共和国保险法》和中国保监会的有关规定予以处罚。"},{"i":30,"n":"第三十条","txt":"保险公司拒绝或者妨碍依法检查监督的，由中国保监会或者其派出机构依照《中华人民共和国保险法》的有关规定予以处罚。"},{"i":31,"n":"第三十一条","txt":"本办法由国家旅游局和中国保监会负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2011年2月1日起施行。国家旅游局2001年5月15日发布的《旅行社投保旅行社责任保险规定》同时废止。"}],"shehuiyishushuipingkaojiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对社会艺术水平考级活动的管理，维护考生利益，促进社会艺术水平考级工作的规范化，保障社会艺术水平考级工作的质量，推动社会艺术教育事业的健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"社会艺术水平考级（以下简称“艺术考级”）是指依照本办法取得资格的社会艺术水平考级机构（以下简称“艺术考级机构”），通过考试形式对学习艺术人员的艺术水平进行测评和给予指导的活动。"},{"i":3,"n":"第三条","txt":"艺术考级必须以普及艺术教育，提高国民素质为宗旨，遵循艺术教育规律，坚持公开、公正、公平和自愿应试的原则，把社会效益放在首位。"},{"i":4,"n":"第四条","txt":"文化部负责全国艺术考级的规划、协调和监督管理工作，履行下列职能： （一）组织制定和贯彻实施艺术考级的政策、法规； （二）制定全国艺术考级工作规划； （三）实施和指导实施对全国艺术考级活动的监督检查； （四）指导艺术考级行业组织开展艺术考级工作； （五）协调有关部门对艺术考级工作的有关重大事项进行研究并作出决定。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府文化行政部门负责在本行政区域内贯彻执行国家关于艺术考级的政策、法规，监督检查艺术考级活动。"},{"i":6,"n":"第六条","txt":"艺术考级行业组织应当依照法律、法规及章程制定行业自律规范，加强职业道德教育，指导、监督成员的艺术考级工作，维护成员的合法权益，促进公平竞争。"},{"i":7,"n":"第七条","txt":"艺术考级机构是指根据本办法规定取得开办艺术考级活动资格的艺术学校、专业艺术团体、专业协会和艺术事业单位。"},{"i":8,"n":"第八条","txt":"申请开办艺术考级活动的单位，应当具备下列条件： （一）独立的法人资格； （二）主要业务与申请开办艺术考级专业相关，并具有良好的艺术、学术水准和社会信誉； （三）自编并正式出版发行的艺术考级教材； （四）申请开办的艺术考级专业必须有本单位的相应专业的考官，并且本单位考官应当占考官总数的三分之二以上； （五）适应艺术考级需要的场所和设施； （六）专门的工作机构和健全的规章制度。"},{"i":9,"n":"第九条","txt":"申请开办艺术考级活动的单位，应当向所在地省、自治区、直辖市人民政府文化行政部门提出申请，并提交以下材料： （一）申请书。申请书中应当载明拟开办的艺术考级专业、设置考场范围，考级工作机构及其负责人的基本情况，开办资金的数量和来源，收费项目和标准等内容；申请书由申请单位的法定代表人签署； （二）法人资格证明文件； （三）考级工作机构的组成和工作规则； （四）考级工作机构主要负责人的证明文件； （五）考级工作机构办公地点和考试场地使用权的证明文件； （六）自编并正式出版发行的艺术考级教材； （七）拟聘请的艺术考级考官的材料； （八）审批机关要求提供的其他有关材料。"},{"i":10,"n":"第十条","txt":"审批机关应当自受理申请之日起20日内，作出是否批准的书面决定。20日内不能作出决定的，经审批机关负责人批准，可以延长10日，并应当将延长期限的理由告知申请单位。批准的，核发《社会艺术水平考级资格证书》；不予批准的，应当书面说明理由。 审批机关作出决定前，应当组织专家对申请单位的申请材料进行论证。论证所需时间不计算在审批期限内，但应当将所需时间书面告知申请单位。"},{"i":11,"n":"第十一条","txt":"艺术考级机构主要负责人、办公地点有变动的，应当自变动之日起20日内，报审批机关备案。"},{"i":12,"n":"第十二条","txt":"艺术考级机构连续2年不开展艺术考级活动的，取消开展艺术考级活动资格。"},{"i":13,"n":"第十三条","txt":"艺术考级考官应具备下列条件： （一）7年以上专业艺术学习经历或者中级以上（含中级）艺术或者艺术教育专业职称； （二）5年以上所申请专业的艺术表演、艺术理论研究或艺术教育工作经历； （三）良好的示范、教学指导及鉴赏能力； （四）良好的政治素质、道德修养。 艺术考级考官由艺术考级机构聘任。"},{"i":14,"n":"第十四条","txt":"艺术考级机构必须组建常设工作机构，配备专职工作人员，按照核准的艺术考级专业组织艺术考级活动。"},{"i":15,"n":"第十五条","txt":"艺术考级机构应当在组织艺术考级前向社会发布考级简章。考级简章内容应当包括开考专业、设点范围、考级时间和地点、收费项目和标准等。"},{"i":16,"n":"第十六条","txt":"艺术考级机构可以委托相关单位承办艺术考级活动。承办单位应当具备下列条件： （一）独立的法人资格； （二）从事艺术教育、艺术表演、艺术培训、艺术研究等与艺术考级专业相关的业务； （三）开展艺术考级活动必要的物质条件； （四）良好的社会信誉。 艺术考级机构必须与承办单位签订合作协议，明确双方的权利和义务。承办单位必须在合作协议规定范围内，以艺术考级机构的名义组织艺术考级活动，艺术考级机构对承办单位与艺术考级有关的行为承担法律责任。"},{"i":17,"n":"第十七条","txt":"艺术考级机构委托承办单位承办艺术考级活动的，应当自合作协议生效之日起20日内，将承办单位的基本情况和合作协议报审批机关及承办单位所在地县级以上文化行政部门备案，同时抄送文化市场综合执法机构。"},{"i":18,"n":"第十八条","txt":"艺术考级机构应当在开展艺术考级活动5日前，将考级简章、考级时间、考级地点、考生数量、考场安排、考官名单等情况报审批机关和艺术考级活动所在地县级以上文化行政部门备案，同时抄送文化市场综合执法机构。"},{"i":19,"n":"第十九条","txt":"艺术考级的内容应当按照本机构教材确定。"},{"i":20,"n":"第二十条","txt":"考场内执考考官由艺术考级机构派遣。同一考场内至少应当有1名相关专业的考官。 开展美术专业艺术考级的考级机构在考场内可以只派遣监考人员。"},{"i":21,"n":"第二十一条","txt":"考官应当对考生的艺术水平作出评定，并提出指导性意见。"},{"i":22,"n":"第二十二条","txt":"考场实行回避制度。与考生有亲属、师生等关系可能影响考试公正的考官，应主动回避。考生或未成年考生的监护人可以申请考官回避，经考场负责人核实后执行。应当回避而未回避的，经查证属实，考试结果无效。"},{"i":23,"n":"第二十三条","txt":"考生通过所报艺术专业级别考试的，由艺术考级机构发给相应级别的艺术考级证书。 艺术考级机构应当自每次艺术考级活动结束之日起60日内将考级结果报审批机关备案。"},{"i":24,"n":"第二十四条","txt":"未经批准擅自开办艺术考级活动的，由县级以上文化行政部门或者文化市场综合执法机构责令停止违法活动，并处10000元以上30000元以下罚款。"},{"i":25,"n":"第二十五条","txt":"艺术考级机构有下列行为之一的，由县级以上文化行政部门或者文化市场综合执法机构予以警告，责令改正并处10000元以下罚款： （一）组织艺术考级活动前未向社会发布考级简章或考级简章内容不符合规定的； （二）未按规定将承办单位的基本情况和合作协议备案的； （三）组织艺术考级活动未按规定将考级简章、考级时间、考级地点、考生数量、考场安排、考官名单等情况备案的； （四）艺术考级活动结束后未按规定报送考级结果的； （五）艺术考级机构主要负责人、办公地点有变动未按规定向审批机关备案的。"},{"i":26,"n":"第二十六条","txt":"艺术考级机构有下列行为之一的，由文化行政部门或者文化市场综合执法机构予以警告，责令改正并处30000元以下罚款；情节严重的，取消开办艺术考级活动资格： （一）委托的承办单位不符合规定的； （二）未按照规定组建常设工作机构并配备专职工作人员的； （三）未按照本机构教材确定艺术考级内容的； （四）未按照规定要求实行回避的； （五）阻挠、抗拒文化行政部门或者文化市场综合执法机构工作人员监督检查的。"},{"i":27,"n":"第二十七条","txt":"文化行政部门或者文化市场综合执法机构的工作人员有下列行为之一的，给予行政处分；构成犯罪的，依法追究刑事责任： （一）违反本办法规定，擅自批准不符合条件的艺术考级机构的； （二）不履行监督职责，对艺术考级机构违法行为不予查处的； （三）利用职权徇私舞弊、收受贿赂的。"},{"i":28,"n":"第二十八条","txt":"本办法由文化部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自2004年7月1日起施行。文化部2002年5月17日发布的《社会艺术水平考级管理办法》同时废止。"}],"yishupinjingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对艺术品经营活动的管理，规范经营行为，繁荣艺术品市场，保护创作者、经营者、消费者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称艺术品，是指绘画作品、书法篆刻作品、雕塑雕刻作品、艺术摄影作品、装置艺术作品、工艺美术作品等及上述作品的有限复制品。本办法所称艺术品不包括文物。 本办法规范的艺术品经营活动包括： （一）收购、销售、租赁； （二）经纪； （三）进出口经营； （四）鉴定、评估、商业性展览等服务； （五）以艺术品为标的物的投资经营活动及服务。 利用信息网络从事艺术品经营活动的适用本办法。"},{"i":3,"n":"第三条","txt":"文化部负责制定艺术品经营管理政策，监督管理全国艺术品经营活动，建立艺术品市场信用监管体系。 省、自治区、直辖市人民政府文化行政部门负责艺术品进出口经营活动审批，建立专家委员会，为文化行政部门开展的内容审查、市场监管相关工作提供专业意见。 县级以上人民政府文化行政部门负责本行政区域内艺术品经营活动的日常监督管理工作，县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构对从事艺术品经营活动违反国家有关规定的行为实施处罚。"},{"i":4,"n":"第四条","txt":"加强艺术品市场社会组织建设。鼓励和引导行业协会等社会组织制定行业标准，指导、监督会员依法开展经营活动，依照章程，加强行业自律，推动诚信建设，促进行业公平竞争。"},{"i":5,"n":"第五条","txt":"设立从事艺术品经营活动的经营单位，应当到其住所地县级以上人民政府工商行政管理部门申领营业执照，并在领取营业执照之日起15日内，到其住所地县级以上人民政府文化行政部门备案。 其他经营单位增设艺术品经营业务的，应当按前款办理备案手续。"},{"i":6,"n":"第六条","txt":"禁止经营含有以下内容的艺术品： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）破坏国家宗教政策，宣扬邪教、迷信的； （六）宣扬恐怖活动，散布谣言，扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、色情、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）违背社会公德或者民族优秀文化传统的； （十）蓄意篡改历史、严重歪曲历史的； （十一）有法律、法规和国家规定禁止的其他内容的。"},{"i":7,"n":"第七条","txt":"禁止经营以下艺术品： （一）走私、盗窃等来源不合法的艺术品； （二）伪造、变造或者冒充他人名义的艺术品； （三）除有合法手续、准许经营的以外，法律、法规禁止交易的动物、植物、矿物、金属、化石等为材质的艺术品； （四）国家规定禁止交易的其他艺术品。"},{"i":8,"n":"第八条","txt":"艺术品经营单位不得有以下经营行为： （一）向消费者隐瞒艺术品来源，或者在艺术品说明中隐瞒重要事项，误导消费者的； （二）伪造、变造艺术品来源证明、艺术品鉴定评估文件以及其他交易凭证的； （三）以非法集资为目的或者以非法传销为手段进行经营的； （四）未经批准，将艺术品权益拆分为均等份额公开发行，以集中竞价、做市商等集中交易方式进行交易的； （五）法律、法规和国家规定禁止的其他经营行为。"},{"i":9,"n":"第九条","txt":"艺术品经营单位应当遵守以下规定： （一）对所经营的艺术品应当标明作者、年代、尺寸、材料、保存状况和销售价格等信息； （二）保留交易有关的原始凭证、销售合同、台账、账簿等销售记录，法律、法规要求有明确期限的，按照法律、法规规定执行；法律、法规没有明确规定的，保存期不得少于5年。"},{"i":10,"n":"第十条","txt":"艺术品经营单位应买受人要求，应当对买受人购买的艺术品进行尽职调查，提供以下证明材料之一： （一）艺术品创作者本人认可或者出具的原创证明文件； （二）第三方鉴定评估机构出具的证明文件； （三）其他能够证明或者追溯艺术品来源的证明文件。"},{"i":11,"n":"第十一条","txt":"艺术品经营单位从事艺术品鉴定、评估等服务，应当遵守以下规定： （一）与委托人签订书面协议，约定鉴定、评估的事项，鉴定、评估的结论适用范围以及被委托人应当承担的责任； （二）明示艺术品鉴定、评估程序或者需要告知、提示委托人的事项； （三）书面出具鉴定、评估结论，鉴定、评估结论应当包括对委托艺术品的全面客观说明，鉴定、评估的程序，做出鉴定、评估结论的证据，鉴定、评估结论的责任说明，并对鉴定、评估结论的真实性负责； （四）保留书面鉴定、评估结论副本及鉴定、评估人签字等档案不得少于5年。"},{"i":12,"n":"第十二条","txt":"文化产权交易所和以艺术品为标的物的投资经营单位，非公开发行艺术品权益或者采取艺术品集中竞价交易的，应当执行国家有关规定。"},{"i":13,"n":"第十三条","txt":"艺术品进出口经营活动包括： （一）从境外进口或者向境外出口艺术品的经营活动； （二）以销售、商业宣传为目的在境内公共展览场所举办的，有境外艺术品创作者或者境外艺术品参加的各类展示活动。"},{"i":14,"n":"第十四条","txt":"从境外进口或者向境外出口艺术品的，应当在艺术品进出口前，向艺术品进出口口岸所在地省、自治区、直辖市人民政府文化行政部门提出申请并报送以下材料： （一）营业执照、对外贸易经营者备案登记表； （二）进出口艺术品的来源、目的地； （三）艺术品图录； （四）审批部门要求的其他材料。 文化行政部门应当自受理申请之日起5日内作出批准或者不批准的决定。批准的，发给批准文件，申请单位持批准文件到海关办理手续；不批准的，书面通知申请人并说明理由。"},{"i":15,"n":"第十五条","txt":"以销售、商业宣传为目的在境内公共展览场所举办有境外艺术品创作者或者境外艺术品参加的展示活动，应当由举办单位于展览日45日前，向展览举办地省、自治区、直辖市人民政府文化行政部门提出申请，并报送以下材料： （一）主办或者承办单位的营业执照、对外贸易经营者备案登记表； （二）参展的境外艺术品创作者或者境外参展单位的名录； （三）艺术品图录； （四）审批部门要求的其他材料。 文化行政部门应当自受理申请之日起15日内作出批准或者不批准的决定。批准的，发给批准文件，申请单位持批准文件到海关办理手续；不批准的，书面通知申请人并说明理由。"},{"i":16,"n":"第十六条","txt":"艺术品进出口口岸所在地省、自治区、直辖市人民政府文化行政部门在艺术品进出口经营活动审批过程中，对申报的艺术品内容有疑义的，可提交专家委员会进行复核。复核时间不超过15日，复核时间不计入审批时限。"},{"i":17,"n":"第十七条","txt":"同一批已经文化行政部门内容审核的艺术品复出口或者复进口，进出口单位可持原批准文件到进口或者出口口岸海关办理相关手续，文化行政部门不再重复审批。"},{"i":18,"n":"第十八条","txt":"任何单位或者个人不得销售或者利用其他商业形式传播未经文化行政部门批准进口的艺术品。 个人携带、邮寄艺术品进出境，不适用本办法。个人携带、邮寄艺术品超过海关认定的自用、合理数量，海关要求办理进出口手续的，应当参照本办法第十四条办理。 以研究、教学参考、馆藏、公益性展览等非经营性用途为目的的艺术品进出境，应当参照本办法第十四条或者第十五条办理进出口手续。"},{"i":19,"n":"第十九条","txt":"违反本办法第五条规定的，由县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构责令改正，并可根据情节轻重处10000元以下罚款。"},{"i":20,"n":"第二十条","txt":"违反本办法第六条、第七条规定的，由县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构没收非法艺术品及违法所得，违法经营额不足10000元的，并处10000元以上20000元以下罚款；违法经营额10000元以上的，并处违法经营额2倍以上3倍以下罚款。"},{"i":21,"n":"第二十一条","txt":"违反本办法第八条规定的，由县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构责令改正，没收违法所得，违法经营额不足10000元的，并处10000元以上20000元以下罚款；违法经营额10000元以上的，并处违法经营额2倍以上3倍以下罚款。"},{"i":22,"n":"第二十二条","txt":"违反本办法第九条、第十一条规定的，由县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构责令改正，并可根据情节轻重处30000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十四条、第十五条规定，擅自开展艺术品进出口经营活动，及违反第十八条第一款规定的,由县级以上人民政府文化行政部门或者依法授权的文化市场综合执法机构责令改正，违法经营额不足10000元的，并处10000元以上20000元以下罚款；违法经营额10000元以上的，并处违法经营额2倍以上3倍以下罚款。"},{"i":24,"n":"第二十四条","txt":"本办法规定的行政许可、备案、专家委员会复核的期限以工作日计算，不含法定节假日。"},{"i":25,"n":"第二十五条","txt":"本办法由文化部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2016年3月15日起施行。2004年7月1日公布的《美术品经营管理办法》同时废止。"}],"yishudanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对艺术档案的科学管理，充分发挥艺术档案在文化事业和社会主义现代化建设中的作用，依据《中华人民共和国档案法》（以下简称《档案法》）及其实施办法的规定，结合艺术档案的特点，制定本办法。"},{"i":2,"n":"第二条","txt":"艺术档案是指文化艺术单位和艺术工作者在艺术创作、艺术演出、艺术教育、艺术研究、文化交流、社会文化等工作和活动中形成的，对国家和社会有保存价值的各种文字、图表、声像、实物等不同形式的历史记录，是宝贵的文化遗产。 艺术档案工作是文化工作的重要组成部分，也是国家档案工作的组成部分。"},{"i":3,"n":"第三条","txt":"在国家档案行政管理部门的统筹规划、组织协调、统一制度和监督指导下，文化部负责对全国文化系统艺术档案工作的指导和管理。"},{"i":4,"n":"第四条","txt":"各级文化行政管理部门应把艺术档案工作列入本部门整体发展规划，在业务上接受同级档案行政管理部门的监督与指导。"},{"i":5,"n":"第五条","txt":"文化艺术单位应当对本单位的艺术档案实行集中统一管理，保证必要的经费，确保艺术档案的完整、安全和有效利用。 文化艺术单位应把艺术档案工作作为工作总结、业务考核内容之一。"},{"i":6,"n":"第六条","txt":"各级文化行政管理部门应当依据《 档案法》 的有关规定对在艺术档案工作中做出显著成绩的单位和个人，给予表彰和奖励。 对于违反《 档案法》 和本办法相关条款的行为，应依据《 档案法》 的有关规定给予处罚。"},{"i":7,"n":"第七条","txt":"文化艺术单位应建立健全艺术档案管理机构，设置艺术档案工作岗位，配备熟悉业务的专职艺术档案工作人员。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市文化行政管理部门可报请地方人民政府批准设立集中保管艺术档案的专门机构，负责征集、接收和保管本地区的艺术档案和有关的艺术档案资料。"},{"i":9,"n":"第九条","txt":"艺术档案工作人员负责管理本单位的艺术档案，对艺术档案的形成、积累和归档实施监督与指导。"},{"i":10,"n":"第十条","txt":"艺术档案工作人员应熟悉自己所保管的艺术档案，编制各种检索工具，编辑、整理、研究档案材料，以便于查找和利用。 从事艺术档案工作的人员，上岗前应接受岗位培训。"},{"i":11,"n":"第十一条","txt":"艺术档案材料的归档范围包括：文学创作，艺术表演，美术、摄影，社会文化，艺术研究，艺术教育，文化交流，个人艺术等活动中形成的具有保存价值的各种艺术材料。"},{"i":12,"n":"第十二条","txt":"在国家主办的各类艺术活动中所形成的具有保存价值的艺术材料（包括文字、声像、照片、实物等载体形式），均属归档范围（艺术档案归档范围详见附件）。 业务人员在职务活动中形成的具有保存价值的艺术材料，也属归档范围。"},{"i":13,"n":"第十三条","txt":"在文化艺术活动中形成的属国家所有的各种载体的艺术材料和实物，任何个人不得据为己有。"},{"i":14,"n":"第十四条","txt":"在文化艺术单位举办业务活动时，主办和承办单位应向本单位艺术档案管理部门提供信息，并在活动结束后将所形成的属国家所有的全部艺术档案材料立卷归档，不得散失。"},{"i":15,"n":"第十五条","txt":"凡是为艺术创作、研究、教学和文化艺术活动参考而收集的图书、报刊、音像带、照片、剧本和有关文章材料等，均作为资料保存。"},{"i":16,"n":"第十六条","txt":"收集艺术档案材料时，应保证艺术档案材料的完整。 整理艺术档案材料时，应遵循艺术材料的形成规律，保持艺术材料之间的有机联系，便于保管和利用。"},{"i":17,"n":"第十七条","txt":"艺术档案材料系统整理过程中，应根据不同内容和载体分别进行立卷。"},{"i":18,"n":"第十八条","txt":"文化艺术单位应加强对名老艺人、艺术家档案材料和散失在社会上珍贵的艺术档案材料的搜集、征集和管理工作。"},{"i":19,"n":"第十九条","txt":"艺术档案分类由大类、属类组成。大类应设业务类、个人业务类、综合类。具体属类应按照归档范围设置。"},{"i":20,"n":"第二十条","txt":"艺术档案材料应按内容、种类组卷。戏剧材料应按剧目分类组卷；音乐歌舞演出材料应按节目分类组卷；艺术科研材料应按科研专题分类组卷；艺术教育材料应按各专业课程分类组卷；社会文化、文化交流材料应按业务活动进行组卷。 对未完成艺术生产程序的艺术材料，整理时应单独存放，待完成后组卷归档。"},{"i":21,"n":"第二十一条","txt":"对录音带、录像带、照片、唱片、光盘等非纸质载体的艺术档案材料进行归档时，应将每一单项（盒或盘）作为一个保管单位，单独编排档号，并采取按年度结合内容的方法分类整理和编号。其中与文字材料有直接联系的应编写互见号或互见卡。"},{"i":22,"n":"第二十二条","txt":"反映和记录本单位的艺术活动并对以后艺术创作、艺术研究有重要参考借鉴作用的艺术档案材料，应永久保存。在本单位组织或参与的重大的艺术活动中形成的，并具有一定艺术参考价值的艺术档案材料。"},{"i":23,"n":"第二十三条","txt":"文化艺术单位应建立、健全艺术档案工作的管理制度，把艺术档案的收集和归档工作列入有关业务部门和人员 的职责范围。"},{"i":24,"n":"第二十四条","txt":"艺术档案管理部门应配备足够的档案用房和档案柜架、装具，备有防火、防盗、防渍、防有害生物等安全设施，并定期检查档案的保管状况。"},{"i":25,"n":"第二十五条","txt":"文化艺术单位被撤销合并的应将原单位的艺术档案整理登记后，妥善移交给主管机关或接收单位，不得散失。"},{"i":26,"n":"第二十六条","txt":"文化艺术档案整理登记后。集体所有的和个人所有的对国家和社会具有保存价值的艺术档案受国家法律保护档案所有者应当妥善保管。"},{"i":27,"n":"第二十七条","txt":"国家所有的艺术档案，需要向国内外组织或个人赠送、交换、出售其复制件时，须报请上级主管部门批准。"},{"i":28,"n":"第二十八条","txt":"艺术档案管理部门应充分运用先进技术手段，积极开发信息资源，配合业务部门参与艺术生产和文化交流活动。"},{"i":29,"n":"第二十九条","txt":"各级文化行政管理部门可根据本办法，制定实施办法或细则。"},{"i":30,"n":"第三十条","txt":"本办法由文化部、国家档案局负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2002年2月1日起施行，文化部、国家档案局1983 年11月9日发布的《 艺术档案工作暂行办法》 同时废止。 附件：艺术档案归档范围 艺术档案归档范围 一、综合活动材料 1．各种艺术节形成的材料； 2．调演、汇演、巡演形成的材料； 3．各种艺术比赛评奖形成的材料； 4．专场文艺演出形成的材料； 5．各种艺术展览形成的材料； 6．各种艺术活动获奖形成的材料； 7．各种艺术学术会议形成的材料； 8．各种艺术活动计划、方案、总结形成的材料； 9 ．各种艺术活动的统计报表材料； 10．各种国内外文化艺术交流活动形成的材料； 11．文艺集成形成的材料； 12．革命文化艺术史料形成的材料； 13．各种综合性的艺术调查研究形成的材料； 14．各种文化艺术刊物创刊以来形成的材料及刊物出版的重要原稿； 15．各种艺术评论、报导、剪报材料； 16．艺术挖掘、抢救材料； 17．艺术院团的大事记、组"}],"yingyexingyanchuguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《营业性演出管理条例》（以下简称《条例》），制定本实施细则。"},{"i":2,"n":"第二条","txt":"《条例》所称营业性演出是指以营利为目的、通过下列方式为公众举办的现场文艺表演活动： （一）售票或者接受赞助的； （二）支付演出单位或者个人报酬的； （三）以演出为媒介进行广告宣传或者产品促销的； （四）以其他营利方式组织演出的。"},{"i":3,"n":"第三条","txt":"国家依法维护营业性演出经营主体、演职员和观众的合法权益，禁止营业性演出中的不正当竞争行为。"},{"i":4,"n":"第四条","txt":"文艺表演团体是指具备《条例》第六条规定条件，从事文艺表演活动的经营单位。"},{"i":5,"n":"第五条","txt":"演出经纪机构是指具备《条例》第六条规定条件，从事下列活动的经营单位： （一）演出组织、制作、营销等经营活动； （二）演出居间、代理、行纪等经纪活动； （三）演员签约、推广、代理等经纪活动。"},{"i":6,"n":"第六条","txt":"演出场所经营单位是指具备《条例》第七条规定条件，为演出活动提供专业演出场地及服务的经营单位。"},{"i":7,"n":"第七条","txt":"依法登记的文艺表演团体申请从事营业性演出活动，应当向文化主管部门提交下列文件： （一）申请书； （二）营业执照和从事的艺术类型； （三）法定代表人或者主要负责人的身份证明； （四）演员的艺术表演能力证明； （五）与业务相适应的演出器材设备书面声明。 前款第四项所称演员的艺术表演能力证明，可以是下列文件之一： （一）中专以上学校文艺表演类专业毕业证书； （二）职称证书； （三）演出行业协会颁发的演员资格证明； （四）其他有效证明。"},{"i":8,"n":"第八条","txt":"依法登记的演出经纪机构申请从事营业性演出经营活动，应当向文化主管部门提交下列文件： （一）申请书； （二）营业执照； （三）法定代表人或者主要负责人的身份证明； （四）演出经纪人员的资格证明。 法人或者其他组织申请增设演出经纪机构经营业务的，应当提交前款第（一）项、第（四）项规定的文件。"},{"i":9,"n":"第九条","txt":"依法登记的演出场所经营单位，应当自领取证照之日起20日内，持证照和有关消防、卫生批准文件，向所在地县级文化主管部门备案，县级文化主管部门应当出具备案证明。备案证明式样由文化部设计，省级文化主管部门印制。 个体演员可以持个人身份证明和本实施细则第七条第二款规定的艺术表演能力证明,个体演出经纪人可以持个人身份证明和演出经纪人员资格证明，向户籍所在地或者常驻地县级文化主管部门申请备案，文化主管部门应当出具备案证明。备案证明式样由文化部设计，省级文化主管部门印制。"},{"i":10,"n":"第十条","txt":"依法登记的中外合资经营、中外合作经营的演出经纪机构申请从事营业性演出经营活动，除了提交本实施细则第八条规定的文件外，还应当提交下列文件： （一）可行性研究报告、合同、章程； （二）外商投资企业批准证书； （三）合资、合作经营各方协商确定的董事长、副董事长、董事或者联合管理委员会主任、副主任、委员的人选名单及身份证明； （四）其他依法需要提交的文件。 中外合资、合作经营演出经纪机构的董事长或者联合委员会的主任应当由中方代表担任，并且中方代表应当在董事会或者联合委员会中居多数。"},{"i":11,"n":"第十一条","txt":"依法登记的中外合资经营、中外合作经营的演出场所经营单位申请从事演出场所经营活动，应当提交下列文件： （一）申请书； （二）营业执照； （三）可行性研究报告、合同、章程； （四）外商投资企业批准证书； （五）合资、合作经营各方协商确定的董事长、副董事长、董事或者联合管理委员会主任、副主任、委员的人选名单及身份证明； （六）其他依法需要提交的文件。 中外合资、合作经营演出场所经营单位的董事长或者联合委员会的主任应当由中方代表担任，并且中方代表应当在董事会或者联合委员会中居多数。"},{"i":12,"n":"第十二条","txt":"香港特别行政区、澳门特别行政区的演出经纪机构经批准可以在内地设立分支机构，分支机构不具有企业法人资格。 香港特别行政区、澳门特别行政区演出经纪机构在内地的分支机构可以依法从事营业性演出的居间、代理活动，但不得从事其他演出经营活动。香港特别行政区、澳门特别行政区的演出经纪机构对其分支机构的经营活动承担民事责任。 香港特别行政区、澳门特别行政区的演出经纪机构在内地设立分支机构，必须在内地指定负责该分支机构的负责人，并向该分支机构拨付与其所从事的经营活动相适应的资金。"},{"i":13,"n":"第十三条","txt":"香港特别行政区、澳门特别行政区的投资者在内地依法登记的独资经营的演出经纪机构申请从事营业性演出经营活动，除提交本实施细则第八条规定文件外，还应当提交下列文件： （一）可行性研究报告； （二）投资者的身份证明； （三）台港澳侨投资企业批准证书； （四）其他依法需要提交的文件。"},{"i":14,"n":"第十四条","txt":"香港特别行政区、澳门特别行政区的投资者在内地依法登记的独资经营的演出场所经营单位申请从事演出场所经营活动，应当提交下列文件： （一）申请书； （二）营业执照； （三）可行性研究报告； （四）法定代表人的身份证明； （五）台港澳侨投资企业批准证书； （六）其他依法需要提交的文件。"},{"i":15,"n":"第十五条","txt":"香港特别行政区、澳门特别行政区投资者在内地依法登记的合资、合作经营的演出经纪机构申请从事营业性演出经营活动，香港特别行政区、澳门特别行政区投资者在内地依法登记的合资、合作经营的演出场所经营单位申请从事演出场所经营活动，参照本实施细则第十条第一款、第十一条第一款的规定办理。 台湾地区的投资者在大陆依法登记的合资、合作经营的演出经纪机构申请从事营业性演出经营活动，台湾地区的投资者在大陆依法登记的合资、合作经营的演出场所经营单位申请从事演出场所经营活动，参照本实施细则第十条、第十一条的规定办理。"},{"i":16,"n":"第十六条","txt":"申请举办营业性演出，应当在演出日期3日前将申请材料提交负责审批的文化主管部门。 申请举办营业性涉外或者涉港澳台演出，应当在演出日期20日前将申请材料提交负责审批的文化主管部门。"},{"i":17,"n":"第十七条","txt":"申请举办营业性演出，应当持营业性演出许可证或者备案证明，向文化主管部门提交符合《条例》第十六条规定的文件。 申请举办临时搭建舞台、看台的营业性演出，还应当提交符合《条例》第二十条第（二）、（三）项规定的文件。 对经批准的临时搭建舞台、看台的演出活动，演出举办单位还应当在演出前向演出所在地县级文化主管部门提交符合《条例》第二十条第（一）项规定的文件，不符合规定条件的，演出活动不得举行。 《条例》第二十条所称临时搭建舞台、看台的营业性演出是指符合《大型群众性活动安全管理条例》规定的营业性演出活动。 《条例》第二十条第（一）项所称演出场所合格证明，是指由演出举办单位组织有关承建单位进行竣工验收，并作出的验收合格证明材料。 申请举办需要未成年人参加的营业性演出，应当符合国家有关规定。"},{"i":18,"n":"第十八条","txt":"申请举办营业性涉外或者涉港澳台演出，除提交本实施细则第十七条规定的文件外，还应当提交下列文件： （一）演员有效身份证明复印件； （二）2年以上举办营业性演出经历的证明文件； （三）近2年内无违反《条例》规定的书面声明。 文化主管部门审核涉外或者涉港澳台营业性演出项目，必要时可以依法组织专家进行论证。"},{"i":19,"n":"第十九条","txt":"经省级文化主管部门批准的营业性涉外演出，在批准的时间内增加演出地的，举办单位或者与其合作的具有涉外演出资格的演出经纪机构，应当在演出日期10日前，持省级文化主管部门批准文件和本实施细则第十七条规定的文件，到增加地省级文化主管部门备案，省级文化主管部门应当出具备案证明。"},{"i":20,"n":"第二十条","txt":"经批准到艺术院校从事教学、研究工作的外国或者港澳台艺术人员从事营业性演出的，应当委托演出经纪机构承办。"},{"i":21,"n":"第二十一条","txt":"歌舞娱乐场所、旅游景区、主题公园、游乐园、宾馆、饭店、酒吧、餐饮场所等非演出场所经营单位需要在本场所内举办营业性演出的，应当委托演出经纪机构承办。 在上述场所举办驻场涉外演出，应当报演出所在地省级文化主管部门审批。"},{"i":22,"n":"第二十二条","txt":"申请举办含有内地演员和香港特别行政区、澳门特别行政区、台湾地区演员以及外国演员共同参加的营业性演出，可以报演出所在地省级文化主管部门审批，具体办法由省级文化主管部门制定。 国家另有规定的，从其规定。"},{"i":23,"n":"第二十三条","txt":"在演播厅外从事电视文艺节目的现场录制，符合本实施细则第二条规定条件的，应当依照《条例》和本实施细则的规定办理审批手续。"},{"i":24,"n":"第二十四条","txt":"举办募捐义演，应当依照《条例》和本实施细则的规定办理审批手续。 参加募捐义演的演职人员不得获取演出报酬；演出举办单位或者演员应当将扣除成本后的演出收入捐赠给社会公益事业，不得从中获取利润。 演出收入是指门票收入、捐赠款物、赞助收入等与演出活动相关的全部收入。演出成本是指演职员食、宿、交通费用和舞台灯光音响、服装道具、场地、宣传等费用。 募捐义演结束后10日内，演出举办单位或者演员应当将演出收支结算报审批机关备案。 举办其他符合本实施细则第二条所述方式的公益性演出，参照本条规定执行。"},{"i":25,"n":"第二十五条","txt":"营业性演出经营主体举办营业性演出，应当履行下列义务： （一）办理演出申报手续； （二）安排演出节目内容； （三）安排演出场地并负责演出现场管理； （四）确定演出票价并负责演出活动的收支结算； （五）依法缴纳或者代扣代缴有关税费； （六）接受文化主管部门的监督管理； （七）其他依法需要承担的义务。"},{"i":26,"n":"第二十六条","txt":"举办营业性涉外或者涉港澳台演出，举办单位应当负责统一办理外国或者港澳台文艺表演团体、个人的入出境手续，巡回演出的还要负责其全程联络和节目安排。"},{"i":27,"n":"第二十七条","txt":"营业性演出活动经批准后方可出售门票。"},{"i":28,"n":"第二十八条","txt":"营业性演出不得以假唱、假演奏等手段欺骗观众。 前款所称假唱、假演奏是指演员在演出过程中，使用事先录制好的歌曲、乐曲代替现场演唱、演奏的行为。 演出举办单位应当派专人对演唱、演奏行为进行监督，并作出记录备查。记录内容包括演员、乐队、曲目的名称和演唱、演奏过程的基本情况，并由演出举办单位负责人和监督人员签字确认。"},{"i":29,"n":"第二十九条","txt":"举办营业性演出，应当根据舞台设计要求，优先选用境内演出器材。"},{"i":30,"n":"第三十条","txt":"举办营业性演出，举办单位或者个人可以为演出活动投保安全责任保险。"},{"i":31,"n":"第三十一条","txt":"鼓励演出经营主体协作经营，建立演出院线，共享演出资源。"},{"i":32,"n":"第三十二条","txt":"各级文化主管部门应当将营业性演出的审批事项向社会公布。"},{"i":33,"n":"第三十三条","txt":"文化主管部门对体现民族特色和国家水准的演出，应当依照有关规定给予补助和支持。 县级以上人民政府有关部门可以依照《条例》的有关规定和财务管理制度，鼓励和支持体现民族特色和国家水准的演出。"},{"i":34,"n":"第三十四条","txt":"文化主管部门或者文化行政执法机构检查营业性演出现场，应当出示文化市场行政执法证件，演出举办单位应当配合。"},{"i":35,"n":"第三十五条","txt":"文化主管部门可以采用技术手段，加强对营业性演出活动的监管。"},{"i":36,"n":"第三十六条","txt":"各级文化主管部门应当建立演出经营主体基本信息登记和公布制度、演出信息报送制度、演出市场巡查责任制度，加强对演出市场的管理和监督。"},{"i":37,"n":"第三十七条","txt":"演出行业协会是演出经营主体和演出从业人员的自律组织。 全国性演出行业协会负责组织实施演员、演出经纪人员等演出从业人员的资格认定工作。 各级文化主管部门可以委托演出行业协会开展有关工作，并加强指导和监督。"},{"i":38,"n":"第三十八条","txt":"文艺表演团体和演出经纪机构的营业性演出许可证包括1份正本和2份副本，有效期为2年。 营业性演出许可证由文化部设计，省级文化主管部门印制，发证机关填写、盖章。"},{"i":39,"n":"第三十九条","txt":"文化主管部门吊销文艺表演团体或者演出经纪机构的营业性演出许可证，应当通知工商行政管理部门变更其经营范围或者吊销营业执照。 文艺表演团体和演出经纪机构的营业性演出许可证，除文化主管部门可以依法暂扣或者吊销外，其他任何单位和个人不得收缴、扣押。"},{"i":40,"n":"第四十条","txt":"吊销、注销文艺表演团体营业性演出许可证的，应当报省级文化主管部门备案。吊销、注销演出经纪机构营业性演出许可证的，应当报文化部备案。"},{"i":41,"n":"第四十一条","txt":"文化主管部门对文艺表演团体和演出经纪机构实施行政处罚的，应当将处罚决定记录在营业性演出许可证副本上并加盖处罚机关公章，同时将处罚决定通知发证机关。"},{"i":42,"n":"第四十二条","txt":"违反本实施细则第十七条的规定，未在演出前向演出所在地县级文化主管部门提交《条例》第二十条规定的演出场所合格证明而举办临时搭建舞台、看台营业性演出的，由县级文化主管部门依照《条例》第四十四条第一款的规定给予处罚。"},{"i":43,"n":"第四十三条","txt":"举办营业性涉外或者涉港澳台演出，隐瞒近2年内违反《条例》规定的记录，提交虚假书面声明的，由负责审批的文化主管部门处以3万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"违反本实施细则第十九条规定，经省级文化主管部门批准的涉外演出在批准的时间内增加演出地，未到演出所在地省级文化主管部门备案的，由县级文化主管部门依照《条例》第四十四条第一款的规定给予处罚。"},{"i":45,"n":"第四十五条","txt":"违反本实施细则第二十条规定，经批准到艺术院校从事教学、研究工作的外国或者港澳台艺术人员擅自从事营业性演出的，由县级文化主管部门依照《条例》第四十三条规定给予处罚。"},{"i":46,"n":"第四十六条","txt":"违反本实施细则第二十一条规定，非演出场所经营单位擅自举办演出的，由县级文化主管部门依照《条例》第四十三条规定给予处罚。"},{"i":47,"n":"第四十七条","txt":"非演出场所经营单位为未经批准的营业性演出提供场地的，由县级文化主管部门移送有关部门处理。"},{"i":48,"n":"第四十八条","txt":"违反本实施细则第二十三条规定，在演播厅外从事符合本实施细则第二条规定条件的电视文艺节目的现场录制，未办理审批手续的，由县级文化主管部门依照《条例》第四十三条规定给予处罚。"},{"i":49,"n":"第四十九条","txt":"违反本实施细则第二十四条规定，擅自举办募捐义演或者其他公益性演出的，由县级以上文化主管部门依照《条例》第四十三条规定给予处罚。"},{"i":50,"n":"第五十条","txt":"违反本实施细则第二十五条、第二十六条规定，在演出经营活动中，不履行应尽义务，倒卖、转让演出活动经营权的，由县级文化主管部门依照《条例》第四十五条规定给予处罚。"},{"i":51,"n":"第五十一条","txt":"违反本实施细则第二十七条规定，未经批准，擅自出售演出门票的，由县级文化主管部门责令停止违法活动，并处3万元以下罚款。"},{"i":52,"n":"第五十二条","txt":"违反本实施细则第二十八条规定，演出举办单位没有现场演唱、演奏记录的，由县级文化主管部门处以3000元以下罚款。 以假演奏等手段欺骗观众的，由县级文化主管部门依照《条例》第四十七条的规定给予处罚。"},{"i":53,"n":"第五十三条","txt":"县级以上文化主管部门或者文化行政执法机构检查营业性演出现场，演出举办单位拒不接受检查的，由县级以上文化主管部门或者文化行政执法机构处以3万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"上级文化主管部门在必要时，可以依照《条例》和本实施细则的规定，调查、处理由下级文化主管部门调查、处理的案件。 下级文化主管部门认为案件重大、复杂的，可以请求移送上级文化主管部门调查、处理。"},{"i":55,"n":"第五十五条","txt":"本实施细则由文化部负责解释。"},{"i":56,"n":"第五十六条","txt":"本实施细则自2009年10月1日起施行，2005年8月30日发布的《营业性演出管理条例实施细则》同时废止。"}],"bianjinglvyouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了进一步扩大我国旅游业的对外开放，促进边境地区的经济繁荣和社会稳定，增进同毗邻国家人民的交往和友谊，完善边境旅游管理，根据《中华人民共和国旅游法》《中华人民共和国出境入境管理法》《中华人民共和国陆地国界法》《旅行社条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称边境旅游，是指符合条件的旅行社组织和接待我国及毗邻国家的公民，采取团队方式从指定的边境口岸出入境，在双方政府商定的边境区域和期限内进行的旅游活动。"},{"i":3,"n":"第三条","txt":"国家鼓励边境地区与毗邻国家边境地区加强合作，促进边境旅游发展，打造具有特色的边境旅游目的地。"},{"i":4,"n":"第四条","txt":"国务院文化和旅游主管部门负责全国边境旅游工作的统筹协调、宏观指导和监督检查；国务院外交、公安、海关、移民等有关部门在各自职责范围内负责边境旅游有关工作。"},{"i":5,"n":"第五条","txt":"边境地区县级以上地方文化和旅游主管部门会同外事、公安、海关、移民等有关部门，负责边境旅游合作协议的商谈工作，依据国家有关规定制定本行政区域内边境旅游管理的工作制度，依据职责对本行政区域内的边境旅游活动进行监督管理，定期向上一级文化和旅游主管部门报告开展边境旅游的情况。 省、自治区人民政府或者边境市、县人民政府负责与对方国家边境地区相应级别政府签订意向性边境旅游合作协议和正式边境旅游合作协议。"},{"i":6,"n":"第六条","txt":"开展边境旅游，应当符合下列条件： （一）有经国务院批准对外国人开放的边境市、县； （二）有经国务院批准的正式对外开放且允许人员出入境的边境口岸，能够保障边境旅游活动顺利开展的口岸查验基础设施； （三）具备交通条件和接待设施； （四）遵守入境国防范生物安全风险的有关规定； （五）签订了意向性边境旅游合作协议。 意向性边境旅游合作协议签订前，省、自治区人民政府应当征求国务院文化和旅游主管部门的意见，并由国务院文化和旅游主管部门征求外交、公安、交通、海关、移民等部门的意见。"},{"i":7,"n":"第七条","txt":"意向性边境旅游合作协议应当包括下列主要内容： （一）双方组织边境旅游的区域范围； （二）出入境证件、出入境口岸、停留期限； （三）旅游团队最低人数； （四）双方组织边境旅游的市场监管、执法协作、安全保障和纠纷处理机制； （五）关于双方组团单位负责教育本国旅游者遵守对方国家的法律法规，以及两国缔结或者共同参加的相关条约的承诺。"},{"i":8,"n":"第八条","txt":"意向性边境旅游合作协议签订后，省、自治区人民政府应当向国务院文化和旅游主管部门提出开展边境旅游活动的申请。国务院文化和旅游主管部门应当征求外交、公安、交通、海关、移民等部门的意见，并报国务院批准。 国务院批准同意后，有关地方可以对外签订正式边境旅游合作协议，并将正式边境旅游合作协议逐级报国务院文化和旅游主管部门备案。"},{"i":9,"n":"第九条","txt":"双方旅游者应当持有效国际旅行证件。中国公民相关证件按照国家有关规定统一办理。"},{"i":10,"n":"第十条","txt":"我国公民均可以参加边境旅游，但有关法律法规规定不准出境的除外。"},{"i":11,"n":"第十一条","txt":"边境旅游的出入境活动应当遵守下列规定： （一）双方旅游团队出入境的手续按边境旅游合作协议办理； （二）双方旅游团队可以在边境旅游合作协议商定的范围内，灵活选择出入境口岸，并在边境旅游团队名单表内注明； （三）双方旅游团队的旅游者应当以团队形式经口岸出入境，接受海关检疫查验和出入境边防检查，向出入境边防检查机关提交边境旅游团队名单表，经查验准许后通行。确需分团出入境的，应当符合分团有关规定，由组团社事先向所在地文化和旅游主管部门报告，并按规定向公安机关出入境管理机构、出入境边防检查机关办理相关手续； （四）双方旅游者携带的进出境行李物品，应当符合进出境地所在国法律法规的规定，并依法接受检查。"},{"i":12,"n":"第十二条","txt":"经营边境旅游业务的旅行社（以下简称边境社）应当具备下列条件： （一）住所地在开展边境旅游的市、县行政区域内； （二）连续经营旅行社业务满两年； （三）近两年未发生安全生产责任事故，未因侵害旅游者合法权益受到行政机关罚款以上处罚； （四）未被认定为严重失信主体； （五）法定代表人、股东和实际控制人未因涉黄、涉赌、涉毒犯罪被判处刑罚。"},{"i":13,"n":"第十三条","txt":"旅行社经营边境旅游业务的，应当向所在地省、自治区人民政府文化和旅游主管部门提出申请，并提交下列文件： （一）申请书； （二）旅行社业务经营许可证（正副本）； （三）企业营业执照； （四）增存旅游服务质量保证金承诺书； （五）连续两年未因损害旅游者合法权益受到行政机关罚款以上行政处罚、未被认定为严重失信主体、无本办法第十二条第五项规定的犯罪记录的承诺书。 受理申请的文化和旅游主管部门应当自受理之日起20个工作日内作出许可或者不予许可的决定。作出许可决定的，文化和旅游主管部门应当及时通知同级公安机关出入境管理机构、出入境边防检查机关。 未经许可，任何单位和个人不得经营边境旅游业务。"},{"i":14,"n":"第十四条","txt":"边境社的旅游服务质量保证金交纳数额，由省级人民政府确定，并向国务院文化和旅游主管部门备案。"},{"i":15,"n":"第十五条","txt":"边境社组织旅游活动应当向合格的供应商订购产品和服务，并对相关产品和服务进行安全评估，制定安全风险管控措施和应急预案，发现履行辅助人提供的服务不符合法律法规规定或者存在安全隐患的，应当予以制止或者更换。"},{"i":16,"n":"第十六条","txt":"边境社及其领队应当在出境前向旅游者介绍旅游目的地国家的相关法律、风俗习惯、安全风险以及其他有关注意事项。"},{"i":17,"n":"第十七条","txt":"边境社应当在旅游团队出发前，通过全国旅游监管服务平台如实填报边境旅游团队名单表有关信息。"},{"i":18,"n":"第十八条","txt":"边境社及其领队应当遵守我国相关法律法规，不得安排旅游者参观或者参与下列项目或者活动： （一）损害国家尊严、荣誉和利益，危害国家安全的； （二）宣扬民族、种族、宗教歧视及邪教等内容的； （三）宣扬恐怖主义、极端主义内容的； （四）含有淫秽、赌博、吸贩毒内容的； （五）影响边境地区社会稳定的； （六）影响同其他国家特别是毗邻国家睦邻友好关系的； （七）移动、损毁界标和界线辅助设施，损害陆地国界清晰和安全稳定的； （八）其他违反法律法规和社会公德的项目或者活动。 边境社及其领队发现旅游者有前款规定行为的，应当及时制止，并报告有关主管部门。"},{"i":19,"n":"第十九条","txt":"边境社应当在边境旅游合作协议载明的区域范围、停留期限内开展活动，不得安排旅游者到国家禁止前往和不对外国人开放的地区旅游。"},{"i":20,"n":"第二十条","txt":"边境社组织、接待旅游活动应当分别安排领队、导游全程陪同，整团出入境，不得擅自分团；旅游者应当随团活动，不得擅自脱团、非法滞留。 边境社应当加强对旅游团队的管理，发现旅游者从事违法活动、有违反前款规定情形或者旅游团队发生突发事件、旅游安全事故的，应当及时向所在地文化和旅游主管部门、公安机关出入境管理机构、出入境边防检查机关、外事部门或者我国驻外机构报告。 外国旅游者非法进入边境旅游合作协议载明的区域范围之外的地区或者非法滞留的，边境社应当及时报告公安机关、文化和旅游主管部门，协助有关部门进行处理。"},{"i":21,"n":"第二十一条","txt":"在边境旅游合作协议商定的区域范围内，多次发生旅游者参与赌博、非法滞留等情形的，国务院文化和旅游主管部门可以在征求外交、公安、移民等部门意见后，报国务院暂停或者终止该区域的边境旅游活动。边境地区需要恢复边境旅游活动的，应当在整改完成后按照原程序申请。"},{"i":22,"n":"第二十二条","txt":"边境社违反本办法规定，有下列情形之一的，由文化和旅游主管部门给予警告或者通报批评，并处以1万元以上10万元以下罚款： （一）旅游团队出发前未如实填报边境旅游团队名单表有关信息的； （二）安排旅游者超出边境旅游合作协议载明的区域范围、停留期限开展活动的； （三）安排旅游者到国家禁止前往和不对外国人开放的地区旅游的。"},{"i":23,"n":"第二十三条","txt":"违反本办法其他规定的，依照有关法律、行政法规的规定进行处罚；对他人合法权益造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"本办法所指边境地区，按照我国与毗邻国家签署的边界或者边境口岸管理制度协定执行。 本办法所指市包括设区的市、地区、自治州、盟；县包括县级市、县、设区市的区、旗。"},{"i":25,"n":"第二十五条","txt":"本办法自2025年6月1日起施行。1997年10月15日原国家旅游局、外交部、公安部、海关总署发布的《边境旅游暂行管理办法》同时废止。"}]};
